  val wy = Array.fill(n-1)(0L)
  wx(0) = n-2
  wy(0) = n-2
  var xmin = n-2
  var ymin = n-2

  def binSearch(a: ArrayBuffer[Int], begin: Int, end: Int, k: Int): Int = {
    if (end - begin <= 1) {
      end
    } else {
      val m = begin + (end - begin) / 2
      if (a(m) >= k) binSearch(a, begin, m, k) else binSearch(a, m, end, k)
    }
