void push(ll v,vector<ll>&t,vector<bool>&lazy){
    if(!lazy[v])return;
    lazy[v*2]=lazy[v*2+1]=true;
    lazy[v]=false;
    umin(t[v*2],t[v]);
    umin(t[v*2+1],t[v]);
}
void update(ll v,ll tl,ll tr,ll l,ll r,vector<bool>&lazy,vector<ll>&t,ll val){
    if(l>r)return;
    if(tl==l && tr==r){
        umin(t[v],val);
        lazy[v]=true;
        return;
    }
    push(v,t,lazy);
    ll tm=(tl+tr)/2;
    update(v*2,tl,tm,l,min(r,tm),lazy,t,val);
    update(v*2+1,tm+1,tr,max(tm+1,l),r,lazy,t,val);
}
ll get(ll v,ll tl,ll tr,ll ind,vector<ll>&t,vector<bool>&lazy){
    if(tl==tr)return t[v];
    ll tm=(tl+tr)/2;
    push(v,t,lazy);
    if(ind<=tm)return get(v*2,tl,tm,ind,t,lazy);
    return get(v*2+1,tm+1,tr,ind,t,lazy);
}
