	#define l(p) e[p].l
	#define r(p) e[p].r
	#define m(p) e[p].mx
	#define c(p) e[p].cnt
	#define s(p) e[p].se
	void up(int p){
        c(p)=0;
        m(p)=max(m(p<<1),m(p<<1|1));
        s(p)=max(s(p<<1),s(p<<1|1));
        if(m(p<<1)!=m(p<<1|1))s(p)=max(s(p),min(m(p<<1),m(p<<1|1)));
        if(m(p<<1)==m(p))c(p)+=c(p<<1);
        if(m(p<<1|1)==m(p))c(p)+=c(p<<1|1);
	}
	void bld(int p,int l,int r){
		l(p)=l;r(p)=r;c(p)=-1;
		if(l==r){m(p)=n;s(p)=-1;c(p)=1;return;}
		int mid=l+r>>1;
		bld(p<<1,l,mid);bld(p<<1|1,mid+1,r);
		up(p);
	}
	void MIN(int p,int v){
        if(v>=m(p))return;
        m(p)=v;
	}
	void init(int _n){n=_n;bld(1,1,n);}
	void psd(int p){
        MIN(p<<1,m(p));
        MIN(p<<1|1,m(p));
    }
    void Min(int p,int ql,int qr,int v){
        if(v>=m(p))return;
        if(ql<=l(p)&&r(p)<=qr&&s(p)<v){
            MIN(p,v);
            return;
        }
        psd(p);
		int mid=l(p)+r(p)>>1;
        if(ql<=mid)Min(p<<1,ql,qr,v);
		if(qr>mid)Min(p<<1|1,ql,qr,v);
		up(p);
    }
	int ask(int p,int x){
		if(l(p)==r(p))return m(p);
		int mid=l(p)+r(p)>>1;
		psd(p);
		int ans=0;
		if(x<=mid)ans=ask(p<<1,x);
		else ans=ask(p<<1|1,x);
		up(p);
		return ans;
	}
}row,col;
