int read()
{
	int x=0,f=1;char ch=getchar();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
	while(ch>='0'&&ch<='9')x=x*10+ch-'0',ch=getchar();
	return x*f;
}
int n,m;
struct Node
{
	int tag,v,lc,rc,l,r;
};
struct Seg
{
	Node tr[Maxn<<1];
	int tot;
	void init(){tot=0;}
	void build(int l,int r)
	{
		int x=++tot;
		tr[x].l=l;tr[x].r=r;
		if(l==r){tr[x].v=n;return;}
		int mid=l+r>>1;
		tr[x].lc=tot+1;build(l,mid);
		tr[x].rc=tot+1;build(mid+1,r); 
	}
	void down(int x)
	{
		int t=tr[x].tag;
		if(t)
		{
			int lc=tr[x].lc,rc=tr[x].rc;
			tr[lc].tag+=t;tr[rc].tag+=t;
			tr[lc].v-=t;tr[rc].v-=t;
			tr[x].tag=0;
		}
	}
	void modify(int x,int l,int r,int v)
	{
		if(tr[x].l==l&&tr[x].r==r)
		{
			tr[x].v-=v;
			tr[x].tag+=v;
			return;
		}
		down(x);
		int mid=tr[x].l+tr[x].r>>1,lc=tr[x].lc,rc=tr[x].rc;
		if(r<=mid)modify(lc,l,r,v);
		else if(l>mid)modify(rc,l,r,v);
		else modify(lc,l,mid,v),modify(rc,mid+1,r,v);
	}
	int query(int x,int p)
	{
		if(tr[x].l==tr[x].r)return tr[x].v;
		down(x);
		int mid=tr[x].l+tr[x].r>>1,lc=tr[x].lc,rc=tr[x].rc;
		if(p<=mid)return query(lc,p);return query(rc,p);
	}
}T[2];
int main()
{
	n=read();m=read();
	LL ans=(LL)(n-2)*(n-2);
	for(int i=0;i<2;i++)T[i].init(),T[i].build(2,n-1);
//	printf("%d\n",T[0].query(1,2));
	while(m--)
	{
		int o=read()-1,x=read(),r=T[o^1].query(1,x);
		ans-=(r-2);//printf("   %lld %lld\n",r,ans);
		int t=T[o].query(1,2);
		if(x<t&&r!=2)T[o].modify(1,2,r-1,t-x);

	}
	printf("%lld",ans);
}

