//rang min, get point
struct SegmentTree{
private:
  int N;
  vector<long long> node;
  long long identity=1e18;
public:
  SegmentTree(vector<long long> v){
    int SZ=(int)v.size();
    N=1;
    while(N<SZ) N*=2;
    node.resize(2*N-1,identity);

    for(int i=0;i<SZ;i++) node.at(i+N-1)=v.at(i);
    for(int i=N-2;i>=0;i--) node.at(i)=min(node.at(2*i+1),node.at(2*i+2));
  }

  void rangmin(int a,int b,long long x,int k=0,int l=0,int r=-1){
    if(r==-1) r=N;
    if(r<=a || b<=l)  return;
    if(a<=l && r<=b){
      node.at(k)=min(node.at(k),x);
      return;
    }
    rangmin(a,b,x,2*k+1,l,(l+r)/2);
    rangmin(a,b,x,2*k+2,(l+r)/2,r);
    return;
  }

  long long getpoint(int i){
    i+=N-1;
    long long ans=node.at(i);
    while(i>0){
      i=(i-1)/2;
      ans=min(ans,node.at(i));
    }
    return ans;
  }
};

int main(){
  ios_base::sync_with_stdio(false);cin.tie(0);
  ll N,Q;
  cin >> N >> Q;

  ll ans = (N-2)*(N-2);
  SegmentTree seg1(vector<ll>(N-2,N-2));
  SegmentTree seg2(vector<ll>(N-2,N-2));

  rep(_,Q){
    int q,x;
    cin >> q >> x;
    x-=2;
    if(q==1){
      int tmp = seg1.getpoint(x);
      ans -= tmp;
      seg2.rangmin(0,tmp+1,x);
    }
    else if(q==2){
      int tmp = seg2.getpoint(x);
      ans -= tmp;
      seg1.rangmin(0,tmp+1,x);
    }
  }
  cout << ans << endl;

  return 0;
}

