            ll t=row.query_sum(no,no+1);
//            cout << t << el;
            ans-=(t-1);
            col.update_min(0,t+1,no);
        }
        else{
            // top col
            no--;
            ll t=col.query_sum(no,no+1);
//            cout << t << el;
            ans-=(t-1);
            row.update_min(0,t+1,no);
        }
//        cout << ans << el;
    }
    cout << ans << el;
