class segmentTree{
  public:
    vector<ll> segment;
    segmentTree(){}
    segmentTree(ll ssize){
       for(ll i = 0; i < 4LL * ssize + 1LL; i++){
           segment.push_back(0LL);
       }
    }

    ll query(ll l, ll r, ll start, ll end, ll node){
        if(r < start || l > end) return -INF;
        if(start <= l && end >= r) return segment[node];
        ll mid = (l + r) >> 1;
        ll left = query(l, mid, start, end, node + node);
        ll right = query(mid + 1, r, start, end, node + node + 1);
        return max(left, right);
    }

    void update(ll l, ll r, ll index, ll val, ll node){
        if(l == r){
            segment[node] = val;
            return;
        }
        ll mid = (l + r) >> 1;
        if(l <= index && index <= mid) update(l, mid, index, val, node + node);
        else update(mid + 1, r, index, val, node + node + 1);
        segment[node] = max(segment[node + node], segment[node + node + 1]);
    }
};


