constexpr int INF = 2e9;
template <typename T> struct LazySegmentTree {

  int n;
  vector<T> node, lazy;

  LazySegmentTree (int sz, T init = 0) {
    n = 1; while (n < sz) n <<= 1;
    node.assign(2*n, init);
    lazy.assign(2*n,-1); /*区間加算の時は0*/
  }

  void eval (int k) {
    if (lazy[k] == -1) return ;
    node[k] = lazy[k]; /*区間加算に注意*/
    if (k < n) {
      lazy[2*k+1] = lazy[k];
      lazy[2*k+2] = lazy[k];
    }
    lazy[k] = -1;
  }

  void update(int a, int b, T x, int k = 0, int l = 0, int r = -1) {
    eval(k);
    if (r < 0) r = n;
    if (b <= l || r <= a) return ;
    if (a <= l && r <= b) {
      lazy[k] = x;
      eval(k);
    } else {
      update(a, b, x, 2*k+1, l, (r+l)/2);
      update(a, b, x, 2*k+2, (r+l)/2, r);
      node[k] = min(node[2*k+1], node[2*k+2]);
    }
  }

  T query(int a, int b, int k = 0, int l = 0, int r = -1) {
    eval(k);
    if (r < 0) r = n;
    if (r <= a || b <= l) return INF;
    if (a <= l && r <= b) return node[k];
    T vl = query(a, b, 2*k+1, l, (l+r)/2);
    T vr = query(a, b, 2*k+2, (l+r)/2, r);
    return min(vl, vr);
  }

};
int main() {
  int n, q;
  cin >> n >> q;
  LazySegmentTree<int> left(n, n), bottom(n, n);

  ll res = ll(n - 2) * (n - 2);
  while (q--) {
    int t, x;
    cin >> t >> x;
    x--;
    if (t == 1) {
      int b = bottom.query(x, x + 1);
      res -= max(0, b - 2);
      if (left.query(0, b) > x + 1) left.update(0, b, x + 1);
    } else {
      int l = left.query(x, x + 1);
      res -= max(0, l - 2);
      if (bottom.query(0, l) > x + 1) bottom.update(0, l, x + 1);
    }
  }
  cout << res << endl;
  return 0; 
}

