typedef vector<int> vi;

ll n, q, tot = 0;

vector<pii> rowBound, colBound;//x, value sorted descending

void processRows(vi rows) {
	sort(rows.begin(), rows.end());
	if (colBound.empty()) {
		rowBound.pb(mp(rows[0], n - 2));
		tot += (ll)rows.size() * (n - 2);
	}
	else {
		if (rowBound.empty()) {
			rowBound.pb(mp(rows[0], colBound.back().first - 2));
			tot += (ll)rows.size() * (colBound.back().first - 2);
		}
		else {
			if (rows[0] < rowBound.back().first) {
				rowBound.pb(mp(rows[0], colBound.back().first - 2));
			}
			int mySz = rows.size(), i = 0, boundInd = rowBound.size() - 1;
			while (i < mySz) {
				while (boundInd >= 0 && rowBound[boundInd].first <= rows[i]) {
					boundInd--;
				}
				tot += rowBound[boundInd + 1].second;
				i++;
			}
		}
	}
}

void processCols(vi cols) {
	sort(cols.begin(), cols.end());
	if (rowBound.empty()) {
		colBound.pb(mp(cols[0], n - 2));
		tot += (ll)cols.size() * (n - 2);
	}
	else {
		if (colBound.empty()) {
			colBound.pb(mp(cols[0], rowBound.back().first - 2));
			tot += (ll)cols.size() * (rowBound.back().first - 2);
		}
		else {
			if (cols[0] < colBound.back().first) {
				colBound.pb(mp(cols[0], rowBound.back().first - 2));
			}
			int mySz = cols.size(), i = 0, boundInd = colBound.size() - 1;
			while (i < mySz) {
				while (boundInd >= 0 && colBound[boundInd].first <= cols[i]) {
					boundInd--;
				}
				tot += colBound[boundInd + 1].second;
				i++;
			}
		}
	}
}

int main() {
	fast;
	cin >> n >> q;
	int type, x, prv = -1;
	vi cur;
	foru(i, 0, q) {
		cin >> type >> x;
		if (i&&prv != type) {
			if (prv == 1)processRows(cur);
			else processCols(cur);
			cur.clear();
		}
		cur.pb(x);
		prv = type;
	}
	if (!cur.empty()) {
		if (prv == 1)processRows(cur);
		else processCols(cur);
	}
	cout << (n - 2) * (n - 2) - tot << endl;
	return 0;
}

