using namespace std;

int n, k;

int solve(int l, int r, int b, int t, vector<pair<int, int>> &v) {
    //printf("%lld %lld %lld %lld\n", l, r, b, t);
    if(r < l || t < b) return 0;
    if(v.empty()) {
        return (r - l + 1) * (t - b + 1);
    }
    int ret = 0;
    if(v[0].first == 1) { // l, r
        vector<pair<int, int>> L, R;
        for(int i = 1; i < SZ(v); i++) {
            if(v[i].second < v[0].second)
                L.push_back(v[i]);
            else
                R.push_back(v[i]);
        }
        ret += solve(l, v[0].second - 1, b, t, L);
        ret += solve(v[0].second + 1, r, b, t, R);
    } else { // b, t
        vector<pair<int, int>> B, T;
        for(int i = 1; i < SZ(v); i++) {
            if(v[i].first < v[0].first)
                B.push_back(v[i]);
            else
                T.push_back(v[i]);
        }
        ret += solve(l, r, b, v[0].first - 1, B);
        ret += solve(l, r, v[0].first + 1, t, T);
    }
    return ret;
}

