using namespace std;
struct node{
    node *l,*r;
    int a,b;
    int tag;
    node(int _a,int _b):l(NULL),r(NULL),a(_a),b(_b),tag(1e9){

    }
}*root[2];
void build(node *n,int k){
    if(n->a==n->b){
        n->tag=k;
        return ;
    }
    int mid=(n->a+n->b)/2;
    n->l=new node(n->a,mid);
    n->r=new node(mid+1,n->b);
    build(n->l,k);
    build(n->r,k);
}
void add(node *n,int l,int r,int k){
    if(n->a>=l&&n->b<=r){
        n->tag=min(n->tag,k);
        return ;
    }
    if(n->b<l||n->a>r)return ;
    add(n->l,l,r,k);
    add(n->r,l,r,k);
}
int query(node *n,int x){
    if(n->a==n->b)return n->tag;
    int mid=(n->a+n->b)/2;
    if(x<=mid)return min(query(n->l,x),n->tag);
    else return min(query(n->r,x),n->tag);
}
void solve(){
    int n,q;
    scanf("%d %d",&n,&q);
    root[0]=new node(1,n);
    root[1]=new node(1,n);
    LL ans=(n-2)*1ll*(n-2);
    build(root[0],n-1);
    build(root[1],n-1);
    while(q--){
        int op,x;
        scanf("%d %d",&op,&x);
        op%=2;
        int val=query(root[op],x);
        ans-=val-1;
       // printf("%d\n",val);
        add(root[1-op],1,val,x-1);
    }
    printf("%lld\n",ans);
}
int main(){
    int t=1;
    int T=1;
    while(t--){
        solve();
    }
}
