#include<bits/stdc++.h>

#pragma GCC optimize("Ofast")
#pragma GCC optimize("unroll-loops")

using namespace std;

typedef long long ll;

const ll MOD = 998244353;
const int MAXN = 2e5 + 5;

int n;

int closeup[4 * MAXN];
int closeright[4 * MAXN];

int lson(int v) {
    return 2 * v + 1;
}

int rson(int v) {
    return 2 * v + 2;
}

void push(int v, int setting[]) {
    if (setting[v] == -1) return;
    setting[lson(v)] = setting[rson(v)] = setting[v];
    setting[v] = -1;
}

void build(int v = 0, int tl = 0, int tr = n - 1) {
    if (tl == tr) {
        closeup[v] = n - 1;
        closeright[v] = n - 1;
        return;
    }
    int tm = (tl + tr) / 2;
    closeright[v] = closeup[v] = -1;
    build(lson(v), tl, tm);
    build(rson(v), tm + 1, tr);
}

void set_on_seg(int l, int r, int val, int setting[], int v = 0, int tl = 0, int tr = n - 1) {
    if (tl > r || tr < l || l > r) return;
    if (tl >= l && tr <= r) {
        setting[v] = val;
        return;
    }
    int tm = (tl + tr) / 2;
    push(v, setting);
    set_on_seg(l, r, val, setting, lson(v), tl, tm);
    set_on_seg(l, r, val, setting, rson(v), tm + 1, tr);
}

int get_elem(int ind, int setting[], int v = 0, int tl = 0, int tr = n - 1) {
    //cout << "v: " << v << ' ' << tl << ' ' << tr << ' ' << setting[v] << endl;
    if (tl == tr) {
        return setting[v];
    }
    int tm = (tl + tr) / 2;
    push(v, setting);
    if (ind <= tm) return get_elem(ind, setting, lson(v), tl, tm);
    else return get_elem(ind, setting, rson(v), tm + 1, tr);
}

int main() {
    int q;
    cin >> n >> q;
    ll blacks = (n - 2) * 1ll * (n - 2);
    build();
    while (q--) {
        int t, x;
        cin >> t >> x;
        --x;
        if (t == 1) {
            int minival = get_elem(x, closeup);
            //cout << "closeup: " << minival << endl;
            int l = -1, r = minival;
            blacks -= max(0, (minival - 1));
            while (r - l > 1) {
                int mid = (l + r) / 2;
                //cout << "mid: " << mid << ' ' << get_elem(mid, closeright) << endl;
                if (get_elem(mid, closeright) >= x) r = mid;
                else l = mid;
            }
           // cout << "seg: " << r << ' ' << minival - 1 << endl;
            if (r < minival) set_on_seg(r, minival - 1, x, closeright);
        } else {
            int minival = get_elem(x, closeright);
            //cout << "closeright: " << minival << endl;
            int l = -1, r = minival;
            blacks -= max(0, (minival - 1));
            while (r - l > 1) {
                int mid = (l + r) / 2;
                if (get_elem(mid, closeup) >= x) r = mid;
                else l = mid;
            }
            if (r < minival) set_on_seg(r, minival - 1, x, closeup);
        }
    }
    cout << blacks << endl;
    return 0;
}

