int n,segtree[2][816225][2];
bool delayed[2][816225];

void eval(int k, int i, int l, int r){
	if(delayed[k][i]){
		segtree[k][i][0] = segtree[k][i][1];
		if(r-l>1){
			segtree[k][i*2+1][1] = segtree[k][i][1];
			segtree[k][i*2+2][1] = segtree[k][i][1];
			delayed[k][i*2+1] = true;
			delayed[k][i*2+2] = true;
		}
		delayed[k][i] = false;
	}
}

int query(int k, int a, int b, int i=0, int l=0, int r=n){
	eval(k,i,l,r);
	if(r<=a || b<=l){
		return INF;
	}else if(a<=l && r<=b){
		return segtree[k][i][0];
	}else{
		return std::min(query(k,a,b,i*2+1,l,(l+r)/2),query(k,a,b,i*2+2,(l+r)/2,r));
	}
}

void update(int k, int a, int b, int v, int i=0, int l=0, int r=n){
	eval(k,i,l,r);
	// printf("%d %d %d %d %d %d %d\n",k,a,b,v,i,l,r);
	if(r<=a || b<=l){
		return;
	}else if(a<=l && r<=b){
		delayed[k][i] = true;
		segtree[k][i][1] = v;
		eval(k,i,l,r);
	}else{
		update(k,a,b,v,i*2+1,l,(l+r)/2);
		update(k,a,b,v,i*2+2,(l+r)/2,r);
		segtree[k][i][0] = std::min(segtree[k][i*2+1][0],segtree[k][i*2+2][0]);
	}
}

