		v->length = j - i + 1;
		v->s = i;
		v->e = j;
		if (i == j) return;
		v->l = new node();
		v->r = new node();
		build(i, (i + j) / 2, v->l);
		build((i + j) / 2 + 1, j, v->r);
	}

	segt() {}
	segt(int n) {
		rt = new node();
		build(0, n - 1, rt);
	}

	inline void prop(node* v) {
		if (v->l != nullptr) {
			if (v->set) {
				v->l->lazyby = v->r->lazyby = 0;
				v->l->lazyto = v->r->lazyto = v->lazyto;
				v->l->set = v->r->set = true;
			}
			v->l->lazyby += v->lazyby;
			v->r->lazyby += v->lazyby;
		}
		if (v->set) {
			v->t = v->lazyto * v->length;
			v->mx = v->lazyto;
		}
		v->t += v->lazyby * v->length;
		v->mx += v->lazyby;
		v->set = v->lazyby = v->lazyto = 0;
	}

	void update(int i, int j, ll val, bool by, node* v) {
		if (j < v->s || v->e < i) return;
		if (i <= v->s && v->e <= j) {
			prop(v);
			if (by) v->lazyby += val;
			else {
				v->lazyto = val;
				v->set = true;
			}
			prop(v);
			return;
		}
		prop(v);
		update(i, j, val, by, v->l);
		update(i, j, val, by, v->r);
		prop(v->l);
		prop(v->r);
		v->t = v->l->t + v->r->t;
		v->mx = max(v->l->mx, v->r->mx);

	}

	void updateby(int i, int j, int val) { update(i, j, val, true, rt); }
	void updateto(int i, int j, int val) { update(i, j, val, false, rt); }


	ll query(int i, int j, bool m, node* v) {
		if (j < v->s || v->e < i) {
			if (m) return -1000000000;
			return 0;
		}
		prop(v);
		if (i <= v->s && v->e <= j) {
			if (m) return v->mx;
			return v->t;
		}
		ll l = query(i, j, m, v->l);
		ll r = query(i, j, m, v->r);
		if (m) return max(l, r);
		return l + r;
	}

	ll querysum(int i, int j) { return query(i, j, false, rt); }
	ll querymax(int i, int j) { return query(i, j, true, rt); }
};

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

	int n, q;
	cin >> n >> q;
	segt a(n + 3);
	segt b(n + 3);

	a.updateto(2, n - 1, n);
	b.updateto(2, n - 1, n);

	ll ans = (n - 2);
	ans *= (n - 2);
	int minfr = n;
	int minsc = n;
	for (int i = 0; i < q; i++) {
		int x, y;
		cin >> x >> y;
		if (x == 1) {
			int z = b.querysum(y, y);
			ans -= (z-2);
			minfr = min(minfr, y);
			if (minfr == y) {
				a.updateto(2, z, y);
			}
		}
		if (x == 2) {
			int z = a.querysum(y, y);
			ans -= (z - 2);
			minsc = min(minsc, y);
			if (minsc == y) {
				b.updateto(2, z, y);
			}
		}
	}

	cout << ans << endl;
}

