        st_r[pos]=min(st_r[pos],lz_r[pos]);
        if(be!=en)
        {
            lz_r[2*pos+1]=min(lz_r[2*pos+1],lz_r[pos]);
            lz_r[2*pos+2]=min(lz_r[2*pos+2],lz_r[pos]);
        }
        lz_r[pos]=N;
