    ll m=(be+en)/2;
    updaterange_r(be,m,2*pos+1,l,r,v);
    updaterange_r(m+1,en,2*pos+2,l,r,v);
    st_r[pos]=min(st_r[2*pos+1],st_r[2*pos+2]);
