int get(vector<int>& C,int p,int i,int l,int r) {
  if(C[i] >= 0)return C[i];
  else if(p < (l+r)/2)return get(C,p,2*i+1,l,(l+r)/2);
  else return get(C,p,2*i+2,(l+r)/2,r);
}

void update(vector<int>& C,int n,int a,int b,int i,int l,int r,int pre) {
  if(pre >= 0)C[i] = min((C[i]<0?1000000:C[i]),pre);
  if(a == b)return;
  else if(b <= l || r <= a) {
    return;
  }
  else if(a <= l && r <= b) {
    C[i] = min((C[i]<0?1000000:C[i]),n);
    return;
  }
  else {
    update(C,n,a,b,i*2+1,l,(l+r)/2,C[i]);
    update(C,n,a,b,i*2+2,(l+r)/2,r,C[i]);
    C[i] = -1;
  }
}

