int n,q;
struct segment{
#define ls rt<<1
#define rs rt<<1|1
#define lson ls,l,mid
#define rson rs,mid+1,r
	int mi[N<<2],tag[N<<2];
	inline void up(int rt){mi[rt]=std::min(mi[ls],mi[rs]);}
	inline void build(int rt,int l,int r){
		mi[rt]=2e9,tag[rt]=2e9;
		if(l==r) return mi[rt]=n,void();
		int mid=l+r>>1; build(lson),build(rson),up(rt);
	}
	inline void down(int rt){
		if(tag[rt]==2e9) return;
		mi[ls]=std::min(mi[ls],tag[rt]);
		mi[rs]=std::min(mi[rs],tag[rt]);
		tag[ls]=std::min(tag[ls],tag[rt]);
		tag[rs]=std::min(tag[rs],tag[rt]);
		tag[rt]=2e9;
	}
	inline void assign(int rt,int l,int r,int x,int y,int v){
		if(x<=l&&r<=y) return mi[rt]=std::min(mi[rt],v),tag[rt]=std::min(tag[rt],v),void();
		int mid=l+r>>1; down(rt);
		if(x<=mid) assign(lson,x,y,v); if(mid<y) assign(rson,x,y,v); up(rt);
	}
	inline int qry(int rt,int l,int r,int x){

		if(l==r) return mi[rt];
		int mid=l+r>>1; down(rt);
//		std::cerr<<"seg: "<<(ls)<<' '<<l<<' '<<r<<' '<<tag[ls]<<'\n';
		if(x<=mid) return qry(lson,x); else return qry(rson,x);
	}
} r,c;
int main(){
	std::ios::sync_with_stdio(0);
	std::cin>>n>>q;
	ll sum=0;
	r.build(1,1,n),c.build(1,1,n);
	while(q--){
		int opt,x; std::cin>>opt>>x;
		if(opt==1){
			int pos=c.qry(1,1,n,x);
			sum+=pos-2;
			c.assign(1,1,n,x,x,1);
			r.assign(1,1,n,1,pos,x);
		} else {
			int pos=r.qry(1,1,n,x);
			sum+=pos-2;
			r.assign(1,1,n,x,x,1);
			c.assign(1,1,n,1,pos,x);
		}
//		rep(i,1,n) std::cerr<<r.qry(1,1,n,i)<<" \n"[i==n];
//		rep(i,1,n) std::cerr<<c.qry(1,1,n,i)<<" \n"[i==n];
	}
	std::cout<<(n-2ll)*(n-2ll)-sum<<'\n';
	return 0;
}

