    void upd(int v, int l, int r, int lq, int rq, int x) {
        if (lq >= r || l >= rq) return;
        if (lq <= l && r <= rq) {
            tree[v].val = min(x, tree[v].val);
            return;
        }
        upd(v<<1, l, (l+r)>>1, lq, rq, x);
        upd((v<<1)+1, (l+r)>>1, r, lq, rq, x);
    }

    int get(int v, int l, int r, int pos) {
        if (pos >= r || pos < l) return INFi;
        if (l + 1 == r) {
            return tree[v].val;
        }
        return min(min(get(v<<1, l, (l+r)>>1, pos), get((v<<1)+1, (l+r)>>1, r, pos)), tree[v].val);
    }

    void upd(int lq, int rq, int x) {
        upd(1, 0, n, lq, rq, x);
    }

    int get(int pos) {
        return get(1, 0, n, pos);
    }
};

void solve() {
    int n, q; cin >> n >> q;
    seg_tree cols, rows;
    cols.build(n + 5);
    rows.build(n + 5);
    vector<int> cu(n), ru(n+1);
    ll ans = 1ll * (n - 2) * (n - 2);
    range(_, q) {
        int t, x; cin >> t >> x;
        if (t == 1) {
            if (cu[x]) continue;
            int e = rows.get(x);
            e = min(e, n);
            cols.upd(1, e, x);
            ans -= e - 2;
            cu[x] = 1;
        } else {
            if (ru[x]) continue;
            int e = cols.get(x);
            e = min(e, n);
            rows.upd(1, e, x);
            ans -= e - 2;
            ru[x] = 1;
        }
    }
    cout << ans << "\n";
}

