#include <bits/stdc++.h>

using namespace std;

void rmq_update(vector<int> &t, int i, int val)
{
	for (t[i += t.size() / 2] = val; i /= 2; )
		t[i] = min(t[i * 2], t[i * 2 + 1]);
}

int rmq_query(const vector<int> &t, int l, int r, int def = INT_MAX)
{
	int n = t.size() / 2, a = def, b = def;
	for (int i = l + n, j = r + n; i < j; i /= 2, j /= 2) {
		if (i % 2) a = min(a, t[i++]);
		if (j % 2) b = min(b, t[--j]);
	}
	return min(a, b);
}

int main(int argc, char *argv[])
{
	ios::sync_with_stdio(false); cin.tie(0);
	int n, q;
	cin >> n >> q;
	long long ans = (long long) (n - 2) * (n - 2);
	vector<int> tx(n * 2, n - 2), ty(n * 2, n - 2);
	for (int qi = 0; qi < q; qi++) {
		int c, x;
		cin >> c >> x;
		x -= 2;
		if (c == 1) {
			int v = rmq_query(tx, x, n);
			ans -= v;
			if (rmq_query(ty, v, v + 1) > x) rmq_update(ty, v, x);
		} else if (c == 2) {
			int v = rmq_query(ty, x, n);
			ans -= v;
			if (rmq_query(tx, v, v + 1) > x) rmq_update(tx, v, x);
		}
	}
	cout << ans << endl;

	return 0;
}

