const int N = 1 << 18;

struct Tour{
  int n, off;
  vector<int> tree;

  Tour(int _n){
    n = _n;
    int i;
    for(i = 1; i <= n; i *= 2);
    off = i;
    tree.resize(2 * off + 1);
  }

  void build(int node, int a, int b){
    if(a == b){
      tree[node] = 0;
      return;
    }
    int mid = (a + b) / 2;
    build(node * 2, a, mid);    
    build(node * 2 + 1, mid + 1, b);    
    tree[node] = max(tree[node * 2], tree[node * 2 + 1]);
  }

  void update(int node, int a, int b, int pos, int val){
    if(a == b){
      tree[node] = max(tree[node], val);
      return;
    }
    int mid = (a + b) / 2;
    if(pos <= mid)
      update(node * 2, a, mid, pos, val);
    else
      update(node * 2 + 1, mid + 1, b, pos, val);

    tree[node] = max(tree[node * 2], tree[node * 2 + 1]);
  }

  pii walk(int node, int a, int b, int least){
    if(a == b) return mp(a, tree[node]);
    int mid = (a + b) / 2;
    if(tree[node * 2] >= least)
      return walk(node * 2, a, mid, least);
    else return walk(node * 2 + 1, mid + 1, b, least);
  }

  int query(int least){
    if(tree[1] < least) return n;
    return walk(1, 0, off - 1, least).fi;
  }

  void build(){
    build(1, 0, off - 1);
  }

  void update(int p, int val){
    update(1, 0, off - 1, p, val);
  }

};

int n, q;

int main(){
  scanf("%d %d", &n, &q);
  Tour rows(n), cols(n);
  rows.build(); cols.build();

  ll ans = (ll)(n - 2) * (ll)(n - 2);

  while(q--){
    int f, x; scanf("%d %d", &f, &x);
    if(f == 1){
      //x-ta kolona, spustam dolje
      int dokle = rows.query(x);
      ans -= (ll)(dokle - 2);
      cols.update(x, dokle);
    }

    else{
      int dokle = cols.query(x);
      ans -= (ll)(dokle - 2);
      rows.update(x, dokle);
    }
  }

  printf("%lld\n", ans);

  return 0;
}

