void push(int t[],bool marked[], int v) 
{
    if (marked[v]) 
    {
        //t[v*2] = t[v*2+1] = t[v];
        t[v*2]=min(t[v*2],t[v]);
        t[v*2+1]=min(t[v*2+1],t[v]);
        marked[v*2] = marked[v*2+1] = true;
        marked[v] = false;
    }
}

void update(int t[], bool marked[],int v, int tl, int tr, int l, int r, int new_val) 
{
    if (l > r) 
        return;
    if (l == tl && tr == r) 
    {
        t[v] = min(t[v],new_val);
        marked[v] = true;
    } 
    else 
    {
        push(t,marked,v);
        int tm = (tl + tr) / 2;
        update(t,marked,v*2, tl, tm, l, min(r, tm), new_val);
        update(t,marked,v*2+1, tm+1, tr, max(l, tm+1), r, new_val);
    }
}

int get(int t[],bool marked[],int v, int tl, int tr, int pos) 
{
    if (tl == tr) 
    {
        return t[v];
    }
    push(t,marked,v);
    int tm = (tl + tr) / 2;
    if (pos <= tm) 
        return get(t,marked,v*2, tl, tm, pos);
    else
        return get(t,marked,v*2+1, tm+1, tr, pos);
}
