		if(a==1)
		{
			int pos = get(T1,m1,1,1,n,b);
			//cout<<pos<<'\n';
			ans -= pos-2;
			update(T2,m2,1,1,n,2,pos-1,b);
		}
		else
		{
			int pos = get(T2,m2,1,1,n,b);
			//cout<<pos<<'\n';
			ans -= pos-2;
			update(T1,m1,1,1,n,2,pos-1,b);
		}
	}
	cout<<ans<<'\n';
}

