const int N=2e5+5;
int st_row[4*N];
int st_col[4*N];
int row[N],col[N];

void build(int l,int r,int node,int type)
{
	if(l==r)
	{
		if(type)
			st_row[node]=row[l];
		else
			st_col[node]=col[l];
		return ;
	}

	int mid=(l+r)/2;
	build(l,mid,2*node,type);
	build(mid+1,r,2*node+1,type);
	if(type)
		st_row[node]=max(st_row[2*node],st_row[2*node+1]);
	else
		st_col[node]=max(st_col[2*node],st_col[2*node+1]);
}

void update(int l,int r,int id,int node,int type,int val)
{
	if(l==r)
	{
		if(type)
			st_row[node]=row[l];
		else
			st_col[node]=col[l];
		return;
	}

	int mid=(l+r)/2;
	if(id<=mid)
		update(l,mid,id,2*node,type,val);
	else
		update(mid+1,r,id,2*node+1,type,val);

	if(type)
		st_row[node]=max(st_row[2*node],st_row[2*node+1]);
	else
		st_col[node]=max(st_col[2*node],st_col[2*node+1]);
}

int query(int l,int r,int ql,int qr,int node,int type)
{
	//trace3(l,r,node);
	if(l>qr or r<ql)
		return -1e18;

	if(ql<=l and r<=qr)
	{
		if(type)
			return st_row[node];
		else
			return st_col[node];
	}

	int mid=(l+r)/2;
	int p=query(l,mid,ql,qr,2*node,type);
	int q=query(mid+1,r,ql,qr,2*node+1,type);

	return max(p,q);
}


