using namespace std;
typedef long long ll;
typedef pair<int,int> pii;
const int MAXN = 2e5 + 5;

struct Segment_Tree
{
	int mx[MAXN<<2], tag[MAXN<<2];
	#define ls(u) ((u)<<1)
	#define rs(u) ((u)<<1|1)
	#define lson(u) ls(u),l,mid
	#define rson(u) rs(u),mid+1,r
	inline void push_up(int u){ mx[u] = max(mx[ls(u)], mx[rs(u)]);}
	inline void push_down(int u)
	{
		if(~tag[u])
		{
			mx[ls(u)] = tag[ls(u)] = tag[u];
			mx[rs(u)] = tag[rs(u)] = tag[u];
			tag[u] = -1;
		}
	}
	void build(int u,int l,int r,int k)
	{
		mx[u]=k; tag[u]=-1;
		if(l==r) return;
		int mid = (l+r)>>1;
		build(lson(u),k); build(rson(u),k);
	}
	void update(int u,int l,int r,int ql,int qr,int k)
	{
		if(ql<=l && r<=qr){ mx[u]=tag[u]=k; return;}
		push_down(u);
		int mid = (l+r)>>1;
		if(ql<=mid) update(lson(u),ql,qr,k);
		if(mid<qr) update(rson(u),ql,qr,k);
		push_up(u);
	}
	int query(int u,int l,int r,int q)
	{
		if(l==r) return mx[u];
		push_down(u);
		int mid = (l+r)>>1;
		if(q<=mid) return query(lson(u),q);
		else return query(rson(u),q);
	}
	int find_greater(int u,int l,int r,int k)
	{
		if(mx[u] <= k) return r+1;
		if(l==r) return l;
		push_down(u);
		int mid = (l+r)>>1;
		if(mx[ls(u)] > k) return find_greater(lson(u),k);
		else return find_greater(rson(u),k);
	}
};

int main(void)
{
	int n,Q;
	scanf("%d%d",&n,&Q);

	ll ans = (ll)(n-2) * (n-2);

	static Segment_Tree up,lef;
	up.build(1,1,n,n-1); lef.build(1,1,n,n-1);

	while(Q--)
	{
		int oper,x;
		scanf("%d%d",&oper,&x);
		if(oper == 1)
		{
			int to = lef.query(1,1,n, x);
			ans -= to-1;
			int pos = up.find_greater(1,1,n, x-1);
			if(pos <= to) up.update(1,1,n, pos,to,x-1);
		}
		else
		{
			int to = up.query(1,1,n, x);
			ans -= to-1;
			int pos = lef.find_greater(1,1,n, x-1);
			if(pos <= to) lef.update(1,1,n, pos,to,x-1);
		}
	}
	printf("%lld",ans);
	return 0;
}

