		{
			if(l==n)
				t[num]=n;
			return;
		}
		int mid=(l+r)>>1;
		build(l,mid,num<<1),build(mid+1,r,num<<1|1);
		t[num]=max(t[num<<1],t[num<<1|1]);
	}
	int ask(int l,int r,int x,int num)
	{
		if(l==r)
			return l;
		int mid=(l+r)>>1;
		if(t[num<<1]>=x)
			return ask(l,mid,x,num<<1);
		return ask(mid+1,r,x,num<<1|1);
	}
	void change(int l,int r,int pos,int x,int num)
	{
		if(l==r)
		{
			t[num]=x;
			return;
		}
		int mid=(l+r)>>1;
		if(pos<=mid)
			change(l,mid,pos,x,num<<1);
		else
			change(mid+1,r,pos,x,num<<1|1);
		t[num]=max(t[num<<1],t[num<<1|1]);
	}
