	#define m(p) e[p].mn
	void bld(int p,int l,int r){
		l(p)=l;r(p)=r;m(p)=n;
		if(l==r){return;}
		int mid=l+r>>1;
		bld(p<<1,l,mid);bld(p<<1|1,mid+1,r);
	}
	void init(int _n){n=_n;bld(1,1,n);}
    void Min(int p,int ql,int qr,int v){
        if(ql<=l(p)&&r(p)<=qr){
            m(p)=min(m(p),v);
            return;
        }
		int mid=l(p)+r(p)>>1;
        if(ql<=mid)Min(p<<1,ql,qr,v);
		if(qr>mid)Min(p<<1|1,ql,qr,v);
    }
	int ask(int p,int x){
		if(l(p)==r(p))return m(p);
		int mid=l(p)+r(p)>>1;
		int ans=m(p);
		if(x<=mid)ans=min(ans,ask(p<<1,x));
		else ans=min(ans,ask(p<<1|1,x));
		return ans;
	}
