using namespace std;
typedef long long LL;

const int MAXN = 2e5 + 5;

int n , Q , vis[MAXN][3];
int tr[MAXN << 2][2] , tag[MAXN << 2][2];
void build(int l , int r , int now) {
	tag[now][0] = 1e9;tag[now][1] = 1e9;
	if(l == r) {
		tr[now][0] = tr[now][1] = n;
		return;
	}
	int mid = (l + r) >> 1;
	build(l , mid , now << 1);
	build(mid + 1 , r , now << 1 | 1);
	tr[now][0] = min(tr[now << 1][0] , tr[now << 1 | 1][0]);
	tr[now][1] = min(tr[now << 1][1] , tr[now << 1 | 1][1]);
}
void push_down(int now) {
	if(tag[now][0] != 1e9) {
		int v = tag[now][0];
		tr[now << 1][0] = min(tr[now << 1][0] , v);tag[now << 1][0] = min(tag[now << 1][0] , v);
		tr[now << 1 | 1][0] = min(tr[now << 1 | 1][0] , v);tag[now << 1 | 1][0] = min(tag[now << 1 | 1][0] , v);
		tag[now][0] = 1e9;
	}
	if(tag[now][1] != 1e9) {
		int v = tag[now][1];
		tr[now << 1][1] = min(tr[now << 1][1] , v);tag[now << 1][1] = min(tag[now << 1][1] , v);
		tr[now << 1 | 1][1] = min(tr[now << 1 | 1][1] , v);tag[now << 1 | 1][1] = min(tag[now << 1 | 1][1] , v);
		tag[now][1] = 1e9;
	}
}
void update(int l , int r , int now , int x , int y , int v , int t) {
	if(l >= x && r <= y) {
		if(t == 0) tr[now][t] = min(tr[now][t] , v) , tag[now][t] = min(tag[now][t] , v);
		if(t == 1) tr[now][t] = min(tr[now][t] , v) , tag[now][t] = min(tag[now][t] , v);
		return;
	}
	int mid = (l + r) >> 1;
	push_down(now);
	if(x <= mid) update(l , mid , now << 1 , x , y , v , t);
	if(y > mid) update(mid + 1 , r , now << 1 | 1 , x , y , v , t);
	tr[now][0] = min(tr[now << 1][0] , tr[now << 1 | 1][0]);
	tr[now][1] = min(tr[now << 1][1] , tr[now << 1 | 1][1]);
}
int find(int l , int r , int now , int x , int t) {
	if(l == r) return tr[now][t];
	push_down(now);
	int mid = (l + r) >> 1;
	if(x <= mid) return find(l , mid , now << 1 , x , t);
	else return find(mid + 1 , r , now << 1 | 1 , x , t);
}
int main() {
	scanf("%d %d" , &n , &Q);
	LL ans = (LL)(n - 2) * (LL)(n - 2);
	build(1 , n , 1);
	while(Q -- > 0) {
		int op , x;
		scanf("%d %d" , &op , &x);
		if(vis[op][x]) continue;
		vis[op][x] = 1;
		if(op == 1) {
			int now = find(1 , n , 1 , x , 0);
			ans -= (now - 2);
			if(now > 2) update(1 , n , 1 , 2 , now - 1 , x , 1);
		}
		else {
			int now = find(1 , n , 1 , x , 1);
			ans -= (now - 2);
			if(now > 2) update(1 , n , 1 , 2 , now - 1 , x , 0);
		}
	}	
	printf("%lld" , ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
int n,q;
int xx[800005],yy[800005];//xx记录一行一行，yy记录一列一列 
int lazy[800005],lazy2[800005];
long long ans=0;
void build(int now,int l,int r){
	if(l==r){
		xx[now]=n,yy[now]=n;
		return;
	}
	int mid=(l+r)>>1;
	build(now*2,l,mid);
	build(now*2+1,mid+1,r);
	xx[now]=xx[now*2]+xx[now*2+1];
	yy[now]=yy[now*2]+yy[now*2+1];
	return ;
}
void downx(int now,int l,int r){
//	cout<<"down : "<<l<<" "<<r<<endl;
	if(!lazy[now])return ;
	int mid=(l+r)>>1;
	if(mid==l){
		xx[now*2]=min(xx[now*2],lazy[now]);

//		cout<<"ll:"<<l<<" rr:"<<r<<endl;
//		cout<<xx[now*2]<<" "<<xx[now*2+1]<<endl;
	}
	if(mid+1==r){
		xx[now*2+1]=min(xx[now*2+1],lazy[now]);
	}
	lazy[now*2]=lazy[now*2]?min(lazy[now*2],lazy[now]):lazy[now];
	lazy[now*2+1]=lazy[now*2+1]?min(lazy[now*2+1],lazy[now]):lazy[now];
	lazy[now]=0;
	return ;
}
void downy(int now,int l,int r){
	if(!lazy2[now])return ;
	int mid=(l+r)>>1;
	if(mid==l){
		yy[now*2]=min(yy[now*2],lazy2[now]);

	}
	if(mid+1==r){
		yy[now*2+1]=min(yy[now*2+1],lazy2[now]);
	}
	lazy2[now*2]=lazy2[now*2]?min(lazy2[now*2],lazy2[now]):lazy2[now];
	lazy2[now*2+1]=lazy2[now*2+1]?min(lazy2[now*2+1],lazy2[now]):lazy2[now];
	lazy2[now]=0;
	return ;
}
void add(int now,int l,int r,int gl,int gr,int sum){
	if(l>=gl&&r<=gr){
//		cout<<"x from "<<l<<" to "<<r<<endl;
		if(lazy[now]!=0)lazy[now]=min(lazy[now],sum);
		else lazy[now]=sum;
		return ;
	}
	int mid=(l+r)>>1;
	downx(now,l,r);
	if(gl<=mid)add(now*2,l,mid,gl,gr,sum);
	if(gr>mid)add(now*2+1,mid+1,r,gl,gr,sum);
	return ;
}
void modify(int now,int l,int r,int to){
//	cout<<"l:"<<l<<" r:"<<r<<endl;
	if(l==r){
		int d=yy[now];
//		cout<<"dy:"<<d<<endl;
		if(yy[now]==1)ans+=0;
		else ans+=d-2;
		yy[now]=1;
//		cout<<"in add"<<endl;
		add(1,1,n,1,d-1,l);
//		cout<<"going to return"<<endl;
		return ;
	}
	downy(now,l,r);
	int mid=(l+r)>>1; 
	if(mid>=to)modify(now*2,l,mid,to);
	else if(mid+1<=to)modify(now*2+1,mid+1,r,to);
	return;
}
void add2(int now,int l,int r,int gl,int gr,int sum){//处理列 
	if(l>=gl&&r<=gr){
		if(lazy2[now]!=0)lazy2[now]=min(lazy2[now],sum);
		else lazy2[now]=sum;
//		cout<<"y from "<<l<<" to "<<r<<endl;
		return ;
	}
	int mid=(l+r)>>1;
	downy(now,l,r);
	if(gl<=mid)add2(now*2,l,mid,gl,gr,sum);
	if(gr>mid)add2(now*2+1,mid+1,r,gl,gr,sum);
	return ;
}
void modify2(int now,int l,int r,int to){//一行满 
//	cout<<"l:"<<l<<" r:"<<r<<endl;
	if(l==r){
		int d=xx[now];
//		cout<<"dx:"<<d<<endl;
		if(xx[now]==1)ans+=0;
		else ans+=d-2;
		xx[now]=1;
//		cout<<"in add2"<<endl;
		add2(1,1,n,1,d-1,l);
//		cout<<"going to return"<<endl;
		return ;
	}
	downx(now,l,r);
	int mid=(l+r)>>1;
	if(mid>=to)modify2(now*2,l,mid,to);
	else if(mid+1<=to)modify2(now*2+1,mid+1,r,to);
	return ;
} 
int main(){
	cin>>n>>q;
	int op,dir;
	build(1,1,n);
	for(int i=1;i<=q;i++){
		cin>>op>>dir;
		if(op==1){
			modify(1,1,n,dir);
		}else{
			modify2(1,1,n,dir);
		}
//		cout<<ans<<endl;
	}
	cout<<(long long)(n-2)*(long long)(n-2)-ans<<endl;
	return 0;
}

