int n, q;

struct Segtree {
	int dt[1 << 20], wp[1 << 20];
	void inline init() {
		memset(dt, 0x3f, sizeof(dt));
		memset(wp, 0x3f, sizeof(wp));
	}
	void inline pd(int now) {
		if(wp[now] != Inf) {
			dt[now << 1] = min(dt[now << 1], wp[now]);
			dt[now << 1 | 1] = min(dt[now << 1 | 1], wp[now]);
			wp[now << 1] = min(wp[now << 1], wp[now]);
			wp[now << 1 | 1] = min(wp[now << 1 | 1], wp[now]);
			wp[now] = Inf;
		}
	}
	void inline pu(int now) {
		dt[now] = min(dt[now << 1], dt[now << 1 | 1]);
	}
	void inline qmin(int l, int r, int x, int now = 1, int nl = 1, int nr = n) {
		if(nl >= l && nr <= r) {
			dt[now] = min(dt[now], x);
			wp[now] = min(wp[now], x);
			return;
		}
		if(nl > r || nr < l) return;
		pd(now);
		int m = (nl + nr) >> 1;
		qmin(l, r, x, now << 1, nl, m);
		qmin(l, r, x, now << 1 | 1, m + 1, nr);
		pu(now);
	}
	int inline get(int to, int now = 1, int nl = 1, int nr = n) {
		if(nl == nr) return dt[now];
		pd(now);
		int m = (nl + nr) >> 1;
		if(m >= to) return get(to, now << 1, nl, m);
		else return get(to, now << 1 | 1, m + 1, nr);
	}
} sl, su;

set<int> lgl, lgu;

int main() {
	scanf("%d%d", &n, &q);
	sl.init(); su.init();
	sl.qmin(2, n - 1, n);
	su.qmin(2, n - 1, n);
	ll al = (n - 2ll) * (n - 2ll);
	while(q--) {
		int md, p;
		scanf("%d%d", &md, &p);
		if(md == 1) {
			if(lgl.count(p)) continue;
			int bn = sl.get(p);
			al -= bn - 2;
			lgl.insert(p);
			su.qmin(2, bn, p);
		} else {
			if(lgu.count(p)) continue;
			int bn = su.get(p);
			al -= bn - 2;
			lgu.insert(p);
			sl.qmin(2, bn, p);
		}
	}
	printf("%lld\n", al);
	return 0;
}

