const int N = (int) 2e5 + 7;

struct tree
{
    int t[N];
    tree()
    {
        for (int i = 0; i < N; i++)
        {
            t[i] = 0;
        }
    }
    void upd(int i, int x)
    {
        while (i < N)
        {
            t[i] = max(t[i], x);
            i += i & (-i);
        }
    }
    int get(int i)
    {
        int sol = 0;
        while (i)
        {
            sol = max(sol, t[i]);
            i -= i & (-i);
        }
        return sol;
    }
};

