int main() {
  ll n, q;
  cin >> n >> q;
  ll ans = (n - 2) * (n - 2);
  int last_down = n - 2, last_right = n - 2;
  vector<int> can_down(n - 2, -1), can_right(n - 2, -1);
  for (int i = 0; i < q; i++) {
    ll flag, x;
    cin >> flag >> x;
    x -= 2;
    if (flag == 1) {
      if (can_down[x] == -1) {
        ans -= last_right;
        while (last_down > x) {
          last_down--;
          can_down[last_down] = last_right;
        }
      } else {
        ans -= can_down[x];
      }
    } else {
      if (can_right[x] == -1) {
        ans -= last_down;
        while (last_right > x) {
          last_right--;
          can_right[last_right] = last_down;
        }
      } else {
        ans -= can_right[x];
      }
    }
  }
  cout << ans << endl;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int N = 4e6;
int x[2][N], lz[2][N];
ll n, q, t;

void push(int t, int v) {
    x[t][v] = min(x[t][v], lz[t][v]);
    lz[t][2 * v] = min(lz[t][2 * v], x[t][v]);
    lz[t][2 * v + 1] = min(lz[t][2 * v + 1], x[t][v]);
}
int find_min(int v, int l, int r, int b) {
    push(t, v);
    if (l == r && r == b) {
        return x[t][v];
    }
    int m = (l + r) / 2;
    if (b <= m) {
        return find_min(2 * v, l, m, b);
    }
    return find_min(2 * v + 1, m + 1, r, b);
}
void upd(int v, int l, int r, int L, int R, int z) {
    if (L <= l && r <= R) {
        lz[t][v] = min(lz[t][v], z);
      	push(t, v);
        return;
    }
    if (r < L || R < l) {
        return;
    }
    push(t, v);
    int m = (l + r) / 2;
    upd(2 * v, l, m, L, R, z);
    upd(2 * v + 1, m + 1, r, L, R, z);
    x[t][v] = min(x[t][2 * v], x[t][2 *  v + 1]);
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> q;
    for (int i = 0; i < 10 * n; i++) {
        x[0][i] = lz[0][i] = n;
        x[1][i] = lz[1][i] = n;
    }
    ll r = (n - 2) * (n - 2);
    while (q--) {
        int a; cin >> t >> a; t--;
        int b = find_min(1, 1, n, a);
        r -= max(0, b - 2); t = 1 - t;
        upd(1, 1, n, 1, b, a);
    }
    cout << r << endl;
    return 0;
}

