          A[i] = x + 1;
        }
        W = x + 1;
      }
      res -= max(0, B[x] - 1);
    } else {
      if (x < H) {
        for (int i = 0; i < W; i++) {
          B[i] = x + 1;
        }
        H = x + 1;
      }
      res -= max(0, A[x] - 1);
    }
  }
  cout << res << '\n';
  return 0;
}

