using io::read; using io::write; using io::flush; using io::space; using io::endl; using io::getc; using io::putc;

const int N = 200005;

struct segtree {
  int mn[N * 4];
  segtree() {
    memset(mn, 0x3f, sizeof mn);
  }
  void mdy(int x, int l, int r, int ql, int qr, int v) {
    if (ql <= l && r <= qr) {
      mn[x] = min(mn[x], v);
      return;
    }
    int mid = (l + r) >> 1;
    if (ql <= mid) mdy(x << 1, l, mid, ql, qr, v);
    if (qr > mid) mdy(x << 1 | 1, mid + 1, r, ql, qr, v);
  }
  int query(int x, int l, int r, int p) {
    if (l == r) return mn[x];
    int mid = (l + r) >> 1;
    return min(p <= mid ? query(x << 1, l, mid, p) : query(x << 1 | 1, mid + 1, r, p), mn[x]);
  }
}t[2];

int main() {
  int n, q;
  ll s;
  read(n, q);
  s = 1LL * (n - 2) * (n - 2);
  for (int i = 1; i <= q; ++i) {
    int op, x;
    read(op, x);
    --op; --x;
    int p = t[op].query(1, 1, n - 2, x);
    p = min(p, n - 2);
    if (p == 0) continue;
    s -= p;
    t[op ^ 1].mdy(1, 1, n - 2, 1, p, x - 1);
  }
  printf("%lld\n", s);
  return 0;
}

