const ll INF=1e18;

struct node{
    ll lz,val;
    node():lz(INF),val(0){}
    void updt(node& a,node& b){
        val=min(a.val,b.val);
    }
};
struct seg{
    ll base;
    vector<node> v;
    seg(ll n, ll* arr=NULL){
        base=1;
        while(base<n) base<<=1;
        v.resize(base<<1);
        if(arr==NULL) return;
        FOR(i,1,n) v[base+i-1].val=arr[i];
        for(ll i=base-1; i; --i){
            v[i].updt(v[i<<1],v[i<<1|1]);
        }
    }
    void lazy(ll vi,ll s,ll e){
        ll& lz=v[vi].lz;
        if(!lz) return;
        if(s!=e){
            v[vi<<1].lz=min(v[vi<<1].lz,lz);
            v[vi<<1|1].lz=min(v[vi<<1|1].lz,lz);
        }
        v[vi].val=min(v[vi].val,lz);
        lz=INF;
    }
    void updt(ll l,ll r,ll val){updt(l,r,val,1,base,1);}
    void updt(ll l,ll r,ll val,ll s,ll e,ll vi){
        if(l<=s && e<=r){
            v[vi].lz=min(v[vi].lz,val);
            lazy(vi,s,e);
            return;
        }
        lazy(vi,s,e);
        if(r<s || e<l) return;
        ll m=s+e>>1;
        updt(l,r,val,s,m,vi<<1);
        updt(l,r,val,m+1,e,vi<<1|1);
        v[vi].updt(v[vi<<1],v[vi<<1|1]);
    }
    ll query(ll l,ll r){return query(l,r,1,base,1);}
    ll query(ll l,ll r,ll s,ll e,ll vi){
        if(r<s || e<l) return 0;
        lazy(vi,s,e);
        if(l<=s && e<=r) return v[vi].val;
        ll m=s+e>>1;
        ll lval=query(l,r,s,m,vi<<1);
        ll rval=query(l,r,m+1,e,vi<<1|1);
        return lval+rval;
    }
};

int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    ll n,q;
    cin>>n>>q;
    ll tmp[n+5];
    FOR(i,1,n) tmp[i]=n;
    seg bot(n-1,tmp),right(n-1,tmp);
    ll ans=0;
    while(q--){
        ll a,b;
        cin>>a>>b;
        if(a==1){
            ll tmp=bot.query(b,b);
            ans+=tmp-2;
            right.updt(2,tmp-1,b);
        }
        else{
            ll tmp=right.query(b,b);
            ans+=tmp-2;
            bot.updt(2,tmp-1,b);
        }
    }
    cout<<(n-2)*(n-2)-ans;
    return 0;
}

