void update(int n, int v, int k) {
  n += leaf;
  tateyoko[k][n] = std::min(tateyoko[k][n], v);
  // printf("iunput tateyoko[%d][%d]=%d\n",k,n,v);
  n /= 2;
  while(n>0) {
    tateyoko[k][n] = std::min(tateyoko[k][2*n], tateyoko[k][2*n+1]);
    n /= 2;
  }
  return;
} 

int getmin(int v, int min, int max, int L, int R, int k){
  if (max<L || R<min) {
    // printf("v=%d, L=%d, R=%d, neglect\n", v, L, R);
    return 1001001001;
  } else if (min<=L && R<=max) {
    // printf("return tateyoko[%d]=%d\n",v,tateyoko[k][v]);
    return tateyoko[k][v];
  } else {
    // printf("v=%d, split. L=%d, R=%d\n", v, L, R);
    return std::min(getmin(v*2, min, max, L, (L+R)/2, k),
                    getmin(v*2+1, min, max, (L+R)/2+1, R, k));
  }
}

