struct custom_hash {
    static uint64_t splitmix64(uint64_t x) {
        // http://xorshift.di.unimi.it/splitmix64.c
        x += 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) * 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    size_t operator()(uint64_t x) const {
        static const uint64_t FIXED_RANDOM = chrono::steady_clock::now().time_since_epoch().count();
        return splitmix64(x + FIXED_RANDOM);
    }
};
inline int binexp(int a,int b,int m)
{
    if(a == 0) {
        ret 0;
    }
    int res=1;
    a%=m;
    while(b)
    {
        if(b&1)
            res=(res*1ll*a)%m;
        a=(a*1ll*a)%m;
        b>>=1;
    }
    return res;
}
inline int binmul(int a, int b, int m) {
    a %= m;
    int res = 0;
    w(b) {
        if(b & 1) {
            res = (res + a) % m;
        }
        a = (a + a) % m;
        b >>= 1;
    }
    ret res;
}
const int N = 2e5+5;
int n;
int row[4 * N], col[4 * N], lazyrow[4 * N], lazycol[4 * N];
void build(int node, int s, int e) {
    if(s == e) {
        row[node] = col[node] = n;
        lazyrow[node] = lazycol[node] = inf;
    } else {
        int mid = (s + e) >> 1, p = node << 1, q = p | 1;
        build(p, s, mid);
        build(q, mid + 1, e);
        row[node] = col[node] = n;
        lazyrow[node] = lazycol[node] = inf;
    }
}
void updateRange(int node, int start, int end, int l, int r, int val, int seg[], int lazy[])
{
    if(lazy[node] != inf)
    { 
        seg[node] = min(seg[node], lazy[node]);    
        if(start != end)
        {
            lazy[node*2] = min(lazy[node * 2], lazy[node]);                  
            lazy[node*2+1] = min(lazy[node * 2 + 1], lazy[node]);                
        }
        lazy[node] = inf;                                  
    }
    if(start > end or start > r or end < l)              
        return;
    if(start >= l and end <= r)
    {
        seg[node] = min(seg[node], val);
        if(start != end)
        {
            lazy[node*2] = min(lazy[node*2], val);
            lazy[node*2+1] = min(lazy[node * 2 + 1], val);
        }
        return;
    }
    int mid = (start + end) / 2;
    updateRange(node*2, start, mid, l, r, val, seg, lazy);            
    updateRange(node*2 + 1, mid + 1, end, l, r, val, seg, lazy);   
    seg[node] = min(seg[node*2], seg[node*2+1]);         
}

int queryRange(int node, int start, int end, int l, int r, int seg[], int lazy[])
{
    if(start > end or start > r or end < l)
        return inf;         
    if(lazy[node] != inf)
    { 
        seg[node] = min(seg[node], lazy[node]);    
        if(start != end)
        {
            lazy[node*2] = min(lazy[node * 2], lazy[node]);                  
            lazy[node*2+1] = min(lazy[node * 2 + 1], lazy[node]);                
        }
        lazy[node] = inf;                                  
    }
    if(start >= l and end <= r)             
        return seg[node];
    int mid = (start + end) / 2;
    int p1 = queryRange(node*2, start, mid, l, r, seg, lazy);         
    int p2 = queryRange(node*2 + 1, mid + 1, end, l, r, seg, lazy); 
 //   cout << p1 << " " << p2 << " " << start << " " << mid << " " << end << "\n";
    return min(p1, p2);
}
void solve() {
    int q;
    cin >> n >> q;
    int ans = (n - 2) * (n - 2);
    build(1, 1, n);
    w(q--) {
        int t, x;
        cin >> t >> x;
        if(t == 1) {
            int e = queryRange(1, 1, n, x, x, row, lazyrow);
            ans -= e - 2;
          //  cout << e << "\n";
            updateRange(1, 1, n, 2, e - 1, x, col, lazycol);
        } else {
            int e = queryRange(1, 1, n, x, x, col, lazycol);
            ans -= e - 2;
        //    cout << e << "\n";
            updateRange(1, 1, n, 2, e - 1, x, row, lazyrow);
        }
    }
    cout << ans << "\n";
}
