// segment tree for minimum
class segtree
{
public:
    vi a,seg,lazy;
    segtree(ll n)
    {
        a.resize(200005,n);
        seg.resize(800005);
        lazy.resize(800005);
    }
    void build(ll n,ll l,ll r)
    {
        if(l==r)
        {
            seg[n]=a[l];
            return;
        }
        ll m=(l+r)>>1;
        build(2*n,l,m);
        build(2*n+1,m+1,r);
        seg[n]=min(seg[2*n],seg[2*n+1]);
    }
    void push(ll n)
    {
        if(lazy[n]!=0)
        {
            if(lazy[2*n]==0)
                lazy[2*n]=lazy[n];
            else
                lazy[2*n]=min(lazy[2*n],lazy[n]);
            if(lazy[2*n+1]==0)
                lazy[2*n+1]=lazy[n];
            else
                lazy[2*n+1]=min(lazy[2*n+1],lazy[n]);
            seg[2*n]=min(seg[2*n],lazy[n]);
            seg[2*n+1]=min(seg[2*n+1],lazy[n]);
            lazy[n]=0;
        }
    }
    void update(ll n,ll l,ll r,ll low,ll high,ll val)
    {
        if(l>high||low>r)
            return;
        if(low<=l&&r<=high)
        {
            seg[n]=min(seg[n],val);
            if(lazy[n]==0)
                lazy[n]=val;
            else
            {
                lazy[n]=min(lazy[n],val);
            }
            return;
        }
        push(n);
        ll mid=(l+r)>>1;
        update(2*n,l,mid,low,high,val);
        update(2*n+1,mid+1,r,low,high,val);
        seg[n]=min(seg[2*n],seg[2*n+1]);
    }
    ll query(ll n,ll l,ll r,ll idx)
    {
        if(l==r)
            return seg[n];
        ll mid=(l+r)>>1;
        push(n);
        if(idx<=mid)
            return query(2*n,l,mid,idx);
        else
            return query(2*n+1,mid+1,r,idx);
    }
};
void solve()
{
    ll n,q;
    cin>>n>>q;
    segtree segx(n),segy(n);
    segx.build(1,1,n);
    segy.build(1,1,n);
    ll ans=2*n-1;
    ll total=(n-2)*(n-2)+2*n-1+q;
    while(q--)
    {
        ll x,y;
        cin>>x>>y;
        if(x==1)
        {
            ll z=segy.query(1,1,n,y)-1;
            ans+=z;
            segx.update(1,1,n,1,z,y);
        }
        else
        {
            ll z=segx.query(1,1,n,y)-1;
            ans+=z;
            segy.update(1,1,n,1,z,y);
        }
    }
    cout<<total-ans<<endl;
}
