#define ll long long
ll s[2][800001], l[2][800001];
void upd(ll t, ll id, ll v){
	l[t][id] = min(l[t][id], v);
	s[t][id] = min(s[t][id], v);
}
void prop(ll t, ll id){
	upd(t, id * 2, l[t][id]);
	upd(t, id * 2 + 1, l[t][id]);
	l[t][id] = 2147483647;
}
ll query(ll t, ll id, ll l, ll r, ll p){
	if (l == r) return s[t][id];
	prop(t, id);
	ll mid = (l + r) / 2;
	if (p <= mid) return query(t, id * 2, l, mid, p);
	return query(t, id * 2 + 1, mid + 1, r, p);
}
void update(ll t, ll id, ll l, ll r, ll L, ll R, ll v){
	if (r < L || R < l) return;
	if (L <= l && r <= R){
		upd(t, id, v);
		return;
	}
	prop(t, id);
	ll mid = (l + r) / 2;
	update(t, id * 2, l, mid, L, R, v);
	update(t, id * 2 + 1, mid + 1, r, L, R, v);
	s[t][id] = min(s[t][id * 2], s[t][id * 2 + 1]);
}
int main(){
	ll n, q, a, b, ans = 0;
	cin >> n >> q, n--;
	for (int i = 0; i <= n * 4; i++){
		s[0][i] = s[1][i] = n - 1;
		l[0][i] = l[1][i] = 2147483647;
	}
	for (int i = 0; i < q; i++){
		cin >> a >> b, b--;
		if (a == 1){
			ll temp = query(1, 1, 0, n - 1, b);
			ans += temp;
			update(0, 1, 0, n - 1, 1, temp, b - 1);
			update(1, 1, 0, n - 1, b, b, 0);
		}else{
			ll temp = query(0, 1, 0, n - 1, b);
			ans += temp;
			update(1, 1, 0, n - 1, 1, temp, b - 1);
			update(0, 1, 0, n - 1, b, b, 0);
		}
	}
	printf("%lld\n", (n - 1) * (n - 1) - ans);
}

