template<typename T>
struct LazySegmentTree{//区間更新,区間最小,0オリジン
    private:
        int n;
        vector<T>node,lazy;
        vector<bool>flag;
        const T inf=numeric_limits<T>::max();

    public:
        LazySegmentTree(vector<T>v){
            int sz=(int)v.size();//vをinfで初期化して渡すこと
            n=1;
            while(n<sz)n*=2;
            node.resize(2*n-1);
            lazy.resize(2*n-1,inf);
            flag.resize(2*n-1,false);

            for(int i=0;i<sz;i++)node[i+n-1]=v[i];
            for(int i=n-2;i>=0;--i)node[i]=min(node[2*i+1],node[2*i+2]);
        }

        //k番目のノードについて遅延評価
        void eval(int k,int l,int r){
            //遅延配列が空でなければ値の伝播が起こる
            if(flag[k]){
                node[k]=lazy[k];

                if(r-l>1){//最下段かどうかの確認
                    lazy[2*k+1]=lazy[2*k+2]=lazy[k];
                    flag[2*k+2]=true,flag[2*k+1]=true;
                }

                flag[k]=0;
            }
        }

        void update(int a,int b,T x,int k=0,int l=0,int r=-1){
            if(r<0)r=n;

            //k番目のノードに遅延評価
            eval(k,l,r);

            //範囲外
            if(b<=l||r<=a)return;

            //完全に被覆しているなら遅延配列に代入した後に評価
            if(a<=l&&r<=b){
                lazy[k]=x;
                flag[k]=true;
                eval(k,l,r);
            }

            //それ以外なら子ノードを再帰的に計算
            else{
                update(a,b,x,2*k+1,l,(l+r)/2);
                update(a,b,x,2*k+2,(l+r)/2,r);
                node[k]=min(node[2*k+1],node[2*k+2]);
            }
        }

        T getval(int a,int b,int k=0,int l=0,int r=-1){//区間和の取得
            if(r<0)r=n;

            eval(k,l,r);

            if(b<=l||r<=a)return inf;
            if(a<=l&&r<=b)return node[k];
            T vall=getval(a,b,2*k+1,l,(l+r)/2);
            T valr=getval(a,b,2*k+2,(l+r)/2,r);
            return min(vall,valr);
        }
};


void solve(){
	ll n,t;
	cin>>n>>t;
	vector<ll>v(n-2,n-2);
	LazySegmentTree<ll>row(v),clm(v);
	ll ans=(n-2)*(n-2);
	while(t--){
		ll q,x;
		cin>>q>>x;
		x-=2;
		if(q==1){
			ll val=clm.getval(x,x+1);
			ans-=val;
			if(row.getval(0,1)>x)row.update(0,val,x);
			clm.update(x,x+1,0);
		}
		else{
			ll val=row.getval(x,x+1);
			ans-=val;
			if(clm.getval(0,1)>x)clm.update(0,val,x);
			row.update(x,x+1,0);
		}
		// rep(i,n-2){
		// 	cout<<"row"<<row.getval(i,i+1)<<"\n";
		// 	cout<<"column"<<clm.getval(i,i+1)<<"\n";
		// }
		// cout<<"\n";
	}
	cout<<ans;
}


int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

