const ll INF=0x3f3f3f3f;

struct node{
    ll mn,tg;
};
ll n,q;
//node seg1[MAXn * 4],seg2[MAXn * 4];
void build(ll id,ll l,ll r,node *seg){
    if (l == r-1) {
        seg[id].mn = n-1;
        seg[id].tg = -1;
        return;
    }
    ll mid = (l+r)>>1;
    build(id*2+1,l,mid,seg);
    build(id*2+2,mid,r,seg);
    seg[id].mn = min(seg[id*2+1].mn,seg[id*2+2].mn);
    debug(seg[id].mn,l,r);
}
void push(ll id,node *seg){
    if (seg[id].tg == -1) return;
    if (seg[id*2+1].tg == -1) seg[id*2+1].tg = seg[id].tg;
    else seg[id*2+1].tg = min(seg[id*2+1].tg,seg[id].tg);
    if (seg[id*2+2].tg == -1) seg[id*2+2].tg = seg[id].tg;
    else seg[id*2+2].tg = min(seg[id*2+2].tg,seg[id].tg);
    seg[id].mn = seg[id].tg;
    seg[id].tg = -1;
}
void ins(ll id,ll L,ll R,ll l,ll r,ll val,node *seg){
    debug(L,R);
    if (L == l && R == r) {
        if (seg[id].tg == -1) seg[id].tg = val;
        else seg[id].tg = min(seg[id].tg,val);
        return;
    }
    push(id,seg);
    ll mid = (L+R)>>1;
    if (l >= mid) ins(id*2+2,mid,R,l,r,val,seg);
    else if (r <= mid) ins(id*2+1,L,mid,l,r,val,seg);
    else {
        ins(id*2+1,L,mid,l,mid,val,seg);
        ins(id*2+2,mid,R,mid,r,val,seg);
    }
}
ll qr(ll id,ll L,ll R,ll l,ll r,node *seg){
    debug(L,R);
    if (L == l && R == r) {
        if (seg[id].tg == -1) return seg[id].mn;
        return seg[id].tg;
    }
    push(id,seg);
    ll mid = (L+R)>>1;
    if (l >= mid) return qr(id*2+2,mid,R,l,r,seg);
    else if (r <= mid) return qr(id*2+1,L,mid,l,r,seg);
    else {
        return min(qr(id*2+1,L,mid,l,mid,seg),qr(id*2+2,mid,R,mid,r,seg));
    }
}
ll seg1[MAXn*2],seg2[MAXn*2];
void build(ll *zkw){
	for (int i=n-1; i>0; i--) {
		zkw[i] = min(zkw[i<<1],zkw[i<<1|1]);
	}
}

void modify(int l,int r, ll value, ll *zkw) {
    for (l += n, r += n; l < r;l>>=1, r>>=1) {
        if (l&1) zkw[l] = min(zkw[l],value),l++;
        if (r&1) r--,zkw[r] = min(zkw[r],value);
    }
}

int query(int p,ll *zkw) {
    ll res = INF;
    for (p += n; p > 0; p >>= 1) res = min(res,zkw[p]);
    return res;
}
