class Beats{
    const ll inf=LLONG_MAX;
    vector<ll> mx,smx,mxc,mi,smi,mic,sum,lazy;
    int sz;
    // smx[k]<x<mx[k]の部分の更新
    void update_node_max(int k,ll x){
        sum[k]+=(x-mx[k])*mxc[k];
        if(mx[k]==mi[k]) mx[k]=x,mi[k]=x;
        else if(mx[k]==smi[k]) mx[k]=x,smi[k]=x;
        else mx[k]=x;
    }
    void update_node_min(int k,ll x){
        sum[k]+=(x-mi[k])*mic[k];
        if(mx[k]==mi[k]) mx[k]=x,mi[k]=x;
        else if(smx[k]==mi[k]) smx[k]=x,mi[k]=x;
        else mi[k]=x;
    }
    void update_node_add(int k,ll len,ll x){
        mx[k]+=x;
        if(smx[k]!=-inf)smx[k]+=x;
        mi[k]+=x;
        if(smi[k]!=inf) smi[k]+=x;
        sum[k]+=x*len;
        lazy[k]+=x;
    }
    // 遅延分を処理，node-kは今の値，子は古い値かもしれない
    void push(int k,ll len){
        if(k>=sz) return ;
        if(lazy[k]!=0){
            update_node_add(2*k,len/2,lazy[k]);
            update_node_add(2*k+1,len/2,lazy[k]);
            lazy[k]=0;
        }
        // 子が古い値なら更新．ここがポイント
        if(mx[2*k]>mx[k])  update_node_max(2*k,mx[k]);
        if(mx[2*k+1]>mx[k])update_node_max(2*k+1,mx[k]);
        if(mi[2*k]<mi[k])  update_node_min(2*k,mi[k]);
        if(mi[2*k+1]<mi[k])update_node_min(2*k+1,mi[k]);
    }
    // 子からnode-kの更新
    void update(int k){
        sum[k]=sum[2*k]+sum[2*k+1];
        if(mx[2*k]<mx[2*k+1]){
            mx[k]=mx[2*k+1];mxc[k]=mxc[2*k+1];
            smx[k]=max(mx[2*k],smx[2*k+1]);
        }else if(mx[2*k]>mx[2*k+1]){
            mx[k]=mx[2*k];mxc[k]=mxc[2*k];
            smx[k]=max(smx[2*k],mx[2*k+1]);
        }else{
            mx[k]=mx[2*k];mxc[k]=mxc[2*k]+mxc[2*k+1];
            smx[k]=max(smx[2*k],smx[2*k+1]);
        }
        if(mi[2*k]<mi[2*k+1]){
            mi[k]=mi[2*k];mic[k]=mic[2*k];
            smi[k]=min(smi[2*k],mi[2*k+1]);
        }else if(mi[2*k]>mi[2*k+1]){
            mi[k]=mi[2*k+1];mic[k]=mic[2*k+1];
            smi[k]=min(mi[2*k],smi[2*k+1]);
        }else{
            mi[k]=mi[2*k];mic[k]=mic[2*k]+mic[2*k+1];
            smi[k]=min(smi[2*k],smi[2*k+1]);
        }
    }

    public:
    ll operator[](const int &k){
        return sum[k+sz];
    }
    Beats(int n){
        sz=1;
        while(sz<n)sz<<=1;
        mx.resize(2*sz);smx.resize(2*sz,-inf);mxc.resize(2*sz,1);
        mi.resize(2*sz);smi.resize(2*sz,inf);mic.resize(2*sz,1);
        sum.resize(2*sz);lazy.resize(2*sz);
    }
    void set(int k,ll x){
        mx[k+sz]=x;mi[k+sz]=x;sum[k+sz]=x;
    }
    void build(){
        for(int i=sz-1;i;i--) update(i);
    }
    // [a,b)を更新，[l,r)探索区間，k-node
    void update_min(int a,int b,ll x,int k=1,int l=0,int r=-1){
        if(r==-1) r=sz;
        if(r<=a or b<=l or mx[k]<=x) return ;
        if(a<=l and r<=b and smx[k]<x){
            update_node_max(k,x);
            return ;
        }
        push(k,r-l);
        update_min(a,b,x,2*k,l,(l+r)/2);
        update_min(a,b,x,2*k+1,(l+r)/2,r);
        update(k);
    }
    void update_max(int a,int b,ll x,int k=1,int l=0,int r=-1){
        if(r==-1) r=sz;
        if(r<=a or b<=l or mi[k]>=x) return ;
        if(a<=l and r<=b and smi[k]>x){
            update_node_min(k,x);
            return ;
        }
        push(k,r-l);
        update_max(a,b,x,2*k,l,(l+r)/2);
        update_max(a,b,x,2*k+1,(l+r)/2,r);
        update(k);
    }
    void update_add(int a,int b,ll x,int k=1,int l=0,int r=-1){
        if(r==-1) r=sz;
        if(r<=a or b<=l) return ;
        if(a<=l and r<=b){
            update_node_add(k,r-l,x);
            return ;
        }
        push(k,r-l);
        update_add(a,b,x,2*k,l,(l+r)/2);
        update_add(a,b,x,2*k+1,(l+r)/2,r);
        update(k);
    }
    ll query_sum(int a,int b,int k=1,int l=0,int r=-1){
        if(r==-1)r=sz;
        if(r<=a or b<=l)return 0;
        if(a<=l and r<=b) return sum[k];
        push(k,r-l);
        ll lsum=query_sum(a,b,2*k,l,(l+r)/2);
        ll rsum=query_sum(a,b,2*k+1,(l+r)/2,r);
        return lsum+rsum;
    }
};


