using namespace std;
const int maxn = 2e5 + 5;

int tree1[maxn << 2], tree2[maxn << 2];
int n, q;

void init(int id, int l, int r) {
    if (l == r) {
        tree1[id] = tree2[id] = n;
        return;
    }
    int mid = (l + r) >> 1;
    init(id << 1, l, mid);
    init(id << 1 | 1, mid + 1, r);
    tree1[id] = tree2[id] = INT_MAX;
}


int query(int id, int l, int r, int v, int *tree) {
//    printf("%d %d %d\n", l, r, tree[id]);
    if (l == r) {
        return tree[id];
    }
    if (tree[id] != INT_MAX) {
        tree[id << 1] = min(tree[id], tree[id << 1]);
        tree[id << 1 | 1] = min(tree[id], tree[id << 1 | 1]);
        tree[id] = INT_MAX;
    }
    int mid = (l + r) >> 1;
    if (v <= mid) return query(id << 1, l, mid, v, tree);
    else return query(id << 1 | 1, mid + 1, r, v, tree);
}

void up(int id, int l, int r, int tl, int tr, int val, int *tree) {
    if (l == tl && r == tr) {
        tree[id] = min(tree[id], val);
        return;
    }
    if (tree[id] != INT_MAX) {
        tree[id << 1] = min(tree[id], tree[id << 1]);
        tree[id << 1 | 1] = min(tree[id], tree[id << 1 | 1]);
        tree[id] = INT_MAX;
    }
    int mid = (l + r) >> 1;
    if (tr <= mid) {
        up(id << 1, l, mid, tl, tr, val, tree);
    } else if (tl > mid) {
        up(id << 1 | 1, mid + 1, r, tl, tr, val, tree);
    } else {
        up(id << 1, l, mid, tl, mid, val, tree);
        up(id << 1 | 1, mid + 1, r, mid + 1, tr, val, tree);
    }
}

int main() {
    scanf("%d%d", &n, &q);
    init(1, 1, n);
    long long ans = 1LL * (n - 2) * (n - 2);
    for (int i = 0; i < q; i++) {
        int op, x;
        scanf("%d%d", &op, &x);
//        if(x==1) continue;
        if (op == 1) {
            int v = query(1, 1, n, x, tree1);
            ans -= (v - 2);
            up(1, 1, n, 1, v - 1, x, tree2);
        } else {
            int v = query(1, 1, n, x, tree2);
            ans -= (v - 2);
            up(1, 1, n, 1, v - 1, x, tree1);
        }
//        printf("%lld\n", ans);
    }
    printf("%lld\n", ans);
    return 0;
}

