int main() {
    int64_t N, Q;
    cin >> N >> Q;

    vector<int64_t> op(Q), pos(Q);
    for (int64_t i = 0; i < Q; i++) {
        cin >> op[i] >> pos[i];
        pos[i]--;
    }

    //i回目のクエリより前に現れた最小の値
    vector<int64_t> min_y_before(Q, N - 1), min_x_before(Q, N - 1);
    for (int64_t i = 0; i < Q - 1; i++) {
        if (op[i] == 1) {
            min_y_before[i + 1] = min_y_before[i];
            min_x_before[i + 1] = min(min_x_before[i], pos[i]);
        } else {
            min_y_before[i + 1] = min(min_y_before[i], pos[i]);
            min_x_before[i + 1] = min_x_before[i];
        }
    }

    //valueより小さく、1番最初に出たクエリを知りたい
    struct Query {
        Query(int64_t i, int64_t v) : index(i), value(v) {}
        int64_t index, value;
        bool operator<(const Query& rhs) const {
            return value < rhs.value;
        }
    };
    vector<Query> x_queries, y_queries;
    for (int64_t i = 0; i < Q; i++) {
        if (op[i] == 1) {
            x_queries.emplace_back(i, pos[i]);
        } else {
            y_queries.emplace_back(i, pos[i]);
        }
    }
    sort(x_queries.begin(), x_queries.end());
    sort(y_queries.begin(), y_queries.end());

    vector<int64_t> interceptor(Q);
    int64_t x_min_index = N, y_min_index = N;
    for (const Query& q : x_queries) {
        interceptor[q.index] = x_min_index;
        x_min_index = min(x_min_index, q.index);
    }

    for (const Query& q : y_queries) {
        interceptor[q.index] = y_min_index;
        y_min_index = min(y_min_index, q.index);
    }

    int64_t ans = (N - 2) * (N - 2);
    for (int64_t i = 0; i < Q; i++) {
        //inより前に出ている一番小さい値を求める
        int64_t in = interceptor[i];

        if (op[i] == 1) {
            int64_t m = min_y_before[min(in, i)];
            ans -= max(m - 1, (int64_t)0);
        } else {
            int64_t m = min_x_before[min(in, i)];
            ans -= max(m - 1, (int64_t)0);
        }
    }

    assert(ans >= 0);
    cout << ans << endl;
}

