class SegmentTree {
public:
	vi tree, lazy;
	SegmentTree(int n, int in) {
		tree = vi(n * 4 + 9, in), lazy = vi(n * 4 + 9);
	}
	void unlockLazy(int segIdx, int startNode, int endNode) {
		if (!lazy[segIdx])
			return;
		if (startNode == endNode) {
			tree[segIdx] = min(tree[segIdx], lazy[segIdx]);
			return;
		}
		int l = segIdx << 1, r = l | 1;
		lazy[l] = (lazy[l] == 0 || lazy[l] > lazy[segIdx] ? lazy[segIdx] : lazy[l]);
		lazy[r] = (lazy[r] == 0 || lazy[r] > lazy[segIdx] ? lazy[segIdx] : lazy[r]);
		lazy[segIdx] = 0;
	}
	void update(int segIdx, int startNode, int endNode, int s, int e, int val) {
		unlockLazy(segIdx, startNode, endNode);
		if (e < startNode || s > endNode)
			return;
		if (s <= startNode && e >= endNode) {
			lazy[segIdx] = val;
			unlockLazy(segIdx, startNode, endNode);
			return;
		}
		int mid = startNode + (endNode - startNode) / 2;
		int l = segIdx << 1, r = l | 1;
		update(l, startNode, mid, s, e, val);
		update(r, mid + 1, endNode, s, e, val);
	}
	int query(int segIdx, int startNode, int endNode, int idx) {
		unlockLazy(segIdx, startNode, endNode);
		if (startNode == endNode)
			return tree[segIdx];
		int mid = startNode + (endNode - startNode) / 2;
		int l = segIdx << 1, r = l | 1;
		if (idx <= mid)
			return query(l, startNode, mid, idx);
		else
			return query(r, mid + 1, endNode, idx);
	}
};
int main() {
	file();
	fast();
	int n, q; cin >> n >> q;
	SegmentTree row = SegmentTree(n, n);
	SegmentTree col = SegmentTree(n, n);
	ll ans = (n - 2LL) * (n - 2LL);
	while (q--) {
		int type, x; cin >> type >> x;
		if (type == 1) {
			int gt = col.query(1, 1, n, x);
			ans -= (gt - 2LL);
			row.update(1, 1, n, 1, gt, x);
		}
		else {
			int gt = row.query(1, 1, n, x);
			ans -= (gt - 2LL);
			col.update(1, 1, n, 1, gt, x);
		}
	}
	cout << ans << endl;
	return 0;
}

