void myupdate_tree(vector<long long int>& mytree, int index, int l, int r, int target_l, int target_r, long long int val) {
    if (r < target_l || target_r < l) return;
    if (l == r && l >= target_l && r <= target_r) {
        mytree[index] = min(val, mytree[index]);
        return;
    }
    if (l >= target_l && r <= target_r) {
        mytree[index] = min(val, mytree[index]);
        return;
    }

    int m = (l + r) / 2;
    myupdate_tree(mytree, index * 2 + 1, l, m, target_l, target_r, val);
    myupdate_tree(mytree, index * 2 + 2, m + 1, r, target_l, target_r, val);
    // mytree[index] = min(val, min(mytree[index * 2 + 1], mytree[index * 2 + 2]));   
}

long long int myquery_tree(vector<long long int>& mytree, int index, int l, int r, int target_l, int target_r) {
    if (r < target_l || l > target_r) return 0x3f3f3f3f;
    if (l >= target_l && r <= target_r) return mytree[index];

    int m = (l + r) / 2;
    long long int res = min(myquery_tree(mytree, index * 2 + 1, l, m, target_l, target_r), myquery_tree(mytree, index * 2 + 2, m + 1, r, target_l, target_r));    
    res = min(res, mytree[index]);
    return res;
}

int main() {
    int n, q;
    cin >> n >> q;
    long long int nn = n - 2;
    long long int res = nn * nn;

    vector<long long int> v1(4 * nn, nn), v2(4 * nn, nn);
    for (int i = 0; i < q; i++) {
        int t, x;
        cin >> t >> x;
        x -= 2;
        int index = 0;
        if (t == 1) {
            index = myquery_tree(v1, 0, 0, nn - 1, x, x);

            res -= index;
            if (index > 0) {
                myupdate_tree(v2, 0, 0, nn - 1, 0, index - 1, x);
            }

        } else {
            index = myquery_tree(v2, 0, 0, nn - 1, x, x);

            res -= index;
            if (index > 0) {
                myupdate_tree(v1, 0, 0, nn - 1, 0, index - 1, x);
            }
        }
    }
    cout << res << endl;
}

