typedef long long ll;
struct FenwickTree {
	int n; // [1, n]
	vector<int> bit;
	FenwickTree(int n) : n(n), bit(n+1, 1<<30) {}
	int sum(int i) {
		int s = 1<<30;
		while (i > 0) {
			s = min(s, bit[i]);
			i -= i&-i;
		}
		return s;
	}
	void add(int i, int x) {
		while (i <= n) {
			bit[i] = min(bit[i], x);
			i += i&-i;
		}
	}
};
int main() {
	ll N, Q;
	cin >> N >> Q;
	FenwickTree a(N-1), b(N-1);
	a.add(1, N-2);
	b.add(1, N-2);
	ll r = 0;
	for (int i = 0; i < Q; ++ i) {
		int t, x;
		cin >> t >> x;
		x -= 2;
		if (t == 1) {
			int y = a.sum(N-1-x);
			r += y;
			b.add(N-1-y, x);
		} else {
			int y = b.sum(N-1-x);
			r += y;
			a.add(N-1-y, x);
		}
	}
	cout << (N-2)*(N-2) - r << endl;
}

