class Segment_Tree {
public:
	vector<long long int>v;
	int num;
	long long int ret;
	long long int Update(int place) {
		if (place >= v.size() / 2) {
			return v[place];
		}
		v[place] = min(Update(place * 2), Update(place * 2 + 1));
		return v[place];
	}
	Segment_Tree(int n) {
		n++;
		num = 1;
		while (num < n * 2) {
			num *= 2;
		}
		v.resize(num, N-1);
	}
	int Get(int place) {
		ret = N - 1;
		place += v.size() / 2;
		while (place) {
			ret = min(ret, v[place]);
			place /= 2;
		}
		return ret;
	}
	void TopDown() {
		Update(1);
	}
	void Modify(int a, int b,long long int c) {
		b++;
		for (a += num / 2, b += num / 2; a < b; a >>= 1, b >>= 1) {
			if (a & 1) {
				v[a] = min(v[a], c);
				a++;
			}
			if (b & 1) {
				b--;
				v[b] = min(v[b], c);
			}
		}
	}
};

