using namespace std;

const int N=2e5+5;
int val[2][N*2],tag[2][N*2];
int lson[N*2],rson[N*2];
int n,q,m;
long long ans;

void chmin(int &x,int y){
	x=min(x,y);
}

int cmin(int tp,int pos){
	return min(tag[tp][pos],val[tp][pos]);
}

void update(int tp,int pos){
	val[tp][pos]=min(cmin(tp,lson[pos]),cmin(tp,rson[pos]));
}

int query(int tp,int pos,int x,int y,int l,int r){
	if(x>=l&&y<=r) return cmin(tp,pos);
	if(x>r||y<l) return n;
	int mid=(x+y)>>1;
	int q=min(query(tp,lson[pos],x,mid,l,r),query(tp,rson[pos],mid+1,y,l,r));
	update(tp,pos);
	return min(q,tag[tp][pos]);
}

void modify(int tp,int pos,int x,int y,int l,int r,int v){
	if(x>=l&&y<=r){
		chmin(tag[tp][pos],v);
		return;
	}
	if(x>r||y<l) return;
	int mid=(x+y)>>1;
	modify(tp,lson[pos],x,mid,l,r,v);
	modify(tp,rson[pos],mid+1,y,l,r,v);
	update(tp,pos);
}

void build(int pos,int x,int y){
	if(x==y) return;
	int mid=(x+y)>>1;
	lson[pos]=++m;
	rson[pos]=++m;
	build(lson[pos],x,mid);
	build(rson[pos],mid+1,y);
}

int main(){
	scanf("%d%d",&n,&q);
	ans=1ll*(n-2)*(n-2);
	for(int i=0;i<2;i++) for(int j=0;j<N*2;j++) val[i][j]=tag[i][j]=n;
	m=1;build(1,1,n);
	for(int i=1;i<=q;i++){
		int o,x;
		scanf("%d%d",&o,&x);
		o--;
		int res=query(o,1,1,n,x,x);
		ans-=res-2;
//		printf("%d:%d\n",i,res);
		modify(o^1,1,1,n,1,res,x);
	}
	printf("%lld\n",ans);
	return 0;
}

