void build(ll node, ll curr_l, ll curr_r)
{
	if(curr_l == curr_r) segtree[node] = a[curr_r]; 
	else
	{
		ll mid = (curr_l + curr_r) >> 1;
		build(2 * node + 1, curr_l, mid);
		build(2 * node + 2, mid + 1, curr_r);
		segtree[node] = combine(segtree[2 * node + 1], segtree[2 * node + 2]);
	}
}

// To add val to range [l .. r]
void range_update(ll node, ll curr_l, ll curr_r, ll update_l, ll update_r, ll val)
{
	if(lazy[node] != 1e18)
	{
		segtree[node] = min(segtree[node], lazy[node]);
		if(curr_l != curr_r)
		{
			lazy[2 * node + 1] = min(lazy[2 * node + 1], lazy[node]);
			lazy[2 * node + 2] = min(lazy[2 * node + 2], lazy[node]);
		} 
		lazy[node] = 1e18;
	}
	if(update_l > update_r || curr_l > curr_r || curr_l > update_r || curr_r < update_l) return;
	if(curr_l >= update_l && curr_r <= update_r)
	{
		segtree[node] = min(segtree[node], val);
		if(curr_l != curr_r)
		{
			lazy[2 * node + 1] = min(lazy[2 * node + 1], val);
			lazy[2 * node + 2] = min(lazy[2 * node + 2], val);
		} 
		return;
	}
	ll mid = (curr_l + curr_r) >> 1;
	range_update(2 * node + 1, curr_l, mid, update_l, update_r, val);
	range_update(2 * node + 2, mid + 1, curr_r, update_l, update_r, val);
	segtree[node] = combine(segtree[2 * node + 1], segtree[2 * node + 2]);
}

ll query(ll node, ll curr_l, ll curr_r, ll query_l, ll query_r)
{
	if(query_l > query_r || curr_l > curr_r || curr_l > query_r || curr_r < query_l) return 1e18;
	if(lazy[node] != 1e18)
	{
		segtree[node] = min(segtree[node], lazy[node]);
		if(curr_l != curr_r)
		{
			lazy[2 * node + 1] = min(lazy[2 * node + 1], lazy[node]);
			lazy[2 * node + 2] = min(lazy[2 * node + 2], lazy[node]);
		}  
		lazy[node] = 1e18;
	}
	if(curr_l >= query_l && curr_r <= query_r) return segtree[node];
	else
	{
		ll mid = (curr_l + curr_r) >> 1;
		ll left_value = query(2 * node + 1, curr_l, mid, query_l, min(query_r, curr_r)); 
		ll right_value = query(2 * node + 2, mid + 1, curr_r, max(query_l, curr_l), query_r);
		return combine(left_value, right_value);
	}
}

