using ll = long long;
constexpr int MAX_N = 200000;
int cnt[2][MAX_N+2] = {};

void cnt_init(){
    for(int i=0; i<2; ++i){
        for(int j=0; j<=MAX_N; ++j){
            cnt[i][j]=-1;
        }
    }
}

int main()
{
    ll n, q;
    cin >> n >> q;
    cnt_init();
    ll ans=(n-2)*(n-2);
    // 各queryで出てきたbの最小値
    // 相手のqueryの最小値-2個だけひっくり返せる
    ll min_val[2] = {n, n};
    for(int i=0; i<q; ++i){
        int a, b;
        cin >> a >> b;
        if(cnt[a-1][b] >= 0){
            ans -= cnt[a-1][b]-2;
        }else{
            ll val = min_val[2-a];
            min_val[a-1] = b;
            for(int j=b; cnt[a-1][j]<0 && j<=n; ++j)cnt[a-1][j]=val;
            ans -= val-2;
        }
    }
    cout << ans << endl;
    return 0;
}

