		return;
	}
	LL m = (l + r) >> 1;
	build(l, m, p << 1,o), build(m + 1, r, (p << 1) | 1,o);
	d[o][p] = min(d[o][p << 1] , d[o][(p << 1) | 1]);
	b[o][p]=1e9;
}
void update(LL l, LL r, LL c, LL s, LL t, LL p,int o) {
	if (l <= s && t <= r) {
		d[o][p]=min(d[o][p],c), b[o][p] = min(b[o][p],c);
		return;
	}
	LL m = (s + t) >> 1;
	if (b[o][p]!=1e9)
		d[o][p << 1] = min(d[o][p<<1],b[o][p]),d[o][(p << 1) | 1] =min(d[o][(p<<1)|1],b[o][p]),
		b[o][p << 1] = min(b[o][p<<1],b[o][p]), b[o][(p << 1) | 1] = min(b[o][(p<<1)|1],b[o][p]),
	b[o][p] = 1e9;
	if (l <= m) update(l, r, c, s, m, p << 1,o);
	if (r > m) update(l, r, c, m + 1, t, (p << 1) | 1,o);
	d[o][p] = min(d[o][p << 1] , d[o][(p << 1) | 1]);
}
LL getsum(LL l, LL r, LL s, LL t, LL p,int o) {
	if (l <= s && t <= r) return d[o][p];
	LL m = (s + t) >> 1;
	if (b[o][p]!=1e9)
		d[o][p << 1]=min(d[o][p<<1],b[o][p]),d[o][(p << 1) | 1] =min(d[o][(p<<1)|1],b[o][p]),
		b[o][p << 1] = min(b[o][p<<1],b[o][p]), b[o][(p << 1) | 1] = min(b[o][(p<<1)|1],b[o][p]),
	b[o][p] = 1e9;
	LL sum = 1000000000;
	if (l <= m) sum = getsum(l, r, s, m, p << 1,o);
	if (r > m) sum = min(getsum(l, r, m + 1, t, (p << 1) | 1,o),sum);
	return sum;
}
