const ll inf = 2e18;
const int mod = 1e9 + 7;
const int N = 2e5 + 10;

int n, t[4*N][2], lazy[4*N][2];

void build(int v, int tl, int tr, int i) {
	if (tl == tr) {
		t[v][i] = n;
	} else {
		int tm = (tl + tr) / 2;
		build(v*2, tl, tm, i);
		build(v*2+1, tm+1, tr, i);
		t[v][i] = min(t[v*2][i], t[v*2+1][i]);
	}
}

void push(int v, int i) {
	if(lazy[v][i] != inf) {
		t[v*2][i] = min(t[v*2][i], lazy[v][i]);
		lazy[v*2][i] = min(lazy[v*2][i], lazy[v][i]);
		t[v*2+1][i] = min(t[v*2+1][i], lazy[v][i]);
		lazy[v*2+1][i] = min(lazy[v*2+1][i], lazy[v][i]);
		lazy[v][i] = inf;
	}
}

void update(int v, int tl, int tr, int l, int r, int addend, int i) {
	if (l > r) 
		return;
	if (l == tl && tr == r) {
		t[v][i] = min(t[v][i], addend);
		lazy[v][i] = min({lazy[v][i], addend});
	} else {
		push(v, i);
		int tm = (tl + tr) / 2;
		update(v*2, tl, tm, l, min(r, tm), addend, i);
		update(v*2+1, tm+1, tr, max(l, tm+1), r, addend, i);
		t[v][i] = min(t[v*2][i], t[v*2+1][i]);
	}
}

int query(int v, int tl, int tr, int l, int r, int i) {
	if (l > r)
		return inf;
	if (l <= tl && tr <= r)
		return t[v][i];
	push(v, i);
	int tm = (tl + tr) / 2;
	return min(query(v*2, tl, tm, l, min(r, tm), i), query(v*2+1, tm+1, tr, max(l, tm+1), r, i));
}

signed main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

	int q;
	cin >> n >> q;
	build(1, 2, n - 1, 0);
	build(1, 2, n - 1, 1);
	for(int i = 0; i < 4*N; i++) {
		lazy[i][0] = inf;
		lazy[i][1] = inf;
	}
	int ans = (n - 2) * (n - 2);
