		if(a == 1) {
			int mn = query(1, 2, n - 1, b, b, 0);
			ans -= (mn - 2);
			if(mn > 2) {
				update(1, 2, n - 1, 2, mn - 1, b, 1);
			}
		}
		else {
			int mn = query(1, 2, n - 1, b, b, 1);
			ans -= (mn - 2);
			if(mn > 2) {
				update(1, 2, n - 1, 2, mn - 1, b, 0);
			}
		}
	}
	cout << ans;

	return 0;
}

