void solve() {
    ll n, q;
    cin >> n >> q;
    vec aa(n+10, 0);

    aa[n-1] = INF;
    ll ans = (n - 2) * (n - 2);
    segtree<ll, op, e> seg1(aa), seg2(aa);
    for(int i=0;i<q;i++){
        ll a, b;
        cin >> a >> target;
        target--;
        ll res = 0;
        if (a == 1) {
            ll idx = seg2.max_right<f>(1ll);
            seg1.set(target, idx);
            res = idx;
        } else {
            ll idx = seg1.max_right<f>(1ll);
            seg2.set(target, idx);
            res = idx;
        }
        ll reduce = res - 1;
        ans -= reduce;
    }

    p(ans);
    return;
}

