long long int modulo(long long int a,long long  int b, long long int n){

    if(b==0)
        return 1;
    long long int  x=1, y=a%n; 


    while (b > 0) {
        if (b%2 == 1) {
            x = (x*y) % n; // multiplying with base
        }
        y = (y*y) % n; // squaring the base
        b /= 2;
    }
    return x % n;
}


