map<int, int> vert, horz;
int vert_min, horz_min;
int query(const map<int, int> &m, int x) {
    auto it = m.lower_bound(x);
    if (it != m.end() && it->first == x)
        return it->second;
    --it;
    return it->second;
}
int main() {
    int N, Q; fin, N, Q;
    vert[1] = N - 2;
    horz[1] = N - 2;
    vert_min = N;
    horz_min = N;
    int64_t ans = 1LL * (N - 2) * (N - 2);
    while (Q--) {
        int ty, x; fin, ty, x;
        if (ty == 1) {
            int q = query(vert, x); 
            ans -= q;
            if (x < vert_min) {
                horz[1 + q + 1] = horz[1];
                horz[1] = x - 2;
                vert_min = x;
            }
        pr_debug("v remove %d\n", q);
