            for (auto kv: horz) {
                pr_debug("horz %d = %d\n", kv.first, kv.second);
            }
            int q = query(horz, x); 
            ans -= q;
            if (x < horz_min) {
                vert[1 + q + 1] = vert[1];
                vert[1] = x - 2;
                horz_min = x;
            }
        pr_debug("h remove %d\n", q);
        }
    }
    fout, ans, '\n';
    return 0;
}

