template <typename T,typename E>
struct LazySegmentTree{
  using F = function<T(T,T)>;
  using G = function<T(T,E,int)>;
  using H = function<E(E,E)>;
  F f;
  G g;
  H h;
  T ti;
  E ei;
  int _n, size, log;
  vector<T> dat;
  vector<E> laz;
  vector<int> len;
  LazySegmentTree(F f,G g,H h,T ti,E ei):
    f(f),g(g),h(h),ti(ti),ei(ei){}
  void apply(int k) {dat[k] = f(dat[2*k], dat[2*k+1]);}
  void all_apply(int k, E e) {
    dat[k] = g(dat[k],e,len[MSB(k)]);
    if (k < size) laz[k] = h(laz[k],e);
  }
  void push(int k) {
    all_apply(2 * k, laz[k]);
    all_apply(2 * k + 1, laz[k]);
    laz[k] = ei;
  }

  void init(){
    log = MSB(_n)+1;
    size = 1 << log;
    dat.assign(2*size,ti);
    laz.assign(2*size,ei);
    len.assign(log,1);
    RREP(i,log-1) len[i] = len[i+1]*2;
  }

  void build(const vector<T> &v){
    _n=v.size();
    init();
    for (int i = 0; i < _n; i++) dat[size + i] = v[i];
    for (int i = size - 1; i >= 1; i--) apply(i);
  }

  void set(int p, T x) {
    assert(0 <= p && p < _n);
    p += size;
    for (int i = log; i >= 1; i--) push(p >> i);
    dat[p] = x;
    for (int i = 1; i <= log; i++) apply(p >> i);
  }

  void update(int p, E e) {
    assert(0 <= p && p < _n);
    p += size;
    for (int i = log; i >= 1; i--) push(p >> i);
    dat[p] = g(dat[p],e,len[MSB(p)]);
    for (int i = 1; i <= log; i++) apply(p >> i);
  }
  void update(int l, int r, E e) {
    assert(0 <= l && l <= r && r <= _n);
    if (l == r) return;

    l += size; r += size;

    for (int i = log; i >= 1; i--) {
      if (((l >> i) << i) != l) push(l >> i);
      if (((r >> i) << i) != r) push((r - 1) >> i);
    }

    int l2 = l, r2 = r;
    while (l < r) {
      if (l & 1) all_apply(l++, e);
      if (r & 1) all_apply(--r, e);
      l >>= 1;
      r >>= 1;
    }
    l = l2; r = r2;

    for (int i = 1; i <= log; i++) {
      if (((l >> i) << i) != l) apply(l >> i);
      if (((r >> i) << i) != r) apply((r - 1) >> i);
    }
  }

  T get(int p) {
      assert(0 <= p && p < _n);
      p += size;
      for (int i = log; i >= 1; i--) push(p >> i);
      return dat[p];
  }

  T query(int l, int r) {
    assert(0 <= l && l <= r && r <= _n);
    if (l == r) return ti;
    l += size; r += size;
    for (int i = log; i >= 1; i--) {
      if (((l >> i) << i) != l) push(l >> i);
      if (((r >> i) << i) != r) push(r >> i);
    }

    T sml = ti, smr = ti;
    while (l < r) {
      if (l & 1) sml = f(sml, dat[l++]);
      if (r & 1) smr = f(dat[--r], smr);
      l >>= 1;
      r >>= 1;
    }

    return f(sml, smr);
  }


  template<typename C> int max_right(int l, C check) {
    assert(0 <= l && l <= _n);
    if (l == _n) return _n;
    l += size;
    for (int i = log; i >= 1; i--) push(l >> i);
    T sm = ti;
    do {
      while (l % 2 == 0) l >>= 1;
      if (!check(f(sm, dat[l]))) {
        while (l < size) {
          push(l);
          l = (2 * l);
          if (check(f(sm, dat[l]))) {
            sm = f(sm, dat[l]);
            l++;
          }
        }
        return l - size;
      }
      sm = f(sm, dat[l]);
      l++;
    } while ((l & -l) != l);
    return _n;
    }

  template <class C> int min_left(int r, C check) {
    assert(0 <= r && r <= _n);
    if (r == 0) return 0;
    r += size;
    for (int i = log; i >= 1; i--) push((r - 1) >> i);
    T sm = ti;
    do {
      r--;
      while (r > 1 && (r % 2)) r >>= 1;
      if (!check(f(dat[r], sm))) {
        while (r < size) {
          push(r);
          r = (2 * r + 1);
          if (check(f(dat[r], sm))) {
            sm = f(dat[r], sm);
            r--;
          }
        }
        return r + 1 - size;
      }
      sm = f(dat[r], sm);
    } while ((r & -r) != r);
    return 0;
  }
};

