void solve(){
  int N,Q;
  cin >> N >> Q;

  int ans = (N-2)*(N-2);

  auto f = [](int a, int b){return min(a,b);};
  auto g = [](int a, int b, int len){return min(a,b);};
  LazySegmentTree<int,int> x(f,g,f,INF,INF),y(f,g,f,INF,INF);
  x.build(vec(N,N-1)); y.build(vec(N,N-1));

  REP(_,Q){
    int t,v;
    cin >> t >> v; v--;
    if(t==1){
      int u = x.get(v); ans -= u-1;
      y.update(0,u,v);
    }
    else{
      int u = y.get(v); ans -= u-1;
      x.update(0,u,v);      
    }
  }

  cout << ans << endl;
}

signed main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int T = 1;
  // cin >> T;

  while(T--) solve();

  return 0;
}

