    LazySegmentTree<ll> row_tree(
        n+1, LINF, n, 
        [](ll a, ll b) { return min(a, b); }, 
        [](ll a, ll b) { return min(a, b); }, 
        [](ll a, ll b) { return min(a, b); }
    );
    LazySegmentTree<ll> column_tree(
        n+1, LINF, n, 
        [](ll a, ll b) { return min(a, b); }, 
        [](ll a, ll b) { return min(a, b); }, 
        [](ll a, ll b) { return min(a, b); }
    );
    ll ans = ll(n-2) * ll(n-2);

    int query, x;
    for(int i=0;i<q;++i) {
        cin >> query >> x;
        ll y = 2LL;
        if(query == 1) {
            y = column_tree.find(x, x+1);
            row_tree.update(2, y, x);
        } else {
            y = row_tree.find(x, x+1);
            column_tree.update(2, y, x);
        }
        ans -= y - 2LL;
    }

    cout << ans << endl;

}

