struct RMQ {
    int N, aN;
    vector<int> V;
    void init(int n) {
        aN = n;
        N = 1; while (N < n) N *= 2;
        V.assign(N * 2, aN);
    }
    void upd(int p,int v) {
        p += N; V[p] = min(V[p], v);
        while (p >= 1) {
            p /= 2;
            V[p] = min(V[p * 2], V[p * 2 + 1]);
        }
    }
    int query(int l, int r, int a = 0, int b = 0, int i = -1) {
        if (i == -1) { a = 0; b = N; i = 1; }
        if (r <= a || b <= l) return aN;
        if (l <= a && b <= r) return V[i];
        int q1 = query(l, r, a, (a + b) / 2, i * 2);
        int q2 = query(l, r, (a + b) / 2, b, i * 2 + 1);
        return min(q1, q2);
    }
    int find(int v, int w = 1000000000, int a = 0, int b = 0, int i = -1) {
        if (i == -1) { a = 0; b = N; i = 1; }
        if (!(V[i] <= v)) return aN;
        if (b - a == 1) return a;
        int x = find(v, w, a, (a + b) / 2, i * 2);
        if (x != aN) return x;
        return find(v, min(w, V[i * 2]), (a + b) / 2, b, i * 2 + 1);
    }
};

int main() {
    int N, Q; cin >> N >> Q; N -= 2;
    RMQ X, Y;
    X.init(N); Y.init(N);
    LL ans = LL(N) * N;
    while (Q--) {
        int c, x; cin >> c >> x; x -= 2; x = N - 1 - x;
        if (c == 1) {
            int p = X.query(0, x + 1);
            ans -= p;
            Y.upd(N - p, N - 1 - x);
        }
        if (c == 2) {
            int p = Y.query(0, x + 1);
            ans -= p;
            X.upd(N - p, N - 1 - x);
        }
    }
    cout << ans << endl;
    return 0;
}

