#include <bits/stdc++.h>
using namespace std;
const int maxN = 2e5 + 5;
const int BIG = 2e9;

struct SegmentTree {
    int n;
    vector<int> tree;
    vector<int> lazy;

    SegmentTree() {}
    SegmentTree(int _n) {
        n = _n;
        tree.resize(4 * (n + 2) + 5, BIG);
        lazy.resize(4 * (n + 2) + 5, BIG);
    }

    void propagate(int id, int l, int r) {
        tree[id] = min(tree[id], lazy[id]);

        if(l != r) {
            lazy[id * 2] = min(lazy[id * 2], lazy[id]);
            lazy[id * 2 + 1] = min(lazy[id * 2 + 1], lazy[id]);
        }

        lazy[id] = BIG;
    }

    void update(int id, int l, int r, int L, int R, int val) {
        propagate(id, l, r);

        if(L <= l && r <= R) {
            lazy[id] = min(lazy[id], val);
            propagate(id, l, r);
            return;
        }

        if(r < L || l > R)
            return;

        int mid = (l + r) / 2;
        update(id * 2, l, mid, L, R, val);
        update(id * 2 + 1, mid + 1, r, L, R, val);

        tree[id] = min(tree[id * 2], tree[id * 2 + 1]);
    }

    int getMin(int id, int l, int r, int L, int R) {
        propagate(id, l, r);
        if(L <= l && r <= R)
            return tree[id];

        if(r < L || l > R)
            return BIG;

        int mid = (l + r) / 2;

        return min(getMin(id * 2, l, mid, L, R),
                   getMin(id * 2 + 1, mid + 1, r, L, R));
    }

    void update(int l, int r, int val) {
        update(1, 0, n + 1, l, r, val);
    }

    int getMin(int l, int r) {
        return getMin(1, 0, n + 1, l, r);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;  cin >> n;
    SegmentTree row(n), col(n);

    for(int i = 1; i <= n - 1; i++) {
        row.update(i, i, n);
        col.update(i, i, n);
    }

    int64_t blackCnt = (int64_t)(n - 2) * (n - 2);

    int q;  cin >> q;

    while(q--) {
        int tp, x;  cin >> tp >> x;
        if(tp == 1) {
            int to = col.getMin(x, x);
            if(2 <= to - 1) {
                blackCnt -= (int64_t)(to - 1 - 2 + 1);
                row.update(1, to - 1, x);
            }
        } else {
            int to = row.getMin(x, x);
            if(2 <= to - 1) {
                blackCnt -= (int64_t)(to - 1 - 2 + 1);
                col.update(1, to - 1, x);
            }
        }
        //cerr << blackCnt << '\n';
    }

    cout << blackCnt << '\n';

    return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

struct Node{
    int left, right;
    bool lazy;
    int k;
}nodes[2][800000];

void build(int tp, int u, int l, int r, int n){
    nodes[tp][u].left = l;
    nodes[tp][u].right = r;
    nodes[tp][u].k = n;
    nodes[tp][u].lazy = false;
    if(l == r){
        return;
    }
    build(tp, u << 1, l, (l + r) >> 1, n);
    build(tp, (u << 1) + 1, ((l + r) >> 1) + 1, r, n);
    return;
}

int query(int tp, int u, int x){
    if(!nodes[tp][u].lazy)
        return nodes[tp][u].k;
    if(x <= nodes[tp][u << 1].right)
        return query(tp, u << 1, x);
    else
        return query(tp, (u << 1) + 1, x);
}

void modify(int tp, int u, int l, int r, int k){
    if(nodes[tp][u].left == l && nodes[tp][u].right == r && !nodes[tp][u].lazy){
        if(k < nodes[tp][u].k)
            nodes[tp][u].k = k;
        return;
    }
    nodes[tp][u].lazy = true;
    if(r <= nodes[tp][u << 1].right)
        modify(tp, u << 1, l, r, k);
    else if(l >= nodes[tp][(u << 1) + 1].left)
        modify(tp, (u << 1) + 1, l, r, k);
    else{
        modify(tp, u << 1, l, nodes[tp][u << 1].right, k);
        modify(tp, (u << 1) + 1, nodes[tp][(u << 1) + 1].left, r, k);
    }
}


void solve(){
    int n, q;
    cin >> n >> q;
    build(0, 1, 1, n, n);
    build(1, 1, 1, n, n);
    long long ans = (n - 2) * 1ll * (n - 2);
    while(q--){
        int t, x;
        cin >> t >> x;
        int m = query(t - 1, 1, x);
        if(m <= 2)
            continue;
        ans -= m * 1ll - 2;
        modify(2 - t, 1, 2, m - 1, x);
    }
    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int T = 1;
    //cin >> T;
    while(T--){
        solve();
    }
    return 0;
}

