const int inf = 1e9;

void se(int i, int x) {
	i += Q;
	st[i] = x;
	i >>= 1;
	while (i > 0) {
		st[i] = min(st[2 * i], st[2 * i + 1]);
		i >>= 1;
	}
}

int ge(int r) {
	r += Q;
	int res = inf;
	for (int l = Q; l < r; l >>= 1, r >>= 1) {
		if (l & 1) {
			res = min(res, st[l++]);
		}
		if (r & 1) {
			res = min(res, st[--r]);
		}
	}
	return res;
}

