void update(vector<int> &tree,int a,int b,int x,int i,int left,int right){
  if(b<=left||right<=a){
    return;
  }
  if(a<=left&&right<=b){
    tree[i]=min(x,tree[i]);
    return;
  }
  update(tree,a,b,x,2*i+1,left,(left+right)/2);
  update(tree,a,b,x,2*i+2,(left+right)/2,right);
}

