struct FenwickTreeMin {
    vector<ll> bit;
    ll n;

    FenwickTreeMin(ll n) {
        this->n = n;
        bit.assign(n, INF);
    }

    FenwickTreeMin(vector<ll> a) : FenwickTreeMin(a.size()) {
        for (size_t i = 0; i < a.size(); i++)
            update(i, a[i]);
    }

    ll getmin(ll r) {
        ll ret = INF;
        for (; r >= 0; r = (r & (r + 1)) - 1)
            ret = min(ret, bit[r]);
        return ret;
    }

    void update(ll idx, ll val) {
        for (; idx < n; idx = idx | (idx + 1))
            bit[idx] = min(bit[idx], val);
    }
};

