struct Segmenttree {
	static const int N = 1 << 18;
	vector<ll>seg;
	vector<ll>idx;
	void st(ll p, ll v) {
		p += N - 1;
		seg[p] = v;
		idx[p] = p - N + 1;
		while (p > 0) {
			p = (p - 1) / 2;
			seg[p] = max(seg[2 * p + 1], seg[2 * p + 2]);
			if (seg[2 * p + 1] < seg[2 * p + 2])idx[p] = idx[2 * p + 2];
			else if (seg[2 * p + 1] > seg[2 * p + 2])idx[p] = idx[2 * p + 1];
			else idx[p] = min(idx[2 * p + 1], idx[2 * p + 2]);
		}
	}
	pair<ll, ll> query(ll l, ll r, ll a, ll b, ll k) {
		if (r <= a || b <= l)return { -inf,inf };
		if (l <= a && b <= r)return { seg[k],idx[k] };
		ll m = (a + b) / 2;
		auto p1 = query(l, r, a, m, 2 * k + 1);
		auto p2 = query(l, r, m, b, 2 * k + 2);
		if (p1.first > p2.first) return p1;
		else if (p1.first < p2.first)return p2;
		else return { p1.first,min(p1.second,p2.second) };
	}

	void init() {
		seg.resize(2 * N);
		idx.resize(2 * N);
		for (int i = 0; i < 2 * N; i++)seg[i] = -inf;
	}
	//[l,r]
	ll get(int l, int r) {
		return query(l, r + 1, 0, N, 0).first;
	}
	ll getidx(int l, int r) {
		return query(l, r + 1, 0, N, 0).second;
	}
	pair<ll, ll>getp(int l, int r) {
		return query(l, r + 1, 0, N, 0);
	}
};


int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	Segmenttree seg1 = Segmenttree();
	Segmenttree seg2 = Segmenttree();

	ll n, q;
	cin >> n >> q;
	seg1.init(), seg2.init();

	for (int i = 0; i < n-2; i++)seg1.st(i,-1),seg2.st(i,-1);


	ll cur = (n - 2)*(n - 2);
	for (int i = 0; i < q; i++) {
		int t, x;
		cin >> t >> x;
		x -= 2;
		if (t == 1) {
			int ok = -1, ng = n - 2;
			while (ng - ok > 1) {
				int mid = (ng + ok) / 2;
				if (seg1.get(0,mid) < x)ok = mid;
				else ng = mid;
			}
			cur -= (ok + 1);
			seg2.st(x,ok);
		}
		else {
			int ok = -1, ng = n - 2;
			while (ng - ok > 1) {
				int mid = (ng + ok) / 2;
				if (seg2.get(0, mid) < x)ok = mid;
				else ng = mid;
			}
			cur -= (ok + 1);
			seg1.st(x, ok);
		}
	}
	puts(cur);

	return 0;
}

