			*/
			return min(utol(ty, a, b, 2 * k + 1, L, (L + R) / 2),
				utol(ty, a, b, 2 * k + 2, (L + R) / 2, R));
		}
	}

	if (ty == 2) {

		// not range
		if (b <= L || R <= a) {
			return 1e6;
		}

		else if (a <= L && R <= b) {
			//printf("k=%d L=%d R=%d yoko[%d]=%d\n", k, L, R, k, yoko[k]);
			return yoko[k];
		}

		else {
			return min(utol(ty, a, b, 2 * k + 1, L, (L + R) / 2),
				utol(ty, a, b, 2 * k + 2, (L + R) / 2, R));
		}
	}

}

void ltou(int ty, int a, int p) {
	if (ty == 1) {
		while (a != 0) {
			yoko[a] = min(yoko[a], p);
			a = (a - 1) / 2;
		}
		yoko[0] = min(yoko[0], p);
	}
	if (ty == 2) {
		while (a != 0) {
			tate[a] = min(tate[a], p);
			a = (a - 1) / 2;
		}
		tate[0] = min(tate[0], p);
	}
}

