const int N=2e5+5;
int pos;
struct segment
{
    int ST[4*N],lazy[4*N];
    void dolazy(int id,int l,int r)
    {
        if (lazy[id]==0)
            return;
        ST[id]=lazy[id];
        if (l!=r)
        {
            lazy[id*2]=lazy[id];
            lazy[id*2+1]=lazy[id];
        }
        lazy[id]=0;
    }

    void update(int id,int l,int r,int L,int R,int val)
    {
        dolazy(id,l,r);
        if (r<L||R<l)
            return;
        if(L<=l&&r<=R)
        {
            ST[id]=val;
            if (l!=r)
            {
                lazy[id*2]=val;
                lazy[id*2+1]=val;
            }
            return;
        }
        int mid=(l+r)/2;
        update(id*2,l,mid,L,R,val);
        update(id*2+1,mid+1,r,L,R,val);
        ST[id]=max(ST[id*2],ST[id*2+1]);
    }

    int get (int id,int l,int r,int L,int R)
    {
        dolazy(id,l,r);
        if (r<L||R<l)
            return -1e9;
        if (L<=l&&r<=R)
            return ST[id];
        int mid=(l+r)/2;
        return max (get (id*2,l,mid,L,R),get (id*2+1,mid+1,r,L,R));
    }
    void fin(int id,int l,int r,int u,int v,int val)
    {
        dolazy(id,l,r);
        if(u>r||v<l||ST[id]<=val||pos!=-1) return ;
        int mid=(l+r)/2;
        if(u<=l&&r<=v)
        {
            if(l==r)
            {
                pos=l;
                return ;
            }
        }
        fin(id*2,l,mid,u,v,val);
        fin(id*2+1,mid+1,r,u,v,val);
    }

} T[2];


