	}
}

void push(int id, int v)
{
	tree[id][v << 1] = min(tree[id][v << 1], tree[id][v]);
	tree[id][v << 1 | 1] = min(tree[id][v << 1 | 1], tree[id][v]);
}

int get(int id, int v, int tl, int tr, int p)
{
	if (tl == p && p == tr)
		return a[id][p] = min(a[id][p], tree[id][v]);
	int tm = (tl + tr) / 2;
	push(id, v);
	if (p <= tm)
		return get(id, v << 1, tl, tm, p);
	else 
		return get(id, v << 1 | 1, tm + 1, tr, p);
}

void setv(int id, int v, int val, int l, int r, int tl, int tr) 
{
	if (r < l) return;
	if (l == tl && tr == r) 
		tree[id][v] = min(tree[id][v], val);
	else
	{
		int tm = (tl + tr) / 2;
		setv(id, v << 1, val, l, min(r, tm), tl, tm);
		setv(id, v << 1 | 1, val, max(l, tm + 1), r, tm + 1, tr);
	}
}

