		if(l == r) {
			return mn[x];
		}
		int mid = l + r >> 1;
		if(p <= mid) {
			return min(mn[x], query(l, mid, x << 1, p));
		} else {
			return min(mn[x], query(mid + 1, r, x << 1 | 1, p));
		}
	}
};

