void init(int rsiz)
{

    m = 1;

    while (m < rsiz)
        m *= 2;

    node[0].resize(2 * m - 1);
    node[1].resize(2 * m - 1);

    for (int i = 0; i < 2 * m - 1; ++i)
    {
        node[0][i] = node[1][i] = INF;
    }

} //ここで初期化して

