void upd(int x, int idx, int val)
{

    idx += m - 1;

    if (node[x][idx] <= val)
        return;

    node[x][idx] = val;

    while (idx > 0)
    {
        idx = (idx - 1) / 2;
        node[x][idx] = std::min(node[x][2 * idx + 1], node[x][2 * idx + 2]);
    }
}

int get(int x, int a, int b, int k = 0, int l = 0, int r = m)
{ //上からだんだんと下へ//[a,b) [l,r)

    if (r <= a || b <= l)
        return INF; //範囲外

    if (a <= l && r <= b)
        return node[x][k]; //完全に範囲内

    //部分的に範囲内

    int lv = get(x, a, b, 2 * k + 1, l, (l + r) / 2);
    int rv = get(x, a, b, 2 * k + 2, (l + r) / 2, r);

    return std::min(lv, rv);
}

int main()
{
    ll n, q;

    std::cin >> n >> q;

    init(n);
    upd(0, n - 1, n - 1);
    upd(1, n - 1, n - 1);

    ll ans = 0;

    rep(i, q)
    {
        int x, y;
        std::cin >> x >> y;
        --y;
        --x;
        int v = get(!x, y, n);
        ans += v - 1;
        upd(x, v - 1, y);
    }

    ans = (n - 2) * (n - 2) - ans;

    std::cout << ans << std::endl;

    return 0;
}

