const int maxn=1e6+5;
struct SegmentTree{
	int n;
	std::vector<int> tree,tag;
	SegmentTree(int n):n(n),tree(n*4),tag(n*4){}
	void build(int l,int r,int p) {
		if(l==r) {tree[p]=n;return;}
		int mid=l+r>>1;
		build(l,mid,p<<1);build(mid+1,r,p<<1|1);
	}
	void cg(int p,int nx) {
		tree[p]=min(nx,tree[p]);
		if(tag[p]) tag[p]=min(nx,tag[p]);
		else tag[p]=nx;
	}
	void push_down(int p) {
		if(!tag[p]) return;
		cg(p<<1,tag[p]);
		cg(p<<1|1,tag[p]);
		tag[p]=0;
	}
	void update(int l,int r,int nx,int nl,int nr,int p) {
		if(nl>=l&&nr<=r) {cg(p,nx);return;}
		int mid=nl+nr>>1;push_down(p);
		if(l<=mid) update(l,r,nx,nl,mid,p<<1);
		if(r>mid) update(l,r,nx,mid+1,nr,p<<1|1);
	}
	ll query(int x,int nl,int nr,int p) {
		if(nl==nr) return tree[p];
		int mid=nl+nr>>1;push_down(p);
		if(x<=mid) return query(x,nl,mid,p<<1);
		return query(x,mid+1,nr,p<<1|1);
	}
};
