    		mn=col.query(x,1,n,1);
    		row.update(1,mn,x,1,n,1);
    	}
    	else {
    		mn=row.query(x,1,n,1);
    		col.update(1,mn,x,1,n,1);
    	}
		ans-=(mn-2);
    }
    cout<<ans<<endl;
    return 0;
}

