				;
			}
			lazy[ind][type] = n;
		}
	}
}

void pull(long long ind) {
	for (auto type : {0, 1}) {
		tree[ind][type] = min(tree[2 * ind][type], tree[2 * ind + 1][type]);
	}
}

void update(long long ul, long long ur, long long uval, long long l, long long r, long long ind, long long type) {
	push(l, r, ind);
	if (ur < l or r < ul) return;

	if (ul <= l and r <= ur) {
		lazy[ind][type] = uval;
		push(l, r, ind);
		return;
	}

	long long mid((l + r) >> 1);
	update(ul, ur, uval, l, mid, 2 * ind, type);
	update(ul, ur, uval, mid + 1, r, 2 * ind + 1, type);

	pull(ind);
}

long long query(long long qi, long long l, long long r, long long ind, long long type) {
	push(l, r, ind);
	if (l == r) {
		if (l == qi) return tree[ind][type];
		return INT_MAX;
	}

	long long mid((l + r) >> 1);
	if (qi <= mid) return query(qi, l, mid, 2 * ind, type);
	else return query(qi, mid + 1, r, 2 * ind + 1, type);
}

int main() {

	cin >> n >> q;

	tree.resize(4 * n + 1, vector<long long>(2, n));
	lazy.resize(4 * n + 1, vector<long long>(2, n));

	long long ans = (n - 2) * (n - 2);
	while (q--) {
		long long qt, x; cin >> qt >> x;
		if (qt == 1) {
			//place at (1,x)
			long long j = query(x, 1, n, 1, 1);
			ans -= (j - 2);
			update(2, j, x, 1, n, 1, 0);
		}
		else {
			//place at (x,1);
			long long j = query(x, 1, n, 1, 0);
			ans -= (j - 2);
			update(2, j, x, 1, n, 1, 1);
		}
	}

	cout << ans;

	return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int N = 2e6;

int x[2][N], lz[2][N];

void build(int v, int l, int r, int n) {
    if (l == r) {
        x[0][v] = x[1][v] = n;
        return;
    }
    int m = (l + r) / 2;
    build(2 * v, l, m, n);
    build(2 * v + 1, m + 1, r, n);
    x[0][v] = x[1][v] = n;
}
void push(int t, int v) {
    if (!lz[t][v]) {
        return;
    }
    x[t][v] = min(x[t][v], lz[t][v]);
    if (!lz[t][2 * v]) {
        lz[t][2 * v] = 1e9;
    }
    if (!lz[t][2 * v + 1]) {
        lz[t][2 * v + 1] = 1e9;
    }
    lz[t][2 * v] = min(lz[t][2 * v], x[t][v]);
    lz[t][2 * v + 1] = min(lz[t][2 * v + 1], x[t][v]);
    lz[t][v] = 0;
}
int find_min(int t, int v, int l, int r, int L, int R) {
    push(t, v);
    if (L <= l && r <= R) {
        return x[t][v];
    }
    if (r < L || R < l) {
        return 1e9;
    }
    int m = (l + r) / 2;
    return min(find_min(t, 2 * v, l, m, L, R),
               find_min(t, 2 * v + 1, m + 1, r, L, R));
}
void upd(int t, int v, int l, int r, int L, int R, int z) {
    if (L <= l && r <= R) {
        if (!lz[t][v] || z < lz[t][v]) {
            lz[t][v] = z;
            push(t, v);
        }
        return;
    }
    if (r < L || R < l) {
        return;
    }
    int m = (l + r) / 2;
    upd(t, 2 * v, l, m, L, R, z);
    upd(t, 2 * v + 1, m + 1, r, L, R, z);
    x[t][v] = min(x[t][2 * v], x[t][2 * v + 1]);
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    ll n, q; cin >> n >> q;
    build(1, 1, n, n);
    ll r = (ll)(n - 2) * (n - 2);
    while (q--) {
        int t, a; cin >> t >> a;
        int b = find_min(t - 1, 1, 1, n, a, a);
        r -= max(0, b - 2);
        if (b > 1) {
            upd(2 - t, 1, 1, n, 2, b, a);
        }
    }
    cout << max(0ll, r) << endl;
    return 0;
}

