struct Range {
  int l, r, d;
  Range() {}
  Range(int _l, int _r, int _d): l(_l), r(_r), d(_d) {}

  bool operator<(const Range &e) const { return r < e.r; }
};

typedef deque<Range> dr;

/* global variables */

dr hrs, vrs;

/* subroutines */

/* main */

int main() {
  int n, q;
  scanf("%d%d", &n, &q);
  n -= 2;

  hrs.push_front(Range(0, n, n));
  vrs.push_front(Range(0, n, n));
  ll sum = 0;

  while (q--) {
    int op, x;
    scanf("%d%d", &op, &x);
    x -= 2;

    if (op == 1) { // to down
      int k =
	lower_bound(hrs.begin(), hrs.end(), Range(x, x, 0)) - hrs.begin();
      if (hrs[k].d > 0) {
	sum += hrs[k].d;
	if (k == 0) {
	  if (x == hrs[0].r - 1) hrs[0].r--;
	  else {
	    hrs[0].l = x + 1;
	    hrs.push_front(Range(0, x, hrs[0].d));
	  }
	  vrs[0].d = x;
	}
      }
    }
    else { // to right
      int k =
	lower_bound(vrs.begin(), vrs.end(), Range(x, x, 0)) - vrs.begin();
      if (vrs[k].d > 0) {
	sum += vrs[k].d;
	if (k == 0) {
	  if (x == vrs[0].r - 1) vrs[0].r--;
	  else {
	    vrs[0].l = x + 1;
	    vrs.push_front(Range(0, x, vrs[0].d));
	  }
	  hrs[0].d = x;
	}
      }
    }
  }
  //printf("sum=%lld\n", sum);

  printf("%lld\n", (ll)n * n - sum);
  return 0;
}

