ll ans;
void build(int o,int l,int r){
	if(l==r){
		tr[0][o]=tr[1][o]=n;
		return;
	}
	tr[0][o]=tr[1][o]=0x7fffffff;
	int mid=(l+r)>>1;
	build(o<<1,l,mid);
	build(o<<1|1,mid+1,r);
	return;
}
void update(int o,int l,int r,int L,int R,int idx,int v){
	if(L<=l&&r<=R){
		tr[idx][o]=min(tr[idx][o],v);
		return;
	}
	int mid=(l+r)>>1;
	if(L<=mid)
		update(o<<1,l,mid,L,R,idx,v);
	if(R>mid)
		update(o<<1|1,mid+1,r,L,R,idx,v);
	return;
}
int query(int o,int l,int r,int x,int idx){
	if(l==r)
		return tr[idx][o];
	int mid=(l+r)>>1;
	if(x<=mid)
		return min(tr[idx][o],query(o<<1,l,mid,x,idx));
	return min(tr[idx][o],query(o<<1|1,mid+1,r,x,idx));
}
int main(){
	scanf("%d%d",&n,&m);
	build(1,1,n);
	now[0]=now[1]=n;
	for(int i=1;i<=m;i++){
		int opt,x;
		scanf("%d%d",&opt,&x);
		opt--;
		update(1,1,n,1,now[opt],opt^1,x);
		now[opt^1]=min(now[opt^1],x);
		update(1,1,n,x,x,opt,1);
	}
	for(int i=2;i<n;i++)
		ans+=max(query(1,1,n,i,0)-2,0)+max(query(1,1,n,i,1)-2,0);
	for(int i=2;i<n;i++){
		int tmp=query(1,1,n,i,0);
		if(tmp==1)
			break;
		ans-=tmp-2;
	}
	printf("%lld\n",ans);
	return 0;
}

