template<typename T>
struct LazySegtree {
    int n;
    T e; // default value
    vector<T> dat, lazy;
    typedef function<T(T a, T b)> Func;
    Func f;

    LazySegtree(){}
    LazySegtree(int n_input, Func f_input, T e_input) {
        initialize(n_input, f_input, e_input);
    }

    void initialize(int n_input, Func f_input, T e_input) {
        f = f_input;
        e = e_input;
        n = 1;
        while ( n<n_input ) { n<<=1; }
        dat.resize(2*n-1, e);
        lazy.resize(2*n-1, e);
    }

    // [l, r)
    void propagate(int k, int l, int r) {
        // dat[k] += (r - l) * lazy[k];
        dat[k] = f(dat[k], lazy[k]);
        if ( l+1<r ) { 
           lazy[2*k+1] = f(lazy[2*k+1], lazy[k]);
           lazy[2*k+2] = f(lazy[2*k+2], lazy[k]);
        }
        lazy[k] = n;
    }

    void update(int a, int b, T x) {
        _update(a, b, 0, 0, n, x);
    }

    // top-down
    void _update(int a, int b, int k, int l, int r, T x) {
        propagate(k, l, r);
        if ( r<=a || b<=l ) {
            return;
        }
        if ( a<=l && r<=b ) {
            lazy[k] = f(lazy[k], x);
            return;
        }
        _update(a, b, 2*k+1, l, (l+r)/2, x);
        _update(a, b, 2*k+2, (l+r)/2, r, x);
        propagate(2*k+1, l, (l+r)/2);
        propagate(2*k+2, (l+r)/2, r);
        dat[k] = f(dat[2*k+1], dat[2*k+2]);
    }

    T get(int k) {
        return query(k, k+1);
    }

    // [a, b)
    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    // [a, b)
    T _query(int a, int b, int k, int l, int r) {
        propagate(k, l, r);
        if ( r<=a || b<=l ) return e;  // not in range
        if ( a<=l && r<=b ) return dat[k]; // in range
        T vl = _query(a, b, 2*k+1, l, (l+r)/2);
        T vr = _query(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }
};
