    void init(int l, int r, int id) {
        ST[id].val = ST[id].tag = n;
        if (l == r) {
            return;
        } else {
            int m = (l + r) >> 1, lson = 2 * id + 1, rson = 2 * id + 2;
            init(l, m, lson);
            init(m+1, r, rson);
        }
    }

    void push(int l, int r, int id) {
        if (l == r) {
            ST[id].val = min(ST[id].val, ST[id].tag);
            ST[id].tag = n;
            return;
        }
        ll x = ST[id].tag, lson = 2 * id + 1, rson = 2 * id + 2;
        ST[id].tag = n;
        ST[lson].tag = min(ST[lson].tag, x);
        ST[rson].tag = min(ST[rson].tag, x);
    }

    ll query(int l, int r, int id, int pt) {
        push(l, r, id);
        if (l > pt || r < pt) return n;
        else if (l == r && l == pt) return min(ST[id].val, ST[id].tag);
        else if (l <= pt && pt <= r) {
            push(l, r, id);
            int m = (l + r) >> 1, lson = 2 * id + 1, rson = 2 * id + 2;
            return min(query(l, m, lson, pt), query(m + 1, r, rson, pt));
        }
        else {
            int m = (l + r) >> 1, lson = 2 * id + 1, rson = 2 * id + 2;
            push(l, r, id);
            return min(query(l, m, lson, pt), query(m + 1, r, rson, pt));
        }
    }

    void modify(int l, int r, int id, int xl, int xr, ll val) {
        if (l > xr || r < xl) return;
