        while(q--)
        {
            int op,x;
            cin>>op>>x;
            if(op==1)
            {
                col=min(col,x);
                res-=b.query(1,x)-2;
                a.modify(1,1,row,x);
            }
            else
            {
                row=min(row,x);
                res-=a.query(1,x)-2;
                b.modify(1,1,col,x);
            }
        }
        cout<<res<<'\n';
    }
    return 0;
}

