using namespace std;

struct RT_node {
	int val;
	bool mod;
};

const int MAX_N = 200010;
int N, Q;
int RT_size;
RT_node RT[3][MAX_N * 4];

void RT_build(int k, int p, int L, int R) {
	RT[k][p].val = N;
	if (R - L == 1) return;
	RT_build(k, p << 1, L, (L + R) / 2);
	RT_build(k, (p << 1) | 1, (L + R) / 2, R);
}

void propagate(int k, int p) {
	int l = p << 1, r = (p << 1) | 1;
	RT[k][p].mod = false;
	if (RT[k][l].val > RT[k][p].val) {
		RT[k][l].val = RT[k][p].val;
		RT[k][l].mod = true;
	}
	if (RT[k][r].val > RT[k][p].val) {
		RT[k][r].val = RT[k][p].val;
		RT[k][r].mod = true;
	}
}

void RT_update(int k, int p, int L, int R, int x, int y, int v) {
	if (x >= R || y <= L) return;
	if (L >= x && R <= y) {
		if (RT[k][p].val > v) {
			RT[k][p].val = v;
			RT[k][p].mod = true;
		}
		return;
	}

	if (RT[k][p].mod) propagate(k, p);
	RT_update(k, p << 1, L, (L + R) >> 1, x, y, v);
	RT_update(k, (p << 1) | 1, (L + R) >> 1, R, x, y, v);
}

int RT_query(int k, int p, int L, int R, int x) {
	if (x < L || x >= R) return 1000000;
	if (R - L == 1)
		return RT[k][p].val;

	if (RT[k][p].mod) propagate(k, p);
	return min(RT_query(k, p << 1, L, (L + R) >> 1, x),
			   RT_query(k, (p << 1) | 1, (L + R) >> 1, R, x));
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	cin >> N >> Q;

	RT_size = 1;
	while (RT_size <= N)
		RT_size <<= 1;
	RT_build(1, 1, 0, RT_size);
	RT_build(2, 1, 0, RT_size);

	long long ans = (long long)(N - 2) * (long long)(N - 2);
	for (int i = 0; i < Q; i++) {
		int t, x;
		cin >> t >> x;
		int res = RT_query(t, 1, 0, RT_size, x);
		ans -= max(0LL, (long long)(res - 2));
		RT_update(3 - t, 1, 0, RT_size, 1, res - 1, x);

		cout << res << "\n";
	}

	cout << ans << "\n";

	return 0;
}

