void upd(int v, int l, int r, int askl, int askr, ll val, int ind) {
	tree[v * 2 + 1][ind] = min(tree[v * 2 + 1][ind], tree[v][ind]);
	tree[v * 2 + 2][ind] = min(tree[v * 2 + 2][ind], tree[v][ind]);

	if (l >= askr || r <= askl) return;

	if (l >= askl && r <= askr) {
		tree[v][ind] = min(tree[v][ind], val);
		return;
	}

	int mid = (l + r) / 2;

	upd(v * 2 + 1, l, mid, askl, askr, val, ind);
	upd(v * 2 + 2, mid, r, askl, askr, val, ind);
}

ll get(int v, int l, int r, int askl, int askr, int ind) {
	tree[v * 2 + 1][ind] = min(tree[v * 2 + 1][ind], tree[v][ind]);
	tree[v * 2 + 2][ind] = min(tree[v * 2 + 2][ind], tree[v][ind]);

	if (l >= askr || r <= askl) return n;

	if (l >= askl && r <= askr) return tree[v][ind];

	int mid = (l + r) / 2;

	return min(get(v * 2 + 1, l, mid, askl, askr, ind), get(v * 2 + 2, mid, r, askl, askr, ind));
}
