			arr[i + n] = n, tag[i] = INF;
	}
	void upd(int p, int v) {
		if(p < n) 
			tag[p] = min(tag[p], v);
		else
			arr[p] = min(arr[p], v);
	}
	void push(int p) {
		for(int h = __lg(p); ~h; h--) {
			int i = p >> h;
			upd(i, tag[i >> 1]);
			upd(i ^ 1, tag[i >> 1]);
			tag[i >> 1] = INF;
		}
	}
	void edt(int l, int r, int v) {
		int tl = l + n, tr = r + n - 1;
		push(tl); push(tr);
		for(l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if(l & 1)
				upd(l++, v);
			if(r & 1)
				upd(--r, v);
		}
	}
	int operator[](int p) {
		push(p += n);
		return arr[p];
	}
} col, row;

