const int N = 8e5 + 10;
const int mod = 0;
struct lazy{
	int a[N];
	int lazy[N];
	const int INF = 1e9;
	void build(int id, int l, int r, int val){
		if(l > r) return;
		a[id] = val;
		lazy[id] = INF;
		if(l == r) return;
		int mid = (l + r) >> 1;
		build(2*id, l, mid, val), build(2*id + 1, mid + 1, r, val);
	}
	void push(int id, int l, int r){
		if(l == r || lazy[id] == INF) return;
		a[2 * id] = min(a[2 * id], lazy[id]);
		a[2 * id + 1]= min(a[2 * id+1], lazy[id]);
		lazy[2 * id + 1]= min(lazy[2 * id + 1], lazy[id]);
		lazy[2 * id] = min(lazy[2 * id], lazy[id]);
		lazy[id] = INF;
	}
	void update(int id, int val, int l, int r, int L, int R){
		if(R == 0) return;
		if(l > R || r < L) return;
		push(id, l, r);
		a[id] = min(a[id], val);
		if(l >= L && r <= R){
			lazy[id] = val;
			return;
		}
		update(2 * id, val, l, (l + r >> 1), L, R);
		update(2 * id + 1, val, (l + r >> 1) + 1, r, L, R);
	}
	int query(int id,int l, int r, int L, int R){
		if(R == 0) return 0;
		if(l > R || r < L) return INF;
		push(id, l, r);
		if(l >= L && r <= R) return a[id];
		int ret = min(query(2 * id, l, l + r>> 1, L, R), query(2 * id + 1, (l + r >> 1) + 1, r, L, R));
		return ret;
	}
}row, col;
int main(){
	int n, q;
	scanf("%d %d", &n, &q);
	ll ans = 1LL * (n - 2) * (n - 2);
	row.build(1, 1, n - 2, n - 2);
	col.build(1, 1, n - 2, n - 2);
	for(int i = 1; i <= q; i++){
		int x, y;
		scanf("%d %d" ,&x, &y);
		if(x == 1){
			int k = col.query(1, 1, n - 2, y - 1, y - 1);
			ans -= 1LL * k;
			row.update(1, y - 2, 1, n - 2, 1, k);
		}
		else if(x == 2){
			int k = row.query(1, 1, n-2, y - 1, y - 1);
			ans -= 1LL * k;
			col.update(1, y - 2, 1, n - 2, 1, k);
		}
	}
	printf("%lld", ans);
}

