struct SegTree {
    int sz;
    vector<int> dat;
    SegTree(int n, int INF = 1 << 30) {
        for(sz = 1; sz < n;)
            sz <<= 1;
        dat.assign(sz << 1, INF);
    }
    void update(int l, int r, int x) {
        for(l += sz, r += sz; l < r; l >>= 1, r >>= 1) {
            if(l & 1) dat[l] = min(dat[l], x), l++;
            if(r & 1) --r, dat[r] = min(dat[r], x);
        }
    }
    int get(int k) {
        k += sz;
        int res = dat[k];
        while(k >>= 1)
            res = min(res, dat[k]);
        return res;
    }
};

