struct bit {
  int n;
  vector<int> a;
  bit(int n): n(n) {
    a.resize(n + 1, n);
  }
  int rev(int i) {
    return i = n - i + 1;
  }
  void update(int i, int v) {
    i = rev(i);
    for (; i <= n; i += i & -i) {
      chmin(a[i], v);
    }
  }
  int get(int i) {
    i = rev(i);
    int v = n;
    for (; i; i -= i & -i) {
      chmin(v, a[i]);
    }
    return v;
  }
};

void Main() {
  int n, q;
  cin >> n >> q;
  bit row(n), col(n);
  int ans = (n - 2) * (n - 2);
  for (int i = 1; i <= q; i++) {
    int t, x;
    cin >> t >> x;
    if (t == 1) {
      int g = col.get(x);
      ans -= g - 2;
      row.update(g - 1, x);
    }
    else {
      int g = row.get(x);
      ans -= g - 2;
      col.update(g - 1, x);
    }
  }
  cout << ans << '\n';
}

