const ll MAX_N = 1e6 + 10;

struct SegTree {
    ll tree[4 * MAX_N], lazy[4 * MAX_N];

    void build(ll n) {
    	for(ll i = 0; i < 4 * MAX_N; i ++) {
    		lazy[i] = MAX_N;
    		tree[i] = n;
    	}
    }

    void push(ll curr, ll l, ll r) {
    	if(lazy[curr] == MAX_N) {return;}
        tree[curr] = lazy[curr];
        if(l != r) {
            lazy[curr * 2] = lazy[curr]; lazy[curr * 2 + 1] = lazy[curr];
        }
        lazy[curr] = MAX_N;
    }

    void upd(ll curr, ll l, ll r, ll ql, ll qr, ll val) {
        push(curr, l, r);
        if(ql <= l && r <= qr) {
            lazy[curr] = val;
            push(curr, l, r);
            return;
        } else if(l > qr || r < ql) {return;}
        ll m = (l + r) / 2;
        upd(curr * 2, l, m, ql, qr, val);
        upd(curr * 2 + 1, m + 1, r, ql, qr, val);
        tree[curr] = min(tree[curr * 2], tree[curr * 2 + 1]);
    }

    ll query(ll curr, ll l, ll r, ll ql, ll qr) {
        push(curr, l, r);
        if(ql <= l && r <= qr) {
            return tree[curr];
        } else if(l > qr || r < ql) {return MAX_N;}
        ll m = (l + r) / 2;
        return min(query(curr * 2, l, m, ql, qr), query(curr * 2 + 1, m + 1, r, ql, qr));
    }
};

