		if (r <= s || e <= l || l >= r)
			return;
		if (r - l > 1)
			push(v);
		if (s <= l && r <= e)
		{
			res = min(res, t[v]);
			return;
		}
		int m = (l + r) >> 1, vl = v << 1, vr = vl + 1;
		query(vl, l, m);
		query(vr, m, r);
	}
	void upd(int _s, int _e, int _val)
	{
		s = _s;
		e = _e;
		val = _val;
		upd_t(1, 0, n);
	}
	void upd_t(int v, int l, int r)
	{
		if (r <= s || e <= l || l >= r)
			return;
		if (r - l > 1)
			push(v);
		if (s <= l && r <= e)
		{
			t[v] = add[v] = val;
			return;
		}
		int m = (l + r) >> 1, vl = v << 1, vr = vl + 1;
		upd_t(vl, l, m);
		upd_t(vr, m, r);
		upd_v(v);
	}
};

