template<class M> class DualSegmentTree {
public:
	using T = typename M::value_type;
private:
	ll m;
	ll n;
	vector<T> data;

	void rec(ll l, ll r, ll node, ll node_l, ll node_r, const T& val) {
		if(node_r <= l || node_l >= r)return;
		if(node_l >= l && node_r <= r){data[node] = M::upd(data[node], val); return;}
		ll mid = (node_l + node_r) / 2;
		rec(l, r, node * 2, node_l, mid, val);
		rec(l, r, node * 2 + 1, mid, node_r,val);
	}

public:
	DualSegmentTree(vector<T> a) {
		m = a.size();
		for(n = 1; n < (ll)a.size(); n <<= 1);
		data.resize(n<<1, M::id);
		for(ll i = 0; i < (ll)a.size(); i++)data[i + n] = a[i];
	}

	void update(ll l, ll r, T val) {
		rec(l, r, 1, 0, n, val);
	}

	T get(ll index) {
		T ret = data[index += n];
		while(index /= 2) {
			ret = M::op(ret, data[index]);
		}
		return ret;
	}

	T operator[] (ll i){
		return data[i + n];
	}
};

