const long long INF = 1e18;
//const ll mod = 1000000007;
struct LazySegmentTree {
private:
    int n;
    vector<ll> node, lazy;

public:
    LazySegmentTree() {
        int sz = 201000;
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, INF);

        for(int i=0; i<sz; i++) node[i+n-1] = INF;
        for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1], node[i*2+2]);
    }
    void eval(int k, int l, int r) {
        if(lazy[k] != INF) {
            chmin(node[k], lazy[k]);
            if(r - l > 1) {
                chmin(lazy[2*k+1], lazy[k]);
                chmin(lazy[2*k+2], lazy[k]);
            }
            lazy[k] = INF;
        }
    }

    void set(int a, int b, ll x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            chmin(lazy[k], x);
            eval(k, l, r);
        }
        else {
            set(a, b, x, 2*k+1, l, (l+r)/2);
            set(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1], node[2*k+2]);
        }
    }

    ll getmin(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        eval(k, l, r);

        if(b <= l || r <= a) return INF;
        if(a <= l && r <= b) return node[k];
        ll vl = getmin(a, b, 2*k+1, l, (l+r)/2);
        ll vr = getmin(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }

};

ll N, Q, ans;
int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> N >> Q;
    LazySegmentTree row, column;
    row.set(0, N, N - 2);
    column.set(0, N, N - 2);
    for(int q = 0; q < Q; q++) {
        int t, x;
        cin >> t >> x;
        x -= 2;
        if(t == 1) {
            ll c = row.getmin(x, x + 1);
            ans += c;
            column.set(0, c, x);
        } else {
            ll c = column.getmin(x, x + 1);
            ans += c;
            row.set(0, c, x);
        }
    }
    cout << (N - 2) * (N - 2) - ans << endl;
    return 0;
}

