// zero-based numbering
template<class T> struct FenwickMin {
    vector<T> bit; int N, I;
    FenwickMin(int n, int init) : N(n), I(init) { bit.assign(n+1, init); }
    // add w to a
    void add(int a, T w) {
        for (int x = ++a; x <= N; x += x & -x) bit[x] = min(bit[x], w);
    }
    // range_min [0, a)
    T range_min(int a) {
        T ret = I;
        for (int x = a; x > 0; x -= x & -x) ret = min(ret, bit[x]);
        return ret;
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    long long N, Q; cin >> N >> Q;
    FenwickMin<long long> H(N, N-2), W(N, N-2);
    long long Ans = (N-2) * (N-2);

    auto query = [&N](long long x, auto &H, auto &W) {
        auto U = H.range_min(N-x+1);
        W.add(N-U-1, x-2);
        return U;
    };

    while (Q--) {
        int type; long long x; cin >> type >> x;
        if (type == 1) Ans -= query(x, H, W);
        else Ans -= query(x, W, H);
    }
    cout << Ans << "\n";
    return 0;
}

