map<int, int> vert, horz;
int vert_min, horz_min;
int query(const map<int, int> &m, int x) {
    auto it = m.lower_bound(x);
    if (it != m.end() && it->first == x)
        return it->second;
    --it;
    assert(it != m.end() && it->first <= x);
    return it->second;
}
int main() {
    int N, Q; // fin, N, Q;
    scanf("%d%d", &N, &Q);
    vert[2] = N - 2;
    horz[2] = N - 2;
    vert_min = N;
    horz_min = N;
    int64_t ans = 1LL * (N - 2) * (N - 2);
    while (Q--) {
        int ty, x; // fin, ty, x;
        scanf("%d%d", &ty, &x);
        if (ty == 1) {
            int q = query(vert, x); 
            ans -= q;
            if (x < vert_min) {
                assert(q == horz_min - 2);
                horz[horz_min + 1] = vert_min - 2;
                horz[2] = x - 2;
                vert_min = x;
            }
        } else {
            assert(ty == 2);
            int q = query(horz, x); 
            ans -= q;
            if (x < horz_min) {
                assert(q == vert_min - 2);
                vert[vert_min + 1] = horz_min - 2;
                vert[2] = x - 2;
                horz_min = x;
            }
        }
    }
