struct SegmentTree {
    int n;
    vector<int> left, right;
    vector<ll> dat;

    SegmentTree(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        left = right = vector<int>(2 * n - 1);
        dat = vector<ll>(2 * n - 1, N - 1);
        set_range(0, 0, n);
    }

    void set_range(int i, int l, int r) {
        left[i] = l;
        right[i] = r;
        if (i < n - 1) {
            set_range(2 * i + 1, l, (l + r) / 2);
            set_range(2 * i + 2, (l + r) / 2, r);
        }
    }

    void chmin_recur(int i, int l, int r, ll x) {
        if (left[i] == l && right[i] == r) {
            dat[i] = min(dat[i], x);
            return;
        }
        int c = (left[i] + right[i]) / 2;
        if (l < c) chmin_recur(2 * i + 1, l, min(c, r), x);
        if (c < r) chmin_recur(2 * i + 2, max(c, l), r, x);
    }

    void chmin(int l, int r, ll x) {
        chmin_recur(0, l, r, x);
    }

    ll val(int i) {
        i += n - 1;
        ll ret = dat[i];
        while (i > 0) {
            i = (i - 1) / 2;
            ret = min(ret, dat[i]);
        }
        return ret;
    }
};


int main() {
    input();
    SegmentTree w1 = SegmentTree(N);
    SegmentTree w2 = SegmentTree(N);
    ll ans = (N - 2) * (N - 2);
    for (P p : query) {
