        if (p.first == 1) {
            int v = w1.val(x - 1);
            ans -= v - 1;
            w1.chmin(x - 1, x, 0);
            w2.chmin(0, v, x - 1);
        } else {
            int v = w2.val(x - 1);
            ans -= v - 1;
            w2.chmin(x - 1, x, 0);
            w1.chmin(0, v, x - 1);
        }
    }
    cout << ans << endl;
}

