  function<int(int, int)> max_fn = [](int x, int y) {
    return max(x, y);
  };

  int n, q;
  cin >> n >> q;

  int64 ans = 0;

  SegmentTree<int> r_tree(max_fn, 0, vector<int>(n - 2, 0));
  SegmentTree<int> c_tree(max_fn, 0, vector<int>(n - 2, 0));
  for (int q_index = 0; q_index < q; q_index++) {
    int t;
    int x;
    cin >> t >> x;
    x -= 2;

    auto process_r_fn = [&] {
      int r = x;
      if (c_tree.Get(0) >= r + 1) {
        return;
      }
      if (c_tree.GetRange(0, n - 2 + 1) <= r) {
        ans += n - 2;
        r_tree.Update(r, n - 2);
        return;
      }

      auto is_upper_fn = [&](int c) -> bool {
        c_tree.GetRange(0, c + 1) >= r + 1;
      };
      int l = 0;
      int u = n - 2;
      tie(l, u) = BinarySearch(l, u, is_upper_fn);
      ans += l + 1;
      r_tree.Update(r, l + 1);
    };

    auto process_c_fn = [&] {
      int c = x;
      if (r_tree.Get(0) >= c + 1) {
        return;
      }
      if (r_tree.GetRange(0, n - 2 + 1) <= c) {
        ans += n - 2;
        c_tree.Update(c, n - 2);
        return;
      }

      auto is_upper_fn = [&](int r) -> bool {
        r_tree.GetRange(0, r + 1) >= c + 1;
      };
      int l = 0;
      int u = n - 2;
      tie(l, u) = BinarySearch(l, u, is_upper_fn);
      ans += l + 1;
      c_tree.Update(c, l + 1);
    };

    if (t == 1) {
      process_c_fn();
    } else {
      process_r_fn();
    }

    // cout << "q_index: " << q_index << " " << ans << endl;
    // cout << "r_tree: ";
