  } 
  void pushdown(int u){
    if(tag[u]!=1e9){
      tag[ls]=min(tag[ls],tag[u]);
      tag[rs]=min(tag[rs],tag[u]);
      minn[ls]=min(minn[ls],tag[u]);
      minn[rs]=min(minn[rs],tag[u]);
      tag[u]=1e9;
    }
  }
  void build(int u,int l,int r){
    tag[u]=1e9,minn[u]=n;
    if(l==r)return;
    int mid=l+r>>1;
    build(ls,l,mid),build(rs,mid+1,r);
  }
  void update(int u,int l,int r,int ql,int qr,int dlt){
    pushdown(u);
    if(ql<=l&&r<=qr){
      minn[u]=min(minn[u],dlt);
      tag[u]=min(tag[u],dlt);
      return;
    }
    pushdown(u);
    int mid=l+r>>1;
    if(ql<=mid)update(ls,l,mid,ql,qr,dlt);
    if(qr>mid)update(rs,mid+1,r,ql,qr,dlt);
    pushup(u);
