        int f, x; cin >> f >> x;
        x-=2;
        if (f == 1) {
            if (x < min1) {
                REP(i, a1[x]) {
                    chmin(a2[i], x);
                }
            }
            ret -= a1[x];
            a1[x] = 0;
        } else if (f == 2) {
            if (x < min2) {
                REP(i, a2[x]) {
                    chmin(a1[i], x);
                }
            }
            ret -= a2[x];
            a2[x] = 0;
        }
    }

    cout << std::fixed << std::setprecision(10) << ret << "\n";
}

