const int maxn = 1 << 18, inf = 1e9;
struct segt {
    int t[maxn*2], lazy[maxn*2];
    void init() {
    	fill(t, t+maxn*2, inf);
    }
    int merge(int a, int b) { return min(a, b); }
    void propagate(int s, int e, int x) {
    	if (lazy[x] and s != e) {
    		int l = lazy[x];
    		t[2*x] = min(t[2*x], l);
    		lazy[2*x] = lazy[2*x] ? min(lazy[2*x], l) : l;
    		t[2*x+1] = min(t[2*x+1], l);
    		lazy[2*x+1] = lazy[2*x+1] ? min(lazy[2*x+1], l) : l;
    		lazy[x] = 0;
    	}
    }
    void update(int s, int e, int x, int l, int r, int v) {
    	propagate(s, e, x);
    	if (l <= s and e <= r) {
    		lazy[x] = v;
    		t[x] = v;
    	} else if (l <= e and s <= r) {
    		int m = (s+e) / 2;
    		update(s, m, 2*x, l, r, v);
    		update(m+1, e, 2*x+1, l, r, v);
    		t[x] = merge(t[2*x], t[2*x+1]);
    	}
    }
    void update(int l, int r, int v) { return update(0, maxn-1, 1, l, r, v); }
    int query(int s, int e, int x, int p) {
    	propagate(s, e, x);
    	if (s == e) return t[x];
		else {
    		int m = (s+e) / 2;
    		if (p <= m) return query(s, m, 2*x, p);
    		else return query(m+1, e, 2*x+1, p);
    	}
    }
    int query(int p) { return query(0, maxn-1, 1, p); }
} tleft, tup;

// update(l, r, x) := arr[l..r] = min(arr[l..r], x)
// query(x) := x 이하가 되는 첫 위치

int N, Q;

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

	cin >> N >> Q;

	tup.init();
	tup.update(0, N-1, N);
	tup.update(N, N, 1);
	tleft.init();
	tleft.update(0, N-1, N);
	tleft.update(N, N, 1);

	lint ans = (N-2) * (lint)(N-2);
	while (Q--) {
		int t, x;

		cin >> t >> x;

		if (t == 1) { // top
			int now = tup.query(x);
			tup.update(x, x, 1);
			tleft.update(1, now-1, x);
			ans -= now-2;
		} else { // left
			int now = tleft.query(x);
			tleft.update(x, x, 1);
			tup.update(1, now-1, x);
			ans -= now-2;
		}
	}

	cout << ans << '\n';
}

