int main(){
    using namespace std;
    unsigned long N, Q;
    cin >> N >> Q;
    vector<unsigned long> sgtate(2 * N - 4, N - 2), sgyoko(2 * N - 4, N - 2);
    const auto& get = [&N](const auto& sgt, unsigned long x) -> unsigned long {
        unsigned long ret{N - 2};
        unsigned long L{x + N - 2}, R{2 * N - 4};
        while(L < R){
            if(L & 1){
                ret = min(sgt[L], ret);
                ++L;
            }
            if(R & 1){
                --R;
                ret = min(sgt[R], ret);
            }
            L >>= 1;
            R >>= 1;
        }
        return ret;
    };
    const auto& set = [&N](auto& sgt, unsigned long idx, unsigned long val){
        idx += N - 2;
        while(idx){
            sgt[idx] = min(val, sgt[idx]);
            idx >>= 1;
        }
    };
    const auto& put = [&get, &set, &sgtate, &sgyoko](const auto& sg1, auto& sg2, unsigned long x) -> unsigned long {
        unsigned long y{get(sg1, x)};
        if(y)set(sg2, y - 1, x);
        return y;
    };
    unsigned long ans{(N - 2) * (N - 2)};
    for(unsigned long i{0}, t, x; i < Q; ++i){
        cin >> t >> x;
        ans -= put(t == 1 ? sgtate : sgyoko, t == 1 ? sgyoko : sgtate, x - 2);
        cout << ans << endl;
    }
    cout << ans << endl;
}

