int sz;

void upd(vector<int>& seg, int l, int r, int val) {
    for (l+=sz, r+=sz; l<r; l/=2, r/=2) {
        if (l&1) seg[l] = min(seg[l], val), l++;
        if (r&1) --r, seg[r] = min(seg[r], val);
    }
}

int query(vector<int>& seg, int i) {
    int ans;
    for (ans=seg[i+=sz]; i/=2; ) ans = min(ans, seg[i]);
    return ans;
}


