using Int = long long;
struct SegTree {
    int N;
    vector<int> A, B;
    SegTree(int n, int init) {
        N = 1;
        while (N < n) N *= 2;
        A.resize(2 * N);
        B.resize(2 * N, INT_MAX);
        for (int i = 0; i < n; i++) {
            A[i + N] = init;
        }
        for (int n = N - 1; n > 0; n--) {
            A[n] = min(A[2*n+0], A[2*n+1]);
        }
    }
    void down(int node, int nodeL, int nodeR) {
        if (B[node] == INT_MAX) return;
        A[2*node+0] = min(A[2*node+0], B[node]);
        A[2*node+1] = min(A[2*node+1], B[node]);
        B[2*node+0] = min(B[2*node+0], B[node]);
        B[2*node+1] = min(B[2*node+1], B[node]);
        B[node] = INT_MAX;
    }
    void set_0(int L, int R, int val, int node, int nodeL, int nodeR) {
        if (R <= nodeL || nodeR <= L) return;
        if (L <= nodeL && nodeR <= R) {
            A[node] = min(A[node], val);
            B[node] = min(B[node], val);
            return;
        }
        down(node, nodeL, nodeR);
        set_0(L, R, val, 2*node+0, nodeL, (nodeL + nodeR) / 2);
        set_0(L, R, val, 2*node+1, (nodeL + nodeR) / 2, nodeR);
        A[node] = min(A[2*node+0], A[2*node+1]);
    }
    void set(int L, int R, int val) {
        set_0(L, R, val, 1, 0, N);
    }
    int minimum_0(int L, int R, int node, int nodeL, int nodeR) {
        if (R <= nodeL || nodeR <= L) return INT_MAX;
        if (L <= nodeL && nodeR <= R) return A[node];
        down(node, nodeL, nodeR);
        int ans = INT_MAX;
        ans = min(ans, minimum_0(L, R, 2*node+0, nodeL, (nodeL + nodeR) / 2));
        ans = min(ans, minimum_0(L, R, 2*node+1, (nodeL + nodeR) / 2, nodeR));
        return ans;
    }
    int minimum(int L, int R) {
        return minimum_0(L, R, 1, 0, N);
    }
    void dump() {
        for (int i = 0; i < N; i++) {
            cout << minimum(i, i+1) << ' ';
        }
        cout << endl;
    }
};
int main() {
    int N, Q; cin >> N >> Q;
    SegTree X(N + 1, N - 2), Y(N + 1, N - 2);
    X.set(0, 2, 0); X.set(N, N + 1, 0);
    Y.set(0, 2, 0); Y.set(N, N + 1, 0);
    Int ans = 0;
    while (Q--) {
        int axis, x; cin >> axis >> x;
        SegTree &A = (axis == 1 ? X : Y);
        SegTree &B = (axis == 1 ? Y : X);
        int ok = N, ng = 1;
        while (abs(ok - ng) > 1) {
            int mid = (ok + ng) / 2;
            bool b = B.minimum(2, mid + 1) <= x - 2;
            (b ? ok : ng) = mid;
        }
        ans += A.minimum(x, x+1);
        A.set(x, x+1, 0);
        B.set(2, ok, x-2);
    }
    cout << (Int)(N - 2) * (N - 2) - ans << endl;
    return 0;
}

