void solve() {
	int n; cin >> n;
	set<pii> row, col;

	col.insert(mp(n, n));
	row.insert(mp(n, n));

	int q; cin >> q;
	int ans = (n-2)*(n-2);

	while(q--) {
		int t, x;
		cin >> t >> x;
		if(t == 1) {
			auto it = row.lb(mp(x, -1));
			ans -= (it->S-2);
			col.insert(mp(it->S, x));
		}
		else {
			auto it = col.lb(mp(x, -1));
			ans -= (it->S-2);
			row.insert(mp(it->S, x));
		}
	}
	cout << ans << endl;
}

