		cin >> n >> q;
		ll ans = (ll)(n-2) * (n-2);
		set<pair<int,int>> sUp, sLeft;
		map<pair<int,int>, int> mpUp, mpLeft;
		sUp.insert(make_pair(1, n));
		mpUp[make_pair(1, n)] = n;
		sLeft.insert(make_pair(1, n));
