			if(ty == 1) {
				auto it = sUp.upper_bound(make_pair(x,n+5));
				assert(it!=sUp.begin());
				it--;
				int lim = mpUp[*it];
				ans -= lim - 2;
				// [1, lim] -> x
				auto it2 = sLeft.begin();
				int from = (*it2).first;
				int to = (*it2).second;
				int mini = mpLeft[*it2];
				if(x < mini) {
					sLeft.erase(it2);
					sLeft.insert(make_pair(1, lim));
					mpLeft[make_pair(1, lim)] = x;
					if(lim+1 <= to) {
						sLeft.insert(make_pair(lim+1, to));
						mpLeft[make_pair(lim+1, to)] = mini;
					}
				}	
			} else {
				auto it = sLeft.upper_bound(make_pair(x,n+5));
				assert(it!=sLeft.begin());
				it--;
				int lim = mpLeft[*it];
				ans -= lim - 2;
				// [1, lim] -> x
				auto it2 = sUp.begin();
				int from = (*it2).first;
