					sUp.insert(make_pair(1, lim));
					mpUp[make_pair(1, lim)] = x;
					if(lim+1 <= to) {
						sUp.insert(make_pair(lim+1, to));
						mpUp[make_pair(lim+1, to)] = mini;
					}
				}	

			}
		}
