typedef pair<ll, ll> pll;

void proc(ll x, ll h, ll& w, vector<pll>& hs, ll& ans) {
    if (x < w) {
        hs.emplace_back(x, h);
        ans += (w - x - 1) * (h - 2);
        w = x;
    } else {
        auto it = lower_bound(hs.begin(), hs.end(), pll(x, -1), [](const pll& left, const pll& right)
                              {
                                  return left.first > right.first;
                              });
        ans -= it->second - 2;
    }
}

