struct SegTree{
    int sz;
    vector<int> dat,laz;
    SegTree(int x,int v){
        sz=1;while(sz<x)sz<<=1;
        dat.resize(sz<<1,v);
        laz.resize(sz<<1,v);
    }

    void upd(int id,int l,int r,int ql,int qr,int val){
        if(qr<l||r<ql)return;
        if(ql<=l&&r<=qr){
            laz[id]=min(laz[id],val);
            dat[id]=min(dat[id],val);
            return;
        }
        laz[id<<1]=min(laz[id<<1],laz[id]);
        dat[id<<1]=min(dat[id<<1],laz[id]);
        laz[id<<1|1]=min(laz[id<<1|1],laz[id]);
        dat[id<<1|1]=min(dat[id<<1|1],laz[id]);
        upd(id<<1,l,l+r>>1,ql,qr,val);
        upd(id<<1|1,(l+r>>1)+1,r,ql,qr,val);
        dat[id]=min(dat[id<<1],dat[id<<1|1]);
    }

    int qry(int id,int l,int r,int q){
        if(q<l||r<q)return 1e9;
        if(q==l&&r==q){
            return dat[id];
        }
        laz[id<<1]=min(laz[id<<1],laz[id]);
        dat[id<<1]=min(dat[id<<1],laz[id]);
        laz[id<<1|1]=min(laz[id<<1|1],laz[id]);
        dat[id<<1|1]=min(dat[id<<1|1],laz[id]);
        return min(qry(id<<1,l,l+r>>1,q),qry(id<<1|1,(l+r>>1)+1,r,q));
    }
};

