      ans -= r-2;
      ty.set(r, min(ty.get(r), i));
    }
    else {
      int r = ty.query(i, n+1);
      ans -= r-2;
      tx.set(r, min(tx.get(r), i));
    }
  }
  cout << ans << endl;
  return 0;
}

