class Block {
 public:
  void Init(int N, int value) {
    A.assign(N, value);
  }

  void Flush() {
    if (!has_mark) {
      return;
    }

    has_mark = false;
    for (int& a : A) {
      a = min(a, mark);
    }
  }

  void Mark(int value) {
    if (!has_mark) {
      mark = value;
      has_mark = true;
    } else {
      mark = min(mark, value);
    }
  }

  void Update(int i, int value) {
    Flush();
    A[i] = min(A[i], value);
  }

  int Get(int i) const {
    if (has_mark) {
      return min(A[i], mark);
    } else {
      return A[i];
    }
  }

 private:
  vector<int> A;
  bool has_mark = false;
  int mark;
};

class Blocks {
 public:
  Blocks(int N, int value) : 
    kBlockSize(max(1, (int) sqrt(N))),
    B((N + kBlockSize - 1) / kBlockSize) {
    for (auto& b : B) {
      b.Init(kBlockSize, value);
    }
  }

  int Get(int idx) const {
    return B[idx / kBlockSize].Get(idx % kBlockSize);
  }

  void Update(int l, int r, int value) {
    int bl = l / kBlockSize;
    int br = r / kBlockSize;

    if (bl == br) {
      B[bl].Flush();
      for (int i = l % kBlockSize; i <= r % kBlockSize; ++i) {
        B[bl].Update(i, value);
      }
      return;
    }

    for (int i = l % kBlockSize; i < kBlockSize; ++i) {
      B[bl].Update(i, value);
    }
    for (int i = 0; i <= r % kBlockSize; ++i) {
      B[br].Update(i, value);
    }
    for (int i = bl + 1; i < br; ++i) {
      B[i].Mark(value);
    }
  }

 private:
  const int kBlockSize;
  vector<Block> B;
};

