template<typename T>
struct segment_tree {
    int n;
    vector<T> segtree;
    function<T(const T&,const T&)> join;
    T base = T();
    segment_tree(int n, function<T(const T&,const T&)> join, T base = T()) : n(n), join(join), base(base){
        segtree.resize(n << 1, base);
    }
    void build() {
        for (int i = n - 1; i > 0; --i) {
            segtree[i] = join(segtree[(i << 1)], segtree[(i << 1) | 1]);
        }
    }
    segment_tree(vector<T> seq, function<T(const T&,const T&)> join, T base = T()) : n(seq.size()), join(join), base(base){
        segtree.resize(n << 1, base);
        for (int i = 0; i < n; i++) {
            segtree[n + i] = seq[i];
        }
        build();
    }
    T query(int pos){
        pos += n;
        ll ans = segtree[pos];
        pos >>= 1;
        while (pos) {
            ans = join(ans, segtree[pos]);
            pos >>= 1;
        }
        return ans;
    }
    void update(int l, int r, T val) {
        l += n;
        r += n + 1;
        while (l < r) {
            if (l & 1) {
                segtree[l] = join(val, segtree[l]);
                ++l;
            }
            if (r & 1) {
                --r;
                segtree[r] = join(segtree[r], val);
            }
            l >>= 1;
            r >>= 1;
        }
    }
    void debug(){
        for(int i=0;i<n;i++){
            cout<<query(i)<<" ";
        }
        cout<<"\n";
    }
};
