int n, q;
ll st[N * 4][2], lz[N * 4][2];

void build(int nd, int cl, int cr){
	st[nd][0] = st[nd][1] = n - 2;
	lz[nd][0] = lz[nd][1] = inf;

	if(cl == cr) return;
	build(nd * 2, cl, (cl + cr) / 2);
	build(nd * 2 + 1, (cl + cr) / 2 + 1, cr);
}

void prop(int nd, int cl, int cr, int tp){
	if(lz[nd][tp] != inf){
		st[nd][tp] = min(st[nd][tp], lz[nd][tp]);
		if(cl != cr){
			lz[nd * 2][tp] = min(lz[nd * 2][tp], lz[nd][tp]);
			lz[nd * 2 + 1][tp] = min(lz[nd * 2 + 1][tp], lz[nd][tp]);
		}
		lz[nd][tp] = inf;
	}
}

void upd(int nd, int cl, int cr, int l, int r, ll v, int tp){
	prop(nd, cl, cr, tp);
	if(cr < l || r < cl) return;
	if(l <= cl && cr <= r){
		lz[nd][tp] = min(lz[nd][tp], v);
		prop(nd, cl, cr, tp);
		return;
	}

	upd(nd * 2, cl, (cl + cr) / 2, l, r, v, tp);
	upd(nd * 2 + 1, (cl + cr) / 2 + 1, cr, l, r, v, tp);
	st[nd][tp] = min(st[nd * 2][tp], st[nd * 2 + 1][tp]);
}

ll que(int nd, int cl, int cr, int l, int r, int tp){
	prop(nd, cl, cr, tp);
	if(cr < l || r < cl) return inf;
	if(l <= cl && cr <= r) return st[nd][tp];

	return min(que(nd * 2, cl, (cl + cr) / 2, l, r, tp), que(nd * 2 + 1, (cl + cr) / 2 + 1, cr, l, r, tp));
}

