void upd(ll ql,ll qr,ll val,ll l=1,ll r=n,ll pos=1)
{
  ll lc=pos<<1,rc=lc^1,mid=(l+r)>>1;
  if(lz[pos]!=infl)
  {
    st[pos]=min(lz[pos],st[pos]);
    if(l!=r)
    {
      lz[lc]=min(lz[pos],lz[lc]);
      lz[rc]=min(lz[pos],lz[rc]);
    }
    lz[pos]=infl;
  }

  if(ql>r || qr<l) return;
  else if(ql<=l && qr>=r)
  {
    st[pos]=min(val,st[pos]);
    if(l!=r)
    {
      lz[lc]=min(val,lz[lc]);
      lz[rc]=min(val,lz[rc]);
    }
    return;
  }

  upd(ql,qr,val,l,mid,lc);
  upd(ql,qr,val,mid+1,r,rc);
  st[pos]=min(st[lc],st[rc]);
}

