template <typename T>
class segment_tree {
public: //  '0' based indexing queries
#define lzy  if( lz and lazy[i] )push(i, l, r)

    int sz, lz = 0;  vector<T> segt; vector<int> lazy;
    void init(int x, int *ar) { lz = 1; sz = x; segt.assign(4 * sz, 0); lazy.assign(4 * sz, 0); build(0, sz - 1, 0,  ar); } // check it;

    T ff(T a, T b) {
        // bug(a, b);
        return max(a, b);
    }

    void push(int i, int l, int r) {          // change it

        if ( !lazy[i] ) return;
        segt[i] =  lazy[i];
        if ( l != r )
        {
            lazy[2 * i + 1] = lazy[i];
            lazy[2 * i + 2] = lazy[i];
        }
        lazy[i] = 0;
    }

    T qry(int l, int r, int i, int L, int R) {

        lzy;
        if ( r  < L or R < l )   return 0;    // change unwanted value
        if ( L <= l and r <= R)   return segt[i];
        int mid = (l + r) / 2;
        T a = qry(l, mid, 2 * i + 1, L, R), b = qry(mid + 1, r  , 2 * i + 2, L, R);
        if (lz)get(i);

        // bug(l, r, a, b);
        return ff(a, b);
    }

    void upd( int l, int r, int i, int L, int R,  int val)
    {
        lzy;
        if ( l > R or L > r ) return ;
        if ( L <= l and r <= R )
        {
            lazy[i] = val;                // change here
            push(i, l, r);
            return;
        }
        int mid = (l + r) / 2;  upd(l, mid, i * 2 + 1, L, R, val); upd(mid + 1, r, i * 2 + 2, L, R, val); get(i);

    }

    void build(int l, int r, int i, int *arr)
    {
        if (l == r)
        {
            // bug(arr[l]);
            segt[i] =  arr[l];                // change here
            return;
        }
        int mid = (l + r) / 2; build(l, mid, 2 * i + 1, arr); build(mid + 1, r, 2 * i + 2, arr); get(i);
        // bug( segt[i] );

    }

    T query(int L, int R = -1) { if (R == -1) R = L; return qry(0, sz - 1, 0, L, R); }
    void update(int val, int L, int R = -1) { if ( R == -1 ) R = L; upd(0, sz - 1, 0, L, R, val); }
    void get(int i) { segt[i] = ff(segt[2 * i + 1], segt[2 * i + 2]); }

};


