struct segtree{
	int m;
	vector<int> dat;
	segtree(int n, int init){
		for(m = 1; m < n; ++m);
		dat.assign(m * 2 - 1, init);
	}
	void update(int a, int b, int v){
		update(a, b, v, 0, 0, m);
	}
	void update(int a, int b, int v, int k, int l, int r){
		if(r <= a || b <= l){ return; }
		if(a <= l && r <= b){
			chmin(dat[k], v);
		}
		else{
			update(a, b, v, k * 2 + 1, l, (l + r) >> 1);
			update(a, b, v, k * 2 + 2, (l + r) >> 1, r);
		}
	}
	int query(int p){
		int k = 0, l = 0, r = m, ret = dat[0];
		while(k < m - 1){
			int x = (l + r) >> 1;
			if(p < x){
				k = k * 2 + 1;
				r = x;
			}
			else{
				k = k * 2 + 2;
				l = x;
			}
			chmin(ret, dat[k]);
		}
		return ret;
	}
};

