typedef long long ll;

const ll INF = 1e9;

struct segtree {
  int i, j, val, temp_val = INF;
  segtree *l, *r;
  segtree(int n, int _i, int _j) : i(_i), j(_j) {
    if (i == j) {
      val = n;
      l = r = NULL;
    } else {
      int k = (i + j) >> 1;
      l = new segtree(n, i, k);
      r = new segtree(n, k+1, j);
      val = std::min(l->val, r->val);
    }
  }
  void visit() {
    if (temp_val != INF) {
      val = std::min(val, temp_val);
      if (l) {
        l->temp_val = std::min(l->temp_val, temp_val);
        r->temp_val = std::min(l->temp_val, temp_val);
      }
      temp_val = INF;
    }
  }
  void update(int _i, int _j, int nv) {
    visit();
    if (_i <= i && j <= _j) {
      temp_val = std::min(temp_val, nv);
      visit();
    } else if (_j < i or j < _i) {
      // do nothing
    } else {
      l->update(_i, _j, nv);
      r->update(_i, _j, nv);
      val = std::min(l->val, r->val);
    }
  }
  int query(int _i, int _j) {
    visit();
    if (_i <= i and j <= _j) {
      return val;
    } else if (_j < i || j < _i) {
      return INF;
    } else {
      return std::min(l->query(_i, _j), r->query(_i, _j));
    }
  }
};

ll N, Q;

int main() {
  std::cin >> N >> Q;
  segtree *top_root = new segtree(N, 1, N);
  segtree *left_root = new segtree(N, 1, N);

  ll ans = (N-2)*(N-2);
  while (Q--) {
    int t, x; std::cin >> t >> x;
    if (t == 1) {
      int y = top_root->query(x, x);
      ans -= y-2;
      left_root->update(1, y, x);
    } else {
      int y = left_root->query(x, x);
      ans -= y-2;
      top_root->update(1, y, x);
    }
  }
  std::cout << ans << "\n";

  return 0;
}

