void solve()
{
    ll N, Q;
    in(N, Q);
    vll yoko(N, N - 2);
    vll tate(N, N - 2);
    ll ans = (N - 2) * (N - 2);
    for1 (i, Q) {
        ll t, x;
        in(t, x);
        x -= 2;
        if (t == 1) {
            for1 (y, tate[x] + 1) {
                chmin(yoko[y], x);
            }
            ans -= tate[x];
            tate[x] = 0;
        }
        else {
            for1 (y, yoko[x] + 1) {
                chmin(tate[y], x);
            }
            ans -= yoko[x];
            yoko[x] = 0;
        }
    }
    print(ans);
}
