struct LazySegTree{ 
    int n;
    vector <int> node, lazy;

    LazySegTree(vector <int> v){
        int sz = v.size();
        n = 1;
        while(n<sz) n*=2;

        node.resize(2*n-1, INF);
        lazy.resize(2*n-1, INF);

        for(int i=0; i<sz; i++) node[i+n-1] = v[i]; 
        for(int i=n-2;i>=0;i--) node[i] = min(node[i * 2 + 1], node[i * 2 + 2]);


    }

    void eval(int k,int l, int r){
        if(lazy[k] != INF){
            chmin(node[k],lazy[k]);
            if(r - l >1){
                chmin(lazy[2*k+1] , lazy[k]);
                chmin(lazy[2*k+2] , lazy[k]);
            }
            lazy[k] = INF;
        }
    }

    void minimize(int a, int b, int x, int k=0, int l=0, int r=-1) {
        //区間に足すのではなくminで更新する
        if(r < 0) r = n;
        eval(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] = x;
            eval(k, l, r);
        }
        else {
            minimize(a, b, x, 2*k+1, l, (l+r)/2);
            minimize(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1] , node[2*k+2]);    
        }
    }
    int getmin(int a, int b, int k=0, int l=0, int r=-1) {

        if(r < 0) r = n;
        if(b <= l || r <= a) return INF;
        eval(k, l, r);

        if(a <= l && r <= b) {
            //cout<<node[k]<<"+"<<endl;
            return node[k];
        }
        int vl = getmin(a, b, 2*k+1, l, (l+r)/2);
        int vr = getmin(a, b, 2*k+2, (l+r)/2, r);

        //cout<<vl<<' '<< l<<' '<<r<<endl<<vr<<'+'<<(l+r)/2<<'+'<<r<<endl;
        return min(vl, vr);
    }
};

signed main(void) { cin.tie(0); ios::sync_with_stdio(false);
    int n, q; cin>>n>>q;
    int ans = (n-2) * (n-2);
    vector <int> tmp(n-2, n-2);

    LazySegTree tate(tmp), yoko(tmp);

    rep(i, q){
        int c; cin>>c;
        if(c==1){ //横をしよう
            int x; cin>>x;
            x-=2;
            int depth = yoko.getmin(x, x+1);
            ans -= depth;
            tate.minimize(0, depth+1, x);
        }else{//縦を使用
            int y; cin>>y;
            y-=2;
            int depth = tate.getmin(y, y+1);
            ans -= depth;
            yoko.minimize(0, depth+1, y);
        }
    }
    print(ans);
}

