	ll n, q; cin >> n >> q;
	segment_tree<M::min_t<>> col(n), row(n);
	rep(i, 0, n) {
		col.update(n - 1, n-1);
		row.update(n -1, n-1);
	}
	ll res = 0;
	while (q--) {
		ll rowcol; cin >> rowcol;
		ll m; cin >> m; m--;
		if (rowcol == 1) {
			// col
			ll x = col.query(m, n);
			res += x - 1;
			row.update(x, min(m, row.query(x)));
		}
		else {
			// row
			ll x = row.query(m, n);
			res += x - 1;
			col.update(x, min(m, col.query(x)));
		}

	}
	cout << (n-2)* (n-2) - res << endl;
	return 0;
}

