const ll MOD = 1000000007;

vector<int> segh(524288, MOD), segv(524288, MOD);

void ruq(vector<int>& V, int s, int t, int v, int k = 1, int l = 0, int r = 262143) {
	if (t < l || r < s)return;
	if (s <= l && r <= t) {
		V[k] = min(V[k], v);
		return;
	}
	if (V[k] <= v)return;

	if (V[k] != MOD) {
		V[k * 2] = V[k];
		V[k * 2 + 1] = V[k];
		V[k] = MOD;
	}
	ruq(V, s, t, v, k * 2, l, (l + r) / 2);
	ruq(V, s, t, v, k * 2 + 1, (l + r) / 2 + 1, r);
}

int gets(vector<int>& V, int x) {
	x += 262144;
	int ans = V[x];
	while (x) {
		x /= 2;
		if (V[x] != MOD)ans = V[x];
	}
	return ans;
}

int main() {
	ll N, Q;
	cin >> N >> Q;
	ruq(segh, 0, N, N);
	ruq(segv, 0, N, N);
	ll x, qn, c, cnt = 0;
	for (int i = 0;i < Q;i++) {
		cin >> qn >> x;
		if (qn == 1) {
			c = gets(segh, x);
			cnt += c - 2;
			ruq(segv, 2, c - 1, x);
		}
		else {
			c = gets(segv, x);
			cnt += c - 2;
			ruq(segh, 2, c - 1, x);
		}
	}
	cout << (N - 2) * (N - 2) - cnt << endl;
}

