struct Segment_tree {
	int T[800010], lazy[800010];
	void Build(int now, int l, int r, int n) {
		lazy[now] = 0x3f3f3f3f;
		if (l == r) {
			T[now] = n - 1;
			return ;
		}
		int mid = l + r >> 1;
		Build(now << 1, l, mid, n), Build(now << 1 | 1, mid + 1, r, n);
		T[now] = min(T[now << 1], T[now << 1 | 1]);
	}
	void pushdown(int now) {
		T[now << 1] = min(T[now << 1], lazy[now]), lazy[now << 1] = min(lazy[now << 1], lazy[now]);
		T[now << 1 | 1] = min(T[now << 1 | 1], lazy[now]), lazy[now << 1 | 1] = min(lazy[now << 1 | 1], lazy[now]);
		lazy[now] = 0x3f3f3f3f;
	}
	void Update(int now, int l, int r, int L, int R, int x) {
		if (l == L && r == R) {
			T[now] = min(T[now], x);
			lazy[now] = min(lazy[now], x);
			return ;
		}
		pushdown(now);
		int mid = l + r >> 1;
		if (R <= mid) Update(now << 1, l, mid, L, R, x);
		else if (L > mid) Update(now << 1 | 1, mid + 1, r, L, R, x);
		else Update(now << 1, l, mid, L, mid, x), Update(now << 1 | 1, mid + 1, r, mid + 1, R, x);
		T[now] = min(T[now << 1], T[now << 1 | 1]);
	}
	int Query(int now, int l, int r, int pos) {
		if (l == r) return T[now];
		pushdown(now);
		int mid = l + r >> 1;
		if (pos <= mid) return Query(now << 1, l, mid, pos);
		return Query(now << 1 | 1, mid + 1, r, pos);
	}
};

Segment_tree seg1, seg2;

int main () {
	int n, q; scanf("%d%d", &n, &q);
	long long ans = 1ll * (n - 2) * (n - 2);
	seg1.Build(1, 1, n, n), seg2.Build(1, 1, n, n);
	while (q--) {
		int op, x; scanf("%d%d", &op, &x);
		if (op == 1) {
			int len = seg1.Query(1, 1, n, x);
			ans -= len - 1;
			seg2.Update(1, 1, n, 1, len, x - 1);
		} else {
			int len = seg2.Query(1, 1, n, x);
			ans -= len - 1;
			seg1.Update(1, 1, n, 1, len, x - 1);
		}
	}
	printf("%lld\n", ans);
	return 0;
}

