#include<bits/stdc++.h>
#define ll long long
using namespace std;
int N;

/*Thanks AshishGup for the below Segment Tree Implementation.*/
struct node{
    int mn;
    node():mn(N){};
};

struct SegTree
{
    int n;
    vector<node> st;
    vector<bool> cLazy;
    vector<int> lazy;

    SegTree(int _n){
        n=_n;
        st.resize(4*n + 5);
        cLazy.assign(4*n + 5, false);
        lazy.assign(4*n + 5, N);
    }

    void merge(node &cur,node &lChild,node &rChild){
        cur.mn=min(lChild.mn,rChild.mn);
    }

    int leftIndex(int i){return 2*i+1;}
    int rightIndex(int i){return 2*i+2;}

    void propagate(int index,int l,int r){
        if(l!=r){
            int lindex=leftIndex(index);
            int rindex=rightIndex(index);
            cLazy[lindex]=1;
            cLazy[rindex]=1;
            lazy[lindex]=min(lazy[index],lazy[lindex]);
            lazy[rindex]=min(lazy[index],lazy[rindex]); 
        }
        st[index].mn=min(st[index].mn,lazy[index]);
        cLazy[index]=0;
    }

    void build(int index,int l,int r){
        if(l==r){
            st[index].mn = N;
            return;
        }
        int mid=(l+r)/2;
        int lindex=leftIndex(index);
        int rindex=rightIndex(index);
        build(lindex,l,mid);
        build(rindex,mid+1,r);
        merge(st[index],st[lindex],st[rindex]);
    }

    node query(int index,int l,int r,int pos){
        if(cLazy[index])    propagate(index,l,r);
        if(l==r)            return st[index];
        int mid=(l+r)/2;
        int lindex=leftIndex(index);
        int rindex=rightIndex(index);
        if(pos<=mid)    return query(lindex,l,mid,pos);
        else            return query(rindex,mid+1,r,pos);
    }   

    node query(int pos){return query(0,0,n-1,pos);}

    void update(int index,int l,int r,int ql,int qr,int val){
        if(cLazy[index])    propagate(index,l,r);
        if(qr<l || ql>r)    return;

        if(ql<=l && r<=qr){
            cLazy[index]=1;
            lazy[index]=val;
            propagate(index,l,r);
            return;
        }
        int mid=(l+r)/2;
        int lindex=leftIndex(index);
        int rindex=rightIndex(index);

        update(lindex,l,mid,ql,qr,val);
        update(rindex,mid+1,r,ql,qr,val);
        merge(st[index],st[lindex],st[rindex]);
    }
    void update(int l,int r,int val){update(0,0,n-1,l,r,val);}
};

