void change(int k, int l, int r, int L, int x, int ovo){
	if (l == r && l == L){
		mn[k][ovo] = min(mn[k][ovo], x);
		return;
	}
	int mid = (l + r) >> 1;
	if (L <= mid){
		change(lc(k), l, mid, L, x, ovo);
	}
	else{
		change(rc(k), mid + 1, r, L, x, ovo);
	}
	pushup(k, ovo);
}

void query(int k, int l, int r, int L, int R, int ovo){
	if (L <= l && r <= R){
		ans = min(ans, mn[k][ovo]);
		return;
	}
	int mid = (l + r) >> 1;
