      sh.update(0, 0, n - 1, foo, n - 1, n - x + 1);
    }else{
      lli foo = sh.query(0, 0, n - 1, x - 1, x - 1);
      res -= max(0ll, n - foo - 1);
      sh.update(0, 0, n - 1, x, x, n);
      sv.update(0, 0, n - 1, 0, n - foo, n - x + 1);
    }
  }
  cout << res << ENDL;
  return 0;
}

