#include <bits/stdc++.h>

using namespace std;

struct SegTree{
    int NN;
    int dval;
    vector<int> seg;
    vector<int> lazy;

    void init(int n, int val){
        NN = 1;
        while (NN < n)
            NN <<= 1;

        dval = val;
        seg = vector<int>(NN * 2, val);
        lazy = vector<int>(NN * 2, 0x3f3f3f3f);
    }

    int func(int a, int b){
        return min(a, b);
    }

    void push(int u, int l, int r){
        if (lazy[u] != 0x3f3f3f3f){
            int mid = (l + r) / 2;

            seg[u * 2 + 1] = func(seg[u * 2 + 1], lazy[u]);
            seg[u * 2 + 2] = func(seg[u * 2 + 2],  lazy[u]);

            lazy[u * 2 + 1] = func(lazy[u * 2 + 1], lazy[u]);
            lazy[u * 2 + 2] = func(lazy[u * 2 + 2], lazy[u]);

            lazy[u] = 0x3f3f3f3f;
        }
    }

    void gather(int u){
        seg[u] = func(seg[u * 2 + 1], seg[u * 2 + 2]);
    }

    void update(int u, int a, int b, int l, int r, int x){
        if (b <= l || r <= a)
            return ;
        if (a <= l && r <= b){
            seg[u] = func(seg[u], x);
            lazy[u] = func(lazy[u], x);
            return ;
        }

        int mid = (l + r) / 2;
        push(u, l, r);
        update(u * 2 + 1, a, b, l, mid, x);
        update(u * 2 + 2, a, b, mid, r, x);
        gather(u);
    }

    int query(int u, int a, int b, int l, int r){
        if (b <= l || r <= a)
            return dval;
        if (a <= l && r <= b){
            return seg[u];
        }

        int mid = (l + r) / 2;
        push(u, l, r);
        int res1 = query(u * 2 + 1, a, b, l, mid);
        int res2 = query(u * 2 + 2, a, b, mid, r);
        gather(u);

        return func(res1, res2);
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    long long n, q;
    cin >> n >> q;

    SegTree col, row;
    col.init(n, n);
    row.init(n, n);
    long long ans = (n - 2) * (n - 2);
    while (q--){
        int t, x;
        cin >> t >> x;

        if (t == 1){
            int cnt = col.query(0, x - 1, x, 0, col.NN);
            ans -= cnt - 2;
            row.update(0, 0, cnt, 0, col.NN, x);
        }
        else{
            int cnt = row.query(0, x - 1, x, 0, row.NN);
            ans -= cnt - 2;
            col.update(0, 0, cnt, 0, col.NN, x);
        }
    }

    cout << ans << '\n';

    return 0;
}

