#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int Q_MAX = 200002;

int n, q;

int a1[Q_MAX], b1[Q_MAX];
int lg1;

int a2[Q_MAX], b2[Q_MAX];
int lg2;

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> q;
    n -= 2;
    lg1++;
    a1[lg1] = n + 1;
    b1[lg1] = n + 1;
    lg2++;
    a2[lg2] = n + 1;
    b2[lg2] = n + 1;
    ll ans = 1LL * n * n;
    for(int i = 1; i <= q; i++)
    {
        int op, x;
        cin >> op >> x;
        x--;
        if(op == 1)
        {
            int l = 1, r = lg2;
            while(l < r)
            {
                int mid = ((l + r + 1) >> 1);
                if(b2[mid] < x)
                    r = mid - 1;
                else
                    l = mid;
            }
            if(x < b1[lg1])
            {
                lg1++;
                a1[lg1] = a2[l] - 1;
                b1[lg1] = x;
            }
            ans -= a2[l] - 1;
        }
        else
        {
            int l = 1, r = lg1;
            while(l < r)
            {
                int mid = ((l + r + 1) >> 1);
                if(a1[mid] < x)
                    r = mid - 1;
                else
                    l = mid;
            }
            if(x < a2[lg2])
            {
                lg2++;
                a2[lg2] = x;
                b2[lg2] = b1[l] - 1;
            }
            ans -= b1[l] - 1;
        }
    }
    cout << ans << "\n";
    return 0;
}

