template<class T>
class Segtree2{
	int n;
	vector<T>dat;
	T INIT;
	function<T(T,T)>F;
public:
	Segtree2(int n_,T INIT,function<T(T,T)>F):INIT(INIT),F(F){
		n=1;while(n<n_)n<<=1;
		dat=vector<T>(2*n,INIT);
	}
	void update(int l,int r,T x){
		for(l+=n,r+=n;l<r;l>>=1,r>>=1){
			if(l&1){dat[l]=F(dat[l],x);l++;}
			if(r&1){r--;dat[r]=F(dat[r],x);}
		}
	}
	T query(int k){
		k+=n;
		T res=dat[k];
		while(k>1){
			k>>=1;
			res=F(res,dat[k]);
		}
		return res;
	}
};

