template <typename T,typename E>
struct SegmentTree{
  typedef function<T(T,T)> F;
  typedef function<T(T,E)> G;
  int n;
  F f;
  G g;
  T d1;
  E d0;
  vector<T> dat;
  SegmentTree(){};
  SegmentTree(int n_,F f,G g,T d1,
	      vector<T> v=vector<T>()):
    f(f),g(g),d1(d1){
    init(n_);
    if(n_==(int)v.size()) build(n_,v);
  }
  void init(int n_){
    n=1;
    while(n<n_) n*=2;
    dat.clear();
    dat.resize(2*n-1,d1);
  }
  void build(int n_, vector<T> v){
    for(int i=0;i<n_;i++) dat[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--)
      dat[i]=f(dat[i*2+1],dat[i*2+2]);
  }
  void update(int k,E a){
    k+=n-1;
    dat[k]=g(dat[k],a);
    while(k>0){
      k=(k-1)/2;
      dat[k]=f(dat[k*2+1],dat[k*2+2]);
    }
  }
  inline T query(int a,int b){
    T vl=d1,vr=d1;
    for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1) {
      if(l&1) vl=f(vl,dat[(l++)-1]);
      if(r&1) vr=f(dat[(--r)-1],vr);
    }
    return f(vl,vr);
  }

};
//END CUT HERE

int main(){
    int64_t n, q;
    cin >> n >> q;
    SegmentTree<int,int> A(n,
                [](int a,int b){return min(a,b);},
                [](int a,int b){return b;},
                n - 1);

    SegmentTree<int,int> B(n,
            [](int a,int b){return min(a,b);},
            [](int a,int b){return b;},
            n - 1);

    int64_t ans = (n - 2) * (n - 2);
    for (int Q = 0; Q < q; Q++){
        int a, b;
        cin >> a >> b;
        auto &C = (a == 1 ? A : B);
        auto &D = (a == 1 ? B : A);
        b--;
        int d = C.query(b, n);
        ans -= d - 1;
        if (D.query(d, d + 1) > b)
            D.update(d, b);
    }

    cout << ans << endl;
}

