using namespace std;

#define int long long
#define pii pair<int, int>
#define pb push_back
#define lc (i<<1)
#define rc (lc|1)
#define mid ((l+r)>>1)

int const N = 2e5 + 10;
int tree[4*N][2], lazy[4*N][2], row[N], col[N], n, Q;
int merge(int x, int y) { return min(x, y); }
int cnt(int l, int r){ return 1; } // 1 for RMQ

void build(int i,int l,int r, bool b){
    if(l == r){
        tree[i][b] = n;
        lazy[i][b] = n;
        return;
    }
    build(lc,l,mid,b);build(rc,mid+1,r,b);
    tree[i][b] = merge(tree[lc][b],tree[rc][b]);
    lazy[i][b] = n;
}
void propogate(int i, int l, int r, bool b) {
  if(l != r){lazy[lc][b] = min(lazy[lc][b], lazy[i][b]); lazy[rc][b] = min(lazy[rc][b], lazy[i][b]);}
  tree[i][b] = min(tree[i][b], lazy[i][b]); lazy[i][b] = min(lazy[i][b], n);
}

void update(int i, int l, int r, int ql, int qr, int val, bool b) {
  propogate(i, l, r, b);
  if(r < ql || l > qr) return;
  if(ql <= l && r <= qr)
  { lazy[i][b] = val; propogate(i, l, r, b); return; }
  update(lc, l, mid, ql, qr, val, b);
  update(rc, mid+1, r, ql, qr, val, b);
  tree[i][b] = merge(tree[lc][b], tree[rc][b]);
}

int query(int i, int l, int r, int ql, int qr, bool b) {
  propogate(i, l, r, b);
  if(r < ql || l > qr) return n; // -inf for RMQ
  if(ql <= l && r <= qr) return tree[i][b];
  int q1 = query(lc, l, mid, ql, qr, b);
  int q2 = query(rc, mid+1, r, ql, qr, b);
  return merge(q1, q2);
}


signed main() {
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);
    cin >> n >> Q;
    int ans = (n-2)*(n-2);
    build(1, 1, n, 0); build(1, 1, n, 1);
    while (Q--) {
        int t, x;
        cin >> t >> x;
        if (t == 1) {
            int min_col = query(1, 1, n, x, x, 1);
            ans -= max(0LL, (min_col - 2));
            update(1, 1, n, 1, min_col, x, 0);
        } else {
            int min_row = query(1, 1, n, x, x, 0);
            ans -= max(0LL, (min_row - 2));
            update(1, 1, n, 1, min_row, x, 1);
        }
    }
    cout << ans << endl;
    return 0;
}

