struct B {
    i64 width, length;
};

int main() {
    i64 n, q;
    in(n, q);

    pair<i64, i64> LU(n - 2, n - 2);
    map<i64, B> L, U;

    i64 ans = (n - 2) * (n - 2);

    for (int i = 0; i < q; i++) {
        int d, x;
        in(d, x);
        x-=2;

        if (d == 1) {
            if (LU.second > x) {
                ans -= LU.first;

                if (LU.second != x + 1) {
                    B tmp = {LU.second - x - 1, LU.first};
                    U[x + 1] = tmp;
                }

                LU.second = x;
            } else {
                auto [pos, target] = *prev(U.upper_bound(x));
                U.erase(pos);

                ans -= target.length;

                B part1 = {x - pos - 1, target.length};
                B part2 = {target.width - (x - pos), target.length};

                if (part1.width > 0) {
                    U[pos] = part1;
                }

                if (part2.width > 0) {
                    U[x + 1] = part2;
                }

            }
        } else {
            if (LU.first > x) {
                ans -= LU.second;

                if (LU.first != x + 1) {
                    B tmp = {LU.first - x - 1, LU.second};
                    L[x + 1] = tmp;
                }

                LU.first = x;
            } else {
                auto [pos, target] = *prev(L.upper_bound(x));
                L.erase(pos);

                ans -= target.length;

                B part1 = {x - pos - 1, target.length};
                B part2 = {target.width - (x - pos), target.length};

                if (part1.width > 0) {
                    L[pos] = part1;
                }

                if (part2.width > 0) {
                    L[x + 1] = part2;
                }
            }
        }
    }

    out(ans);
}

