using namespace std;
int Read() {
	int x = 0, f = 1; char ch = getchar();
	while(!isdigit(ch)) {if(ch == '-')  f = -1; ch = getchar();}
	while(isdigit(ch)) {x = (x << 3) + (x << 1) + ch - '0'; ch = getchar();}
	return x * f;
}
int n, q, h[800005], L[800005], covh[800005], covL[800005];
void build(int o, int l, int r) {
	if(l == r) {
		h[o] = L[o] = n;
		return ;
	}
	int mid = (l + r) >> 1;
	build(o << 1, l, mid);
	build(o << 1 | 1, mid + 1, r);
	h[o] = min(h[o << 1], h[o << 1 | 1]);
	L[o] = min(L[o << 1], L[o << 1 | 1]);
}
void pushh(int o, int x) {
	h[o] = min(h[o], x);
	if(!covh[o])  covh[o] = x;
	covh[o] = min(covh[o], x);
}
void pushl(int o, int x) {
	L[o] = min(L[o], x);
	if(!covL[o])  covL[o] = x;
	covL[o] = min(covL[o], x);
}
void pushdown(int o) {
	if(covh[o]) {
		pushh(o << 1, covh[o]); pushh(o << 1 | 1, covh[o]);
		covh[o] = 0;
	}
	if(covL[o]) {
		pushl(o << 1, covL[o]); pushl(o << 1 | 1, covL[o]);
		covL[o] = 0;
	}
}
void modify_h(int o, int l, int r, int nl, int nr, int num) {
	if(nl <= l && r <= nr) {
		pushh(o, num);
		return;
	}
	int mid = (l + r) >> 1;
	pushdown(o);
	if(nl <= mid)  modify_h(o << 1, l, mid, nl, nr, num);
	if(mid < nr)  modify_h(o << 1 | 1, mid + 1, r, nl, nr, num);
	h[o] = min(h[o << 1], h[o << 1 | 1]);
}
void modify_l(int o, int l, int r, int nl, int nr, int num) {
	if(nl <= l && r <= nr) {
		pushl(o, num);
		return ;
	}
	int mid = (l + r) >> 1;
	pushdown(o);
	if(nl <= mid)  modify_l(o << 1, l, mid, nl, nr, num);
	if(mid < nr)  modify_l(o << 1 | 1, mid + 1, r, nl, nr, num);
	L[o] = min(L[o << 1], L[o << 1 | 1]);
}
int query_h(int o, int l, int r, int pos) {
	if(l == r)  return h[o];
	int mid = (l + r) >> 1;
	pushdown(o);
	if(pos <= mid)  return query_h(o << 1, l, mid, pos);
	else  return query_h(o << 1 | 1, mid + 1, r, pos);
}
int query_l(int o, int l, int r, int pos) {
	if(l == r)  return L[o];
	int mid = (l + r) >> 1;
	pushdown(o);
	if(pos <= mid)  return query_l(o << 1, l, mid, pos);
	else  return query_l(o << 1 | 1, mid + 1, r, pos);
}
signed main() {
	n = Read(), q = Read(); int ans = (n - 2) * (n - 2);
	build(1, 1, n);
	for(int i = 1; i <= q; i++) {
		int opt = Read(), x = Read();
		if(opt == 1) {
			int mn = query_l(1, 1, n, x);
			ans -= mn - 2;
			modify_h(1, 1, n, 2, mn - 1, x);
		}
		else {
			int mn = query_h(1, 1, n, x);
			ans -= mn - 2;
			modify_l(1, 1, n, 2, mn - 1, x);
		}
	}
	cout << ans << endl;
	return 0;
}

