int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, Q;
    cin >> N >> Q;
    vector<int> kind(Q), x(Q);
    vector<vector<bool>> P(2, vector<bool>(N, false));
    for (int i = 0; i < Q; ++i) {
        cin >> kind[i] >> x[i];
        --kind[i];
        --x[i];
        P[kind[i]][x[i]] = true;
    }
    long long ans = (long long)(N - 2) * (long long)(N - 2);
    int right = N - 1, down = N - 1;
    for (int i = 0; i < Q; ++i) {
        if (P[kind[i]][x[i]]) {
            if (kind[i] == 0) {
                int new_right = x[i];
                for (int j = new_right; j < right; ++j) {
                    if (P[0][j]) {
                        P[0][j] = false;
                        // cout << 0 << " " << j << " : " << down - 1 << '\n';
                        ans -= (down - 1); // 1 ~ down - 1
                    }
                }
                right = new_right;
            } else {
                int new_down = x[i];
                for (int j = new_down; j < down; ++j) {
                    if (P[1][j]) {
                        P[1][j] = false;
                        // cout << 1 << " " << j << " : " << right - 1 << '\n';
                        ans -= (right - 1);
                    }
                }
                down = new_down;
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

