        if(l!=r)
        {
            lazy[2*i+1]=min(x,lazy[2*i+1]);
            lazy[2*i+2]=min(x,lazy[2*i+2]);
        }
        return;
    }
    int m=(l+r)/2;
    update(2*i+1,l,m,qs,qe,x);
    update(2*i+2,m+1,r,qs,qe,x);
    st[i]=min(st[2*i+1],st[2*i+2]);
