const int MAXN = (int) 2e5 + 2;
const int INF = numeric_limits<int>::max() >> 1;
const int MOD = (int) 998244353;
struct lazy_segment_tree{
  using it_type = long long;
  int32_t n;
  vector<it_type> it;
  vector<long long> lz;
  const it_type FAILED_STAGE = INF;
  void init(int _){
    n = _;
    it.resize((n << 2)|1);
    lz.resize((n << 2)|1, INF); // check init lazy
  }
  it_type merge(it_type a, it_type b){
    return min(a, b);
  }
  it_type build(int32_t u, int32_t l, int32_t r, auto &a){ // 1 indexed
    if(l == r) return it[u] = a[l];
    return it[u] = merge(build(u << 1, l, ((l + r)>>1), a), build((u << 1)|1, ((l + r)>>1) + 1, r, a)); // merge stage
  }
  void lazy(int32_t u, int32_t l, int32_t r){ // lazy 
    if(lz[u] == INF) return;
    it[u] = min(it[u], lz[u]);
    if(l != r){
      lz[u << 1] = min(lz[u << 1], lz[u]);
      lz[(u << 1)|1] = min(lz[(u << 1)|1], lz[u]);
    }
    lz[u] = INF;
  }
  void update(int32_t u, int32_t l, int32_t r, int32_t L, int32_t R, int val){
    if(R < L) return;
    lazy(u, l, r);
    if(l > R || r < L) return;
    if(L <= l && r <= R){
      lz[u] = val; // lazy update 
      lazy(u, l, r);
      return;
    }
    update(u << 1, l, ((l + r)>>1), L, R, val);
    update((u << 1)|1, ((l + r)>>1) + 1, r, L, R, val);
    it[u] = merge(it[u << 1], it[(u << 1)|1]); // merge stage
  }
  it_type get(int32_t u, int32_t l, int32_t r, int32_t L, int32_t R){
    if(l > R || r < L) return FAILED_STAGE; // check for failed stage
    lazy(u, l, r);
    if(L <= l && r <= R) return it[u];
    return merge(get(u << 1, l, ((l + r)>>1), L, R), get((u << 1)|1, ((l + r)>>1) + 1, r, L, R)); // merge stage
  }
};
