int ge(int r) {
	r += Q;
	int res = inf;
	for (int l = Q; l < r; l >>= 1, r >>= 1) {
		if (l & 1) {
			res = min(res, st[l++]);
		}
		if (r & 1) {
			res = min(res, st[--r]);
		}
	}
	return res;
}

