					tt.push_back(uu);
					se(uu.second, inf);
				}
			}
			for (auto uu : tt) {
				rows.erase(uu);
			}
			ans += rows.size();
		}
	}
	cout << (long long)(n - 2) * (n - 2) - ans;
	return 0;
}

