        {
            // cout<<index<<" "<<tree[index]<<endl;
            return tree[index];
        }
        int mid=(ss+se)/2;
        if(idx<=mid)
            return get(2*index,ss,mid,idx);
        else
            return get(2*index+1,mid+1,se,idx);
    }


    int get(int idx)
    {
        return get(1,1,n,idx);
    }

};


