class LazySegmentTree
{
public:
    vector<int> tree;
    vector<int> delta;

    LazySegmentTree(int n, int val)
    {
        tree.resize(4 * n + 2, val);
        delta.resize(4 * n + 2, INF);
    }

    void build(int node, int start, int end)
    {
        if (start == end)
        {
           // tree[node] = v[start];
            return;
        }
        int mid = (start + end) / 2;
        build(2 * node + 1, start, mid);
        build(2 * node + 2, mid + 1, end);

        tree[node] = operation(tree[2 * node + 1], tree[2 * node + 2]);
    }

    void updateRange(int node, int start, int end, int l, int r, int diff)
    {
        if (delta[node] != INF)
        {
            updateDelta(node, delta[node], start, end);
            delta[node] = INF;
        }
        if (start > end || start > r || end < l)
            return;

        if (start >= l && end <= r)
        {
            updateDelta(node, diff, start, end);
            return;
        }

        int mid = (start + end) / 2;
        updateRange(node * 2 + 1, start, mid, l, r, diff);
        updateRange(node * 2 + 2, mid + 1, end, l, r, diff);

        tree[node] = operation(tree[node * 2 + 1], tree[node * 2 + 2]);
    }

    int query(int node, int start, int end, int l, int r)
    {
        if (delta[node] != INF)
        {
            updateDelta(node, delta[node], start, end);
            delta[node] = INF;
        }
        if (r < start || l > end)
        {
            return INF;
        }

        if (l <= start && r >= end)
        {
            return tree[node];
        }
        int mid = (start + end) / 2;
        int a = query(2 * node + 1, start, mid, l, r);
        int b = query(2 * node + 2, mid + 1, end, l, r);

        return operation(a, b);
    }

    void updateDelta(int node, int val, int start, int end)
    {
        tree[node] = min(tree[node], val);

        if (start != end)
        {
            delta[node * 2 + 1] = min(delta[node * 2 + 1], val);
            delta[node * 2 + 2] = min(delta[node * 2 + 2], val);
        }
    }
    int operation(int a, int b)
    {
        return min(a, b);
    }
};
