using namespace atcoder;

int N;
int INF;

using S = int;
S op(S x, S y) { return min(x, y); }
S e() { return INF; }
using F = int;
S mapping(F f, S x) { return min(f, x); }
F composition(F f, F g) { return min(f, g); }
F id() { return INF; }

void dbg(lazy_segtree<S, op, e, F, mapping, composition, id> s) {
	rep2(i, 1, N + 1) {
		dbl(i);
		dbl(s.get(i));
	}
}

int main() {
	// 1-ind
	int Q; cin >> N >> Q;
	INF = N;
	ll ans = (ll)(N - 2) * (N - 2);
	lazy_segtree<S, op, e, F, mapping, composition, id> h(N + 1), w(N + 1);
	h.set(N, 1);
		w.set(N, 1);
		// dbl(ans);
		// dbg(h); dbg(w);
	while (Q--) {
		int q, x; cin >> q >> x;
		// h[i]: 第i行のうち，最も左にある白石の列番号
		// w[j]: 第j列のうち，最も上にある白石の行番号		
		if (q == 1) {
			// 第1行第x列に白石を置く。
			// この列は，(w[x],x)が最も上にある白石であるから，
			// (2,x)~(w[x]-1,x)までのw[x]-2個の黒石が白石になる。
			// これにより，第1行から第w[x]-1行までにつき，最も左にある白石が更新される可能性がある。
			// 第x列の最も上の白石の行番号は1になる。
			ans -= w.get(x) - 2;
			h.apply(1, w.get(x), x);
			w.set(x, 1);
		} else if (q == 2) {
			// 第x行第1列に白石を置く。
			// この行は，(x,h[x])が最も左にある白石であるから，
			// (x,2)~(x,h[x]-1)までのh[x]-2個の黒石が白石になる。
			// これにより，第1列から第h[x]-1列までにつき，最も上にある白石が更新される可能性がある。
			// 第x行の最も左の白石の列番号は1になる。
			ans -= h.get(x) - 2;
			w.apply(1, h.get(x), x);
			h.set(x, 1);
		}
		// cout << "h: "; dbg(h); cout << endl;
		// cout << "w: "; dbg(w); cout << endl;
		// dbl(ans);
	}
	cout << ans << endl;
}

