struct Seg {
    vector <int> seg, lazy;
    Seg (int n) {
        seg.resize (4 * n + 1, n + 1);
        lazy.resize (4 * n + 1, n + 1);
    }
    void push (int x) {
        int l = x * 2;
        int r = x * 2 + 1;
        seg[l] = min (seg[l], lazy[x]);
        seg[r] = min (seg[r], lazy[x]);
        lazy[l] = min (lazy[l], lazy[x]);
        lazy[r] = min (lazy[r], lazy[x]);
        lazy[x] = (1 << 30);
    }
    void updateRange (int node, int lb, int rb, int ql, int qr, int val) {
        if (ql <= lb && rb <= qr) {
            seg[node] = min (seg[node], val);
            lazy[node] = min (lazy[node], val);
            return;
        }
        push (node);
        int mid = (lb + rb) / 2;
        if (ql <= mid)
            updateRange (node * 2, lb, mid, ql, qr, val);
        if (qr >= mid + 1)
            updateRange (node * 2 + 1, mid + 1, rb, ql, qr, val);
    }
    int queryPos (int node, int lb, int rb, int pos) {
        if (lb == rb)
            return seg[node];
        push (node);
        int mid = (lb + rb) / 2;
        if (pos <= mid)
            return queryPos (node * 2, lb, mid, pos);
        else
            return queryPos (node * 2 + 1, mid + 1, rb, pos);
    }
};
int main () {
    ios::sync_with_stdio (false);
    cin.tie (0); cout.tie (0);

    int n, q;
    cin >> n >> q;
    n -= 2;
    Seg L (n), C (n);
    ll black = 1ll * n * n;
    while (q--) {
        int type, x;
        cin >> type >> x; x--;
        if (type == 1) {
            int to = C.queryPos (1, 1, n, x) - 1;
            black -= to;
            C.updateRange (1, 1, n, x, x, 1);
            if (to)
                L.updateRange (1, 1, n, 1, to, x);
        }
        else {
            int to = L.queryPos (1, 1, n, x) - 1;
            black -= to;
            L.updateRange (1, 1, n, x, x, 1);
            if (to)
                C.updateRange (1, 1, n, 1, to, x);
        }
    }
    cout << black << "\n";
    return 0;
}

