ll mpow(ll a, ll n, ll mod)
{
	ll r = 1;
	while (n) {
		if (n&1) r = r*a%mod;
		a = a*a%mod;
		n >>= 1;
	}
	return r;
}

const int N = 2e5 + 5;

int seg_v[4*N+5], seg_h[4*N+5];

void upd(int seg[], int node, int L, int R, int pos, int val)
{
	if (L+1 == R) {
		seg[node] = val;
		return;
	}
	int mid = (L+R)/2;
	if (pos < mid) upd(seg, node<<1, L, mid, pos, val);
	else upd(seg, node<<1|1, mid, R, pos, val);
	seg[node] = max(seg[node<<1], seg[node<<1|1]);
}

int qu(int seg[], int node, int L, int R, int val)
{
	if (L+1 == R) {
		return L;
	}
	int mid = (L+R)/2;
	if (seg[node<<1] >= val) return qu(seg, node<<1, L, mid, val);
	else return qu(seg, node<<1|1, mid, R, val);
}

