#include <bits/stdc++.h>
using namespace std;
using ll=long long;
using vi=vector<int>;

template <typename T>
struct RMQ {
    const T INF = numeric_limits<T>::max();
    int n;
    vector<T> dat, lazy;
    RMQ(int n_) : n(), dat(n_ * 4, INF), lazy(n_ * 4, INF) {
        int x = 1;
        while (n_ > x) x *= 2;
        n = x;
    }

    void eval(int k) {
        if (lazy[k] == INF) return;
        if (k < n - 1) {
            lazy[k * 2 + 1] = lazy[k];
            lazy[k * 2 + 2] = lazy[k];
        }
        dat[k] = lazy[k];
        lazy[k] = INF;
    }

    void update(int a, int b, T x, int k, int l, int r) {
        eval(k);
        if (a <= l && r <= b) {
            lazy[k] = x;
            eval(k);
        } else if (a < r && l < b) {
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    void update(int a, int b, T x) { update(a, b, x, 0, 0, n); }

    T query_sub(int a, int b, int k, int l, int r) {
        eval(k);
        if (r <= a || b <= l) {
            return INF;
        } else if (a <= l && r <= b) {
            return dat[k];
        } else {
            T vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }
    T query(int a, int b) { return query_sub(a, b, 0, 0, n); }

};
int main() {
    int N,Q;
    cin>>N>>Q;
    RMQ<int> row(N-2),column(N-2);
    ll black=(ll)(N-2)*(N-2);
    row.update(0,N-2,N-2);
    column.update(0,N-2,N-2);
    int leftmost=N-1;
    int top=N-1;
    for (int i = 0; i < Q; i++){
        int a,b; cin>>a>>b;
        b-=2;
        if(a==1){
            int tmp=column.query(b,b+1);
            black-=tmp;
            if(b<leftmost){
                row.update(0,tmp,b);
                leftmost=b;
            }
        }else{
            int tmp=row.query(b,b+1);
            black-=tmp;
            if(b<top){
                column.update(0,tmp,b);
                top=b;
            }
        }
    }
    cout<<black<<endl;
}

