    for (int i = 0; i < h; i++){
        if (ocero.at(x).at(i) != "@"){
            ocero.at(x).at(i) = "@";
        }else{
            break;
        }
    }

    return ocero;
}

int main() {
  int H, Q;

  cin >> H >> Q;

  vector<vector<string>> ocero(H, vector<string>(H, "-"));

  //初期設定
  //端から1マス開けて黒
  for (int i = 1; i < H - 1; i++){
      for (int j = 1; j < H - 1; j++){

       ocero.at(i).at(j) = "@";

      }
  }

  //下端と右端を白
  for (int i = 0; i < H; i++){
      ocero.at(i).at(H - 1) = "O";
  }
  for (int i = 0; i < H - 1; i++){
      ocero.at(H - 1).at(i) = "O";
  }

  //クエリを取得
  for (int i = 0; i < Q; i++){
      int q, num;
      cin >> q >> num;
      if (q == 1){
          ocero = white(H, num, ocero);
      }else{
          ocero = black(H, num, ocero);
      }
  }


  //表示
  show(H, ocero);

}

