constexpr u6 maxprime = 1000;
//素因数分解した数値の管理用
struct pfactors {
	vector<u6> count;
	map<u6, u6> lcount;
	static u6 tblsize;
	static u6 buildprimetable() {
		int i = 0;
		primetbl[i++] = 2;
		primetbl[i++] = 3;
		for (u6 t = 1; t * 6 <= maxprime;++t) {
			for (int ii = -1; ii <= 1; ii += 2) {
				u6 j = 6 * t + ii;
				bool flg = false;
				rep(i2, i) {
					if (j % primetbl[i2] == 0) {
						flg = true; break;
					}
				}
				if (!flg) {
					primetbl[i++] = j;
				}
				if (size(primetbl) <= i) {
					tblsize = i;
					return i;
				}
			}
		}
		tblsize = i;
		return i;
	}

};
//値を素因数分解
pfactors parsepfactors(u6 value) {
	pfactors result;
	result.count.resize(pfactors::tblsize);
	rep(i, pfactors::tblsize) {
		while (1) {
			if (value % primetbl[i] != 0)break;
			result.count[i]++;
			value /= primetbl[i];
		}
		if (value == 1)return result;
	}
	result.lcount.emplace(value, 1);
	return result;
}
