struct SegTree {
	int mn[N*4], mx[N*4];
	int add[N*4];

	void build (int v = 1, int tl = 1, int tr = n) {
		add[v] = 0;
		mn[v] = mx[v] = n;
		if(tl < tr) {
			int tm = (tl+tr)>>1;
			build(v<<1, tl, tm);
			build(v<<1|1, tm + 1, tr);
		}
	}
	void push(int v, int tl, int tr) {
		if(!add[v])
			return;
		if(tl < tr) {
			add[v<<1] = add[v<<1|1] = add[v];
		}

		mn[v] = mx[v] = add[v];
		add[v] = 0;
	}

	void upd (int p, int x, int v = 1, int tl = 1, int tr = n) {
		push(v, tl, tr);

		if(tl > p || mx[v] <= x)
			return;
		if (tr <= p && mn[v] >= x) {
			add[v] = x;
			push(v, tl, tr);
			return;
		}

		int tm = (tl+tr)>>1;
		upd(p, x, v<<1, tl, tm);
		upd(p, x, v<<1|1, tm + 1, tr);
	}

	int get (int p, int v = 1, int tl = 1, int tr = n) {
		push(v, tl, tr);

		if(tl == tr) {
			assert(mx[v] == mn[v]);
			return mx[v];
		}

		int tm = (tl+tr) >> 1;
		if (p <= tm) return get(p, v<<1, tl, tm);
		return get(p, v<<1|1, tm + 1, tr);
	}
} S[2];

int main () {
	SpeedForce;

	cin >> n >> q;
	ans = (n-2) * (ll)(n-2);
	for (int it = 0; it < 2; ++it) S[it].build();
	set < pair<int, int> > used;
	for (int i = 1; i <= q; ++i) {
		int op, x;
		cin >> op >> x;
		--op;
		if(used.count({op, x}))
			continue;
		used.insert({op, x});
		int rev = !op;

		int cur = S[op].get(x);

		ans -= cur - 2;
		S[rev].upd(cur, x);
	}
	cout << ans << '\n';


	return Accepted;
}

