  cout << fixed << setprecision(12);

  int N, Q;
  cin >> N >> Q;

  LL sum = (LL)(N-2)*(N-2);

  LazySegTree<int> segx(
    N+1,
    [](int a, int b){return min(a,b);},
    [](int a, int b){return min(a,b);},
    [](int a, int b){return min(a,b);},
    N,
    INF
  );
  LazySegTree<int> segy(
    N+1,
    [](int a, int b){return min(a,b);},
    [](int a, int b){return min(a,b);},
    [](int a, int b){return min(a,b);},
    N,
    INF
  );

  REP(q,Q){
    int t, x;
    cin >> t >> x;
    if(t == 1){
      int r = segx.at(x);
      sum -= r-2;
      segy.update(0,r,x);
    }else{
      int r = segy.at(x);
      sum -= r-2;
      segx.update(0,r,x);
    }
  }

  COUT(sum);

  return 0;
}

