void update(int l,int h,int pos,int ql,int qh,ll val)
{
	seg[pos]+=lazy[pos];
	if(l!=h)
	{
		lazy[2*pos+1]+=lazy[pos];
		lazy[2*pos+2]+=lazy[pos];
	}
	lazy[pos]=0;

	if(qh<l || ql>h) return;
	if(l>=ql and h<=qh)
	{
		seg[pos]+=val;
		if(l!=h)
		{
			lazy[2*pos+1]+=val;
			lazy[2*pos+2]+=val;
		}
		return;
	}
	int m=(l+h)/2;

	update(l,m,2*pos+1,ql,qh,val);
	update(m+1,h,2*pos+2,ql,qh,val);

	seg[pos]=max(seg[2*pos+1],seg[2*pos+2]);
}

ll query(int l,int h,int pos,int ql,int qh)
{
	seg[pos]+=lazy[pos];
	if(l!=h)
	{
		lazy[2*pos+1]+=lazy[pos];
		lazy[2*pos+2]+=lazy[pos];
	}
	lazy[pos]=0;

	if(qh<l || ql>h) return 0;
	if(l>=ql and h<=qh) return seg[pos];

	int m=(l+h)/2;
	return max(query(l,m,2*pos+1,ql,qh),query(m+1,h,2*pos+2,ql,qh));
}



