#define MAX 1000000

ll n;
struct node
{
    int a;
    node()
    {
        a=n-1;
    }
};

class tree
{
    //SUM segment tree
public:


    node tree[MAX];
    node lazy[MAX];

    node combine(node a, node b)
    {
        node ans;
        ans.a = min(a.a,b.a);
        return ans;
    }
    void push(ll si,ll ss, ll se)
    {
        if(lazy[si].a!=inf)
        {
            tree[si].a=min(tree[si].a,lazy[si].a);
            if(ss != se)
            {
                lazy[2*si+1].a=min(lazy[si].a,lazy[2*si+1].a);
                lazy[2*si+2].a=min(lazy[si].a,lazy[2*si+1].a);
            }
            lazy[si].a = inf;
        }
    }
    void build(node arr[], ll ss, ll se, ll si)
    {  
        lazy[si].a = inf;
        if (ss>se)
            return;
        if (ss==se)
        {
            tree[si]=arr[ss];
            return;
        }
        ll mid=(ss+se)/2;
        build(arr,ss,mid,2*si+1);
        build(arr,mid+1,se,2*si+2);
        tree[si] = combine(tree[2*si+1],tree[2*si+2]);  
    }
    void update(ll ss, ll se, ll us, ll ue, int diff, ll si)
    {  
        push(si,ss,se);  
        if(ss>se||ss>ue||se<us)
            return;
        if(ss>=us && se<=ue)
        {
            lazy[si].a=min(lazy[si].a,diff);
            push(si,ss,se);
            return;
        }
        ll mid=(ss+se)/2;
        update(ss,mid,us,ue,diff,2*si+1);
        update(mid+1,se,us,ue,diff,2*si+2);    
        tree[si] = combine(tree[2*si+1],tree[2*si+2]);
    }   
    node query(ll ss, ll se, ll qs, ll qe, ll si)
    {
        push(si,ss,se);
        if (ss>se||ss>qe||se<qs)
        {
            node small;
            small.a = inf;
            return small; //element for outside query;
        }
        if (ss>=qs && se<=qe)
            return tree[si];
        ll mid=(ss+se)/2;
        node n1 = query(ss,mid,qs,qe,2*si+1);
        node n2 = query(mid+1,se,qs,qe,2*si+2);
        return combine(n1,n2);
    }
};


