ll utol(int ty, int a, int b, int k, int L, int R) {
	if (ty == 1) {
		if (b <= L || R <= a) {
			return 1e8;
		}
		else if (a <= L && R <= b) {
			return tate[k];
		}

		else {
			return min(utol(ty, a, b, 2 * k + 1, L, (L + R) / 2),
				utol(ty, a, b, 2 * k + 2, (L + R) / 2, R));
		}
	}

	if (ty == 2) {
		if (b <= L || R <= a) {
			return 1e8;
		}

		else if (a <= L && R <= b) {
			return yoko[k];
		}
		else {
			return min(utol(ty, a, b, 2 * k + 1, L, (L + R) / 2),
				utol(ty, a, b, 2 * k + 2, (L + R) / 2, R));
		}
	}

}

void ltou(int ty, int a, ll p) {
	if (ty == 1) {
		while (a != 0) {
			yoko[a] = min(yoko[a], p);
			a = (a - 1) / 2;
		}
		yoko[0] = min(yoko[0], p);
	}
	if (ty == 2) {
		while (a != 0) {
			tate[a] = min(tate[a], p);
			a = (a - 1) / 2;
		}
		tate[0] = min(tate[0], p);
	}
}

int main() {
	ll N, Q; cin >> N >> Q;

	while (twos < N) { twos *= 2; }
	twos *= 2;
	tate = vector<ll>(twos, N - 2), yoko = vector<ll>(twos, N - 2);
	//f**k 
	ll ans = (N - 2) * (N - 2);
	for (int i = 0; i < Q; i++) {
		int ty, x; cin >> ty >> x;
		x -= 2;
		ll temp = utol(ty, x, twos / 2, 0, 0, twos / 2);
		ans -= temp;
		if (temp > 0)ltou(ty, twos / 2 + temp - 2, x);
	}

	cout << ans << endl;
}

