    horz[2] = N - 2;
    vert_min = N;
    horz_min = N;
    int64_t ans = 1LL * (N - 2) * (N - 2);
    while (Q--) {
        int ty, x; fin, ty, x;
        if (ty == 1) {
            int q = query(vert, x); 
            ans -= q;
            if (x < vert_min) {
                assert(q == horz_min - 2);
                horz[1 + q + 1] = horz[2];
                horz[2] = x - 2;
                vert_min = x;
            }
        } else {
            int q = query(horz, x); 
            ans -= q;
            if (x < horz_min) {
                assert(q == vert_min - 2);
                vert[1 + q + 1] = vert[2];
                vert[2] = x - 2;
                horz_min = x;
            }
        }
    }
    fout, ans, '\n';
    return 0;
}

