	set<pair<int, int>> rows;
	for (int i = 0; i < q; i++) {
		int t, x;
		cin >> t >> x;
		if (t == 1) {
			cols[x - 1] = i;
		}
		if (t == 2) {
			rows.emplace(x - 1, i);
			se(i, x - 1);
		}
	}
	long long ans = 0;
	for (int i = 1; i <= n - 2; i++) {
		if (cols[i] == -1) {
			ans += rows.size();
		}
