const int MAXN = 2e5 + 10;

int t[2][8 * MAXN], mod[2][8 * MAXN];

void push(int ind, int v) {
    if (mod[ind][v] == -1) {
        return;
    }
    t[ind][v] = mod[ind][v];
    mod[ind][2 * v + 1] = mod[ind][2 * v + 2] = mod[ind][v];
    mod[ind][v] = -1;
    return;
}

void build(int ind, int v, int l, int r, int val) {
    mod[ind][v] = -1;
    if (l + 1 == r) {
        t[ind][v] = val;
        return;
    }
    int m = (l + r) / 2;
    build(ind, 2 * v + 1, l, m, val);
    build(ind, 2 * v + 2, m, r, val);
    t[ind][v] = min(t[ind][2 * v + 1], t[ind][2 * v + 2]);
}

void update(int ind, int v, int l, int r, int askl, int askr, int val) {
    push(ind, v);
    if (l >= askr || r <= askl) return;
    if (l >= askl && r <= askr) {
        mod[ind][v] = val;
        push(ind, v);
        return;
    }
    int m = (l + r) / 2;
    update(ind, 2 * v + 1, l, m, askl, askr, val);
    update(ind, 2 * v + 2, m, r, askl, askr, val);
    t[ind][v] = min(t[ind][2 * v + 1], t[ind][2 * v + 2]);
}

int ask(int ind, int v, int l, int r, int pos) {
    push(ind, v);
    if (l + 1 == r) {
        return t[ind][v];
    }
    int m = (l + r) / 2;
    if (pos < m) return ask(ind, 2 * v + 1, l, m, pos);
    else return ask(ind, 2 * v + 2, m, r, pos);
}

int n, q;

signed main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> q;
    build(0, 0, 0, n, n - 1);
    build(1, 0, 0, n, n - 1);
    int ans = (n - 2) * (n - 2);
