    for (int i = 0; i < q; i++) {
        int t, x;
        cin >> t >> x;
        x--;
        t--;
        int len = ask(t, 0, 0, n, x) - 1;
        ans -= len;
        if (chkmin(mn[t], x)) {
            update(!t, 0, 0, n, 0, len + 1, x);
        }
    }
    cout << ans << "\n";
}
