struct segt
{
	vint t, add;
	int s, e, res, val;
	segt()
	{
		t.assign(4 * n, n - 1);
		add.assign(4 * n, n - 1);
	}
	void upd_v(int v)
	{
		int vl = v << 1, vr = vl + 1;
		t[v] = min(t[vl], t[vr]);
	}
	int get(int _s)
	{
		s = _s;
		return query(1, 0, n);
	}
	int query(int v, int l, int r)
	{
		if (r - l == 1)
			return t[v];
		int m = (l + r) >> 1, vl = v << 1, vr = vl + 1;
		if (s < m)
			return min(add[v], query(vl, l, m));
		else
			return min(add[v], query(vr, m, r));
	}
	void upd(int _s, int _e, int _val)
	{
		s = _s;
		e = _e;
		val = _val;
		upd_t(1, 0, n);
	}
	void upd_t(int v, int l, int r)
	{
		if (r <= s || e <= l || l >= r)
			return;
		if (s <= l && r <= e)
		{
			t[v] = min(t[v], val);
			add[v] = min(add[v], val);
			return;
		}
		int m = (l + r) >> 1, vl = v << 1, vr = vl + 1;
		upd_t(vl, l, m);
		upd_t(vr, m, r);
		upd_v(v);
	}
};

