struct BIT {
	vector<ll> T;
	BIT(int n) {
		T.resize(n+2);
		fill(T.begin(), T.end(), 0);
	}
	void add(int i, int v) {
		for(++i; i < (int)T.size(); i += i&-i) {
			T[i] += v;
		}
	}
	ll get(int r) {
		ll ret = 0;
		for(++r; r > 0; r -= r&-r) ret += T[r];
		return ret;
	}
	void rangeUpdate(int l, int r, int v) {
		add(l, v);
		add(r+1, -v);
	}
};

template<class val_t>
struct segment_tree {
	int n;
	vector<val_t> T;

	template<typename X>
	void init(int sz, const vector<X> a) {
		n = sz;
		T.resize(2*n);
		for(int i = 0; i < n; ++i) {
			T[n + i] = a[i];
		}
		for(int i = n - 1; i > 0; --i) {
			T[i] = T[i<<1] + T[i<<1|1];
		}
	}

	val_t query(int i) {
		val_t ret;
		for(i += n; i > 0; i >>= 1) {
			ret = ret + T[i];
		}
		return ret;
	}

	void update(int l, int r, val_t val) {
		for(l += n, r += n + 1; l < r; l >>= 1, r >>= 1) {
			if(l & 1) T[l] = T[l] + val, ++l;
			if(r & 1) --r, T[r] = T[r] + val;
		}
	}
};

void solve() {
	int n, q;
	read(n, q);
	segment_tree<min_t> rt, ct;
	BIT bit(n);
	for(int i = 1; i < n-1; ++i) bit.rangeUpdate(i, i, n-2);
	rt.init(n, vector<int>(n, n-1));
	ct.init(n, vector<int>(n, n-1));
	for(int i = 0; i < n; i++) {
		// trace(bit.get(i));
	}
	for(int qq = 1; qq <= q; ++qq) {
		int t, x;
		read(t, x); --x;
		if(t == 1) {
			int mx = rt.query(x);
			ct.update(0, mx-1, x);
			bit.rangeUpdate(x, x, -(mx-1));
			trace(qq, t, x, mx);
		}
		else {
			int mx = ct.query(x);
			rt.update(0, mx-1, x);
			bit.rangeUpdate(1, mx-1, -1);
			trace(qq, t, x, mx);
		}
	}
	ll ans = 0;
	for(int i = 1; i < n-1; i++) ans += bit.get(i);
	print(ans);
}

