struct seg_tree{
    int st[800005];
    void update(int n, int s, int e, int i, int v){
        if(s == e) st[n] = v;
        else{
            int mid = (s+e)/2;
            if(i <= mid) update(n+n, s, mid, i, v);
            else update(n+n+1, mid+1, e, i, v);
            st[n] = max(st[n+n], st[n+n+1]);
        }
    }
    int query(int n, int s, int e, int l, int r){
        if(s > r || l > e) return 0;
        if(l <= s && e <= r) return st[n];
        int mid = (s+e)/2;
        return max(query(n+n, s, mid, l, r), query(n+n+1, mid+1, e, l, r));
    }
}st[2];

