void update(int * t, int v, int tl, int tr, int l, int r, int val) {
    if(l > r) return;

    if(tl == l &&  tr == r) {
        t[v] = min(t[v], val);
    } else {
        int tm = (tl + tr) / 2;

        push(t, v);

        update(t, v * 2, tl, tm, l, min(r, tm), val);
        update(t, v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, val);
    }
}

int get(int * t, int v, int tl, int tr, int pos) {
    if(tl == tr) return t[v];

    int tm = (tl + tr) / 2;
    if(pos <= tm)
        return min(t[v], get(t, v * 2, tl, tm, pos));
    else
        return min(t[v], get(t, v * 2 + 1, tm + 1, tr, pos));
}

