  SegTree stx(N-2); rep(i,N-2) stx.update(i,N-2);
  SegTree sty(N-2); rep(i,N-2) sty.update(i,N-2);

  ll result = (N-2)*(N-2);
  rep(i,Q) {
    ll q, x; cin >> q >> x; x-= 2;
    if (q==1) {
      ll num = stx.query(x,N-2);
      result -= num;
      sty.update(num-1,min(sty[num-1],x));
    }
    else {
      ll num = sty.query(x,N-2);
      result -= num;
      stx.update(num-1,min(stx[num-1],x));
    }
    // cout << result << endl;
    // rep(i,N) cout << stx[i] << " "; cout << endl;
    // rep(i,N) cout << sty[i] << " "; cout << endl;
  }

  cout << result << endl;
  return 0;
}

