  mysegtree xbeam(N);
  mysegtree ybeam(N);



  int qu;
  scanner >> qu;

  ll white = 0;
  repeat(_q, qu) {
    int t, idx;
    scanner >> t >> idx;
    idx -= 2;
    if (t == 1) {
      // y beam
      int z = xbeam.get(idx);
      white += z;
      ybeam.apply(0, z, idx);
    }
    else if (t == 2) {
      // y beam
      int z = ybeam.get(idx);
      white += z;
      xbeam.apply(0, z, idx);
    }
    // LOG << (ll(N-2)*ll(N-2) - white);
  }

  cout << (ll(N-2)*ll(N-2) - white) << endl;

  return 0;
}

