struct segtree{
	vector<int> seg;
	int cn;

	void Build(int node,int s,int e, int val){
		assert(s <= e);

		seg[node] = val;

		if (s == e){
			return;
		}

		int mid = ((s + e)/2);


		Build((2 * node), s, mid, val);
		Build(2 * node + 1, mid + 1, e, val);
	}

	void build(int n){
		seg.resize(4 * n + 3);
		Build(1, 1, n, n);
		cn = n;
	}

	void update(int node,int s,int e,int l,int r,int v){
		if (e < l || s > r){
			return;
		}
		if (l <= s && e <= r){
			seg[node] = min(seg[node], v);
			return;
		}
		int mid = (s + e) >> 1;
		update(2 * node, s, mid, l, r, v);
		update(2 * node + 1, mid + 1, e, l, r, v);
	}
	void update(int l,int r,int v){
		update(1, 1, cn, l, r, v);
	}
	int query(int node,int s,int e,int l){
		assert(s <= l && l <= e);

		if (s == e){
			return seg[node];
		}

		int mid = (s + e) >> 1;

		if (l <= mid){
			return min(seg[node], query(2 * node, s, mid, l));
		}
		return min(seg[node], query(2 * node + 1, mid + 1, e, l));
	}

	int query(int l){
		return query(1, 1, cn, l);
	}
};

