		fen[c][x] = min(fen[c][x], y);
}

int get(int c, int x) {
	int res = n;
	for (; x <= n; x |= (x + 1))
		res = min(res, fen[c][x]);
	return res;
}

int main() {
	ios_base::sync_with_stdio(false), cin.tie(NULL);
	cin >> n >> q;
	for (int i = 0; i <= n; i++) fen[0][i] = fen[1][i] = n;
	ans = (ll)(n - 2) * (n - 2);
	while (q--) {
		int t, x;
		cin >> t >> x;
		if (t == 1) {
			int r = get(0, x) - 1;
			upd(1, r, x);
			ans -= r - 1;
		}	else {
			int r = get(1, x) - 1;
			upd(0, r, x);
			ans -= r - 1;
		}
	}
	cout << ans;
}

