template<typename T, size_t N>
struct fenwick {
  T c[N];
  fenwick() {
    fill(c + 1, c + N, 0);
  }
  void add(int x, T y) {
    for (; x; x -= x & -x) {
      c[x] = min(c[x], y);
    }
  }
  T query(int x) {
    T ret = N;
    for (; x < N; x += x & -x) {
      ret = min(ret, c[x]);
    }
    return ret;
  }
};

