struct range_tree {
    int rt[1000000];
    range_tree(int N) {
        for(int n = 1; n < 1000000; ++n) {
            rt[n] = N;
        }
    }
    void propagate(int n) {
        if(rt[n] >= 0) {
            rt[2 * n] = min(rt[2 * n], rt[n]);
            rt[2 * n + 1] = min(rt[2 * n + 1], rt[n]);
            rt[n] = -1;
        }
    }
    int query(int w, int n = 1, int l = 0, int r = 1 << 18) {
        if(l + 1 == r) {
            return rt[n];
        }
        propagate(n);
        if(w < (l + r) / 2) {
            return query(w, 2 * n, l, (l + r) / 2);
        } else {
            return query(w, 2 * n + 1, (l + r) / 2, r);
        }
    }
    void update(int b, int e, int q, int n = 1, int l = 0, int r = 1 << 18) {
        if(b <= l and r <= e) {
            rt[n] = min(rt[n], q);
            return;
        }
        if(e <= l or r <= b) {
            return;
        }
        propagate(n);
        update(b, e, q, 2 * n, l, (l + r) / 2);
        update(b, e, q, 2 * n + 1, (l + r) / 2, r);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int N, Q;
    cin >> N >> Q;
    range_tree hor(N - 2), ver(N - 2);
    LL ans = LL(N - 2) * LL(N - 2);
    while(Q--) {
        int k, x;
        cin >> k >> x;
        if(k == 1) {
            auto y = hor.query(x);
            ans -= y;
            ver.update(2, 2 + y, x - 2);
        } else {
            auto y = ver.query(x);
            ans -= y;
            hor.update(2, 2 + y, x - 2);
        }
    }
    cout << ans << "\n";


    return 0;
}

