void build1(ll cur,ll st,ll end)
{
    if(st==end)
    {
        seg1[cur]=a1[st];
        return;
    }
    ll mid=(st+end)>>1;
    build1(2*cur,st,mid);
    build1(2*cur+1,mid+1,end);
    seg1[cur]=min(seg1[2*cur],seg1[2*cur+1]);    /*  1-change here  */
}
ll query1(ll cur,ll st,ll end,ll l,ll r)
{
    if(l<=st&&r>=end)
    return seg1[cur];
    if(r<st||l>end)
    return hell;                           /*  2-change here  */
    ll mid=(st+end)>>1;
    ll ans1=query1(2*cur,st,mid,l,r);
    ll ans2=query1(2*cur+1,mid+1,end,l,r);
    return min(ans1,ans2);                 /*  3-change here  */
}
void update1(ll cur,ll st,ll end,ll pos,ll upd)
{
    if(st==end)
    {
        a1[pos]=upd;                    /*  4-change here  */
        seg1[cur]=upd;                    /*  5-change here  */
        return;
    }
    ll mid=(st+end)>>1;
    if(st<=pos&&pos<=mid)
        update1(2*cur,st,mid,pos,upd);
    else
        update1(2*cur+1,mid+1,end,pos,upd);
    seg1[cur]=min(seg1[2*cur],seg1[2*cur+1]);    /*  6-change here  */
}
