			remain -= mn - 2;
			update(1, 1, N, 1, mn, 1, x);
		} else {
			int mn = query(1, 1, N, x, 1);
			remain -= mn - 2;
			update(0, 1, N, 1, mn, 1, x);
		}
	}

	cout << remain << endl;
	return 0;
}

