template <typename E>
struct dual_segment_tree {
    using H = function<E(E, E)>;
    int n, height;
    H h;
    E ei;
    vector<E> lazy;
    dual_segment_tree(H h, E ei) : h(h), ei(ei) {}
    void init(int n_) {
        n = 1; height = 0;
        while (n < n_) n <<= 1, height++;
        lazy.assign(2*n, ei);
    }
    inline void propagete(int i) {
        if (lazy[i] == ei) return;
        lazy[i<<1|0] = h(lazy[i<<1|0], lazy[i]);
        lazy[i<<1|1] = h(lazy[i<<1|1], lazy[i]);
        lazy[i] = ei;
    }
    inline void thrust(int i) {
        for (int k = height; k >= 1; --k) propagete(i>>k);
    }
    void update(int a, int b, E x) {
        a += n; b += n;
        thrust(a);
        thrust(b-1);
        int l = a, r = b;
        while (l < r) {
            if (l & 1) lazy[l] = h(lazy[l], x), l++;
            if (r & 1) --r, lazy[r] = h(lazy[r], x);
            l >>= 1; r >>= 1;
        }
    }
    E get_val(int i) {
        i += n;
        thrust(i);
        return lazy[i];
    }
};

int main() {
    ll n; int q;
    cin >> n >> q;
    ll ans = (n - 2) * (n - 2);
    auto f = [](int a, int b) { return min(a, b); };
    dual_segment_tree<int> seg1(f, n-1), seg2(f, n-1);
    seg1.init(n);
    seg2.init(n);
    while (q--) {
        int t, x;
        cin >> t >> x;
        x--;
        if (t == 1) {
            int res = seg1.get_val(x);
            ans -= res - 1;
            seg2.update(0, res, x);
        } else {

            int res = seg2.get_val(x);
            ans -= res - 1;
            seg1.update(0, res, x);
        }
    }
    cout << ans << '\n';
}

