void buildtree(ll si, ll ss, ll se, vl& segtree, ll n)
{
	if (ss == se)
		segtree[si] = n;
	else
	{
		ll mid = (ss + se) / 2;
		buildtree(2 * si, ss, mid, segtree, n);
		buildtree(2 * si + 1, mid + 1, se, segtree, n);
		segtree[si] = min(segtree[2 * si], segtree[2 * si + 1]);
	}
}
void updatetree(ll si, ll ss, ll se, ll l, ll r, ll val, vl& segtree, vl& lazy)
{
	if (lazy[si] != inf)
	{
		segtree[si] = min(segtree[si], lazy[si]);
		if (ss != se)
			lazy[2 * si] = min(lazy[2 * si], lazy[si]) , lazy[2 * si + 1] = min(lazy[2 * si + 1], lazy[si]);
		lazy[si] = inf;
	}
	if (ss > r || se < l)
		return;
	if (ss >= l && se <= r)
	{
		segtree[si] = min(segtree[si], val);
		if (ss != se)
			lazy[2 * si] = min(lazy[2 * si], val) , lazy[2 * si + 1] = min(lazy[2 * si + 1], val);
		return;
	}
	ll mid = (ss + se) / 2;
	updatetree(2 * si, ss, mid, l, r, val, segtree, lazy);
	updatetree(2 * si + 1, mid + 1, se, l, r, val, segtree, lazy);
	segtree[si] = min(segtree[2 * si], segtree[2 * si + 1]);
}
ll query(ll si, ll ss, ll se, ll l, ll r, vl& segtree, vl& lazy)
{
	if (lazy[si] != inf)
	{
		segtree[si] = min(segtree[si], lazy[si]);
		if (ss != se)
			lazy[2 * si] = min(lazy[2 * si], lazy[si]) , lazy[2 * si + 1] = min(lazy[2 * si + 1], lazy[si]);
		lazy[si] = inf;
	}
	if (ss > r || se < l)
		return inf;
	if (ss >= l && se <= r)
		return segtree[si];
	ll mid = (ss + se) / 2;
	ll left = query(2 * si, ss, mid, l, r, segtree, lazy);
	ll right = query(2 * si + 1, mid + 1, se, l, r, segtree, lazy);
	return min(left, right);
}

