template<typename T>
class BIT{
    private:
    vector<T> vs;
    int n;

    public: 
    BIT(int n){
        this->vs.assign(n+1, 0);
        this->n = n;
    }

    void update(T i, T delta){
        for (;i <= n;i += i&(-i)) vs[i] = max(vs[i], delta);
    }

    T query(T i){
        T sum = 0;
        for (;i;i -= i&(-i)) sum += vs[i];
		return sum;
    }

    int size(){
        return n;
    }
};

ll bs(BIT<ll>& vs, ll val){
    int r = vs.size(), l = 0;

    while (l < r-1){
        int mid = (l+r)/2;
        int v = vs.query(mid);

        if (v < val){
            l = mid;
        }
        else {
            r = mid;
        }
    }
    return r;
}
