template <typename DataT, typename ContainerT = vector<DataT>> struct SegTree
{
    //左闭右开
    int n;
    ContainerT node, lazy;
    SegTree() {}
    void build(ContainerT v)
    {
        int s = int(v.size());
        n = 1;
        while (n < s) { n <<= 1; }
        node.resize(2 * n - 1);
        lazy.resize(2 * n - 1, INF);
        for (int i = 0; i < s; i++) { node[i + n - 1] = v[i]; }
        for (int i = n - 2; i >= 0; i--) {
            node[i] = node[i * 2 + 1] + node[i * 2 + 2];
        }
    }
    inline void push(int k, int l, int r)
    {
        if (lazy[k] != INF) {
            node[k] = min(node[k], lazy[k]);
            if (r - l > 1) {
                lazy[(k << 1) + 1] = min(lazy[(k << 1) + 1], lazy[k]);
                lazy[(k << 1) + 2] = min(lazy[(k << 1) + 2], lazy[k]);
            }
            lazy[k] = INF;
        }
    }

    void update(int a, int b, DataT x, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0) r = n;
        push(k, l, r);
        if (b <= l || r <= a) { return; }
        if (a <= l && r <= b) {
            lazy[k] = min(lazy[k], x);
            push(k, l, r);
        } else {
            update(a, b, x, (k << 1) + 1, l, ((l + r) >> 1));
            update(a, b, x, (k << 1) + 2, ((l + r) >> 1), r);
            node[k] = node[(k << 1) + 1] + node[(k << 1) + 2];
        }
    }

    DataT query(int a, int b, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0) r = n;
        push(k, l, r);
        if (b <= l || r <= a) { return 0; }
        if (a <= l && r <= b) { return node[k]; }
        DataT vl = query(a, b, (k << 1) + 1, l, ((l + r) >> 1));
        DataT vr = query(a, b, (k << 1) + 2, ((l + r) >> 1), r);
        return vl + vr;
    }
};
int main()
{
    int n, q;
    io >> n >> q;
    vector<pair<int, int>> queries(q);
    io >> queries;
    int64_t ans = 1ll * (n - 2) * (n - 2);
    SegTree<int> a, b;
    a.build(vector<int>(n, n - 2));
    b = a;
    for (auto [op, x] : queries) {
        --x;
        if (op == 1) {
            ans -= a.query(x, x + 1);
            b.update(0, a.query(x, x + 1) + 1, x - 1);
        }
        if (op == 2) {
            ans -= b.query(x, x + 1);
            a.update(0, b.query(x, x + 1) + 1, x - 1);
        }
        // io.WL(ans);
    }
    io.WL(ans);
    return 0;
}

