struct Node{
    ll L,R,MaxNum;
    Node *Lc,*Rc;
    Node(ll L_,ll R_,ll N):L(L_),R(R_){
        if(L==R){
            MaxNum=N;
            Lc=Rc=0;
            return ;
        }
        MaxNum=0;
        Lc=new Node(L,L+R>>1,N);
        Rc=new Node(Lc->R+1,R,N);
    }
    inline void pushdown(){
        if(!MaxNum||!Lc) return ;
        if(!Lc->MaxNum) Lc->MaxNum=MaxNum;
        else Lc->MaxNum=min(Lc->MaxNum,MaxNum);
        if(!Rc->MaxNum) Rc->MaxNum=MaxNum;
        else Rc->MaxNum=min(Rc->MaxNum,MaxNum);
        MaxNum=0;
    }
    ll query(ll pos){
        if(L==R) return MaxNum;
        pushdown();
        if(pos<=Lc->R) return Lc->query(pos);
        return Rc->query(pos);
    }
    void update(ll Head,ll Tail,ll Val){
        if(L==Head&&Tail==R){
            if(!MaxNum) MaxNum=Val;
            else MaxNum=min(MaxNum,Val);
            return ;
        }
        pushdown();
        if(Lc->R>=Tail) Lc->update(Head,Tail,Val);
        else if(Rc->L<=Head) Rc->update(Head,Tail,Val);
        else Lc->update(Head,Lc->R,Val),Rc->update(Rc->L,Tail,Val);
    }
}*RSide,*USide;
