void Stworz(vector<ll>& T)
{
    int p = 1;
    while (p < n)
        p *= 2;
    l = p;
    Size = 2 * p - 1;
    for (int i = 0; i <= Size; ++i)
        T.push_back(0);
}

void Zmien(vector<ll>& T, ll a, ll b, ll x)
{
    a += l;
    b += l;
    T[a] += x;
    if (a != b)
        T[b] += x;
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0)
            T[a + 1] += x;
        if (b % 2 == 1)
            T[b - 1] += x;
        a /= 2;
        b /= 2;
    }
}

ll Pyt(vector<ll>& T, ll a)
{
    a += l;
    ll wyn = 0;
    while (a != 0)
    {
        wyn += T[a];
        a /= 2;
    }
    return wyn;
}

