template<typename T>
class lazy_segment_tree{
	int n;
	T fval;
	vector<T> dat, lazy;

public:

	lazy_segment_tree(){

	}

	lazy_segment_tree(int n_, T val){
		init(n_, val);
	}

	~lazy_segment_tree(){

	}

	void init(int n_, T val){
		fval = val;

		n = 1;

		while(n < n_) n *= 2;

		dat.resize(2 * n - 1);
		lazy.resize(2 * n - 1, fval);

		for(int i = 0; i < 2 * n - 1; i++) dat[i] = fval;
	}

	void eval(int k, int l, int r){

		if(lazy[k] != fval){
			// dat[k] = dat[k] + lazy[k]/(r - l);
			dat[k] = min(dat[k], lazy[k]);
			if(r - l > 1) {
				lazy[2*k+1] = min(lazy[2*k+1] , lazy[k]);
				lazy[2*k+2] = min(lazy[2*k+2] , lazy[k]);
			}

			lazy[k] = fval;
		}
	}

	void update(int a, int b, T x, int k = 0, int l = 0, int r = -1){
		if(r < 0) r = n;
		eval(k, l, r);
		if(b <= l || r <= a) {return ;}
		if(a <= l && r <= b){
			// lazy[k] = lazy[k] + (r - l) * x;
			lazy[k] = min(lazy[k], x);
			eval(k, l, r);
		} else {
			update(a, b, x, 2*k+1, l, (l+r)/2);
			update(a, b, x, 2*k+2, (l+r)/2, r);
			dat[k] = min(dat[2*k+1], dat[2*k+2]);
		}
	}

	T query(int a, int b, int k = 0, int l = 0, int r = -1){
		if(r < 0) r = n;
		eval(k, l, r);
		if(r <= a || b <= l){
			return INF;
		}
		if(a <= l && r <= b){
			return dat[k];
		}else {
			T vl = query(a, b, k * 2 + 1, l, (l + r) / 2 );
			T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return min(vl, vr);
		}
	}
};

signed main(){
	cout<<fixed<<setprecision(10);

	int N, Q;
	lazy_segment_tree<long long> lseg, lseg2;
	int ans = 0;

	cin>>N>>Q;

	lseg.init(N+4, N);
	lseg2.init(N+4, N);

	for(int i = 0; i < Q; i++){
		int a, b;

		cin>>a>>b;

		if(a == 1) {
			int t = lseg.query(b, b+1);

			ans += t - 1 - 1;
			// cout<<"t1 = "<<t<<endl;
			lseg2.update(1, t+1, b);

		} else if(a == 2) {
			int t = lseg2.query(b, b+1);

			ans += t - 1 - 1;
			// cout<<"t2  = "<<t<<endl;
			lseg.update(1, t+1, b);
		}
		// cout<<"ans = "<<ans<<endl;

		// for(int i = ){
		// }
	}

	ans = (N - 2) * (N - 2) -  ans;

	cout<<ans<<endl;

	return 0;
}

