    	values[v*2] = min(values[v*2],lazy[v]);
    	lazy[v*2] = min(lazy[v*2],lazy[v]);
    	values[v*2+1] = min(values[v*2+1],lazy[v]);
    	lazy[v*2] = min(lazy[v*2],lazy[v]);
    	lazy[v] = inf;
        }

	void update(int v, int tl, int tr, int l, int r, int addend) {
    if (l > r) 
        return;
    if (l == tl && tr == r) {
        values[v] = min(values[v],addend);
        lazy[v]  = min(lazy[v],addend);
    } else {
        push(v);
        int tm = (tl + tr) / 2;
        update(v*2, tl, tm, l, min(r, tm), addend);
        update(v*2+1, tm+1, tr, max(l, tm+1), r, addend);
        values[v] = min(values[v*2], values[v*2+1]);
    }
   }


