}

int addget(SumNode* node, int lv, int rv, int l, int r, int indexl, int indexr)
{
    // l + 1 == rでしかよばない前提
    if( indexr - indexl == 1 || l <= indexl && r >= indexr  ) return node->value;
    int indexc = (indexl + indexr) / 2;
    if( r <= indexc ) return min(lv, node->value);
    if( l >= indexc ) return min(rv, node->value);
    return min(lv, node->value);
}

