struct segtree{

    #define noop LLONG_MAX
    #define left 2*x +1
    #define right 2*x+2
    #define mid (lx+rx)/2 
    vector<int> values;
    int size;

    void init(int n)
    {
        size=1;
        while(size<n)
            size*=2;

        values.assign(2*size,noop);
    }

    void push(int x,int lx,int rx)
    {
        if(rx==lx+1||values[x]==noop)
        {
            return;
        }

        values[left]=min(values[left],values[x]);
        values[right]=min(values[right],values[x]);
        values[x]=noop;
    }

    void change(int x,int lx,int rx,int l,int r,int v)
    {
        push(x,lx,rx);
        if(lx>=r||rx<=l)
            return;
        if(l<=lx&&r>=rx)
        {
            values[x]=min(v,values[x]);
            return;
        }
        change(left,lx,mid,l,r,v);
        change(right,mid,rx,l,r,v);
    }

    void change(int l,int r ,int v)
    {
        change(0,0,size,l,r,v);
    }

    int getval(int x,int lx,int rx,int l)
    {
       // debug(x,lx,rx,values[x]);
        push(x,lx,rx);
        if(lx+1==rx)
        {
            return values[x];
        }

        if(l<mid)
        {
            return getval(left,lx,mid,l);
        }
        return getval(right,mid,rx,l);

    }

    int getval(int l)
    {
        return getval(0,0,size,l);
    }


};

int32_t main()
{
    int n,q;
