        if(type==1)
        {
            int v=down.getval(x-1);
            debug(v);
            down.change(x-1,x,0);
            ans+=v-1;
            ri.change(0,v,x-1);
        }

        else
        {
            int v=ri.getval(x-1);
            debug(v);
            ri.change(x-1,x,0);
            ans+=v-1;
            down.change(0,v,x-1);
        }
        debug(ans);

    }

