void update(int seg[], int N, int l, int r, int val) {
	l += N;
	r += N;
	while (l < r) {
		if (l & 1) {
			seg[l] = min(seg[l], val);
			l++;
		}
		if (r & 1) {
			r--;
			seg[r] = min(seg[r], val);
		}
		l >>= 1;
		r >>= 1;
	}
}

int query(int seg[], int N, int idx) {
	idx += N;
	int ans = N;
	while (idx > 0) {
		ans = min(ans, seg[idx]);
		idx >>= 1;
	}
	return ans;
}


