        int x = 1;
        while (n_ > x) x *= 2;
        n = x;
    }

    /* lazy eval */
    void eval(int k) {
        if (lazy[k] == INF) return;  
        if (k < n - 1) {
            lazy[k * 2 + 1] = lazy[k];
            lazy[k * 2 + 2] = lazy[k];
        }
        dat[k] = lazy[k];
        lazy[k] = INF;
    }

    void update(int a, int b, T x, int k, int l, int r) {
        eval(k);
        if (a <= l && r <= b) {
            lazy[k] = x;
            eval(k);
        } else if (a < r && l < b) {                     // 一部区間が被る時
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);  // 左の子
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);  // 右の子
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    void update(int a, int b, T x) { update(a, b, x, 0, 0, n); }

    T query_sub(int a, int b, int k, int l, int r) {
        eval(k);
        if (r <= a || b <= l) { 
            return INF;
        } else if (a <= l && r <= b) {
            return dat[k];
        } else {  // 一部区間が被る時
            T vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }
    T query(int a, int b) { return query_sub(a, b, 0, 0, n); }
};

int main(){
    ll N,Q;
    cin>>N>>Q;
    ll ans = (N-2)*(N-2);
    ll left = N-1, under = N-1;
    RMQ<ll> tate(N),yoko(N);
  tate.update(0,N,N-1);
  yoko.update(0,N,N-1);
    rep(i,Q){
        ll q,x;
        cin>>q>>x;
        x--;
        if(q == 1){
            if(chmin(left,x)){
                tate.update(0,under,x);
            }
            ans -= yoko.query(x,x+1)-1;
        }
        if(q == 2){
            if(chmin(under,x)){
                yoko.update(0,left,x);
            }
            ans -= tate.query(x,x+1)-1;
        }
    }
    cout<<ans<<endl;
}

