struct lazy{
	int a[N];
	int lazy[N];
	const int INF = 1e9;
	void build(int id, int l, int r, int val){
		if(l > r) return;
		a[id] = val;
		lazy[id] = -1;
		if(l == r) return;
		int mid = (l + r) >> 1;
		build(2*id, l, mid, val), build(2*id + 1, mid + 1, r, val);
	}
	void push(int id, int l, int r){
		if(l == r || lazy[id] == -1) return;
		a[2*id] = min(a[2*id], lazy[id]);
		a[2*id + 1]= min(a[2*id+1], lazy[id]);
		lazy[2*id+1]=lazy[2*id]=lazy[id];
		lazy[id] = -1;
	}
	void update(int id, int val, int l, int r, int L, int R){
		if(l > R || r < L) return;
		push(id, l, r);
		a[id] = min(a[id], val);
		if(l >= L && r <= R){
			lazy[id] = a[id];
			return;
		}
		update(2*id, val, l, (l+r >> 1), L, R);
		update(2*id+1,val,(l+r>>1) + 1, r, L, R);
	}
	int query(int id,int l, int r, int L, int R){
		if(l > R || r < L) return INF;
		push(id, l, r);
		if(l >= L && r <= R) return a[id];
		int ret = min(query(2*id,l, l + r>> 1, L, R), query(2*id+1, (l+r>>1) + 1, r, L, R));
		return ret;
	}
}row, col;
