#include <bits/stdc++.h>
using namespace std;
const int INF = 1000000;
template <typename T>
struct range_chmin{
	int N;
	vector<T> ST;
	range_chmin(vector<T> A){
		int n = A.size();
		N = 1;
		while (N < n){
			N *= 2;
		}
		ST = vector<T>(N * 2 - 1, INF);
		for (int i = 0; i < n; i++){
			ST[N - 1 + i] = A[i];
		}
	}
	T operator [](int k){
		k += N - 1;
		T ans = ST[k];
		while (k > 0){
			k = (k - 1) / 2;
			ans = min(ans, ST[k]);
		}
		return ans;
	}
	void chmin(int L, int R, T x, int i, int l, int r){
		if (R <= l || r <= L){
			return;
		} else if (L <= l && r <= R){
			ST[i] = min(ST[i], x);
			return;
		} else {
			int m = (l + r) / 2;
			chmin(L, R, x, i * 2 + 1, l, m);
			chmin(L, R, x, i * 2 + 2, m, r);
			return;
		}
	}
	void chmin(int L, int R, T x){
		chmin(L, R, x, 0, 0, N);
	}
};
int main(){
  int N, Q;
  cin >> N >> Q;
  vector<int> A(N - 2, N - 2);
  range_chmin<int> H(A), V(A);
  long long ans = (long long) (N - 2) * (N - 2);
  for (int i = 0; i < Q; i++){
    int d, x;
    cin >> d >> x;
    if (d == 1){
      int cnt = V[x - 2];
      ans -= cnt;
      H.chmin(0, cnt, x - 2);
    }
    if (d == 2){
      int cnt = H[x - 2];
      ans -= cnt;
      V.chmin(0, cnt, x - 2);
    }
  }
  cout << ans << endl;
}

