    SegmentTree< int > indexH(N + 1, [](int a, int b) { return min(a, b); }, INT_MAX), indexW(N + 1, [](int a, int b) { return min(a, b); }, INT_MAX);
    ll ans = (N - 2) * (N - 2);
    vector<pair<int, int>> Query;
    for(int i = 0;i < Q;i++){
