        Query.push_back({a, b});
        if(a == 1){
            MinSegW.update(i, b);
        }else{
            MinSegH.update(i, b);
        }
    }
    for(int i = 0;i < Q;i++){
        int a = Query[i].first;
        int b = Query[i].second;
        if(a == 1){
            int w = indexW.query(0, b);
            //cout<<w<<" ";
            if(w == INT_MAX){
