	{
		tree[index]=max(tree[index],lazy[index]);
		if(start!=end)
		{
			lazy[2*index]=max(lazy[2*index],lazy[index]);
			lazy[2*index+1]=max(lazy[2*index+1],lazy[index]);
		}
		lazy[index]=0;
	}
	if(left>end||start>right)
	{
		return ;
	}
	if(start>=left&&end<=right)
	{
		tree[index]=max(tree[index],val);
		if(start!=end)
		{
			lazy[2*index]=max(lazy[2*index],val);
			lazy[2*index+1]=max(lazy[2*index+1],val);
		}
		return ;
	}
	else
	{
		int mid=(start+end)/2;
		update(tree,lazy,start,mid,left,right,val,2*index);
		update(tree,lazy,mid+1,end,left,right,val,2*index+1);
		tree[index]=max(tree[2*index],tree[2*index+1]);
	}
}
int max_query(int tree[],int lazy[],int start,int end,int left,int right,int index)
{
	if(lazy[index]!=0)
	{
		tree[index]=max(tree[index],lazy[index]);
		if(start!=end)
		{
			lazy[2*index]=max(lazy[2*index],lazy[index]);
			lazy[2*index+1]=max(lazy[2*index+1],lazy[index]);
		}
		lazy[index]=0;
	}
	if(left>end||start>right)
	  return -1;
	if(start>=left&&end<=right)
	  return tree[index];
	else
	{
		int mid=(start+end)/2;
		int x=max_query(tree,lazy,start,mid,left,right,2*index);
		int y=max_query(tree,lazy,mid+1,end,left,right,2*index+1);
		return max(x,y);
	}
}
int binary_search(int start,int end,int tree[],int lazy[],int x,int n)
{
	if(start>end)
	{
		return -1;
	}
	else
	{
		int mid=(start+end)/2;
		int val=max_query(tree,lazy,0,n-1,start,mid,1);
		if(val>=x)
		{
			int point=mid;
			int y=binary_search(start,mid-1,tree,lazy,x,n);
			if(y==-1)
			  return point;
			else
			   return y;
		}
		else
		  return binary_search(mid+1,end,tree,lazy,x,n);
	}
}
