int main() {
	int N, Q;
	cin >> N >> Q;
	ll black = (ll)(N - 2) * (N - 2);

	vector<int> row(N, N - 1), col(N, N - 1);
	int rowmin = N - 1, colmin = N - 1;
	while (Q--) {
		int q, x;
		scanf("%d %d", &q, &x); --x;
		if (q == 1) {
			// col x
			if (colmin > x) {
				FOR(i, x, colmin) col[i] = col[colmin];
				row[col[x]] = x;
				colmin = x;
			}
			black -= col[x] - 1;
		}
		else {
			// row x
			if (rowmin > x) {
				FOR(i, x, rowmin) row[i] = row[rowmin];
				col[row[x]] = x;
				rowmin = x;
			}
			black -= row[x] - 1;
		}
	}

	cout << black << endl;
	return 0;
}

