//aのb乗mod c
int kurikaesijijou(int a,int b,int c){
  a%=c;
  if(b==0)
    return 1;
  if(b%2==0){
    int d=kurikaesijijou(a,b/2,c);
    d%=c;
    return d*d%c;
  }
  return a*kurikaesijijou(a,b-1,c)%c;
}
int waINF(int a){
  if(a>=0)
    return a%INF;
  return (a+INF*INF)%INF;
}
