template<typename T>
struct BIT {
    int N;
    vector<T> data;
    BIT(int N) : N(N) {
        data.resize(N+1,0);
    }
    T sum(int k) {
        T res=0;
        for(;k>0;k-=k&-k) {
            res+=data[k];
        }
        return res;
    }
    void add(int k, T x) {
        for(;k<=N;k+=k&-k) {
            data[k]+=x;
        }
    }
    int lowerBound(int w) {
        if (w<=0) return 0;
        int x=0;
        int k=1;
        while(k*2<=N) k*=2;
        for (;k>0;k/=2) {
            if(x+k<=N&&data[x+k]<w){
                w-=data[x+k];
                x+=k;
            }
        }
        return x+1;
    }
};

int main(){
	ll n, q; cin >> n >> q;
	BIT<int> rr(n), uu(n);
	ll ans=(n-2)*(n-2);
	while(q--){
