template<typename T = long long>
class SegmentTree {
    void update(int k) {
        while (k > 0) {
            k = (k - 1) / 2;
            ary[k] = ope(ary[2 * k + 1], ary[2 * k + 2]);
        }
    }
public:
    std::vector<T> ary;
    int n;
    const T default_value = std::numeric_limits<T>::max() / 4;
    SegmentTree(int n) {
        this->n = 1;
        while (this->n < n) this->n *= 2;
        ary.resize(this->n * 2 - 1, default_value); // sum -> 0, min -> INF, 0?
    }
    T ope(T l, T r) {
        return std::min(l, r);
    }
    void add(int k, T d) {
        k += n - 1;
        ary[k] += d;
        update(k);
    }
    void update(int k, T d) {
        k += n - 1;
        if (d >= ary[k]) return;
        ary[k] = d;
        update(k);
    }
    T query(int a, int b) {
        return query(a, b, 0, n, 0);
    }
    T query(int a, int b, int l, int r, int i) {
        if (a <= l && b >= r) return ary[i];
        //if (a >= r || b <= l) return 0; // sum
        if (a >= r || b <= l) return default_value; // min
        int m = (l + r) / 2;
        T vl = query(a, b, l, m, 2 * i + 1);
        T vr = query(a, b, m, r, 2 * i + 2);
        return ope(vl, vr);
    }
};

void solve() {
    int n,q;
    cin >> n >> q;
    int t,x;
    LL ans = 1LL * (n-2) * (n-2);

    SegmentTree<> l(n),r(n);
    REP(i,0,n) l.update(i,n);
    REP(i,0,n) r.update(i,n);
    REP(i,0,q) {
        cin >> t >> x;
        if (t == 1) {
            int v = l.query(x,n);
            // dump(v);
            ans -= v - 2;
            r.update(v-1,x);
        } else {
            int v = r.query(x,n);
            // dump(v);
            ans -= v - 2;
            l.update(v-1,x);
        }
    }
    cout << ans << endl;
}

