struct BIT {
	int n;
	vector<int> ft;

	BIT(int n) {
		this->n = n;
		ft.resize(n+1);
	}

	void update(int p, int v) {
		for (; p <= n; p += p&(-p)) {
			ft[p] += v;
		} 	
	}

	void update(int a, int b, int v) {
		update(a, v);
		update(b+1, -v);
	}

	int query(int p) {
		int sum = 0;
		for(; p > 0; p -= p&(-p)) {
			sum += ft[p];	
		}
		return sum;
	}
};

