    cin.tie(0), cout.tie(0);
    cin >> n >> q;
    ans = (n - 2) * (n - 2);
    build(root1, 1, n);
    build(root2, 1, n);
    for (int i = 1; i <= q; i++) {
        cin >> type >> x;
        if (type == 1) {
            int now = query(root1, x);

            ans -= now - 2;
            modify(root2, 2, now - 1, x);
        } else {
            int now = query(root2, x);
            ans -= now - 2;
            modify(root1, 2, now - 1, x);
        }
    }
    cout << ans;
    return 0;
}

