		{
			x = q;
			y = b;
		}
		else
		{
			x = b;
			y = q;
		}
		adin(ls[0], N-y+1, x);
		adin(ls[1], N-x+1, y);
	}
	printf("%lld\n", ans);
	return 0;
}

