ll mapping(ll l, ll r) {
  if (l == -1) {
    return r;
  } else {
    return min(l, r);
  }
}

ll composition(ll l, ll r) {
  if (r == -1) {
    return l;
  } else if (l == -1) {
    return r;
  } else {
    return min(l, r);
  }
}

ll id() { return -1; }

