long long nCk_pascar[1004][1004];
// nの値までのnCkをパスカルの三角形から求めておく
void Calc_nCk_pascar(int n){
  for (int i=0; i<=n; i++) {
    for (int j=0; j<=i; j++) {
      if (j==0 || j==i) nCk_pascar[i][j] = 1;
      else nCk_pascar[i][j] = nCk_pascar[i-1][j-1] + nCk_pascar[i-1][j];
    }
  }
  return;
}

Mint mynCk(int n, int k)
{
  if (2 * k > n)
    return mynCk(n, n - k);
  Mint retval(1);
  Mint iretval(1);
  for (int i = 0; i < k; i++)
  {
    retval *= Mint(n - i);
  }
  for (int i = 1; i <= k; i++)
  {
    iretval *= Mint(i);
  }
  return retval / iretval;
}

int tateyoko[2][500000];
int leaf = 1;
int N;
void init() {
  while(leaf<N) {
    leaf *= 2;
  }
  for (int i=0; i<500000; i++) {
    tateyoko[0][i] = N-1;
    tateyoko[1][i] = N-1;
  }
  //printf("leaf=%d, depth=%d\n", leaf, depth);
  return;
}

void print(int k){
  for (int i=0; i<N; i++) {
    printf("tateyoko[%d][%d]=%d\n",k,i+leaf,tateyoko[k][i+leaf]);
  }
}

void update(int n, int v, int k) {
  n += leaf;
  tateyoko[k][n] = std::min(tateyoko[k][n], v);
  // printf("iunput tateyoko[%d][%d]=%d\n",k,n,v);
  n /= 2;
  while(n>0) {
    tateyoko[k][n] = std::min(tateyoko[k][2*n], tateyoko[k][2*n+1]);
    n /= 2;
  }
  return;
} 

int getmin(int v, int min, int max, int L, int R, int k){
  if (max<L || R<min) {
    return 1001001001;
  } else if (min<=L && R<=max) {
    return tateyoko[k][v];
  } else {
    return std::min(getmin(v*2, min, max, L, (L+R)/2, k),
                    getmin(v*2+1, min, max, (L+R)/2+1, R, k));
  }
}

// n以上のノードの最小値を取得
