const int Maxn=200000;
int n,q;
struct Segment_Node{
	int lson,rson;
	int num,lazy;
}seg[Maxn*100+5];
int Root_1,Root_2;
int id_tot;
void update_tag(int &root,int x){
	if(root==0){
		root=++id_tot;
	}
	seg[root].lazy=x;
	seg[root].num=x;
}
void push_down(int root){
	if(seg[root].lazy==-1){
		return;
	}
	update_tag(seg[root].lson,seg[root].lazy);
	update_tag(seg[root].rson,seg[root].lazy);
	seg[root].lazy=-1;
}
void update(int l,int r,int a,int &root,int left=1,int right=n-2){
	if(l>right||r<left){
		return;
	}
	if(root==0){
		root=++id_tot;
		seg[root].lazy=-1;
	}
	if(l<=left&&r>=right){
		seg[root].num=a;
		seg[root].lazy=a;
		return;
	}
	push_down(root);
	int mid=(left+right)>>1;
	update(l,r,a,seg[root].lson,left,mid);
	update(l,r,a,seg[root].rson,mid+1,right);
}
int query(int x,int root,int left=1,int right=n-2){
	if(left==right){
		return seg[root].num;
	}
	if(root==0){
		return n-2;
	}
	push_down(root);
	int mid=(left+right)>>1;
	if(x<=mid){
		return query(x,seg[root].lson,left,mid);
	}
	else{
		return query(x,seg[root].rson,mid+1,right);
	}
}
int main(){
	scanf("%d%d",&n,&q);
	ll num=1ll*(n-2)*(n-2);
	update(1,n-2,n-2,Root_1);
	update(1,n-2,n-2,Root_2);
	int last_1=n-2,last_2=n-2;
	for(int i=1;i<=q;i++){
		int op,x;
		scanf("%d%d",&op,&x);
		x--;
		if(op==1){
			int tmp=query(x,Root_1);
			num-=tmp;
			if(x<=last_1){
				update(1,last_2,x-1,Root_2);
				last_1=x-1;
			}
		}
		else{
			int tmp=query(x,Root_2);
			num-=tmp;
			if(x<=last_2){
				update(1,last_1,x-1,Root_1);
				last_2=x-1;
			}
		}
	}
	printf("%lld\n",num);
	return 0;
}

