template <class T>
class bsegment_tree {
   public:
    ll size;
    vector<T> data;
    T default_value;

    bsegment_tree(ll n, T default_value_) {
        default_value = default_value_;

        ll siz = 1;
        while (siz < n) {
            siz = siz * 2;
        }
        data.resize(siz * 2, default_value);
        size = siz;
    }

    ~bsegment_tree() {}

    T compare(T& a, T& b) {
        //  ここをカスタム ex) min
        return min(a, b);
    }

    void update(ll k, T value) {
        // 葉の節点
        k += size - 1;
        data[k] = value;

        while (k > 0) {
            // 順に親に向かっていく
            k = (k - 1) / 2;
            data[k] = compare(data[k * 2 + 1], data[k * 2 + 2]);
        }
    }

    // [a, b) で compare 最強のもの
    T query(ll a, ll b, ll k, ll l, ll r) {
        if (r <= a || b <= l) {  // 共通要素がない
            return default_value;
        }
        if (a <= l && r <= b) {  // 完全に含んでいる
            return data[k];
        }

        // 2つの子の compare で勝つほう
        T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return compare(vl, vr);
    }

    T query(ll a, ll b) {
        return query(a, b, 0, 0, size);
    }
};

using segment_tree = bsegment_tree<ll>;

int main() {
    ll N, Q;
    cin >> N >> Q;

    auto min_hori = segment_tree(N + 1, N);
    auto min_vert = segment_tree(N + 1, N);

    ll darks = (N - 2) * (N - 2);
    for (ll i = 0; i < Q; i++) {
        ll qtype, x;
        cin >> qtype >> x;
        if (qtype == 1) {
            ll hori = min_hori.query(x, N + 1);
            if (min_vert.query(hori, hori + 1) > x) {
                min_vert.update(hori, x);
            }
            darks = darks - hori + 2;
        } else {
            ll vert = min_vert.query(x, N + 1);
            if (min_hori.query(vert, vert + 1) > x) {
                min_hori.update(vert, x);
            }
            darks = darks - vert + 2;
        }
    }
    print(darks);
}

