#define SEGLEN (1 << 18)
struct SegmentTree {
  vll seg;

  void initialize(ll v) {
    seg.resize(SEGLEN * 2);
    rep(i, SEGLEN * 2) seg[i] = v;
  }

  void update(ll l, ll r, ll v) {
    l += SEGLEN;
    r += SEGLEN;
    while (l < r) {
      if (l % 2 == 1) {
        chmin(seg[l], v);
        ++l;
      }
      l /= 2;
      if (r % 2 == 1) {
        chmin(seg[r - 1], v);
        --r;
      }
      r /= 2;
    }
  }

  ll get(ll i) {
    i += SEGLEN;
    ll res = seg[i];
    seg[i] = 0;
    while (true) {
      i /= 2;
      if (i == 0) break;
      chmin(res, seg[i]);
    }
    return res;
  }
};

