struct node
{
	int v = n;
	int lazy = n;
	bool islazy = false;
	// only used to assign value to leaf nodes in build and pupd
	void assign(int val) {
		v = min(v, val);
	}
	// used in build, rquery, pupd, rupd
	void merge(node &l, node &r) {
		v = min(l.v, r.v);
	}
};

struct SegTree
{
	int32_t len = 0;
	node zero;
	vector<node> t;

	SegTree (int32_t _len) {
		len = _len;
		t.resize((len << 2) + 10);
	}
	SegTree () {
		len = maxn;
		t.resize((len << 2) + 10);
	}

	//if a node has lazy tag then its info is correct but its children's info
	//is old, so pushdown() before going into children
	inline void pushdown(int32_t v, int32_t tl, int32_t tr) {
		if (!t[v].islazy) { return; }

		int32_t tm = (tl + tr) >> 1;
		apply((v << 1), tl, tm, t[v].lazy);
		apply(((v << 1) | 1), tm + 1, tr, t[v].lazy);

		t[v].lazy = zero.lazy;
		t[v].islazy = false;
		return;
	}
	//apply() is an auxillary function to apply range update and set lazy tag
	inline void apply(int32_t v, int32_t tl, int32_t tr, int val) {
		if (tl != tr) {
			t[v].lazy = min(t[v].lazy, val);				// modify the lazy by val, eg. lazy += val
			t[v].islazy = true;
		}
		// incorporate the change (=val) in node
		t[v].v = min(t[v].v, val);
		return;
	}
	void build(int a[], int32_t v, int32_t tl, int32_t tr) {
		if (tl == tr) {
			t[v].assign(a[tl]);
			return;
		}
		int32_t tm = (tl + tr) >> 1;
		build(a, (v << 1), tl, tm);
		build(a, ((v << 1) | 1), tm + 1, tr);
		t[v].merge(t[(v << 1)], t[((v << 1) | 1)]);
		return;
	}
	void build(int a[]) {
		build(a, 1, 0, len - 1);
		return;
	}
	node pquery(int32_t v, int32_t tl, int32_t tr, int32_t pos) {
		if (tl == tr) {
			return t[v];
		}
		pushdown(v, tl, tr);
		int32_t tm = (tl + tr) >> 1;
		if (pos <= tm) {
			return pquery((v << 1), tl, tm, pos);
		}
		else {
			return pquery(((v << 1) | 1), tm + 1, tr, pos);
		}
	}
	node pquery(int32_t pos) {
		return pquery(1, 0, len - 1, pos);
	}
	node rquery(int32_t v, int32_t tl, int32_t tr, int32_t l, int32_t r) {
		if (l > tr || r < tl) {
			return zero;
		}
		if (l <= tl && tr <= r) {
			return t[v];
		}
		pushdown(v, tl, tr);
		int32_t tm = (tl + tr) >> 1;
		node a, b, ans;
		a = rquery((v << 1), tl, tm, l, r);
		b = rquery(((v << 1) | 1), tm + 1, tr, l, r);
		ans.merge(a, b);
		return ans;
	}
	node rquery(int32_t l, int32_t r) {
		return rquery(1, 0, len - 1, l, r);
	}
	void pupd(int32_t v, int32_t tl, int32_t tr, int32_t pos, int val) {
		if (tl == tr) {
			t[v].assign(val);
			return;
		}
		pushdown(v, tl, tr);
		int32_t tm = (tl + tr) >> 1;
		if (pos <= tm) {
			pupd((v << 1), tl, tm, pos, val);
		}
		else {
			pupd(((v << 1) | 1), tm + 1, tr, pos, val);
		}
		t[v].merge(t[(v << 1)], t[((v << 1) | 1)]);
		return;
	}
	void pupd(int32_t pos, int val) {
		pupd(1, 0, len - 1, pos, val);
		return;
	}
	void rupd(int32_t v, int32_t tl, int32_t tr, int32_t l, int32_t r, int val) {
		if (l > tr || r < tl) {
			return;
		}
		if (l <= tl && tr <= r) {
			apply(v, tl, tr, val);
			return;
		}
		pushdown(v, tl, tr);
		int32_t tm = (tl + tr) >> 1;
		rupd((v << 1), tl, tm, l, r, val);
		rupd(((v << 1) | 1), tm + 1, tr, l, r, val);
		t[v].merge(t[(v << 1)], t[((v << 1) | 1)]);
		return;
	}
	void rupd(int32_t l, int32_t r, int val) {
		rupd(1, 0, len - 1, l, r, val);
	}
};

