        change(L,R,V,rson,rmid,r);
    }
    int query(int V,int now=1,int l=1,int r=n)
    {
        if(r<V||V<l)
        {
            return INF;
        }
        if(l==r)
        {
            return v[now];
        }
        push_down(now);
        return min(query(V,lson,l,lmid),query(V,rson,rmid,r));
    }
    void build(int now=1,int l=1,int r=n)
    {
        if(l==r)
        {
            v[now]=n;
            return;
        }
        v[now]=INF;
        build(lson,l,lmid);
        build(rson,rmid,r);
    }
}column,row;
