struct SEGTREE
{
    ll a[N];
    SEGTREE(){ mem0(a); }
    node tree[4*N];
    void buildTree(ll v,ll st,ll en)
    {
        if(st==en)
        {
            tree[v].sum = n;
            return ;
        }
        ll mid=(st+en)>>1;
        buildTree(v<<1,st,mid);
        buildTree(v<<1 | 1,mid+1,en);
    }
    void update(ll v,ll st,ll en,ll l,ll r,ll val)
    {
        if(l>r)
            return ;
        if(en<l || st>r)return ;
        if(st>=l && en<=r)
        {
            amin(tree[v].sum,val);
            return ;
        }
        ll mid=(st+en)>>1;
        update(v<<1,st,mid,l,r,val);
        update(v<<1 | 1,mid+1,en,l,r,val);
    }
    ll query(ll v,ll st,ll en,ll x)
    {
        if(st==en)
            return tree[v].sum;
        ll u = tree[v].sum;
        ll mid = (st+en)/2;
        if(x<=mid)
            return min(u,query(v<<1,st,mid,x));
        else
            return min(u,query(v<<1|1,mid+1,en,x));
    }
}segr,segc;

