const int N = 5000005;
int n, q;
struct Seg{
  #define ls (u<<1)
  #define rs (u<<1|1)
  int minn[N],tag[N];
  void pushup(int u){
    minn[u]=min(minn[ls],minn[rs]);
  } 
  void pushdown(int u){
    if(tag[u]!=1e9){
      tag[ls]=min(tag[ls],tag[u]);
      tag[rs]=min(tag[rs],tag[u]);
      minn[ls]=min(minn[ls],tag[u]);
      minn[rs]=min(minn[rs],tag[u]);
      tag[u]=1e9;
    }
  }
  void build(int u,int l,int r){
    tag[u]=1e9,minn[u]=n;
    if(l==r)return;
    int mid=l+r>>1;
    build(ls,l,mid),build(rs,mid+1,r);
  }
  void update(int u,int l,int r,int ql,int qr,int dlt){
    pushdown(u);
    if(ql<=l&&r<=qr){
      minn[u]=min(minn[u],dlt);
      tag[u]=min(tag[u],dlt);
      return;
    }
    pushdown(u);
    int mid=l+r>>1;
    if(ql<=mid)update(ls,l,mid,ql,qr,dlt);
    if(qr>mid)update(rs,mid+1,r,ql,qr,dlt);
    pushup(u);
  }
  int query(int u,int l,int r,int pos){
    pushdown(u);
    if(l==r)return minn[u];
    int mid=l+r>>1;
    if(pos<=mid)return query(ls,l,mid,pos);
    else return query(rs,mid+1,r,pos);
  }
}row,col;
signed main(){
  n=read(),q=read();
  ll ans=1ll*(n-2)*(n-2);
  row.build(1,1,n);
  col.build(1,1,n);
  while(q--){
    int opt=read(),x=read();
    if(opt==1){
      int t=col.query(1,1,n,x);
      ans-=max(0ll,t-2);
      if(t-1>=2)row.update(1,1,n,2,t-1,x);
    }else{
      int t=row.query(1,1,n,x);
      ans-=max(0ll,t-2);
      if(t-1>=2)col.update(1,1,n,2,t-1,x);
    }
  }
  printf("%lld\n",ans);
  return 0;
}

