template<int SZ>
struct SegmentTree {
    int n, st[2*SZ];

    SegmentTree() {
        memset(st, 0, sizeof(st));
    }

    void init(int _n) {
        n = _n;
        for (int i=0; i<2*n; i++)
            st[i] = n - 1;
    }

    int query(int l, int r) {
        int ret = n - 1;
        for (l+=n, r+=n; l<r; l>>=1, r>>=1) {
            if (l&1) ret = min(ret, st[l++]);
            if (r&1) ret = min(ret, st[--r]);
        }
        return ret;
    }

    void update(int p, int val) {
        p += n;
        for (st[p]=min(st[p], val); p>1; p>>=1)
            st[p>>1] = min(st[p], st[p^1]);
    }
};
