struct RangeSumRangeUpdate {
    using NodeType = T;
    using LazyType = U;
    static constexpr NodeType unitnode = 0;
    static constexpr LazyType unitlazy = 1e9 + 1;
    static constexpr NodeType funcNode(NodeType l, NodeType r) {
