	upd(segs[1], n, n, 1, 1, n);
	while(q--) {
		int opt, x;
		cin >> opt >> x;
		if(opt == 1) {
			int maxi = qry(segs[0], x, 1, 1, n);
			maxi--;
			// cout << "maxi = " << maxi << '\n';
			ans += maxi-1;
			upd(segs[1], x, maxi, 1, 1, n);
		}
		else {
			int maxi = qry(segs[1], x, 1, 1, n);
			maxi--;
			// cout << "maxi = " << maxi << '\n';
			ans += maxi-1;
			upd(segs[0], x, maxi, 1, 1, n);
		}
	}
	cout << (n-2)*1ll*(n-2) - ans << '\n';

	return 0;
}

