    BIT(int n){
        this->vs.assign(n+1, 0);
        this->n = n;
    }

    void update(T i, T delta){
        for (;i <= n;i += i&(-i)) vs[i] = max(vs[i], delta);
    }

    T query(T i){
        T sum = 0;
        for (;i;i -= i&(-i)) sum = max(sum, vs[i]);
		return sum;
    }

    int size(){
        return n;
    }
};

ll bs(BIT<ll>& vs, ll val){
    int r = vs.size(), l = 0;

    while (l < r-1){
        int mid = (l+r)/2;
        int v = vs.query(mid);

        if (v <= val){
            l = mid;
        }
        else {
            r = mid;
        }
    }
    return r;
}
int main (){
    ios_base::sync_with_stdio(false);
    ll n, q, ans;
    cin >> n >> q;
    BIT<ll> r(n+1), c(n+1);
    r.update(n, n);
    c.update(n, n);
    ans = (n-2)*(n-2);
    for (int i=0; i<q; i++){
        int a, b;
        ll pos;
        cin >> a >> b;
        if (a == 1){
            pos = bs(r, b);
            ans -= (pos -2);
            c.update(b, pos);
        }
        else {
            pos = bs(c, b);
            ans -= (pos-2);
            r.update(b, pos);
        }
       //  cout << pos << " " << ans << endl;
    }

    cout << ans << endl;
    return 0;   
}

