// For row query R: find first column queried so far. That was before any higher row queries.
// Sorting by low/high and by time.
//
// Find earliest row query < R = ER
// Find first column query that occurred earlier than ER

// given points (x,y)
// Support queries: give me smallest y s.t. exists point (x,y) with x<X
// store them sorted by X descending by Y.
// Query: lookup first thing in map <X. Return corresponding y.
//
// Add: If thing to my left is smaller, delete me.
// While thing to my right is bigger, delete it.
struct Query {
  Query(ll n_) : n(n_) {}
  void add(ll x, ll y) {
    assert(M.count(x)==0);
    if(M.size() > 0) {
      auto it = M.lower_bound(x);
      if(it != M.begin()) {
        it--;
        if(it->second < y) { return; } // I am worse
        it++;
      }
      while(it!=M.end() && it->second > y) {
        it = M.erase(it);
      }
    }
    M.insert({x, y});
  }
  ll query(ll X) {
    auto it = M.lower_bound(X);
    if(it==M.begin()) {
      return n;
    } else {
      it--;
      return it->second;
    }
  }
  map<ll,ll> M;
  ll n;
};

int main() {
  ll n,q;
  cin >> n >> q;
  ll ans = (n-2)*(n-2);
  Query EC(n); // pos -> earliest column < pos
  Query FC(n); // time -> first column earlier than time
  Query ER(n);
  Query FR(n);
  /*EC.add(n, 0);
  FC.add(0, n);
  ER.add(n, 0);
  FR.add(0, n);*/
  for(ll i=1; i<=q; i++) {
    ll typ,pos;
