    if(typ == 1) { // col
      ll ec = EC.query(pos);
      ll fr = FR.query(ec);
      removed = fr-2;
      EC.add(pos, i);
      FC.add(i, pos);
    } else {
      ll er = ER.query(pos);
      ll fc = FC.query(er);
      //cerr << "pos=" << pos << " er=" << er << " fc=" << fc << endl;
      removed = fc-2;
      ER.add(pos, i);
      FR.add(i, pos);
    }
    ans -= removed;
    //cerr << "typ=" << typ << " pos=" << pos << " removed=" << removed << " ans=" << ans << endl;
  }
  cout << ans << endl;
}

