struct item{
    long long int c;
};

struct segtree{
    long long int sizet;
    vector<item> tree;
    vector<item> lazy;

    void init(long long int n){
        sizet = 1;
        while(sizet < n) sizet *= 2;
        tree.assign(2LL*sizet, single(n-1));
        lazy.assign(2LL*sizet, single(LLONG_MAX-1));
        return ;
    }
    item single(long long int val){
        return {val};
    }

    item NO_OPERATION = single(LLONG_MAX-1);
    item NEUTRAL_ELEMENT = single(0); // For minimum

    item modify_op(item a, item b, long long int len){
        if(b.c == NO_OPERATION.c){
            return a;
        }else{
            return {min(a.c, b.c)};
        }
    }

    item merger(item a, item b){
        return single(min(a.c, b.c));
    }

    void apply_modify_op(item &a, item b, long long int len){
        a = modify_op(a,b,len);
        return ;
    }

    void build(int x, int lx, int rx, vector<long long int> &arr, long long int n){
        if(rx -lx == 1){
            if(lx < n){
                tree[x] = single(arr[lx]);
            }
            return ;
        }
        int m = (lx+rx)/2;
        build(2*x+1, lx, m, arr, n);
        build(2*x+2, m, rx, arr, n);
        tree[x] = merger(tree[2*x+1], tree[2*x+2]);
        return ;
    }
    void build(vector<long long int> &arr){
        long long int n = arr.size();
        build(0, 0, sizet, arr, n);
        return ;
    }
    void propagate(int x, int lx, int rx){
        if(rx -lx == 1){
            return ;
        }
        int m = (lx+rx)/2;
        apply_modify_op(tree[2*x+1], lazy[x], m-lx);
        apply_modify_op(lazy[2*x+1], lazy[x], 1);
        apply_modify_op(tree[2*x+2], lazy[x], rx-m);
        apply_modify_op(lazy[2*x+2], lazy[x], 1);
        lazy[x] = NO_OPERATION;
        return ;
    }

    void modify(int l, int r, long long int val, int x, int lx, int rx){
        if(l >= rx || lx >= r){
            return ;
        }
        propagate(x, lx, rx);
        if( l <= lx && rx <= r){
            apply_modify_op(tree[x],single(val),rx-lx);
            apply_modify_op(lazy[x],single(val),1);
            return ;
        }
        int m = (lx+rx)/2;
        modify(l, r, val, 2*x+1, lx, m);
        modify(l, r, val, 2*x+2, m, rx);
        tree[x] = merger(tree[2*x+1], tree[2*x+2]);
        return ;
    }

    void modify(int l, int r, long long int val){
        modify(l, r, val, 0, 0, sizet);
        return ;
    }

    item get(int i, int x, int lx, int rx){

        propagate(x ,lx, rx);
        if(rx-lx == 1){
            return tree[x];
        }
        int m = (lx+rx)/2;
        if(i < m){
