// Myslienka: Ak by sme pre kazdu query vedeli povedat, na aky stlpec/riadok narazime
// vedeli by sme efektivne vediet odcitat pocet ciernych kamienkov. Na to potrebujeme
// datovu strukturu, ktora efektivne zvlada dva typy operacii:
// - Povedz, ake cislo je na policku x.
// - Zmen vsetky cisla na polickach l az r na min(cislo_i, x).
// To znie ako nejaky upraveny intervalac.
// Kazdy vrchol si pamata lazy hodnotu, kazdy list si pamata svoju hodnotu
class intervalac
{
    int N;
    vector<int> l, r;
    vector<int> val;
    void unlazy(int vr)
    {
        val[vr * 2 + 1] = min(val[vr * 2 + 1], val[vr]);
        val[vr * 2 + 2] = min(val[vr * 2 + 2], val[vr]);
    }
public:
    intervalac(int n): N(n)
    {
        int n2 = 1;
        while (n2 < n)
        {
            n2 <<= 1;
        }
        l.resize(n2 * 2);
        r.resize(n2 * 2);
        val.resize(n2 * 2, n);
        for (int i = n2 - 1; i < n2 * 2; i++)
        {
            l[i] = i - (n2 - 1);
            r[i] = i - (n2 - 1);
        }
        for (int i = n2 - 2; i >= 0; i--)
        {
            l[i] = l[i * 2 + 1];
            r[i] = r[i * 2 + 2];
        }
    }
    void update(int li, int ri, int x, int vr = 0)
    {
        if (li > r[vr] || ri < l[vr])
        {
            return;
        }
        if (li <= l[vr] && r[vr] <= ri)
        {
            val[vr] = min(val[vr], x);
            return;
        }
        unlazy(vr);
        update(li, ri, x, vr * 2 + 1);
        update(li, ri, x, vr * 2 + 2);
    }
    int value(int i, int vr = 0)
    {
        if (l[vr] > i || r[vr] < i)
        {
            return -1;
        }
        if (l[vr] == i && r[vr] == i)
        {
            return val[vr];
        }
        unlazy(vr);
        return max(value(i, vr * 2 + 1), value(i, vr * 2 + 2));
    }
};
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    ll n, q;
    cin >> n >> q;
    ll ans = (n - 2ll) * (n - 2ll);
    intervalac i1(n), i2(n);
    for (int i = 0; i < q; i++)
    {
        int typ, x;
        cin >> typ >> x;
        if (typ == 1)
        {
            // i1, ktory narazi na i2
            int zastavi = i2.value(x);
            zastavi--;
            ans -= ll(zastavi-1);
            i1.update(0, zastavi, x);
            //cout << x << " zastavi sa na " << zastavi + 1 << "\n";
        }
        else
        {
            int zastavi = i1.value(x);
            zastavi--;
            ans -= ll(zastavi-1);
            i2.update(0, zastavi, x);
            //cout << x << " zastavi sa na " << zastavi + 1 << "\n";
        }
    }
    cout << ans << "\n";
    return 0;
}

