template <class T, class E>
struct SegmentTree {
    using F = function<T(T, T)>;
    using G = function<T(T, E)>;
    using H = function<E(E, E)>;
    using P = function<E(E, int)>;
    int n;
    F f; // minなら[](ll a, ll b) { return min(a,b);}
    G g; // pで変換したものをdataに移す時
    H h; // lazyを遷移させる時
    P p; // lazyを必要な形に変換(sumならmultipler, minなら初期のまま)
    T d1; // datの初期値かつ単位元
    E d0; // lazyの初期値
    vector<T> dat;
    vector<E> laz;
    SegmentTree(
        int n_, F f, G g, H h, T d1, E d0, vector<T> v = vector<T>(),
        P p = [](E a, int b) { return a; })
        : f(f), g(g), h(h), d1(d1), d0(d0), p(p) {
        init(n_);
        if (n_ == (int)v.size()) build(n_, v);
    }
    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat.clear();
        dat.resize(2 * n - 1, d1);
        laz.clear();
        laz.resize(2 * n - 1, d0);
    }
    void build(int n_, vector<T> v) {
        for (int i = 0; i < n_; i++) dat[i + n - 1] = v[i];
        for (int i = n - 2; i >= 0; i--)
            dat[i] = f(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
    inline void eval(int len, int k) {
        if (laz[k] == d0) return;
        if (k * 2 + 1 < n * 2 - 1) {
            laz[k * 2 + 1] = h(laz[k * 2 + 1], laz[k]);
            laz[k * 2 + 2] = h(laz[k * 2 + 2], laz[k]);
        }
        dat[k] = g(dat[k], p(laz[k], len));
        laz[k] = d0;
    }
    T update(int a, int b, E x, int k, int l, int r) {
        eval(r - l, k);
        if (r <= a || b <= l) return dat[k];
        if (a <= l && r <= b) {
            laz[k] = h(laz[k], x);
            return g(dat[k], p(laz[k], r - l));
        }
        return dat[k] = f(update(a, b, x, k * 2 + 1, l, (l + r) / 2),
                          update(a, b, x, k * 2 + 2, (l + r) / 2, r));
    }
    T update(int a, int b, E x) { return update(a, b, x, 0, 0, n); }
    T _query(int a, int b, int k, int l, int r) {
        eval(r - l, k);
        if (r <= a || b <= l) return d1;
        if (a <= l && r <= b) return dat[k];
        T vl = _query(a, b, k * 2 + 1, l, (l + r) / 2);
        T vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
        return f(vl, vr);
    }
    T query(int a, int b) { return _query(a, b, 0, 0, n); }
    /* debug */
    void _print(int a) { cout << " " << dat[n-1+a];}
    void print() {
        for(int i=0; i<n; i++) _print(i);
        cout << endl;
    }
};
int main() {
    ll n,q;cin>>n>>q;
    ll shiro = 0;
    auto f = [](ll a, ll b) { return min(a,b);};
    SegmentTree<ll,ll> ch1(n, f, f, f, LINF, LINF,
                             vector<ll>(n, n-2));
    SegmentTree<ll,ll> ch2(n, f, f, f, LINF, LINF,
                             vector<ll>(n, n-2));

    while(q--) {
        int k,x;
        cin >> k >> x;x--;
        if(k==1) {
            ll cur = ch1.query(x,x+1);
            if(cur>=0) shiro += cur;
            ch2.update(0, cur+1, x-1);
            debug(cur);
        } else {
            ll cur = ch2.query(x,x+1);
            if(cur>=0) shiro += cur;
            ch1.update(0, cur+1, x-1);
            debug(cur);
        }
    }
    ll ans = (n-2)*(n-2) - shiro;
    cout << ans << endl;
}

