int n, q;

int main(){
  scanf("%d %d", &n, &q);
  Tour rows(n), cols(n);
  rows.build(); cols.build();

  ll ans = (ll)(n - 2) * (ll)(n - 2);

  while(q--){
    int f, x; scanf("%d %d", &f, &x);
    if(f == 1){
      //x-ta kolona, spustam dolje
      int dokle = rows.query(x);
      ans -= (ll)(dokle - 2);
      cols.update(x, dokle);
