	long long ans = (xN + 1)*(yN + 1);
	for (int i = xN + 1; i < N - 2; ++i) {
		ans += A[i];
	}
	for (int i = yN + 1; i < N - 2; ++i) {
		ans += B[i];
	}
	cout << ans << endl;
	return 0;
}

