  while(q--){
    int opt=read(),x=read();
    if(opt==1){
      int t=col.query(1,1,n,x);
      //printf("opt = 1, t=%d\n",t);
      ans-=max(0ll,t-2);
      if(t-1>=2)row.update(1,1,n,2,t-1,x);
    }else{
      int t=row.query(1,1,n,x);
      ans-=max(0ll,t-2);
      if(t-1>=2)col.update(1,1,n,2,t-1,x);
    }
    //printf("%lld\n",ans);
