class RUQ {
  private:
    int size, length;
    std::vector<int> node;
    RUQ() {}
    int find(int return_index, int index, int left, int right) {
        if (node[index] != -1)
            return node[index];
        if ((left + right) / 2 < return_index)
            return find(return_index, index * 2 + 1, (left + right) / 2 + 1, right);
        return find(return_index, index * 2, left, (left + right) / 2);
    }
    void update(int left, int right, int element, int index, int i_left, int i_right) {
        if (element == node[index])
            return;
        if (left <= i_left && i_right <= right) {
            node[index] = element;
            return;
        }
        if (node[index] != -1) {
            node[index * 2] = node[index];
            node[index * 2 + 1] = node[index];
            node[index] = -1;
        }
        int middle = (i_left + i_right) / 2;
        if (middle >= left)
            update(left, right, element, index * 2, i_left, middle);
        if (middle < right)
            update(left, right, element, index * 2 + 1, middle + 1, i_right);
    }

  public:
    RUQ(int size,int def) {
        this->size = getSegTreeSize(size) / 2;
        this->length = getSegTreeSize(size);
        node.resize(this->length);
        fill(node.begin(), node.end(), def);
    }
    void update(int left, int right, int element) {
        update(left, right, element, 1, 1, size);
    }
    int find(int index) {
        return find(index, 1, 1, size);
    }
};

