const int N=200005;
int n,q,ans;
struct seg
{
	int tr[N<<2];
	void build(int k,int l,int r)
	{
		tr[k]=(k==1?n:1e9);
		if(l==r)
			return;
		int mid=l+r>>1;
		build(k<<1,l,mid);
		build(k<<1|1,mid+1,r);
	}
	void update(int k,int l,int r,int a,int b,int v)
	{
		if(l==a&&r==b)
		{
			tr[k]=min(tr[k],v);
			return;
		}
		int mid=l+r>>1;
		if(b<=mid) update(k<<1,l,mid,a,b,v);
		else if(a>mid) update(k<<1|1,mid+1,r,a,b,v);
		else update(k<<1,l,mid,a,mid,v),update(k<<1|1,mid+1,r,mid+1,b,v);
	}
	int query(int k,int l,int r,int x)
	{
		if(l==r)
			return tr[k];
		int mid=l+r>>1;
		if(x<=mid) return min(tr[k],query(k<<1,l,mid,x));
		else return min(tr[k],query(k<<1|1,mid+1,r,x));
	}
}t1,t2;
signed main()
{
	ios::sync_with_stdio(false);
	cin>>n>>q;
	ans=(n-2)*(n-2);
	t1.build(1,1,n);
	t2.build(1,1,n);
	while(q--)
	{
		int t,x;
		cin>>t>>x;
		if(t==1)
		{
			int v=t2.query(1,1,n,x);
			ans-=v-2;
			t1.update(1,1,n,1,v,x);
		}
		else
		{
			int v=t1.query(1,1,n,x);
			ans-=v-2;
			t2.update(1,1,n,1,v,x);
		}
	}
	cout<<ans<<endl;
	return 0;
}

