#include <bits/stdc++.h>
using namespace std;
int N, Q;
const int INF = INT_MAX;
struct LazySegmentTree {
private:
    int n;
    vector<int> node, lazy;
    vector<bool> lazyFlag;
public:
    LazySegmentTree(vector<int> v) {
        int sz = (int)v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, INF);
        lazyFlag.resize(2*n-1, false);
        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1], node[i*2+2]);
    }

    void lazyEvaluate(int k, int l, int r) {
        if(lazyFlag[k]) {
            node[k] = lazy[k];
            if(r - l > 1) {
                lazy[k*2+1] = lazy[k*2+2] = lazy[k];
                lazyFlag[k*2+1] = lazyFlag[k*2+2] = true;
            }
            lazyFlag[k] = false;
        }
    }

    void update(int a, int b, int x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] = x;
            lazyFlag[k] = true;
            lazyEvaluate(k, l, r);
        }
        else {
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1], node[2*k+2]);
        }
    }
    int find(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return INF;
        if(a <= l && r <= b) return node[k];
        int vl = find(a, b, 2*k+1, l, (l+r)/2);
        int vr = find(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

int main() {
    cin >> N >> Q;
    LazySegmentTree tate(vector<int>(N,N - 1));
    LazySegmentTree yoko(vector<int>(N,N - 1));
    tate.update(N - 1,N,0); yoko.update(N - 1,N,0);
    long long ans = (long long)(N - 2)*(long long)(N - 2);
    int d = N - 1,r = N - 1;
    for(int i=0; i<Q; i++) {
        int q,x; cin >> q >> x; x--;
        if(q==1){
            int y = tate.find(x,x + 1);
            ans -= y - 1;
            if(x<r) yoko.update(0,y,x);
            tate.update(x,x + 1,0);
            r = min(r,x);
        }
        if(q==2){
            int t = yoko.find(x,x + 1);
            ans -= t - 1;
            if(x<d) tate.update(0,t,x);
            yoko.update(x,x + 1,0);
            d = min(d,x);
        }
    }
    cout << ans << endl;
}

