void pushdown(int node,int x){
	if(tr[o][node]==oo) return ;
	tr[o][ls]=min(tr[o][ls],x);
	tr[o][rs]=min(tr[o][rs],x);
	lazy[o][ls]=min(lazy[o][ls],x);
	lazy[o][rs]=min(lazy[o][rs],x);	
	lazy[o][node]=oo;
}

int query(int node,int l,int r,int pos){
	if(l>=r){
		int tmp=tr[o][node];
		tr[o][node]=0;
		return tmp;
	}
	pushdown(node,lazy[o][node]);
	int mid=(l+r)>>1;
	if(pos<=mid) return query(ls,l,mid,pos);
	else return query(rs,mid+1,r,pos);
}
void update(int node,int l,int r,int ul,int ur,int x){
	if(l>=ul && r<=ur){
		tr[o][node]=min(tr[o][node],x);
		lazy[o][node]=min(lazy[o][node],x);
		return ;
	}
	pushdown(node,lazy[o][node]);
	int mid=(l+r)>>1;
	if(ur<=mid) update(ls,l,mid,ul,ur,x);
	else if(ul>mid) update(rs,mid+1,r,ul,ur,x);
	else{ update(ls,l,mid,ul,mid,x); update(rs,mid+1,r,mid+1,ur,x); }
}
