const long long INF = 1000000000;

/* RMQ：[0,n-1] について、区間ごとの最小値を管理する構造体
    update(i,x): i 番目の要素を x に更新。O(log(n))
    find(a,b): [a,b) での最小の要素を取得。O(log(n))
*/
template <typename T>
struct RMQ {
    //const T INF = numeric_limits<T>::max();
    long long n;         // 葉の数
    vector<T> dat, lazy; // 完全二分木の配列
    RMQ(long long n_) : n(), dat(n_ * 4, INF), lazy(n_*4, INF) { // 葉の数は 2^x の形
        long long x = 1;
        while (n_ > x) {
            x *= 2;
        }
        n = x;
    }

    void update(long long i, T x) {
        i += n - 1;
        if(dat[i] > x) {
          dat[i] = x;
          while (i > 0) {
              i = (i - 1) / 2;  // parent
              dat[i] = min(dat[i * 2 + 1], dat[i * 2 + 2]);
          }
        }
    }

    // the minimum element of [a,b)
    T query(long long a, long long b) { return query_sub(a, b, 0, 0, n); }
    T query_sub(long long a, long long b, long long k, long long l, long long r) {
        eval(k);
        if (r <= a || b <= l) {
            return INF;
        } else if (a <= l && r <= b) {
            return dat[k];
        } else {
            T vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
            return min(vl, vr);
        }
    }

    vector<long long> getIndexes(long long L, long long R) {
        vector<long long> indexes;
        // cout << n << endl;
        // cout << (n-1+R)/(R&-R) << endl;
        for(long long a = L ? ((n-1+L)/(L&-L)-1)>>1 : 0, b = R ? ((n-1+R)/(R&-R)-1)>>1 : 0; ; b = (b-1) / 2) {
          // cout << a << " " << b << endl;
            if(a == b) {
                for(; a >= 0; a >>= 1) {
                    indexes.push_back(a);
                    a--;
                }
                break;
            }
            if(a > b) swap(a, b);
            indexes.push_back(b);
        }
        return indexes;
    }

    //[a, b)の範囲の最小値、最大値を求める
    T find(long long a, long long b)
    {   
        vector<long long> v;
        v = getIndexes(a, b);
        rep(i, v.size()) {
            eval(v[v.size()-1-i]);
        }
        long long val_left = INF;
        long long val_right = INF;
        for (a += (n - 1), b += (n - 1); a < b; a >>= 1, b >>= 1)
        {
            if ((a & 1) == 0)
            {   
                eval(a);
                val_left = min(val_left, dat[a]);
            }
            if ((b & 1) == 0)
            {   
                b--;
                eval(b);
                val_right = min(val_right, dat[b]);
            }
        }
        return min(val_left, val_right);
    }

    void eval(long long k) {
        if (lazy[k] == INF) return;  // 更新するものが無ければ終了
        if (k < n - 1) {             // 葉でなければ子に伝搬
            lazy[k * 2 + 1] = lazy[k];
            lazy[k * 2 + 2] = lazy[k];
        }
        // 自身を更新
        if(dat[k] > lazy[k]) {
          dat[k] = lazy[k];
        } 
        lazy[k] = INF;
    }
    void update(long long a, long long b, T x, long long k, long long l, long long r) {
        eval(k);
        if (a <= l && r <= b) {  // 完全に内側の時
            lazy[k] = x;
            eval(k);
        } else if (a < r && l < b) {                     // 一部区間が被る時
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);  // 左の子
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);  // 右の子
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }
    void update(long long a, long long b, T x) { update(a, b, x, 0, 0, n); }
};

int main() {
  long long N, Q;
  cin >> N >> Q;
  RMQ<long long> tree1(N);
  RMQ<long long> tree2(N);
  rep(i, N) {
    if(i == 0) continue;
    tree1.update(i, N-1);
    tree2.update(i, N-1);
  }
  long long temp = 0;
