int init(int sid, int l, int r, int id, int v) {
	if (l == r) {
		return a[sid][id] = v;
	}
	int m = (l + r) >> 1;
	return a[sid][id] = min(init(sid, l, m, id << 1, v), init(sid, m + 1, r, id << 1 | 1, v));
}

int query(int sid, int l, int r, int L, int R, int id) {
	// cerr << l << ' ' << r << ' ' << L << ' ' << R << endl;
	if (r < L || R < l) {
		return INF;
	}
	if (l == r) {
		return a[sid][id];
	}
	int m = (l + r) >> 1;
	return min({a[sid][id], query(sid, l, m, L, R, id << 1), query(sid, m + 1, r, L, R, id << 1 | 1)});
}

void update(int sid, int l, int r, int L, int R, int id, int v) {
	// cerr << l << ' ' << r << ' ' << L << ' ' << R << endl;
	if (r < L || R < l) {
		return;
	}
	if (L <= l && r <= R) {
		a[sid][id] = min(a[sid][id], v);
		return;
	}
	int m = (l + r) >> 1;
	update(sid, l, m, L, R, id << 1, v);
	update(sid, m + 1, r, L, R, id << 1 | 1, v);
	//a[sid][id] = min(a[sid][id << 1], a[sid][id << 1 | 1]);
}

