struct segt
{
	vint t, add;
	int s, e, res, val;
	segt()
	{
		t.assign(8 * n, n - 1);
		add.assign(8 * n, n - 1);
	}
	void push(int v)
	{
		int vl = v << 1, vr = vl + 1;
		t[v] = min(t[v], add[v]);
		add[vl] = min(add[vl], add[v]);
		add[vr] = min(add[vr], add[v]);
		t[vl] = min(t[vl], add[v]);
		t[vr] = min(t[vr], add[v]);
	}
	void upd_v(int v)
	{
		int vl = v << 1, vr = vl + 1;
		t[v] = min(t[vl], t[vr]);
		add[v] = min(add[v], t[v]);
	}
	int get(int _s, int _e)
	{
		s = _s;
		e = _e;
		res = n;
		query(1, 0, n);
		return res;
	}
	void query(int v, int l, int r)
	{
		if (r <= s || e <= l || l >= r)
			return;
		if (r - l > 1)
			push(v);
		if (s <= l && r <= e)
		{
			res = min(res, t[v]);
			return;
		}
		int m = (l + r) >> 1, vl = v << 1, vr = vl + 1;
		query(vl, l, m);
		query(vr, m, r);
	}
	void upd(int _s, int _e, int _val)
	{
		s = _s;
		e = _e;
		val = _val;
		upd_t(1, 0, n);
	}
	void upd_t(int v, int l, int r)
	{
		if (r <= s || e <= l || l >= r)
			return;
		push(v);
		if (s <= l && r <= e)
		{
			t[v] = add[v] = val;
			return;
		}
		int m = (l + r) >> 1, vl = v << 1, vr = vl + 1;
		upd_t(vl, l, m);
		upd_t(vr, m, r);
		upd_v(v);
	}
};

