struct SegmentTree{
    int tree[4*mx];

    void init(){
        memset(tree,0,sizeof tree);
    }

    void update(int pos, int l, int r, int idx, int value){
        if(l==r && l==idx){
            tree[pos]=value;
            return;
        }
        int mid=(l+r)>>1;
        if(idx>=l && idx<=mid) update(pos*2,l,mid,idx,value);
        if(idx>=(mid+1) && idx<=r) update(pos*2+1,mid+1,r,idx,value);
        tree[pos]=max(tree[pos*2],tree[pos*2+1]);
    }

    int query2(int pos, int l, int r, int idx){
        if(l==r) return tree[pos];
        int mid=(l+r)>>1;
        if(idx>=l && idx<=mid) return query2(pos*2,l,mid,idx);
        return query2(pos*2+1,mid+1,r,idx);
    }

    int query(int pos, int l, int r, int x){
        if(l==r) return l;
        int mid=(l+r)>>1;
        if(tree[pos*2]>=x) return query(pos*2,l,mid,x);
        return query(pos*2+1,mid+1,r,x);
    }
};

ll n,q;
SegmentTree s1,s2;

int main()
{
    ios::sync_with_stdio(0);
    cin.tie(),cout.tie();
    cin>>n>>q;
    s1.init(),s2.init();
    while(q--){
        int t,x;
        cin>>t>>x;
        if(t==1){
            if(s2.tree[1]<x) s1.update(1,1,n,x,n);
            else{
                int left=s2.query(1,1,n,x);
                s1.update(1,1,n,x,left-1);
            }
        }
        else{
            if(s1.tree[1]<x) s2.update(1,1,n,x,n);
            else{
                int down=s1.query(1,1,n,x);
                s2.update(1,1,n,x,down-1);
            }
        }
    }
    ll bad=0;
    for(int i=2;i<n;i++){
        int v=s1.query2(1,1,n,i);
        //debug()<<imie(i)imie(v);
        if(v==n) bad+=v-2;
        else if(v) bad+=v-1;
        v=s2.query2(1,1,n,i);
        //debug()<<imie(i)imie(v);
        if(v==n) bad+=v-2;
        else if(v) bad+=v-1;
    }
    ll ans=(n-2)*(n-2);
    ans-=bad;
    cout<<ans<<endl;
    return 0;
}

#include <vector>
