using namespace std;

typedef long long ll;

struct st {
	ll v, s;
	bool c;
	st *L, *R;
	void change(ll V) {
		v = V;
		c = 1;
	}
	ll get() {
		if (c) return v*s;
		return v;
	}
	void push() {
		if (c) {
			L->change(v);
			R->change(v);
		}
	}
	void pull() {
		v = L->get()+R->get();
		c = 0;
	}
};

st *build(int L, int R)
{
	st *c = new st();
	if (L == R) {
		c->v = 0;
		c->s = 1;
		c->c = 0;
		return c;
	}
	int m = (L+R)/2;
	c->L = build(L, m);
	c->R = build(m+1, R);
	c->pull();
	c->s = R-L+1;
	return c;
}

void modify(st *c, int L, int R, int x, int y, ll v)
{
	if (x > y) return;
	if (y < L || R < x) return;
	if (x <= L && R <= y) {
		c->change(v);
		return;
	}
	c->push();
	int m = (L+R)/2;
	modify(c->L, L, m, x, y, v);
	modify(c->R, m+1, R, x, y, v);
	c->pull();
}

ll query(st *c, int L, int R, int x)
{
	if (x < L || R < x) return 0;
	if (L == R) return c->get();
	c->push();
	int m = (L+R)/2;
	ll ans;
	if (x <= m) ans = query(c->L, L, m, x);
	else ans = query(c->R, m+1, R, x);
	c->pull();
	return ans;
}

int main()
{
	int n, q, c, x;
	scanf("%d%d", &n, &q);
	ll ans = ll(n-2)*ll(n-2);
	st *C = build(2, n-1), *R = build(2, n-1);
	int safeC = n, safeR = n;
	while (q--) {
		scanf("%d%d", &c, &x);
		if (c == 1) {
			if (x > safeC) ans -= query(C, 2, n-1, x);
			else ans -= ll(safeR-2), modify(C, 2, n-1, x+1, safeC-1, safeR-2), safeC = x;
		}
		else {
			if (x > safeR) ans -= query(R, 2, n-1, x);
			else ans -= ll(safeC-2), modify(R, 2, n-1, x+1, safeR-1, safeC-2), safeR = x;
		}
	}
	printf("%lld\n", ans);
}

