int n, q; ll ans; const int N = 2e5 + 100;
struct SegTree {
    int seg[N*4];
    #define lc(k) (k << 1)
    #define rc(k) (k << 1 | 1)
    void pushdown(int k) {
        seg[lc(k)] = min(seg[lc(k)], seg[k]);
        seg[rc(k)] = min(seg[rc(k)], seg[k]);
    }
    void modify(int k, int l, int r, int L, int R, int v) {
        if(L <= l && r <= R) return seg[k] = min(seg[k], v), void();
        int mid = l + r >> 1; pushdown(k);
        if(L <= mid) modify(lc(k), l, mid, L, R, v);
        if(R > mid) modify(rc(k), mid + 1, r, L, R, v);
        seg[k] = max(seg[lc(k)], seg[rc(k)]);
    }
    int query(int k, int l, int r, int x) {
        if(l == r) return seg[k];
        int mid = l + r >> 1; pushdown(k);
        if(x <= mid) return query(lc(k), l, mid, x);
        else return query(rc(k), mid + 1, r, x);
    }
    void build(int k, int l, int r) {
        if(l == r) return seg[k] = n, void();
        int mid = l + r >> 1;
        build(lc(k), l, mid), build(rc(k), mid + 1, r);
        seg[k] = n;
    }
} lie, hang;

signed main() {
    scanf("%d %d", &n, &q), ans = 1ll * (n - 2) * (n - 2);
    lie.build(1, 1, n), hang.build(1, 1, n);
    while(q--) {
        int op, x; scanf("%d %d", &op, &x);
        if(op == 1) {
            int val = hang.query(1, 1, n, x);
            ans -= val - 2;
            lie.modify(1, 1, n, 2, val - 1, x);
        } else {
            int val = lie.query(1, 1, n, x);
            ans -= val - 2;
            hang.modify(1, 1, n, 2, val - 1, x);
        }
    }
    printf("%lld\n", ans);
    fprintf(stderr, "time=%.4f\n", (db)clock()/CLOCKS_PER_SEC);
    return 0;
    /* 取模直接除，爆零两行泪
     * 不开ll见祖宗
     */
}

