struct seg_tree
{
    LL seg[4*(N+1)+215];
    LL lazy[4*(N+1)+215];
    int n;
    void build(int L, int R, int node)
    {
        lazy[node] = -1;
        if(L==R)
        {
            seg[node] = n-2;
            return;
        }
        build(L,M,2*node);
        build(M+1,R,2*node+1);
    }
    void assign_n(int n)
    {
        this->n = n;
        build(1,n,1);
    }
    void lazy_update(int L, int R, int node)
    {
        if(lazy[node]!=-1)
        {
            if(L==R)
                seg[node] = lazy[node];
            else
                lazy[2*node] = lazy[2*node+1] = lazy[node];

            lazy[node] = -1;
        }
    }
    void range_set(int L, int R, int left, int right, LL val, int node)
    {
        lazy_update(L,R,node);
        if(L > R || L > right || R < left)
            return;
        if(left <= L && R <= right)
            lazy[node] = val;
        else
        {
            range_set(L,M,left,right,val,2*node);
            range_set(M+1,R,left,right,val,2*node+1);
        }
    }
    void range_set(int left, int right, LL val)
    {
        range_set(1,n,left,right,val,1);
    }
    LL query(int L, int R, int pt, int node)
    {
        lazy_update(L,R,node);
        if(L==R)
            return seg[node];
        if(pt <= M)
            return query(L,M,pt,2*node);
        else
            return query(M+1,R,pt,2*node+1);
    }
    LL query(int pt)
    {
        return query(1, n, pt, 1);
    }
};
