template <typename Elem, typename LazyOperand>
class LazySegmentTree {
   public:
    Elem (*f)(Elem a, Elem b);
    Elem (*g)(Elem a, LazyOperand b);
    LazyOperand (*h)(LazyOperand a, LazyOperand b);
    using fTYPE = decltype(f);
    using gTYPE = decltype(g);
    using hTYPE = decltype(h);

    Elem elem_ident;
    LazyOperand lazy_operand_ident;
    vector<Elem> elems;
    vector<LazyOperand> lazy_operands;
    int n, height;

    LazySegmentTree(fTYPE f, gTYPE g, hTYPE h, Elem elem_ident, LazyOperand lazy_operand_ident)
        : f(f), g(g), h(h), elem_ident(elem_ident), lazy_operand_ident(lazy_operand_ident) {}

    void init(int n_temp) {
        n = 1;
        height = 0;
        while (n < n_temp) {
            n <<= 1;
            ++height;
        }
        elems.assign(2 * n, elem_ident);
        lazy_operands.assign(2 * n, lazy_operand_ident);
    }

    void build(const vector<Elem>& v) {
        int n_temp = v.size();
        init(n_temp);
        rep(i, n_temp) elems[n + i] = v[i];
        for (int i = n - 1; i > 0; --i) {
            elems[i] = (*f)(elems[i * 2], elems[i * 2 + 1]);
        }
    }

    inline void assign_merged_lazy(LazyOperand& dest, LazyOperand x) { dest = (*h)(dest, x); }

    inline Elem reflect(int k) {
        return (lazy_operands[k] == lazy_operand_ident) ? elems[k] : (*g)(elems[k], lazy_operands[k]);
    }

    inline void _eval(int k) {
        if (lazy_operands[k] != lazy_operand_ident) {
            assign_merged_lazy(lazy_operands[k * 2], lazy_operands[k]);
            assign_merged_lazy(lazy_operands[k * 2 + 1], lazy_operands[k]);

            elems[k] = reflect(k);
            lazy_operands[k] = lazy_operand_ident;
        }
    }

    inline void eval_down(int k) {
        for (int i = height; i > 0; --i) {
            _eval(k >> i);
        }
    }

    inline void recalc(int k) {
        while (k >>= 1) {
            elems[k] = (*f)(reflect(k * 2), reflect(k * 2 + 1));
        }
    }

    void update(int a, int b, LazyOperand x) {
        a += n;
        b += n;
        eval_down(a);
        eval_down(b - 1);
        for (int l = a, r = b; l < r; l >>= 1, r >>= 1) {
            if (l & 1) assign_merged_lazy(lazy_operands[l++], x);
            if (r & 1) assign_merged_lazy(lazy_operands[--r], x);
        }
        recalc(a);
        recalc(b - 1);
    }

    void set_val(int a, Elem e) {
        a += n;
        eval_down(a);
        elems[a] = e;
        lazy_operands[a] = lazy_operand_ident;
        recalc(a);
    }

    Elem query(int a, int b) {
        a += n;
        b += n;
        eval_down(a);
        eval_down(b - 1);
        Elem vl = elem_ident, vr = elem_ident;
        for (int l = a, r = b; l < r; l >>= 1, r >>= 1) {
            if (l & 1) vl = (*f)(vl, reflect(l++));
            if (r & 1) vr = (*f)(reflect(--r), vr);
        }
        Elem merged = (*f)(vl, vr);
        return merged;
    }

    void desc() {
    }
};

template <typename T>
class MinQueryLazySegTreeBase {
    using Elem = T;
    using LazyOperand = T;

   public:
    LazySegmentTree<Elem, LazyOperand>* st = nullptr;

   public:
    MinQueryLazySegTreeBase(int size) {}
    MinQueryLazySegTreeBase(vector<Elem>& ar) {}
    virtual ~MinQueryLazySegTreeBase() {
        if (st != nullptr) delete st;
    }

   public:
    void update(int l, int r, LazyOperand x) { st->update(l, r, x); }
    Elem query(int l, int r) { return st->query(l, r); };
    void desc() { st->desc(); };
};

template <typename T>
class AssignMinQueryLazySegTree : public MinQueryLazySegTreeBase<T> {
   public:
    using Elem = T;
    using LazyOperand = T;

    static Elem f(Elem a, Elem b) { return min(a, b); }
    static Elem g(Elem a, LazyOperand b) { return (Elem)b; }
    static LazyOperand h(LazyOperand a, LazyOperand b) { return min(a, b); }

   public:
    AssignMinQueryLazySegTree(int size) : MinQueryLazySegTreeBase<T>(size) {
        this->st = new LazySegmentTree<Elem, LazyOperand>(&f, &g, &h, (Elem)INT_MAX, (LazyOperand)INT_MAX);
        this->st->build(vector<Elem>(size, (Elem)INT_MAX));
    }
    AssignMinQueryLazySegTree(vector<Elem>& ar) : MinQueryLazySegTreeBase<T>(ar) {
        this->st = new LazySegmentTree<Elem, LazyOperand>(&f, &g, &h, (Elem)INT_MAX, (LazyOperand)INT_MAX);
        this->st->build(ar);
    }
};

template <typename T>
class AminMinQueryLazySegTree : public MinQueryLazySegTreeBase<T> {
   public:
    using Elem = T;
    using LazyOperand = T;

    static Elem f(Elem a, Elem b) { return min(a, b); }
    static Elem g(Elem a, LazyOperand b) { return min(a, (Elem)b); }
    static LazyOperand h(LazyOperand a, LazyOperand b) { return min(a, b); }

   public:
    AminMinQueryLazySegTree(int size) : MinQueryLazySegTreeBase<T>(size) {
        this->st = new LazySegmentTree<Elem, LazyOperand>(&f, &g, &h, (Elem)INT_MAX, (LazyOperand)INT_MAX);
        this->st->build(vector<Elem>(size, (Elem)INT_MAX));
    }
    AminMinQueryLazySegTree(vector<Elem>& ar) : MinQueryLazySegTreeBase<T>(ar) {
        this->st = new LazySegmentTree<Elem, LazyOperand>(&f, &g, &h, (Elem)INT_MAX, (LazyOperand)INT_MAX);
        this->st->build(ar);
    }
};


int main() {
    int N, Q;
    scanf("%d %d%*c", &N, &Q);

    AminMinQueryLazySegTree<int> horiz(N + 2), vert(N + 2);

    horiz.update(1, N, N - 2);
    vert.update(1, N, N - 2);


    auto op1 = [&](int x) -> int {
        int depth = horiz.query(x, x + 1);
        vert.update(2, 2 + depth, x - 2);
        horiz.update(x, x + 1, 0);
        return depth;
    };
    auto op2 = [&](int x) -> int {
        int depth = vert.query(x, x + 1);
        horiz.update(2, 2 + depth, x - 2);
        vert.update(x, x + 1, 0);
        return depth;
    };

    ll ans = square(N - 2);
    rep(i, Q) {
        int op, x;
        scanf("%d %d%*c", &op, &x);
        ans -= (op == 1) ? op1(x) : op2(x);
    }
    printf("%lld\n", ans);
    return 0;
}

