/* Segtree - range update, range query
 * a - Initializer array. Building is done based on array a[].
 * Check for overflows OR #define int long long!
 * Each function assumes 0-based indexing.
 */
struct node{
    int val;
    int lazy;

    node(){
        val = N + 1;
        lazy = N + 1;
    }

    void init(int x){
        val = x;
    }

    void merge(node &l, node &r){
        val = min(l.val, r.val);
    }

    void no_use(){
        /*Fill neutral values that don't affect the answer */
        val = N + 1;
        lazy = N + 1;
    }
};

//segtree - colBlock, seg1 - rowBlock
node segtree[N << 2], segtree1[N << 2];
int n, q;

/* Magic happens here! */
void propogate(int num, int start, int end, int mul){
    segtree[num].val = min(segtree[num].val, mul);
    if(start != end){
        segtree[num + num + 1].lazy = min(segtree[num + num + 1].lazy, mul);
        segtree[num + num + 2].lazy = min(segtree[num + num + 2].lazy, mul);
    }
}

//Range update. Implemented : add p in range l, r in O(logn).
void update(int num, int start, int end, int l, int r, ll p){
    if(segtree[num].lazy != n + 1){
        //If current node has updates pending, finish them first and pass on the "laziness" to the children.
        propogate(num, start, end, segtree[num].lazy);
        segtree[num].lazy = n + 1;
    }
    if(start > end || start > r || end < l) return;
    if(start >= l && end <= r){
        //If current node is fully within range, update it(lazy won't be changed here!!!).
        //Pass the laziness to children.
        propogate(num, start, end, p);
        return;
    }
    int lc = num + num + 1, rc = lc + 1;
    int mid = (start + end) >> 1;
    update(lc, start, mid, l, r, p);
    update(rc, mid + 1, end, l, r, p);
    segtree[num].merge(segtree[lc], segtree[rc]);
}

//Range Query - Returns the answer of query in O(logn) time.
node query(int num, int start, int end, int qs, int qe){
    if(start > qe || end < qs){
        node ret;
        ret.no_use();
        return ret;
    }
    if(segtree[num].lazy != n + 1){
        //If current node has updates pending, finish them first and pass on the "laziness" to the children.
        propogate(num, start, end, segtree[num].lazy);
        segtree[num].lazy = n + 1;
    }
    if(start >= qs && end <= qe){
        return segtree[num];
    }
    int lc = num + num + 1, rc = lc + 1;
    int mid = (start + end) >> 1;
    node lf = query(lc, start, mid, qs, qe);
    node rg = query(rc, mid + 1, end, qs, qe);
    node ret;
    ret.merge(lf, rg);
    return ret;
}

/* Magic happens here! */
void propogate1(int num, int start, int end, int mul){
    segtree1[num].val = min(segtree1[num].val, mul);
    if(start != end){
        segtree1[num + num + 1].lazy = min(segtree1[num + num + 1].lazy, mul);
        segtree1[num + num + 2].lazy = min(segtree1[num + num + 2].lazy, mul);
    }
}

//Range update1. Implemented : add p in range l, r in O(logn).
void update1(int num, int start, int end, int l, int r, ll p){
    if(segtree1[num].lazy != n + 1){
        //If current node has update1s pending, finish them first and pass on the "laziness" to the children.
        propogate1(num, start, end, segtree1[num].lazy);
        segtree1[num].lazy = n + 1;
    }
    if(start > end || start > r || end < l) return;
    if(start >= l && end <= r){
        //If current node is fully within range, update1 it(lazy won't be changed here!!!).
        //Pass the laziness to children.
        propogate1(num, start, end, p);
        return;
    }
    int lc = num + num + 1, rc = lc + 1;
    int mid = (start + end) >> 1;
    update1(lc, start, mid, l, r, p);
    update1(rc, mid + 1, end, l, r, p);
    segtree1[num].merge(segtree1[lc], segtree1[rc]);
}

//Range query1 - Returns the answer of query1 in O(logn) time.
node query1(int num, int start, int end, int qs, int qe){
    if(start > qe || end < qs){
        node ret;
        ret.no_use();
        return ret;
    }
    if(segtree1[num].lazy != n + 1){
