    }
};

ll bs(BIT<ll>& vs, ll val){
    int r = vs.size(), l = 0;

    while (l < r-1){
        int mid = (l+r)/2;
        int v = vs.query(mid);

        if (v < val){
            l = mid;
        }
        else {
            r = mid;
        }
    }
    return r;
}
