using namespace std;
const int N = 2e5 + 10;
int n, q;

struct ST {
	int st[4 * N];
	int lazy[4 * N];

	ST() {
		memset(lazy, 1, sizeof lazy);
	}

	void build(int v, int tl, int tr) {
		if (tl == tr) {
			st[v] = n;
			return;
		}
		int tm = (tl + tr) / 2;
		build(v * 2, tl, tm);
		build(v * 2 + 1, tm + 1, tr);
		st[v] = n;
	}

	void push(int v) {
		st[v * 2] = min(st[v * 2], lazy[v]);
		st[v * 2 + 1] = min(st[v * 2 + 1], lazy[v]);

		lazy[v * 2] = min(lazy[v * 2], lazy[v]);
		lazy[v * 2 + 1] = min(lazy[v * 2 + 1], lazy[v]);

		lazy[v] = INT_MAX;
	}

	void update(int v, int tl, int tr, int l, int r, int val) {
		if (l > r) {
			return;
		}
		if (tl == l && tr == r) {
			st[v] = min(st[v], val);
			lazy[v] = min(lazy[v], val);
			return;
		}
		push(v);
		int tm = (tl + tr) / 2;
		update(v * 2, tl, tm, l, min(r, tm), val);
		update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, val);
		st[v] = min(st[v * 2], st[v * 2 + 1]);
	}

	int query(int v, int tl, int tr, int idx) {
		if (tl == idx && tl == tr) {
			return st[v];
		}
		push(v);
		int tm = (tl + tr) / 2;
		if (idx <= tm) {
			return query(v * 2, tl, tm, idx);
		}
		return query(v * 2 + 1, tm + 1, tr, idx);
	}
};

ST stx, sty;

int query(ST &st1, ST &st2, int x) {
	int ns = st1.query(1, 1, n, x);
	st2.update(1, 1, n, 1, ns, x);
	return ns - 2;
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

