	for (int qi = 0; qi < q; qi++) {
		cin >> op >> x;

		if (op == 1) {
			ans -= (long long) query(stx, sty, x);
		}
		else {
			ans -= (long long) query(sty, stx, x);
		}
	}

	cout << ans << '\n';

	return 0;
