class RUQ{
public:
  int t[555555],v[555555],k;
  void init(){
    k=1;
    memset(t,0,sizeof(t));
    memset(v,0,sizeof(v));
  }
  void update(int a,int b,int x) {
    v[k]=x;
    update2(a,b,k);
    k++;
  }
  void update2(int a,int b,int x,int k=0,int l=0,int r=1<<18){
    if(b<=l||r<=a)return;
    if(a<=l&&r<=b){t[k]=max(t[k],x);return;}
    int m=(l+r)/2;
    update2(a,b,x,k*2+1,l,m);
    update2(a,b,x,k*2+2,m,r);
  }
  int query(int i){
    i+=(1<<18)-1;
    int res=t[i];
    while(i){
      i=(i-1)/2;
      res=max(res,t[i]);
    }
    return v[res];
  }
};

RUQ tx,ty;

void Main() {
  ll n,T;
  cin >> n >> T;
  ll sum=(n-2)*(n-2);
  tx.init(),ty.init();
  tx.update(0,n,n);
  ty.update(0,n,n);
  ll nx=n,ny=n;
  while(T--) {
    ll z,x;
    cin >> z >> x;
    if(z==1) {
      ll d=tx.query(x);
      sum-=max(0LL,d-2);
      if(x<ny) {
        ny=x;
        ty.update(1,d,ny);
      }
    } else {
      ll d=ty.query(x);
      sum-=max(0LL,d-2);
      if(x<nx) {
        nx=x;
        tx.update(1,d,nx);
      }
    }
  }
  pr(sum);
}

