struct segment_tree {
  vector <int> val;
  vector <int> mod;
  segment_tree (int n) {
    val.resize(n << 2, n - 1);
    mod.resize(n << 2, n - 1);
  }
  void push(int v) {
    mod[v * 2] = min(mod[v * 2], mod[v]);
    mod[v * 2 + 1] = min(mod[v * 2 + 1], mod[v]);
  }
  void update(int v, int tl, int tr, int l, int r, int value) {
    if (l > r) return;
    if (l == tl && r == tr) {
      mod[v] = min(mod[v], value);
      val[v] = min(mod[v], value);
      return;
    }
    int tm = (tl + tr) / 2;
    update(v * 2, tl, tm, l, min(r, tm), value);
    update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, value);
    val[v] = min({val[v], val[v * 2], val[v * 2 + 1]});
  }
  int get(int v, int tl, int tr, int l, int r) {
    if (l > r) return n - 1;
    if (l == tl && r == tr)
      return min(val[v], mod[v]);
    push(v);
    int tm = (tl + tr) / 2;
    int x = get(v * 2, tl, tm, l, min(r, tm));
    int y = get(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r);
    return min(x, y);
  }
};

