const int MAX_N = 1 << 18;//要変更 2 * 10 ^ 5
int n;
vector<ll> dat1, lazy1, dat2, lazy2;//要変更

void init(ll n_) {
  n = 1;
  while (n < n_) {
    n *= 2;
  }
}

void eval(ll k, ll l, ll r, vector<ll>& lazy, vector<ll>& dat) {
  if (lazy.at(k) != INF) {
    dat.at(k) = min(lazy.at(k), dat.at(k));//要変更
    if (r - l > 1) {
      lazy.at(k * 2 + 1) = min(lazy.at(k * 2 + 1), lazy.at(k));//要変更
      lazy.at(k * 2 + 2) = min(lazy.at(k * 2 + 2), lazy.at(k));//要変更
    }
    lazy.at(k) = INF;
  }
}

void update(ll a, ll b, ll plus, vector<ll>& lazy, vector<ll>& dat, ll k = 0, ll l = 0, ll r = n) {
  if (r <= a || b <= l) {
    eval(k, l, r, lazy, dat);//子供のlazyを更新する必要がある
    return;
  }
  if (a <= l && r <= b) {
    lazy.at(k) = min(lazy.at(k), plus);//要変更
    eval(k, l, r, lazy, dat);//子供のlazyを更新する必要がある
  }
  else {
    eval(k, l, r, lazy, dat);//updateで使う子供のlazeとdat.at(k)の更新
    update(a, b, plus, lazy, dat, k * 2 + 1, l, (l + r) / 2);
    update(a, b, plus, lazy, dat, k * 2 + 2, (l + r) / 2, r);
    dat.at(k) = min(dat.at(2 * k + 1), dat.at(2 * k + 2));//要変更
  }
}

ll query(ll a, ll b, vector<ll>& lazy, vector<ll>& dat, ll k = 0, ll l = 0, ll r = n) {
  if (r <= a || b <= l) {
    return INF;//要変更
  }
  eval(k, l, r, lazy, dat);//dat.at(k)と子供のlazy更新のためreturn datとqueryに必要
  if (a <= l && r <= b) {
    return dat.at(k);
  }
  else {
    ll vl = query(a, b, lazy, dat, k * 2 + 1, l, (l + r) / 2);
    ll vr = query(a, b, lazy, dat, k * 2 + 2, (l + r) / 2, r);
    return min(vl, vr);//要変更
  }
}
