const int N = 2e5 + 7;

int t[2][4 * N], add[2][4 * N];

void push(int nt, int v, int l, int r) {
    if (add[nt][v] == 0)
        return;
    if (l != r)
        add[nt][2 * v + 1] = add[nt][2 * v + 2] = add[nt][v];
    else
        t[nt][v] = min(t[nt][v], add[nt][v]);
    add[nt][v] = 0;
}

void change(int nt, int v, int l, int r, int R, int val) {
    push(nt, v, l, r);
    if (l > R)
        return;
    if (r <= R) {
        add[nt][v] = val;
        push(nt, v, l, r);
        return;
    }
    int m = l + r >> 1;
    change(nt, 2 * v + 1, l, m, R, val);
    change(nt, 2 * v + 2, m + 1, r, R, val);
}

int ask(int nt, int v, int l, int r, int pos) {
    push(nt, v, l, r);
    if (l > pos || r < pos)
        return 0;
    if (l == r)
        return t[nt][v];
    int m = l + r >> 1;
    return max(ask(nt, 2 * v + 1, l, m, pos), ask(nt, 2 * v + 2, m + 1, r, pos));
}

void solve() {
    int n, q;
    cin >> n >> q;
    loop(i, 4 * N)
        t[0][i] = t[1][i] = n - 1;
    int ans = 0;
    loop(i, q) {
        int type, x;
        cin >> type >> x;
        x -= 1; --type;
        int to = ask(type, 0, 0, N - 1, x);
        ans += to - 1;
        change(!type, 0, 0, N - 1, to, x);
    }
    cout << (n - 2) * (n - 2) - ans;
}

