using string = std::string;

class lazytree {
  public:
	std::vector<int> prop;
	lazytree (int n) : prop (4*n, INT_MAX) {}

	void update (int l, int r, int v, int tl, int tr, int t) {
	  if (l > r)
		return;
	  if (l == tl && r == tr)
		prop[t] = std::min (v, prop[t]);
	  else {
		int mid = (tl + tr)/2;
		update (l, std::min (r, mid), v, tl, mid, 2*t+1);
		update (std::max(l, mid+1), r, v, mid+1, tr, 2*t+2);
	  }
	}

	int query (int i, int v, int tl, int tr, int t) {
	  if (tl == tr) {
		prop[t] = std::min (v, prop[t]);
		return prop[t];
	  }
	  prop[t] = std::min (v, prop[t]);
	  int mid = (tl + tr)/2;
	  if (i <= mid)
		return query (i, prop[t], tl, mid, 2*t+1);
	  else
		return query (i, prop[t], mid+1, tr, 2*t+2);
	}
};

int main() {
  int n, q; input >> n >> q;
  lazytree mincols (n);
  mincols.update(0, n-1, n, 0, n-1, 0);
  lazytree minrows (n);
  minrows.update(0, n-1, n, 0, n-1, 0);
  lint blacks = (n-2) * (lint) (n-2);
  for (int i=0; i<q; i++) {
	int opt, x; input >> opt >> x;
	if (opt == 1) {
	  int row = minrows.query (x-1, INT_MAX, 0, n-1, 0);
	  mincols.update (0, row-1, x, 0, n-1, 0);
	  blacks -= row-2;
	} else {
	  int col = mincols.query (x-1, INT_MAX, 0, n-1, 0);
	  minrows.update (0, col-1, x, 0, n-1, 0);
	  blacks -= col-2;
	}
  }
  std::cout << blacks << std::endl;
}

