void solve_test() {
	int n, q;
	cin >> n >> q;

	vector<array<int, 2>> Q(q);
	for (int i = 0; i < q; i++)
		cin >> Q[i][0] >> Q[i][1];

	vector<array<int, 2>> Q_horizontal;
	vector<array<int, 2>> Q_vertical;
	for (int i = 0; i < q; i++) {
		int type = Q[i][0];
		int x = Q[i][1];

		if (type == 1)
			Q_horizontal.push_back({x, i});
		else
			Q_vertical.push_back({x, i});
	}
	sort(Q_horizontal.begin(), Q_horizontal.end());
	sort(Q_vertical.begin(), Q_vertical.end());

	LL blacks = (LL) (n - 2) * (n - 2);

	int w = n, h = n;
	vector<bool> marked(q);
	for (int i = 0; i < q; i++) {
		if (marked[i]) continue;

		marked[i] = true;

		int type = Q[i][0];
		int x = Q[i][1];

		if (type == 1) {
			blacks -= h - 2;
			while (!Q_horizontal.empty()) {
				int y = Q_horizontal.back()[0];
				int id = Q_horizontal.back()[1];
				if (y <= x)
					break;
				Q_horizontal.pop_back();

				if (marked[id])
					continue;

				blacks -= h - 2;
				marked[id] = true;
			}

			w = x;
		} else {
			blacks -= w - 2;
			while (!Q_vertical.empty()) {
				int y = Q_vertical.back()[0];
				int id = Q_vertical.back()[1];
				if (y <= x)
					break;
				Q_vertical.pop_back();

				if (marked[id])
					continue;

				blacks -= w - 2;
				marked[id] = true;
			}

			h = x;
		}
	}

	cout << blacks << '\n';
}

int main() {
	int T;
	T = 1;
	for (int t = 1; t <= T; t++)
		solve_test();

	return 0;
}

