template< typename OperatorMonoid >
struct DuelSegmentTree {
  using H = function< OperatorMonoid(OperatorMonoid, OperatorMonoid) >;

  int sz, height;
  vector< OperatorMonoid > lazy;
  const H h;
  const OperatorMonoid OM0;


  DuelSegmentTree(int n, const H h, const OperatorMonoid OM0)
      : h(h), OM0(OM0) {
    sz = 1;
    height = 0;
    while(sz < n) sz <<= 1, height++;
    lazy.assign(2 * sz, OM0);
  }

  inline void propagate(int k) {
    if(lazy[k] != OM0) {
      lazy[2 * k + 0] = h(lazy[2 * k + 0], lazy[k]);
      lazy[2 * k + 1] = h(lazy[2 * k + 1], lazy[k]);
      lazy[k] = OM0;
    }
  }

  inline void thrust(int k) {
    for(int i = height; i > 0; i--) propagate(k >> i);
  }

  void update(int a, int b, const OperatorMonoid &x) {
    thrust(a += sz);
    thrust(b += sz - 1);
    for(int l = a, r = b + 1; l < r; l >>= 1, r >>= 1) {
      if(l & 1) lazy[l] = h(lazy[l], x), ++l;
      if(r & 1) --r, lazy[r] = h(lazy[r], x);
    }
  }

  OperatorMonoid operator[](int k) {
    thrust(k += sz);
    return lazy[k];
  }
};



void solve(){
	ll n,t;
	cin>>n>>t;
	DuelSegmentTree<ll>row(n-2,[](ll a,ll b){return min(a,b);},n-2),
										 clm(n-2,[](ll a,ll b){return min(a,b);},n-2);
	ll ans=(n-2)*(n-2);
	while(t--){
		ll q,x;
		cin>>q>>x;
		x-=2;
		if(q==1){
			ll val=clm.operator[](x);
			ans-=val;
			row.update(0,val,x);
			clm.update(x,x+1,0);
		}
		else{
			ll val=row.operator[](x);
			ans-=val;
			clm.update(0,val,x);
			row.update(x,x+1,0);
		}
	}
	cout<<ans;
}


