/**
 * @brief a segment tree beats (range {chmin, chmax, add, update} + range {min, max, sum})
 * @docs data_structure/segment_tree_beats.md
 * @see https://codeforces.com/blog/entry/57319
 */
class SegmentTreeBeats {
	// MEMO: values for queries (max, min, lazy_add, and lazy_update) already apply to the current node; but not for children
	typedef struct {
		ll max;
		ll max_second;
		int max_count;
		ll min;
		ll min_second;
		int min_count;
		ll lazy_add;
		ll lazy_update;
		ll sum;
	} value_type;

public:
	int n;
	vector<value_type> a;

	SegmentTreeBeats() = default;
	SegmentTreeBeats(int n_) {
		n = 1; while (n < n_) n *= 2;
		a.resize(2 * n - 1);
		tag<UPDATE>(0, 0);
	}
	template <class InputIterator>
	SegmentTreeBeats(InputIterator first, InputIterator last) {
		int n_ = std::distance(first, last);
		n = 1; while (n < n_) n *= 2;
		a.resize(2 * n - 1);
		for(int i=0; i<n_; i++){
			tag<UPDATE>(n - 1 + i, *(first + i));
		}
		for(ll i=n_; i<n; i++){
			tag<UPDATE>(n - 1 + i, 0);
		}
		for(ll i=n-2; i>=0; i--){
			update(i);
		}
	}

	void range_chmin(int l, int r, ll value) {  // 0-based, [l, r)
		assert (0 <= l and l <= r and r <= n);
		range_apply<CHMIN>(0, 0, n, l, r, value);
	}
	void range_chmax(int l, int r, ll value) {  // 0-based, [l, r)
		assert (0 <= l and l <= r and r <= n);
		range_apply<CHMAX>(0, 0, n, l, r, value);
	}
	void range_add(int l, int r, ll value) {  // 0-based, [l, r)
		assert (0 <= l and l <= r and r <= n);
		range_apply<ADD>(0, 0, n, l, r, value);
	}
	void range_update(int l, int r, ll value) {  // 0-based, [l, r)
		assert (0 <= l and l <= r and r <= n);
		range_apply<UPDATE>(0, 0, n, l, r, value);
	}

	ll range_min(int l, int r) {  // 0-based, [l, r)
		assert (0 <= l and l <= r and r <= n);
		return range_get<MIN>(0, 0, n, l, r);
	}
	ll range_max(int l, int r) {  // 0-based, [l, r)
		assert (0 <= l and l <= r and r <= n);
		return range_get<MAX>(0, 0, n, l, r);
	}
	ll range_sum(int l, int r) {  // 0-based, [l, r)
		assert (0 <= l and l <= r and r <= n);
		return range_get<SUM>(0, 0, n, l, r);
	}

private:
	static constexpr char CHMIN = 0;
	static constexpr char CHMAX = 1;
	static constexpr char ADD = 2;
	static constexpr char UPDATE = 3;
	static constexpr char MIN = 10;
	static constexpr char MAX = 11;
	static constexpr char SUM = 12;

	template <char TYPE>
	void range_apply(int i, int il, int ir, int l, int r, ll g) {
		if (ir <= l or r <= il or break_condition<TYPE>(i, g)) {
			// break
		} else if (l <= il and ir <= r and tag_condition<TYPE>(i, g)) {
			tag<TYPE>(i, g);
		} else {
			pushdown(i);
			range_apply<TYPE>(2 * i + 1, il, (il + ir) / 2, l, r, g);
			range_apply<TYPE>(2 * i + 2, (il + ir) / 2, ir, l, r, g);
			update(i);
		}
	}
	template <char TYPE>
	inline bool break_condition(int i, ll g) {
		switch (TYPE) {
			case CHMIN: return a[i].max <= g;
			case CHMAX: return g <= a[i].min;
			case ADD: return false;
			case UPDATE: return false;
			default: assert (false);
		}
	}
	template <char TYPE>
	inline bool tag_condition(int i, ll g) {
		switch (TYPE) {
			case CHMIN: return a[i].max_second < g and g < a[i].max;
			case CHMAX: return a[i].min < g and g < a[i].min_second;
			case ADD: return true;
			case UPDATE: return true;
			default: assert (false);
		}
	}
	template <char TYPE>
	inline void tag(int i, ll g) {
		int length = n >> (32 - __builtin_clz(i + 1) - 1);
		if (TYPE == CHMIN) {
			if (a[i].max == a[i].min or g <= a[i].min) {
				tag<UPDATE>(i, g);
				return;
			}
			if (a[i].max != INT64_MIN) {
				a[i].sum -= a[i].max * a[i].max_count;
			}
			a[i].max = g;
			a[i].min_second = std::min(a[i].min_second, g);
			if (a[i].lazy_update != INT64_MAX) {
				a[i].lazy_update = std::min(a[i].lazy_update, g);
			}
			a[i].sum += g * a[i].max_count;
		} else if (TYPE == CHMAX) {
			if (a[i].max == a[i].min or a[i].max <= g) {
				tag<UPDATE>(i, g);
				return;
			}
			if (a[i].min != INT64_MAX) {
				a[i].sum -= a[i].min * a[i].min_count;
			}
			a[i].min = g;
			a[i].max_second = std::max(a[i].max_second, g);
			if (a[i].lazy_update != INT64_MAX) {
				a[i].lazy_update = std::max(a[i].lazy_update, g);
			}
			a[i].sum += g * a[i].min_count;
		} else if (TYPE == ADD) {
			if (a[i].max != INT64_MAX) {
				a[i].max += g;
			}
			if (a[i].max_second != INT64_MIN) {
				a[i].max_second += g;
			}
			if (a[i].min != INT64_MIN) {
				a[i].min += g;
			}
			if (a[i].min_second != INT64_MAX) {
				a[i].min_second += g;
			}
			a[i].lazy_add += g;
			if (a[i].lazy_update != INT64_MAX) {
				a[i].lazy_update += g;
			}
			a[i].sum += g * length;
		} else if (TYPE == UPDATE) {
			a[i].max = g;
			a[i].max_second = INT64_MIN;
			a[i].max_count = length;
			a[i].min = g;
			a[i].min_second = INT64_MAX;
			a[i].min_count = length;
			a[i].lazy_add = 0;
			a[i].lazy_update = INT64_MAX;
			a[i].sum = g * length;
		} else {
			assert (false);
		}
	}
	void pushdown(int i) {
		int l = 2 * i + 1;
		int r = 2 * i + 2;
		// update
		if (a[i].lazy_update != INT64_MAX) {
			tag<UPDATE>(l, a[i].lazy_update);
			tag<UPDATE>(r, a[i].lazy_update);
			a[i].lazy_update = INT64_MAX;
			return;
		}
		// add
		if (a[i].lazy_add != 0) {
			tag<ADD>(l, a[i].lazy_add);
			tag<ADD>(r, a[i].lazy_add);
			a[i].lazy_add = 0;
		}
		// chmin
		if (a[i].max < a[l].max) {
			tag<CHMIN>(l, a[i].max);
		}
		if (a[i].max < a[r].max) {
			tag<CHMIN>(r, a[i].max);
		}
		// chmax
		if (a[l].min < a[i].min) {
			tag<CHMAX>(l, a[i].min);
		}
		if (a[r].min < a[i].min) {
			tag<CHMAX>(r, a[i].min);
		}
	}
	void update(int i) {
		int l = 2 * i + 1;
		int r = 2 * i + 2;
		// chmin
		vector<ll> b { a[l].max, a[l].max_second, a[r].max, a[r].max_second };
		std::sort(b.rbegin(), b.rend());
		b.erase(std::unique(b.begin(), b.end()), b.end());
		a[i].max = b[0];
		a[i].max_second = b[1];
		a[i].max_count = (b[0] == a[l].max ? a[l].max_count : 0) + (b[0] == a[r].max ? a[r].max_count : 0);
		// chmax
		vector<ll> c { a[l].min, a[l].min_second, a[r].min, a[r].min_second };
		std::sort(c.begin(), c.end());
		c.erase(std::unique(c.begin(), c.end()), c.end());
		a[i].min = c[0];
		a[i].min_second = c[1];
		a[i].min_count = (c[0] == a[l].min ? a[l].min_count : 0) + (c[0] == a[r].min ? a[r].min_count : 0);
		// add
		a[i].lazy_add = 0;
		// update
		a[i].lazy_update = INT64_MAX;
		// sum
		a[i].sum = a[l].sum + a[r].sum;
	}

	template <char TYPE>
	ll range_get(int i, int il, int ir, int l, int r) {
		if (ir <= l or r <= il) {
			switch (TYPE) {
				case MIN: return INT64_MAX;
				case MAX: return INT64_MIN;
				case SUM: return 0;
				default: assert (false);
			}
		} else if (l <= il and ir <= r) {
			// base
			switch (TYPE) {
				case MIN: return a[i].min;
				case MAX: return a[i].max;
				case SUM: return a[i].sum;
				default: assert (false);
			}
		} else {
			pushdown(i);
			ll value_l = range_get<TYPE>(2 * i + 1, il, (il + ir) / 2, l, r);
			ll value_r = range_get<TYPE>(2 * i + 2, (il + ir) / 2, ir, l, r);
			// mult
			switch (TYPE) {
				case MIN: return std::min(value_l, value_r);
				case MAX: return std::max(value_l, value_r);
				case SUM: return value_l + value_r;
				default: assert (false);
			}
		}
	}
};
ostream& operator<<(ostream& s, SegmentTreeBeats& seg) {
	for(ll i=0; i<seg.n; i++) s << seg.range_sum(i, i+1) << "\t\n"[i==seg.n-1];
	return s;
}


//区間add, 区間sum ができる
template< typename T >
class BinaryIndexedTree {
public:
	class BinaryIndexedTreeNaive {
	public:
		ll size;
		vector<T> data;
		BinaryIndexedTreeNaive(ll N) : size(N+1), data(size, 0) {}

		// sum [0, i)
		T sum(ll i) {
			T ret = 0;
			for(--i; i>=0; i=(i&(i+1))-1) ret += data[i];
			return ret;
		}

		// sum [i, j)
		T sum(ll i, ll j) {
			return sum(j) - sum(i);
		}

		// add x to i
		void add(ll i, T x) {
			for(; i < size; i|=i+1) data[i] += x;
		}
	};
	ll size;
	BinaryIndexedTreeNaive b,c;
	BinaryIndexedTree(ll N) : size(N), b(size), c(size) {}

	// add x to [i, j) 
	void add(ll i, ll j, T x) {
		if (i>=j) return;
		b.add(i,x*-i);
		b.add(j,x*j);
		c.add(i,x);
		c.add(j,x*-1);
	}

	// sum [0, i)
	T sum(ll i) { 
		return b.sum(i+1) + c.sum(i+1)*i;
	}

	// sum [i, j)
	T sum(ll i, ll j) {
		if (i>=j) return 0;
		return sum(j) - sum(i);
	}
};
template<typename T> std::ostream& operator<<(std::ostream& s, BinaryIndexedTree<T>& bit) { 
	for(ll i=0; i<bit.size; i++) s << bit.sum(i, i+1) << "\t\n"[i==bit.size-1];
	return s;
}

