template<typename T>
struct SegmentTree{
private:
    int n;
    vector<T> node;
public:
    T merge(T x,T y){
        return max(x,y);
    }
    SegmentTree(vector<T> v){
        int sz=(int)v.size();
        n=1; while(n<sz)n*=2;
        node.resize(2*n-1,-1);
        for(int i=0;i<sz;i++) node[i+n-1]=v[i];
        for(int i=n-2;i>=0;i--){
            node[i]=merge(node[2*i+1],node[2*i+2]);
        }
    }
    void update(int x,T val){
        x+=(n-1);
        node[x]=val;
        while(x>0){
            x=(x-1)/2;
            node[x]=merge(node[2*x+1],node[2*x+2]);
        }
    }
    T query(int a,int b,int idx=0,int l=0,int r=-1){ /* get [a,b) */
        if(r<0) r=n;
        if(r<=a||b<=l) return -1;
        if(a<=l&&r<=b) return node[idx];
        T vl=query(a,b,2*idx+1,l,(l+r)/2);
        T vr=query(a,b,2*idx+2,(l+r)/2,r);
        return merge(vl,vr);
    };
};
signed main(){
    std::cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);
    ll n; cin >> n;
    vector<ll> hoge(n-2,-1);
    SegmentTree<ll> lX(hoge);
    SegmentTree<ll> lY(hoge);
    int q; cin>>q;
    ll ans=0;
    while(q--){
        int x,y; cin >> x >> y;
        y-=2;
        if(x==1&&y==-1){
            continue;
        }else if(x==1){
            if(lX.query(0,1)>=y) continue;
            int l=-1,r=int(n-2);
            while(r-l>1){
                int mid=(l+r)/2;
                ll res=lX.query(0,mid+1);
                if(res<y) l=mid;
                else r=mid;
            }
            //rまで
            ans+=r;
            //cout << r << endl;
            lY.update(y,r-1);
        }else{
            if(lY.query(0,1)>=y) continue;
            int l=-1,r=int(n-2);
            while(r-l>1){
                int mid=(l+r)/2;
                ll res=lY.query(0,mid+1);
                if(res<y) l=mid;
                else r=mid;
            }
            //rまで
            ans+=r;
            //cout << r << endl;
            lX.update(y,r-1);
        }
    }
    ll out=(n-2LL)*(n-2LL)-ans;
    cout << out << endl;
}

