class RangeMaxTree {
 private:
  vector<int64> nodes;
  int num_nodes;

  // Returns the fold of overwrap between [node_l, node_r) and [l, r).
  // nodes[node_index] needs to correspond to [node_l, node_r).
  int64 GetRangeInternal(int node_index, int node_l, int node_r, int l, int r) {
    if (node_r <= l || r <= node_l) return INT64_MIN;
    if (l <= node_l && node_r <= r) return nodes[node_index];
    int node_m = (node_l + node_r) / 2;
    return max(
        GetRangeInternal(2 * node_index, node_l, node_m, l, r),
        GetRangeInternal(2 * node_index + 1, node_m, node_r, l, r));
  }

 public:
  // Arguments:
  // xs: The initial values.
  RangeMaxTree(const vector<int64>& xs) {
    int n = xs.size();
    num_nodes = 1;
    while (num_nodes < n) num_nodes *= 2;
    num_nodes *= 2;
    nodes = vector<int64>(num_nodes, INT64_MIN);
    for (int i = 0; i < xs.size(); ++i) {
      nodes[num_nodes / 2 + i] = xs[i];
    }
    for (int i = num_nodes / 2 - 1; i >= 1; i--) {
      nodes[i] = max(nodes[2 * i], nodes[2 * i + 1]);
    }
  }

  // Updates the i-th element to x.
  void Update(int i, int64 x) {
    nodes[num_nodes / 2 + i] = x;
    for (int cur = (num_nodes / 2 + i) / 2; cur > 0; cur /= 2) {
      nodes[cur] = max(nodes[2 * cur], nodes[2 * cur + 1]);
    }
  }

  // Returns the value of the range [l, r) merged by merge_fn.
  int64 RangeMax(int l, int r) {
    return GetRangeInternal(1, 0, num_nodes / 2, l, r);
  }

  int64 Get(int i) {
    return nodes[num_nodes / 2 + i];
  }
};

// Constraints:
// - is_upper_fn(l) = false.
// - is_upper_fn(u) = true.
// - is_upper_fn() is monotically increasing.
tuple<int, int> BinarySearch(int l, int u, function<bool(int)> is_upper_fn) {
  while (u - l >= 2) {
    int m = (l + u) / 2;
    if (is_upper_fn(m)) {
      u = m;
    } else {
      l = m;
    }
  }
  return {l, u};
}

