int lazy[800005],lazy2[800005];
long long ans=0;
void build(int now,int l,int r){
	if(l==r){
		xx[now]=n,yy[now]=n;
		return;
	}
	int mid=(l+r)>>1;
	build(now*2,l,mid);
	build(now*2+1,mid+1,r);
	xx[now]=xx[now*2]+xx[now*2+1];
	yy[now]=yy[now*2]+yy[now*2+1];
	return ;
}
void downx(int now,int l,int r){
//	cout<<"down : "<<l<<" "<<r<<endl;
	if(!lazy[now])return ;
	int mid=(l+r)>>1;
	if(mid==l){
		xx[now*2]=min(xx[now*2],lazy[now]);

//		cout<<"ll:"<<l<<" rr:"<<r<<endl;
//		cout<<xx[now*2]<<" "<<xx[now*2+1]<<endl;
	}
	if(mid+1==r){
		xx[now*2+1]=min(xx[now*2+1],lazy[now]);
	}
	lazy[now*2]=lazy[now*2]?min(lazy[now*2],lazy[now]):lazy[now];
	lazy[now*2+1]=lazy[now*2+1]?min(lazy[now*2+1],lazy[now]):lazy[now];
	lazy[now]=0;
	return ;
}
void downy(int now,int l,int r){
	if(!lazy2[now])return ;
	int mid=(l+r)>>1;
	if(mid==l){
		yy[now*2]=min(yy[now*2],lazy2[now]);

	}
	if(mid+1==r){
		yy[now*2+1]=min(yy[now*2+1],lazy2[now]);
	}
	lazy2[now*2]=lazy2[now*2]?min(lazy2[now*2],lazy2[now]):lazy2[now];
	lazy2[now*2+1]=lazy2[now*2+1]?min(lazy2[now*2+1],lazy2[now]):lazy2[now];
	lazy2[now]=0;
	return ;
}
void add(int now,int l,int r,int gl,int gr,int sum){
	if(l>=gl&&r<=gr){
//		cout<<"x from "<<l<<" to "<<r<<endl;
		if(lazy[now]!=0)lazy[now]=min(lazy[now],sum);
		else lazy[now]=sum;
		return ;
	}
	int mid=(l+r)>>1;
	downx(now,l,r);
	if(gl<=mid)add(now*2,l,mid,gl,gr,sum);
	if(gr>mid)add(now*2+1,mid+1,r,gl,gr,sum);
	return ;
}
void modify(int now,int l,int r,int to){
