const int INF = 1 << 30;

struct LazySegmentTree {
private:
    int n;
    vector<int> node, lazy;
    vector<bool> lazyFlag;

public:
    LazySegmentTree(vector<int> v) {
        int sz = (int)v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, INF);
        lazyFlag.resize(2*n-1, false);

        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = min(node[i*2+1], node[i*2+2]);
    }

    void lazyEvaluate(int k, int l, int r) {
        if(lazyFlag[k]) {
            chmin(node[k], lazy[k]);
            if(r - l > 1) {
                if (chmin(lazy[k*2+1], lazy[k])) {
                    lazyFlag[k*2+1] = true;
                }
                if (chmin(lazy[k*2+2], lazy[k])) {
                    lazyFlag[k*2+2] = true;
                }
            }
            lazyFlag[k] = false;
        }
    }

    void update(int a, int b, int x, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            if (chmin(lazy[k], x)) {
                lazyFlag[k] = true;
            }
            lazyEvaluate(k, l, r);
        }
        else {
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1], node[2*k+2]);
        }
    }

    int find(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return INF;
        if(a <= l && r <= b) return node[k];
        int vl = find(a, b, 2*k+1, l, (l+r)/2);
        int vr = find(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, Q;
    cin >> N >> Q;
    LazySegmentTree col_seg(vector<int>(N - 1, N - 1)), row_seg(vector<int>(N - 1, N - 1));
    int query, X;
    ll ans = (N - 2) * (N - 2);
    rep(i, 0, Q) {
        cin >> query >> X;
        if (query == 1) {
            ll max_pos = col_seg.find(X - 1, X);
            ans -= max_pos - 1;
            row_seg.update(0, max_pos, X - 1);
        } else {
            ll max_pos = row_seg.find(X - 1, X);
            ans -= max_pos - 1;
            col_seg.update(0, max_pos, X - 1);
        }
    }
    cout << ans << endl;
    return 0;
}

