void read (int &x) {
    char ch = getchar(); x = 0;
    while (!isdigit(ch)) ch = getchar();
    while (isdigit(ch)) x = x * 10 + ch - 48, ch = getchar();
} const int N = 2e5 + 5;
int n, q, res;
struct tree {
    int c[N << 2], tag[N << 2];
    #define ls (p << 1)
    #define rs (p << 1 | 1)
    void build (int p, int l, int r) {
        if (l == r) { c[p] = n; return; }
        int mid (l + r >> 1);
        build (ls, l, mid), build (rs, mid + 1, r);
    }
    void push_down (int p) {
        if (c[p]) {
            if (c[ls] == 0 || c[ls] > c[p]) c[ls] = c[p];
            if (c[rs] == 0 || c[rs] > c[p]) c[rs] = c[p]; c[p] = 0;
        }
    }
    int query (int p, int l, int r, int pos) {
        if (l == r) return c[p];
        int mid (l + r >> 1), res; push_down (p);
        if (pos <= mid) res = query (ls, l, mid, pos);
        else res = query (rs, mid + 1, r, pos);
        return res;
    }
    void modify (int p, int l, int r, int ql, int qr, int v) {
        if (ql <= l && r <= qr) {
            if (c[p] == 0 || c[p] > v) c[p] = v;
            return;
        } int mid (l + r >> 1); push_down (p);
        if (ql <= mid) modify (ls, l, mid, ql, qr, v);
        if (qr > mid) modify (rs, mid + 1, r, ql, qr, v);
    }
} a, b;
signed main() {
    read (n), read (q);
    int o, x;
    a.build (1, 1, n);
    b.build (1, 1, n);
    res = (n - 2) * (n - 2);
    while (q--) {
        read (o), read (x);
        if (o == 1) {
            int w = a.query (1, 1, n, x);
            if (w >= 2) res -= (w - 2);
            if (w >= 2) b.modify (1, 1, n, 1, w - 1, x);
            // printf ("123 %lld %lld\n", w - 1, x);
            a.modify (1, 1, n, x, x, 1);
        } else {
            int w = b.query (1, 1, n, x);
            if (w >= 2) res -= (w - 2);
            if (w >= 2) a.modify (1, 1, n, 1, w - 1, x);
            // printf ("123 %lld\n", w);
            b.modify (1, 1, n, x, x, 1);
        }
        // printf ("%lld\n", res);
    }
    return printf ("%lld\n", res), 0;
}

