int binary(vector<pair<pair<int,int>,int>> &k,int key,int l,int r){
  int mid=(l+r)/2;
  //if(key==2)cout << mid << " " << k[mid].first.second << " " << endl;
  if(l==mid){
    if(key>k[mid].first.first)return k[mid].second;
    else return k[r].second;
  }
  int x,y;
  x=k[mid].first.first;
  y=k[mid].first.second;
  if(x<key&&y>key)return k[mid].second;
  if(y<key)return binary(k,key,l,mid);
  else return binary(k,key,mid,r);
}
