const int  SEG_MAX = (1 << 20); //1<<17 = 2^17 = 131072
int seg1[SEG_MAX * 2] = { 0 };

//[a,b]にxを加算 (節点kをベースに[l,r]に足す)
void add1(int a, int b, int x, int k = 0, int l = 0, int r = SEG_MAX - 1)
{
	if (a <= l && r <= b)
	{
		seg1[k] = min(x, seg1[k]);
	}
	else
	{
		int l0 = l;
		int r0 = l + (r - l) / 2;
		int l1 = r0 + 1;
		int r1 = r;
		if (a <= r0)
		{
			int kk = 2 * k + 1;
			add1(a, b, x, kk, l0, r0);
		}
		if (l1 <= b)
		{
			int kk = 2 * k + 2;
			add1(a, b, x, kk, l1, r1);
		}
	}
}

int get1(int index)
{
	int m = INT_MAX;
	int k = SEG_MAX - 1 + index; //根
	while (true)
	{
		m = min(m, seg1[k]);
		if (k == 0) break;
		k = (k - 1) / 2;
	}
	return m;
}

