		tr[0][o]=tr[1][o]=n;
		return;
	}
	tr[0][o]=tr[1][o]=0x7fffffff;
	int mid=(l+r)>>1;
	build(o<<1,l,mid);
	build(o<<1|1,mid+1,r);
	return;
}
void update(int o,int l,int r,int L,int R,int idx,int v){
	if(L<=l&&r<=R){
		tr[idx][o]=min(tr[idx][o],v);
		return;
	}
	int mid=(l+r)>>1;
	if(L<=mid)
		update(o<<1,l,mid,L,R,idx,v);
	if(R>mid)
		update(o<<1|1,mid+1,r,L,R,idx,v);
	return;
}
int query(int o,int l,int r,int x,int idx){
	if(l==r)
		return tr[idx][o];
	int mid=(l+r)>>1;
	if(x<=mid)
		return min(tr[idx][o],query(o<<1,l,mid,x,idx));
	return min(tr[idx][o],query(o<<1|1,mid+1,r,x,idx));
}
