const int MAX = 2e5 + 10;
template <class T> struct SegTree {
	int n, N; vector <T> tree, lazy;
	const T ID = MAX;
	void init(int _n) { n = _n, N = 4 * _n; tree.assign(N, _n), lazy.assign(N, MAX); }
	T comb(T a, T b) { return min(a, b); }
	void prop(int i, int st, int en) {
		tree[i] = comb(tree[i], lazy[i]);
		if(st != en) {
			lazy[2 * i] = comb(lazy[2 * i], lazy[i]);
			lazy[2 * i + 1] = comb(lazy[2 * i + 1], lazy[i]);
		}
		lazy[i] = MAX;
	}
	void _update(int i, int st, int en, int l, int r, T val) {
		if(lazy[i] != MAX) prop(i, st, en);
		if(en < l || st > r) return;
		if(l <= st && en <= r) {
			lazy[i] = val;
			prop(i, st, en);
			return;
		}
		int mid = (st + en) / 2;
		_update(2 * i, st, mid, l, r, val);
		_update(2 * i + 1, mid + 1, en, l, r, val);
		tree[i] = comb(tree[2 * i], tree[2 * i + 1]);
	}
	T _query(int i, int st, int en, int l, int r) {
		if(lazy[i] != MAX) prop(i, st, en);
		if(en < l || st > r) return ID;
		if(l <= st && en <= r) return tree[i];
		int mid = (st + en) / 2;
		return comb(_query(2 * i, st, mid, l, r), _query(2 * i + 1, mid + 1, en, l, r));
	}
	T query(int l, int r) { return _query(1, 1, n, l, r); }
	void update(int l, int r, T val) { _update(1, 1, n, l, r, val); }
};

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

	int n, q;
	cin >> n >> q;
	ll ans = 1LL * (n - 2) * (n - 2);
	SegTree <int> row, col;
	row.init(n), col.init(n);
	while(q --) {
		int t, x;
		cin >> t >> x;
		if(t == 1) {
			int y = col.query(x, x);
			ans -= (y - 2);
			row.update(1, y - 1, x);
		}
		else {
			int y = row.query(x, x);
			ans -= (y - 2);
			col.update(1, y - 1, x);
		}
	}
	cout << ans;

	return 0;
}

