void solve() {
    VAR(ll, n, q); //

    using rect = tuple<ll, ll, ll, ll>;
    set<rect> rectX;
    set<rect> rectY;
    rectX.emplace(n - 1, n - 1, 2, 2); // xM, yM, xm, ym
    rectY.emplace(n - 1, n - 1, 2, 2); // yM, xM, ym, xm
    ll ret = (n - 2) * (n - 2);
    REP(i, 0, q) {
        VAR(ll, j, x);
        if (j == 1) {
            // (1,x) に白石を置く（縦の線を追加する＝上辺に石を追加）
            rect needle = {x, 2, 2, 2};
            // dump(x);
            auto q = rectX.lower_bound(needle);
            if (q != rectX.end()) {
                auto [xM, yM, xm, ym] = *q;

                // この領域に含まれなかったら計算しない
                if (x < xm || xM < x) continue;

                rectX.erase(q);
                // dump(x, xM, yM, xm, ym);

                if (xm == 2) {
                    // 同じ領域が rectY にもあるはず
                    rect needle2 = {yM, xM, ym, xm};
                    auto q2 = rectY.lower_bound(needle2);
                    if (q2 != rectY.end()) rectY.erase(q2);
                }

                ret -= yM - ym + 1;

                if (xm != x) {
                    rectX.emplace(x - 1, yM, xm, ym);
                    if (xm == 2) {
                        // 同じ領域を rectY にも追加する
                        rectY.emplace(yM, x - 1, ym, xm);
                    }
                }
                if (xM != x) {
                    rectX.emplace(xM, yM, x + 1, ym);
                }
            }
        } else {
            // (x,1) に白石を置く
            rect needle = {x, 2, 2, 2};
            // dump(x);
            auto q = rectY.lower_bound(needle);
            if (q != rectY.end()) {
                auto [yM, xM, ym, xm] = *q;

                // この領域に含まれなかったら計算しない
                if (x < ym || yM < x) continue;

                rectY.erase(q);
                // dump(x, yM, xM, ym, xm);

                if (ym == 2) {
                    // 同じ領域が rectX にもあるはず
                    rect needle2 = {xM, yM, xm, ym};
                    auto q2 = rectX.lower_bound(needle2);
                    if (q2 != rectX.end()) rectX.erase(q2);
                }

                ret -= xM - xm + 1;

                if (ym != x) {
                    rectY.emplace(x - 1, xM, ym, xm);
                    if (ym == 2) {
                        // 同じ領域を rectX にも追加する
                        rectX.emplace(xM, x - 1, xm, ym);
                    }
                }
                if (yM != x) {
                    rectY.emplace(yM, xM, x + 1, xm);
                }
            }
        }
    }
    cout << ret << endl;
}

