			erase_interval_right(interval);
			pii left = {interval.first, x};
			pii right = {x + 1, interval.second};
			VR[left] = v;
			VR[right] = v;
			insert_interval_right(left);
			insert_interval_right(right);
			if (left.first == 1) {
				assert(VD.find({1, v}) != VD.end());
				VD[{1, v}] = x;
