ll stree[800100][2],lazy[800100][2],arr[200100];
ll query(ll strt,ll ed,ll qs,ll qe,ll  idx,ll flag) {
	stree[idx][flag]=min(stree[idx][flag],lazy[idx][flag]);
	if (strt!=ed) {
		lazy[idx*2+1][flag]=min(lazy[idx*2+1][flag],lazy[idx][flag]);
		lazy[idx*2+2][flag]=min(lazy[idx*2+2][flag],lazy[idx][flag]);
	}
	lazy[idx][flag]=1e9;
	if (qs>ed || qe<strt || qs>qe || strt>ed)
		return 2;
	if (qs<=strt && qe>=ed) {
		return stree[idx][flag];
	}
	ll mid=(strt+ed)/2;
	return max(query(strt,mid,qs,qe,idx*2+1,flag),query(mid+1,ed,qs,qe,idx*2+2,flag));
}
void update(ll strt,ll ed,ll qs,ll qe,ll val,ll idx,ll flag) {
	stree[idx][flag]=min(stree[idx][flag],lazy[idx][flag]);
	if (strt!=ed) {
		lazy[idx*2+1][flag]=min(lazy[idx*2+1][flag],lazy[idx][flag]);
		lazy[idx*2+2][flag]=min(lazy[idx*2+2][flag],lazy[idx][flag]);
	}
	lazy[idx][flag]=1e9;
	if (qs>ed || qe<strt)
		return;
	if (qs<=strt && qe>=ed) {
		stree[idx][flag]=min(stree[idx][flag],val);
		if (strt!=ed) {
			lazy[idx*2+1][flag]=min(lazy[idx*2+1][flag],val);
			lazy[idx*2+2][flag]=min(lazy[idx*2+2][flag],val);
		}
		return;
	}
	ll mid=(strt+ed)/2;
	update(strt,mid,qs,qe,val,idx*2+1,flag);

	update(mid+1,ed,qs,qe,val,idx*2+2,flag);
	stree[idx][flag]=min(stree[idx*2+1][flag],stree[idx*2+2][flag]);
}
void build(ll strt,ll ed,ll idx,ll flag) {
	lazy[idx][flag]=1e9;
	if (strt==ed) {
		stree[idx][flag]=arr[strt];
		return;
	}
	ll mid=(strt+ed)/2;
	build(strt,mid,idx*2+1,flag);
	build(mid+1,ed,idx*2+2,flag);
	stree[idx][flag]=min(stree[idx*2+1][flag],stree[idx*2+2][flag]);
}
void solveTestCase() {
	ll n,i,j,k,l,x,m;
	cin>>n>>m;
	for (i=1;i<=n;i++)
		arr[i]=n;
	build(1,n,0,0);
	build(1,n,0,1);
	ll ans=(n-2)*(n-2);
	set<ll> st1,st2;
	while (m--) {
		cin>>j>>k;
		if (j==1) {
			if (k==1 || k==n || st1.find(k)!=st1.end())
				continue;
			else {
				ll op = query(1,n,k,k,0,0);
				ans-=(op-2);
				update(1,n,2,op,k,0,1);
			}
			st1.insert(k);
		} else {
			if (k==1 || k==n || st2.find(k)!=st2.end())
				continue;
			else {
				ll op = query(1,n,k,k,0,1);
				ans-=(op-2);
				update(1,n,2,op,k,0,0);
			}
			st2.insert(k);
		}
	}
	cout<<ans<<'\n';
}
int main() {
	ll t,n,i,j,k,l,m;
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	ll p;
	t=1;
	//cin>>t;
	for (ll T=1;T<=t;T++) {
		solveTestCase();
	}
	return 0;
}

