int n, q, t[2][800800], lz[2][800800];
ll ans;

void build(int node = 1, int l = 1, int r = n){
	if(l == r){
		t[0][node] = t[1][node] = n;
		return;
	}
	build(node*2, l, mid), build(node*2+1, mid+1, r);
}

void lazy_update(int node, int l, int r){
	for(int i=0;i<2;i++){
		t[i][node] = min(t[i][node], lz[i][node]);
		if(l != r) lz[i][node*2] = min(lz[i][node*2], lz[i][node]), lz[i][node*2+1] = min(lz[i][node*2+1], lz[i][node]);
		lz[i][node] = 1e9;
	}
}

int find(int fl, int id, int node = 1, int l = 1, int r = n){
	lazy_update(node, l, r);
	if(id < l || r < id) return 0;
	if(l == r) return t[fl][node];
	return find(fl, id, node*2, l, mid) + find(fl, id, node*2+1, mid+1, r);
}

void update(int fl, int nl, int nr, int x, int node = 1, int l = 1, int r = n){
	lazy_update(node, l, r);
	if(nr < l || r < nl) return;
	if(nl <= l && r <= nr){
		lz[fl][node] = x;
		lazy_update(node, l, r);
		return;
	}
	update(fl, nl, nr, x, node*2, l, mid), update(fl, nl, nr, x, node*2+1, mid+1, r);
}

