class LazySegmentTree{
//区間加算・区間和クエリ
public:
    int n,sz;
    vector<ll> v,lazy;

    LazySegmentTree():n{0},sz{0}{}
    LazySegmentTree(int n_in):n{n_in},sz{1}{
        while(sz<n) sz*=2;
        v.assign(2*sz-1,0);
        lazy.assign(2*sz-1,0);
    }

    void init_u(){
        for(int i=sz-2;i>=0;i--)
        v[i]=v[2*i+1]+v[2*i+2];
    }

    void eval(int k,int l,int r){
        if(lazy[k]==0) return;
        v[k]+=lazy[k];
        if(r-l>1){
            lazy[2*k+1]+=lazy[k]/2;
            lazy[2*k+2]+=lazy[k]/2;
        }
        lazy[k]=0;
    }

    //add(a,b,x,0,0,s.sz); xは加算分
    void add(int a,int b,ll x,int k,int l,int r){
        eval(k,l,r);
        if(b<=l || r<=a) return;
        if(a<=l && r<=b){
            lazy[k]+=(r-l)*x;
            eval(k,l,r);
        }
        else{
            add(a,b,x,2*k+1,l,(l+r)/2);
            add(a,b,x,2*k+2,(l+r)/2,r);
            v[k]=v[2*k+1]+v[2*k+2];
        }
    }

    //query(a,b,0,0,s.sz);
    ll query(int a,int b,int k,int l,int r){
        if(r<=a || b<=l) return 0;
        eval(k,l,r);
        if(a<=l && r<=b) return v[k];
        ll vl=query(a,b,k*2+1,l,(l+r)/2);
        ll vr=query(a,b,k*2+2,(l+r)/2,r);
        return vl+vr;
    }

    ll operator[](const int& idx) const{
        return v[idx+sz-1];
    }
};

