using ll = long long;

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll n, q;
  cin >> n >> q;

  set<tuple<ll, ll, ll>> up, left;
  pair<ll, ll> upleft = make_pair(n - 1, n - 1);

  while (q--) {
    ll tmp, x;
    cin >> tmp >> x;
    if (tmp == 1) {
      if (upleft.second >= x) {
        if (x + 1 <= upleft.second) up.insert(make_tuple(x + 1, upleft.second, upleft.first));
        upleft.second = x - 1;
      }
      else {
        auto it = up.upper_bound(make_tuple(x, 1e9, 1e9));
        if (it == up.begin()) continue;
        it--;
        auto [a, b, c] = *it;
        up.erase(it);
        if (a <= x - 1) up.insert(make_tuple(a, x - 1, c));
        if (x + 1 <= b) up.insert(make_tuple(x + 1, b, c));
      }
    }
    else {
      if (upleft.first >= x) {
        if (x + 1 <= upleft.first) left.insert(make_tuple(x + 1, upleft.first, upleft.second));
        upleft.first = x - 1;
      }
      else {
        auto it = left.upper_bound(make_tuple(x, 1e9, 1e9));
        if (it == left.begin()) continue;
        it--;
        auto [a, b, c] = *it;
        left.erase(it);
        if (a <= x - 1) left.insert(make_tuple(a, x - 1, c));
        if (x + 1 <= b) left.insert(make_tuple(x + 1, b, c));
      }
    }
  }

  ll ans = (upleft.first - 1) * (upleft.second - 1);
  for (auto it = up.begin(); it != up.end(); it++) {
    auto [a, b, c] = *it;
    ans += (b - a + 1) * (c - 1);
  }
  for (auto it = left.begin(); it != left.end(); it++) {
    auto [a, b, c] = *it;
    ans += (b - a + 1) * (c - 1);
  }

  cout << ans << '\n';
}

