              n, [](T a, T b) { return (b == numeric_limits<T>::max() ? a : b); }, numeric_limits<T>::max()) {}
    RST(vector<T> &a)
        : Seg(
              a, [](T a, T b) { return (b == numeric_limits<T>::max() ? a : b); }, numeric_limits<T>::max()) {}
};

