                ans += n-2;
                continue;
            }
            int lo = 1;
            int hi = n-2;
            while(hi-lo>1){
                int mid = (lo+hi)/2;
                if(col.query(1, mid) < x) lo = mid+1;
                else hi = mid;
            }
            int val;
            if(col.query(1, lo) >= x){
                val=lo;
            }
            else{
                val=hi;
            }
            row.upd(x, val-1);
            ans+=(val-1);
//            ps(i, val-1, "HUH");
        }
        else{
            if(row.query(1, n-2) < x){
                col.upd(x, n-2);
                ans += (n-2);
                continue;
            }
            int lo = 1;
            int hi = n-2;
            while(hi-lo>1){
                int mid = (lo+hi)/2;
                if(row.query(1, mid) < x) lo = mid+1;
