//区間更新・区間最小遅延評価セグメント木
//クエリlog(N)
//LazySegmentTree seg(vl(N+10,0));で初期化
//seg.find(a,b);でインデックスa～b-1までの最小値検索
//seg.update(a,b,x);でインデックスa～b-1までの値をxに更新
struct LazySegmentTree {
private:
    ll n;
    vector<ll> node, lazy;
    vector<bool> lazyFlag;

public:
    LazySegmentTree(vector<ll> v) {
        ll sz = (ll)v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1, INF);
        lazyFlag.resize(2*n-1, false);

        for(ll i=0; i<sz; i++) node[i+n-1] = v[i];
        for(ll i=n-2; i>=0; i--) node[i] = min(node[i*2+1], node[i*2+2]);
    }

    void lazyEvaluate(ll k, ll l, ll r) {
        if(lazyFlag[k]) {
            node[k] = lazy[k];
            if(r - l > 1) {
                lazy[k*2+1] = lazy[k*2+2] = lazy[k];
                lazyFlag[k*2+1] = lazyFlag[k*2+2] = true;
            }
            lazyFlag[k] = false;
        }
    }

    void update(ll a, ll b, ll x, ll k=0, ll l=0, ll r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return;
        if(a <= l && r <= b) {
            lazy[k] = x;
            lazyFlag[k] = true;
            lazyEvaluate(k, l, r);
        }
        else {
            update(a, b, x, 2*k+1, l, (l+r)/2);
            update(a, b, x, 2*k+2, (l+r)/2, r);
            node[k] = min(node[2*k+1], node[2*k+2]);
        }
    }

    ll find(ll a, ll b, ll k=0, ll l=0, ll r=-1) {
        if(r < 0) r = n;
        lazyEvaluate(k, l, r);
        if(b <= l || r <= a) return 1000000000;
        if(a <= l && r <= b) return node[k];
        ll vl = find(a, b, 2*k+1, l, (l+r)/2);
        ll vr = find(a, b, 2*k+2, (l+r)/2, r);
        return min(vl, vr);
    }
};


int main(){
    ll N,Q;
    cin>>N>>Q;
    // seg_H:i行目の中で最も左にある白石の位置
    // seg_W:j列目の中で最も上にある白石の位置
    LazySegmentTree seg_H(vl(N+10,N)), seg_W(vl(N+10,N));

    ll ans=pow(N-2,2);
    ll wmin=N;
    ll hmin=N;
    REP(i,Q){
        ll t,x;
        cin>>t>>x;

        if(t==1){
            int val=seg_W.find(x,x+1);
            ans-=(val-2);
            if(x<wmin) seg_H.update(1,val,x);
            wmin=min(wmin,x);
        }else{
            int val=seg_H.find(x,x+1);
            ans-=(val-2);
            if(x<hmin) seg_W.update(1,val,x);
            hmin=min(hmin,x);
        }
    }
    cout<<ans<<endl;

}

