    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long N;cin >> N;int Q;cin >> Q;
    long long black = (N-2)*(N-2);
    vector<long long> cnt_black_tate(N+1,N-2),cnt_black_yoko(N+1,N-2);
    cnt_black_tate.at(1) = 0,cnt_black_yoko.at(1) = 0;cnt_black_tate.at(N) = 0,cnt_black_yoko.at(N) = 0;
