using namespace std;

void updateTreeLazy(ll *lazy,ll *tree,ll s,ll e,ll l,ll r,ll i,ll val){
    if(lazy[i]!=INT_MAX){
        tree[i]=min(tree[i],lazy[i]);
        if(s!=e){
            lazy[2*i]=min(lazy[2*i],val);
            lazy[2*i+1]=min(lazy[2*i+1],val);
        }
        lazy[i]=INT_MAX;
    }
    if(s>e || s>r || e<l)
        return;
    //Complete Overlap
    if(s>=l && e<=r){
        tree[i]=min(tree[i],val);
        if(s!=e){
            lazy[2*i]=min(lazy[2*i],val);
            lazy[2*i+1]=min(lazy[2*i+1],val);
        }
        return;
    }
    ll m=(s+e)/2;
    updateTreeLazy(lazy,tree,m+1,e,l,r,2*i+1,val);
    updateTreeLazy(lazy,tree,s,m,l,r,2*i,val);
    tree[i]=min(tree[2*i],tree[2*i+1]);
    return;

}
ll query(ll *lazy,ll *tree,ll s,ll e,ll i,ll l,ll r){
    if(lazy[i]!=INT_MAX){
        tree[i]=min(tree[i],lazy[i]);
        if(s!=e){
            lazy[2*i]=min(lazy[2*i],lazy[i]);
            lazy[2*i+1]=min(lazy[2*i+1],lazy[i]);
        }
        lazy[i]=INT_MAX;
    }
    if(e<l || s>r)
        return INT_MAX;
    if(s>=l && e<=r){
        return tree[i];
    }
    ll m=(s+e)/2;
    return min(query(lazy,tree,s,m,2*i,l,r),query(lazy,tree,m+1,e,2*i+1,l,r));
}
int main()
{
    ll n,q;
    cin>>n>>q;
    ll *treer=new ll[4*n]();
    ll *treec=new ll[4*n]();
    ll *lazyr=new ll[4*n]();
    ll *lazyc=new ll[4*n]();
    ll ans=(n-2)*(n-2);
    for(int i=0;i<4*n;i++){
        lazyr[i]=INT_MAX;
        lazyc[i]=INT_MAX;
        treer[i]=n;
        treec[i]=n;
    }
    for(ll i=0;i<q;i++){
        ll x,y;
        cin>>x>>y;
        if(x==1 && y>1 && y<n){
            ll val=query(lazyc,treec,0,n-1,1,y-1,y-1);
            updateTreeLazy(lazyr,treer,0,n-1,1,val-1,1,y);
            ans-=val-2;
        }
        else if(x==2 && y>1 && y<n){

            ll val=query(lazyr,treer,0,n-1,1,y-1,y-1);
            updateTreeLazy(lazyc,treec,0,n-1,1,val-1,1,y);
            ans-=val-2;
        }
    }
    cout<<ans;
    return 0;
}

