const int N=1<<18;
struct segtree{
	int tree[N+N],lazy[N+N];
	void init(int num){
		fill(tree+1,tree+N+N,num);
		fill(lazy+1,lazy+N+N,num);
	}
	void push_down(int index){
		check_min(tree[index],lazy[index]);
		if(index<N){
			check_min(lazy[index<<1],lazy[index]);
			check_min(lazy[index<<1|1],lazy[index]);
		} 
	}
	void modify(int a,int b,int val,int now=1,int l=1,int r=N+1){
		push_down(now);
		if(r<=a||l>=b){
			return;
		}
		if(r<=b&&l>=a){
			check_min(lazy[now],val);
			push_down(now);
			return;
		}
		int mid=(l+r)>>1;
		modify(a,b,val,now<<1,l,mid);
		modify(a,b,val,now<<1|1,mid,r);
		tree[now]=min(tree[now<<1],tree[now<<1|1]);
	}
	int query(int a,int b,int now=1,int l=1,int r=N+1){
		push_down(now);
		if(r<=a||l>=b){
			return INF;
		}
		if(r<=b&&l>=a){
			return tree[now];
		}
		int mid=(l+r)>>1;
		return min(query(a,b,now<<1,l,mid),query(a,b,now<<1|1,mid,r));
	}
