using vi = vector<int>;

struct BIT {
	int n;
	vi a;

	BIT(int _n) : n(_n), a(_n + 1, _n) { }

	void upd(int i, int v) {
		for(i = n + 1 - i; i <= n; i += i & -i) ckmin(a[i], v);
	}

	int qry(int i) {
		int r = n;
		for(i = n + 1 - i; i; i -= i & -i) ckmin(r, a[i]);
		return r;
	}
};

