// Binary Indexed Tree (Fenwick Tree)
template <typename T>
struct BIT {
    ll n;
    vector<T> d;
    BIT(ll n = 0) : n(n), d(n + 1, INF) {}
    void add(ll i, T x = 1) {
        for (i++; i <= n; i += i & -i) {
            d[i] = min(d[i], x);
        }
    }
    T sum(ll i) {
        T x = INF;
        for (i++; i; i -= i & -i) {
            x = min(x, d[i]);
        }
        return x;
    }
};

