int tree[2][200200<<2];
int lazy[2][200200<<2];
void pushdown(int id,int rt){
	if(lazy[id][rt]<n) {
		tree[id][rt<<1] = min(tree[id][rt<<1],lazy[id][rt]);
		lazy[id][rt<<1] = min(lazy[id][rt<<1],lazy[id][rt]);
		tree[id][rt<<1|1] = min(tree[id][rt<<1|1],lazy[id][rt]);
		lazy[id][rt<<1|1] = min(lazy[id][rt<<1|1],lazy[id][rt]);
	}
	lazy[id][rt]=n;
}
void build(int id,int rt,int l,int r) {
	tree[id][rt] = n;
	lazy[id][rt] = n;
	if(l==r) {
		return;
	}
	int mid = (l+r)/2;
	build( id,rt<<1,l,mid);
	build( id,rt<<1|1,mid+1,r);
	return ;
}
int query(int id,int rt,int l,int r,int pos){
	if(l==r){
		return tree[id][rt];
	}
	pushdown(id,rt);
	int mid = (l+r)/2;
	if(pos<=mid){
		return query(id,rt<<1,l,mid,pos);
	} else {
		return query(id,rt<<1|1,mid+1,r,pos);
	}
}
void add(int id,int rt,int l,int r,int ql,int qr,int v){
	if(ql<=l&&qr>=r){
		lazy[id][rt]=min(lazy[id][rt],v);
		tree[id][rt]=min(tree[id][rt],v);
		return ;
	}
	int mid = (l+r)/2;
	pushdown(id,rt);
	if(ql<=mid){
		add(id,rt<<1,l,mid,ql,qr,v);
	}
	if(qr>mid){
		add(id,rt<<1|1,mid+1,r,ql,qr,v);
	}
	tree[id][rt]=min(tree[id][rt<<1],tree[id][rt<<1|1]); 
}


int main(){
	scanf("%lld%d",&n,&m);
	long long sum = (n-2)*(n-2);
	build(1,1,1,n);//printf("~~~\n");
	build(0,1,1,n);

	for(int i = 1;i<=m;i++) {
		int x,pos;
		scanf("%d%d",&x,&pos);
		if(pos ==  1) continue;
		x--;
		int tmp = query(1^x,1,1,n,pos);
	//	printf("tmp=%d\n",tmp);
		sum-=tmp-2;
		add(x,1,1,n,1,tmp,pos);
	}
	printf("%lld\n",sum);
}

