int n, q;

struct SEG {
	static const int mxn = 1 << 18;
	int mn[mxn << 1];
	void init() {
		memset(mn, 0x3f, sizeof(mn));
	}
	void upd(int l, int r, int v) {
		for (l += mxn, r += mxn; l < r; l >>= 1, r >>= 1) {
			if (l & 1) mn[l] = min(mn[l], v), l ++;
			if (r & 1) -- r, mn[r] = min(mn[r], v);
		}
	}
	int qry(int x) {
		int ans = n;
		for (x += mxn; x; x >>= 1) ans = min(ans, mn[x]);
		return ans;
	}
} row, col;

int main() {
	scanf("%d %d", &n, &q);
	n -= 2;
	ll tot = 1LL * n * n;
	row.init();
	col.init();
	rep(i, q) {
		int tp, x;
		scanf("%d %d", &tp, &x);
		x -= 2;
		if (tp == 1) {
			int kills = row.qry(x);
			tot -= kills;
			col.upd(0, kills, x);
		} else {
			int kills = col.qry(x);
			tot -= kills;
			row.upd(0, kills, x);
		}
	}
	printf("%lld\n", tot);
	return 0;
}

