#include <iostream>
#include <vector>
#include <functional>

template<typename T> struct segment_tree {
	int N;
	std::vector<T> V;
	std::function<T(T, T)> F;
	T E;

	segment_tree(std::vector<T>& a, std::function<T(T, T)> f, T e) : F(f), E(e) {
		int m = 1;
		while (m < a.size()) m *= 2;
		V.resize(N = m * 2, E);
		for (int i = 0; i < a.size(); i++) V[m + i] = a[i];
		for (int i = m - 1; i > 0; i--) V[i] = F(V[i * 2], V[i * 2 + 1]);
	}

	segment_tree(int n, std::function<T(T, T)> f, T e) : F(f), E(e) {
		int m = 1;
		while (m < n) m *= 2;
		V.resize(N = m * 2, E);
	}

	void point_update(int i, T x, std::function<T(T, T)> update) {
		int idx = N / 2 + i;
		V[idx] = update(V[idx], x);
		while (idx /= 2) V[idx] = F(V[idx * 2], V[idx * 2 + 1]);
	}

	T range_fold(int L, int R, int idx = 1, int l = 0, int r = -1) {
		if (r == -1) r = N / 2;
		if (L <= l && r <= R) return V[idx];
		if (r <= L || R <= l) return E;
		return F(range_fold(L, R, idx * 2, l, (l + r) / 2), range_fold(L, R, idx * 2 + 1, (l + r) / 2, r));
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	long long n, q;
	cin >> n >> q;
	long long ans = (n - 2) * (n - 2);

	segment_tree<int> highest(n, [](int a, int b){return min(a, b);}, n - 1);
	segment_tree<int> leftest(n, [](int a, int b){return min(a, b);}, n - 1);

	while (q--) {
		int op, x;
		cin >> op >> x;
		x--;
		int m;
		if (op == 1) {
			m = highest.range_fold(x, n);
			ans -= m - 1;
			leftest.point_update(m - 1, x, [](int a, int b){return min(a, b);});
		} else {
			m = leftest.range_fold(x, n);
			ans -= m - 1;
			highest.point_update(m - 1, x, [](int a, int b){return min(a, b);});
		}
	}
	cout << ans << endl;

	return 0;
}

