void koro(int node,int l,int r,int val)
{
    if(t[node]==0)
    {
        t[node]=val;
        marked[node]=true;
        return;
    }
    if(l==r || marked[node]==true)
    {
        t[node]=min(t[node],val);
        marked[node]=true;
        return;
    }
    if(t[node]<=val)
        return;
    int mid=(l+r)/2;
    koro(2*node,l,mid,val);
    koro(2*node+1,mid+1,r,val);
    t[node]=max(t[2*node],t[2*node+1]);
    return;
}
