{
    if(indl>indr || indl>r || indr<l)
        return;
    if(l>=indl && r<=indr)
    {
        koro(node,l,r,val);
        return;
    }
    done(node);
    int mid=(l+r)/2;
    update(node*2,l,mid,indl,indr,val);
    update(node*2+1,mid+1,r,indl,indr,val);
    t[node]=max(t[2*node],t[2*node+1]);
