	tree[i][p].l=l;tree[i][p].r=r;tree[i][p].tag=0;
	if(l==r){tree[i][p].v=n;return;}
	buildtree(i*2,l,(l+r)/2,p);
	buildtree(i*2+1,(r+l)/2+1,r,p);
	tree[i][p].v=tree[i*2][p].v+tree[i*2+1][p].v;
}
void update(ll i,ll l,ll r,ll k,ll p){
    if(tree[i][p].l>=l&&tree[i][p].r<=r){
        tree[i][p].tag=k;
		tree[i][p].v=(tree[i][p].r-tree[i][p].l+1)*k;
        return;
    }
    if(tree[i][p].tag) push(i,p);
    ll m=(tree[i][p].l+tree[i][p].r)/2;
    if(l<=m) update(i*2,l,r,k,p);
    if(r>m) update(i*2+1,l,r,k,p);
    tree[i][p].v=tree[i*2][p].v+tree[i*2+1][p].v;
}
ll query(ll i,ll l,ll r,ll p){
    if(tree[i][p].l>=l&&tree[i][p].r<=r){
        return tree[i][p].v;
    }
    if(tree[i][p].tag) push(i,p);
    ll m=(tree[i][p].r+tree[i][p].l)/2,ans=0;
    if(l<=m) ans+=query(i*2,l,r,p);
    if(r>m) ans+=query(i*2+1,l,r,p);
    return ans;
}
int main(){
    cin>>n>>q;ll ans=(n-2)*(n-2);
    buildtree(1,1,n,0);buildtree(1,1,n,1);
    update(1,n,n,1,0);update(1,n,n,1,1);
    while(q--){
        ll op,x;cin>>op>>x;
        if(op==1){
            ll v=query(1,x,x,0);
            ans-=max((ll)0,v-2);
            update(1,x,x,1,0);
            if(query(1,1,1,1)>x){
                update(1,1,v-1,x,1);
            }
        }
        else{
            ll v=query(1,x,x,1);
            ans-=max((ll)0,v-2);
            update(1,x,x,1,1);
            if(query(1,1,1,0)>x){
                update(1,1,v-1,x,0);
            }
        }
    }
    cout<<ans<<endl;
}

