typedef long long LL;
const int INF = 0x3f3f3f3f;
const LL mod = 1e9 + 7;
const int N = 200005;

struct Seg {
    int val[N << 2], lazy[N << 2];
    void init(int n) {
        for (int i = 1; i <= 4 * n; i++) {
            val[i] = n;
            lazy[i] = INF;
        }
    }
    void push_up(int u) {
        val[u] = min(val[u << 1], val[u << 1 | 1]);
    }
    void push_down(int u) {
        if (lazy[u] != INF) {
            val[u << 1] = min(val[u << 1], lazy[u]);
            val[u << 1 | 1] = min(val[u << 1 | 1], lazy[u]);
            lazy[u << 1] = min(lazy[u << 1], lazy[u]);
            lazy[u << 1 | 1] = min(lazy[u << 1 | 1], lazy[u]);
            lazy[u] = INF;
        }
    }
    void update(int u, int l, int r, int x, int y, int v) {
        if (x <= l && r <= y) {
            val[u] = min(val[u], v);
            lazy[u] = min(lazy[u], v);
            return;
        }
        int mid = l + r >> 1;
        push_down(u);
        if (x <= mid) update(u << 1, l, mid, x, y, v);
        if (y > mid) update(u << 1 | 1, mid + 1, r, x, y, v);
        push_up(u);
    }
    int query(int u, int l, int r, int x) {
        if (l == r) return val[u];
        int mid = l + r >> 1;
        push_down(u);
        if (x <= mid)
            return query(u << 1, l, mid, x);
        else
            return query(u << 1 | 1, mid + 1, r, x);
    }
} T1, T2;

int a[N];
int main() {
    int n, q;
    cin >> n >> q;
    T1.init(n);
    T2.init(n);
    LL ans = (n - 2LL) * (n - 2);
    while (q--) {
        int op, x;
        cin >> op >> x;
        if (op == 1) {
            int g = T2.query(1, 1, n, x);
            ans -= g - 2;
            T1.update(1, 1, n, 1, g, x);

        } else {
            int g = T1.query(1, 1, n, x);
            ans -= g - 2;
            T2.update(1, 1, n, 1, g, x);
        }
    }
    cout << ans << endl;
    return 0;
}

