const int undef=998244344;
const int N= 212345;
ll n;

struct MTree {
  ll st[4*N], ls[4*N];

  MTree() {
    rep(i,0,4*N) st[i] = n;
    rep(i,0,4*N) ls[i] = undef;
  }

  void push(int tl, int tr, int id) {
    if (ls[id] != undef) {
      st[id*2] = min(st[id*2], ls[id]);
      st[id*2+1] = min(st[id*2+1], ls[id]);
      ckmin(ls[id*2], ls[id]);
      ckmin(ls[id*2+1], ls[id]);
      ls[id] = undef;
    }
  }

  ll qsum(int l, int r, int tl=0, int tr=n-1, int id=1) {
    if (l > tr or r < tl) return 0;
    if (l <= tl and r >= tr) {
      return st[id];
    } else {
      push(tl, tr, id);
      int tm = (tl+tr)/2;
      return qsum(l, r, tl, tm, id*2) + qsum(l, r, tm+1, tr, id*2+1);
    }
  }

  void put(int l, int r, ll x, int tl=0, int tr=n-1, int id=1) {
    if (l > tr or r < tl) return;
    if (l <= tl and r >= tr) {
      ckmin(st[id], x);
      ckmin(ls[id], x);
    } else {
      push(tl, tr, id);
      int tm = (tl+tr)/2;
      put(l, r, x, tl, tm, id*2);
      put(l, r, x, tm+1, tr, id*2+1);
      ckmin(st[id], min(st[id*2], st[id*2+1]));
    }
  }

  ll qmin(int x) {
    return qsum(x, x);
  }
};


