struct SEG{
    int n;
    int mi[maxn<<2],mi2[maxn<<2],lazy[maxn<<2];
    void init(int N){
        n=N;
        for(int i=0;i<(maxn<<2);i++){
            mi[i] = n;
            mi2[i] = n+1;
            lazy[i] = n+1;
        }
    }
    void push_down(int rt){
        if(lazy[rt]!=n+1){
            lazy[rt<<1] = min(lazy[rt<<1],lazy[rt]);
            lazy[rt<<1|1] = min(lazy[rt<<1|1],lazy[rt]);
            mi[rt<<1] = min(mi[rt<<1],lazy[rt]);
            mi[rt<<1|1] = min(mi[rt<<1|1],lazy[rt]);
            lazy[rt] = n+1;
        }
    }
    void update(int rt,int L,int R,int l,int r,int val){
        if(L<=l&&r<=R){
            // if(mi[rt]<val)
            mi[rt] = min(mi[rt],val);
            lazy[rt] = min(lazy[rt],val);
            return;
        }
        int m = (l+r)>>1;
        push_down(rt);
        if(m>=L) update(rt<<1,L,R,l,m,val);
        if(m<R)  update(rt<<1|1,L,R,m+1,r,val);
        mi[rt] = min(mi[rt<<1],mi[rt<<1|1]);
    }
    int query(int rt,int pos,int l,int r){
        if(l==r) return mi[rt];
        push_down(rt);
        int m=(l+r)>>1;
        if(m>=pos) return query(rt<<1,pos,l,m);
        else return query(rt<<1|1,pos,m+1,r);
    }
}row,col;

