void build(int *tr,int p,int l,int r){
	tr[p]=1; if(l==r) return ; int mid=(l+r)>>1;
	build(tr,LS); build(tr,RS);
}

void upd(int *tr,int p,int l,int r,int el,int er,int v){
	if(el>er) return ;
	if(el<=l && r<=er) return tr[p]=max(tr[p],v),void();
	int mid=(l+r)>>1;
	if(el<=mid) 	upd(tr,LS,el,er,v);
	if(er>=mid+1)	upd(tr,RS,el,er,v);
}
int ask(int *tr,int p,int l,int r,int ep,int v=0){
	v=max(v,tr[p]); if(l==r) return v; int mid=(l+r)>>1;
	if(ep<=mid) 	return ask(tr,LS,ep,v);
	if(ep>=mid+1)	return ask(tr,RS,ep,v);
}

