struct SGT {
	struct node {
		int l, r;
		int mn, add;
	}tr[N * 4];
	void pushup(int u) {
		tr[u].mn = min(tr[u << 1].mn, tr[u << 1 | 1].mn);
	}
	void pushdown(int u) {
		if(tr[u].add != INF) {
			tr[u << 1].mn = min(tr[u << 1].mn, tr[u].add);
			tr[u << 1].add = min(tr[u << 1].add, tr[u].add);
			tr[u << 1 | 1].mn = min(tr[u << 1 | 1].mn, tr[u].add);
			tr[u << 1 | 1].add = min(tr[u << 1 | 1].add, tr[u].add);
			tr[u].add = INF;
		}
	}
	void build(int u, int l, int r) {
		if(l == r) {
			tr[u] = {l, r, n, INF};
		} else {
			int mid = l + r >> 1;
			tr[u] = {l, r, 0, INF};
			build(u << 1, l, mid);build(u << 1 | 1, mid + 1, r);
			pushup(u);
		}
	}
	void modify(int u, int l, int r, int d) {
		if(tr[u].l >= l&&tr[u].r <= r) {
			tr[u].mn = min(tr[u].mn, d);
			tr[u].add = min(tr[u].add, d);
		} else {
			int mid = tr[u].l + tr[u].r >> 1;
			pushdown(u);
			if(l <= mid) modify(u << 1, l, r, d);
			if(r > mid) modify(u << 1 | 1, l, r, d);
			pushup(u);
		}
	}
	int query(int u, int l, int r) {
		if(tr[u].l >= l&&tr[u].r <= r) {
			return tr[u].mn;
		} else {
			int mid = tr[u].l + tr[u].r >> 1;
			pushdown(u);
			int res = INF;
			if(l <= mid) res = min(res, query(u << 1, l, r));
			if(r > mid) res = min(res, query(u << 1 | 1, l, r));
			pushup(u);
			return res;
		}
	}
