    {
        if(ss==se)
        {
            tree[index]=a[ss];
            return;
        }
        int mid=(ss+se)/2;
        build(2*index,ss,mid);
        build(2*index+1,mid+1,se);
        tree[index]=min(tree[2*index],tree[2*index+1]);
    }
