	vpi queries;

	horzused[N] = 1;
	vertused[N] = 1;

	for(int i = 1; i <= Q; i++){
		int typ;
		cin >> typ;
		int x;
		cin >> x;
		if(typ == 1){
			if(vertused[x]) continue;
			vertused[x] = 1;
			queries.pb(mp(1, x));
		}
		else{
			if(horzused[x]) continue;
			horzused[x] = 1;
			queries.pb(mp(2, x));
		}
	}

	set<int> verts;
	set<int> horzs;

	for(auto u: queries){
		if(u.f == 1){
			verts.ins(u.s);
		}
		else horzs.ins(u.s);
	}

	int vlim = N;
	int hlim = N;

	ll ans = ll(N-2)*ll(N-2);

	for(auto u: queries){
		if(done[u.f][u.s]) continue;
		//bg(u.f, u.s);
		if(u.f == 1){
