			verts.erase(u.s);
			while(sz(verts)){
				int a = *(prev(verts.end()));
				if(a <= vlim) break;
				//dbg(a);
				done[u.f][a] = 1;
				if(a > 1) ans-=hlim-2;
				verts.erase(a);
			}
		}
		else{
			assert(u.s < hlim);
			ckmin(hlim, u.s);
			if(u.s > 1) ans-=vlim-2;
			//dbg(u);
			horzs.erase(u.s);
			while(sz(horzs)){
				int a = *(prev(horzs.end()));
				if(a <= hlim) break;
				//dbg(a);
				done[u.f][a] = 1;
				if(a > 1) ans-=vlim-2;
				horzs.erase(a);
			}
		}
		//dbg(ans);
	}

	ps(ans);

	// you should actually read the stuff at the bottom
}

