template <typename T>
class Segment {
 public:
  Segment(int n, T start_val = 0) {
    len = 1;
    while (len < n) len <<= 1;
    data.resize(n + len, start_val);
  }

  void setmin(int l, int r, T val) {
    for (l += len, r += len; l < r; l >>= 1, r >>= 1) {
      if ((l % 2) == 1) {
        data[l] = min(val, data[l]);
        ++l;
      }
      if ((r % 2) == 1) {
        --r;
        data[r] = min(val, data[r]);
      }
    }
  }

  T get(int pos) {
    pos += len;
    T maxi = data[pos];
    for (pos >>= 1; pos > 0; pos >>= 1) {
      maxi = std::min(maxi, data[pos]);
    }
    return maxi;
  }

 private:
  int len;
  vector<T> data;
};

