void update(ll node, bool pos, ll left, ll right, ll p, ll val) {
	if (p < left || p > right) {
		return;
	}
	if (left == right) {
		if (left == p) {
			tree[node][pos] = min(tree[node][pos], val);
		}
		return;
	}
	ll mid = (left + right) / 2;
	update(node * 2, pos, left, mid, p, val);
	update(node * 2 + 1, pos, mid + 1, right, p, val);
	tree[node][pos] = min(tree[node * 2][pos], tree[node * 2 + 1][pos]);
}

ll get(ll node, ll pos, ll left, ll right, ll gLeft, ll gRight) {
	if (gLeft > right || gRight < left) {
		return MAXX;
	}
	if (gLeft <= left && gRight >= right) {
		return tree[node][pos];
	}
	ll mid = (left + right) / 2;
	return min(get(node * 2, pos, left, mid, gLeft, gRight), get(node * 2 + 1, pos, mid + 1, right, gLeft, gRight));
}

