ll ai = 1e15;

class RMQ{
    public:
        vector<ll> x_list;
        ll n;
        ll length = 1;

        RMQ(ll n=1): n(n){
            length = 1;
            while (length < n){
                length *= 2;
            }
            // cout << "length;" << length <<endl;
            x_list.resize(2*length-1);
            fill(x_list.begin(), x_list.end(), ai);
        }

        void update(ll idx, ll v){
            idx += length - 1;
            x_list[idx] = min(v, x_list[idx]);
            // cout << "update idx "<<idx <<" to " << v <<endl;
            while(idx > 0){
                idx = (idx - 1 )/ 2;
