struct segment_tree
{
	int val[maxn<<3];
	int tip[maxn<<3];
	void up(int rt)
	{
		val[rt]=min(val[rt<<1],val[rt<<1|1]);
	}
    void build(int rt,int l,int r)
    {
    	tip[rt]=n+1;
    	if(l==r)
    	{
    		val[rt]=n;
    		return;
		}
		int mid=l+r>>1;
		build(rt<<1,l,mid);
		build(rt<<1|1,mid+1,r);
		up(rt);
	}
	void spread(int rt)
	{
		if(tip[rt]!=n+1)
		{
			val[rt<<1]=min(val[rt<<1],tip[rt]);
			tip[rt<<1]=min(tip[rt<<1],tip[rt]);
			val[rt<<1|1]=min(val[rt<<1|1],tip[rt]);
			tip[rt<<1|1]=min(tip[rt<<1|1],tip[rt]);
			tip[rt]=n+1;
		}
	}
	void modify(int rt,int l,int r,int now,int ll,int rr)
	{
		if(ll<=l&&r<=rr)
		{
			val[rt]=min(val[rt],now);
			tip[rt]=min(tip[rt],now);
			return;
		}
		spread(rt);
		int mid=l+r>>1;
		if(ll<=mid) modify(rt<<1,l,mid,now,ll,rr);
		if(rr>mid) modify(rt<<1|1,mid+1,r,now,ll,rr);
		up(rt);
	}
	int query(int rt,int l,int r,int x)
	{
		if(l==r)
		{
			return val[rt];
		}
		spread(rt);
		int mid=l+r>>1;
		int ans=0x3f3f3f3f;
		if(x<=mid) return query(rt<<1,l,mid,x);
		else return query(rt<<1|1,mid+1,r,x);
	}
}row,col;

