void build(int k, int l, int r) {
    if (l > r) return;
    if (l == r) {
        hor[k] = ver[k] = n;
        lazyHor[k] = lazyVer[k] = 1000000;
        return;
    }
    int m = (l + r) >> 1;
    build(k*2, l, m);
    build(k*2+1, m+1, r);
    lazyHor[k] = lazyVer[k] = 1000000;
    hor[k] = min(hor[k*2], hor[k*2+1]);
    ver[k] = min(ver[k*2], ver[k*2+1]);
}

void lazyUpdateHor(int k, int l, int r) {
    if (l > r) return;
    if (lazyHor[k] == 1000000) return;
    hor[k] = min(hor[k], lazyHor[k]);
    if (l < r) {
        lazyHor[k*2] = min(lazyHor[k*2], lazyHor[k]);
        lazyHor[k*2+1] = min(lazyHor[k*2+1], lazyHor[k]);
    }
    lazyHor[k] = 1000000;
}

void lazyUpdateVer(int k, int l, int r) {
    if (l > r) return;
    if (lazyVer[k] == 1000000) return;
    ver[k] = min(ver[k], lazyVer[k]);
    if (l < r) {
        lazyVer[k*2] = min(lazyVer[k*2], lazyVer[k]);
        lazyVer[k*2+1] = min(lazyVer[k*2+1], lazyVer[k]);
    }
    lazyVer[k] = 1000000;
}

int getVer(int k, int l, int r, int u) {
    lazyUpdateVer(k, l, r);
    if (l > r || r < u || u < l) return -1e9;
    if (l == r) return ver[k];
    int m = (l + r) >> 1;
    if (u <= m) return getVer(k*2, l, m, u);
    return getVer(k*2+1, m+1, r, u);
}

int getHor(int k, int l, int r, int u) {
    lazyUpdateHor(k, l, r);
    if (l > r || r < u || u < l) return -1e9;
    if (l == r) return hor[k];
    int m = (l + r) >> 1;
    if (u <= m) return getHor(k*2, l, m, u);
    return getHor(k*2+1, m+1, r, u);
}

void updateVer(int k, int l, int r, int u, int v, int val) {
    lazyUpdateVer(k, l, r);
    if (l > r || r < u || v < l) return;
    if (u <= l && r <= v) {
        lazyVer[k] = val;
        lazyUpdateVer(k, l, r);
        return;
    }
    int m = (l + r) >> 1;
    updateVer(k*2, l, m, u, v, val);
    updateVer(k*2+1, m+1, r, u, v, val);
    ver[k] = min(ver[k*2], ver[k*2+1]);
}

void updateHor(int k, int l, int r, int u, int v, int val) {
    lazyUpdateHor(k, l, r);
    if (l > r || r < u || v < l) return;
    if (u <= l && r <= v) {
        lazyHor[k] = val;
        lazyUpdateHor(k, l, r);
        return;
    }
    int m = (l + r) >> 1;
    updateHor(k*2, l, m, u, v, val);
    updateHor(k*2+1, m+1, r, u, v, val);
    hor[k] = min(hor[k*2], hor[k*2+1]);
}

