            res -= max(0, x - 2);
            if (2 <= x-1) updateHor(1,1,n,2,x-1,v);
        } else {
            int x = getHor(1,1,n,v);
            res -= max(0, x - 2);
            if (2 <= x-1) updateVer(1,1,n,2,x-1,v);
        }
    }
    cout << res;
    return 0;
}

