class SegmentTree{
public:
	static const int siz = 262144;
	int dat[siz << 1];
	inline int size(){ return siz; }
	inline void build(int x, int l, int r){
		if(l == r){
			dat[x] = n - 1;
			return;
		}
		int md = l + r >> 1;
		build(x << 1, l, md);
		build(x << 1 | 1, md + 1, r);
		dat[x] = n - 1;
		return;
	}
	inline void update(int x, int l, int r, int s, int t, int k){
		if(l >= s && r <= t){
			dat[x] = min(dat[x], k);
			return;
		}
		int md = l + r >> 1;
		if(s <= md)
			update(x << 1, l, md, s, t, k);
		if(t > md)
			update(x << 1 | 1, md + 1, r, s, t, k);
		return;
	}
	inline int query(int x, int l, int r, int y){
		if(l == r)
			return dat[x];
		int md = l + r >> 1;
		if(y <= md)
			return min(dat[x], query(x << 1, l, md, y));
		return min(dat[x], query(x << 1 | 1, md + 1, r, y));
	}
}segc, segr;

