			ans += max(0, res);
			segr.update(1, 0, segr.size() - 1, 1, res, x);
			row[x] = 1;
		}
		if(!tp && !col[x]){
			int res = segr.query(1, 0, segr.size() - 1, x);
			--res;
			ans += max(0, res);
			segc.update(1, 0, segc.size() - 1, 1, res, x);
			col[x] = 1;
		}
	}

	printf("%lld\n", 1ll * (n - 2) * (n - 2) - ans);
	return 0;
}

