template<typename Monoid, typename OperatorMonoid = Monoid>
struct LazySegmentTree{
    using F = function<Monoid(Monoid, Monoid)>;
    using G = function<Monoid(Monoid, OperatorMonoid)>;
    using H = function<OperatorMonoid(OperatorMonoid, OperatorMonoid)>;
    using C = function<OperatorMonoid(OperatorMonoid, int)>;

    int sz;
    vector<Monoid> data;
    vector<OperatorMonoid> lazy;
    const F f;
    const G g;
    const H h;
    const Monoid M1;            // モノイドの単位元
    const OperatorMonoid OM0;   // 作用素モノイドの単位元
    const C c;

    LazySegmentTree(int n, const F f, const G g, const H h, const Monoid &M1,
        const OperatorMonoid OM0, const C c = [](OperatorMonoid a, int b){return a;})
        : f(f), g(g), h(h), M1(M1), OM0(OM0), c(c)
    {
        sz = 1;
        while(sz < n)   sz <<= 1;
        data.assign(sz << 1, M1);
        lazy.assign(sz << 1, OM0);
    }

    void set(int k, const Monoid &x){
        data[k + sz] = x;
    }

    void build(){
        for(int k = sz - 1; k > 0; --k){
            data[k] = f(data[k << 1], data[k << 1 | 1]);
        }
    }

    void propagate(int k, int len){
        if(lazy[k] != OM0){
            if(k < sz){
                lazy[k << 1] = h(lazy[k << 1], lazy[k]);
                lazy[k << 1 | 1] = h(lazy[k << 1 | 1], lazy[k]);
            }
            data[k] = g(data[k], c(lazy[k], len));
            lazy[k] = OM0;
        }
    }

    Monoid update(int a, int b, const OperatorMonoid &x, int k = 1, int l = 0, int r = -1){
        if(r == -1)     r = sz;
        propagate(k, r - l);
        if(r <= a || b <= l)    return data[k];
        else if(a <= l && r <= b){
            lazy[k] = h(lazy[k], x);
            propagate(k, r - l);
            return data[k];
        }
        else{
            return data[k] = f(update(a, b, x, k << 1, l, (l + r) >> 1),
                                update(a, b, x, k << 1 | 1, (l + r) >> 1, r));
        }
    }

    Monoid query(int a, int b, int k = 1, int l = 0, int r = -1){
        if(r == -1)     r = sz;
        propagate(k, r - l);
        if(r <= a || b <= l)    return M1;
        else if(a <= l && r <= b)   return data[k];
        else{
            return f(query(a, b, k << 1, l, (l + r) >> 1),
                        query(a, b, k << 1 | 1, (l + r) >> 1, r));
        }
    }

    Monoid operator[](const int &k){
        return query(k, k + 1);
    }
};

template<typename Monoid>
struct SegmentTree{
    using F = function<Monoid(Monoid, Monoid)>;

    int sz;
    vector<Monoid> seg;

    const F f;      // モノイドに対して二項演算を行う関数オブジェクト
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1){
        sz = 1;
        while(sz < n)   sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x){
        seg[k + sz] = x;
    }

    void build(){
        for(int k = sz - 1; k > 0; --k){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    void update(int k, const Monoid &x){
        k += sz;
        seg[k] = x;
        while(k >>= 1){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    Monoid query(int a, int b){
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1){
            if(a & 1)   L = f(L, seg[a++]);
            if(b & 1)   R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const{
        return seg[k + sz];
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;
    auto f = [](int x, int y){ return min(x, y); };
    vector<LazySegmentTree<int>> seg(2, LazySegmentTree<int>(N + 1, f, f, f, INF, INF));
    for(int i = 2; i < N; ++i){
        seg[0].set(i, N);
        seg[1].set(i, N);
    }
    seg[0].build();
    seg[1].build();
    for(int loop = 0; loop < Q; ++loop){
        int T, x;
        cin >> T >> x;
        --T;
        int R = seg[T ^ 1][x];
        seg[T ^ 1].update(x, x + 1, 1);
        seg[T].update(1, R, x);
    }
    // for(int i = 0; i < 2; ++i){
    //     for(int j = 2; j < N; ++j){
    //         cerr << seg[i][j] << ' ';
    //     } cerr << '\n';
    // }
    SegmentTree<int> S(N + 1, [](int a, int b){return a + b;}, 0);
    vector<P> table;
    for(int i = 2; i < N; ++i){
        int val = seg[1][i];
        table.emplace_back(val, i);
        if(val > 3) S.set(i, 1);
    }
    S.build();
    sort(table.rbegin(), table.rend());
    while(table.size() && table.back().first == 1){
        table.pop_back();
    }
    // cerr << table.size() << endl;
    // cerr << "table\n";
    // for(auto p : table) cerr << p.first << ' ' << p.second << '\n';
    ll ans = 0;
    for(int i = 2; i < N; ++i){
        if(table.size()){
            while(table.size() && table.back().first == i){
                S.update(table.back().second, -1);
                table.pop_back();
            }
        }
        int p = seg[0][i];
        //cerr << p << endl;
        if(p > 1)   ans += p - 2;
        ans += S.query(p, N);
        // cerr << "ans:" << ans << endl;
    }
    cout << ans << endl;
}

