namespace Segtr{
	int tr[2][maxn*4+5];
	#define lc id<<1
	#define rc id<<1|1
	void build(int l,int r,int id){
		if(l==r){
			tr[0][id]=tr[1][id]=n;
			return;
		}
		int mid=l+r>>1;
		build(l,mid,lc); build(mid+1,r,rc);
		tr[0][id]=tr[1][id]=n;
	}
	int query(int l,int r,int st,int id,int k){
		if(tr[k][id]!=1<<30) return tr[k][id];
		int mid=l+r>>1;
		if(st<=mid) return query(l,mid,st,lc,k);
		else return query(mid+1,r,st,rc,k);
	}
	void change(int l,int r,int st,int en,int da,int id,int k){
		if(st<=l&&en>=r){
			tr[k][id]=min(tr[k][id],da);
			return;
		}
		int mid=(l+r)>>1;
		tr[k][id]=1<<30;
		if(st<=mid) change(l,mid,st,en,da,lc,k);
		if(en>mid) change(mid+1,r,st,en,da,rc,k);
	}
}
