pair<vector<vll>,vector<vll>> getOrdering(string s){	s+=char(36);	vector<vll> dp;  dp.reserve(log2(szs(s))+3);	vector<vll> dp2;  dp2.reserve(log2(szs(s))+3);	vll ordering(szs(s)),eqClass(szs(s));	{		vector<pair<char,ll> > temp(szs(s));		f(i,0,szs(s)) temp[i]={s[i],i};		sort(all(temp));		f(i,0,szv(temp)) ordering[temp[i].ss]=i;		eqClass[temp[0].ss]=0;		f(i,1,szv(temp)){			 if(temp[i].ff!=temp[i-1].ff) eqClass[temp[i].ss]=eqClass[temp[i-1].ss]+1;			 else eqClass[temp[i].ss]=eqClass[temp[i-1].ss];		} 		dp.pb(ordering); dp2.pb(eqClass);	}	ll k=1;	while((1<<(k-1))<szs(s)){		vector<pair<pair<ll,ll>,ll> > arr(szs(s));		for(ll i=0;i<szs(s);i++){			arr[i]={{eqClass[i],eqClass[(i+(1<<(k-1)))%szs(s)]},i};		}		spclSort(arr);		f(i,0,szs(s)) ordering[arr[i].ss]=i;		eqClass[arr[0].ss]=0;		f(i,1,szv(s)){			 if(arr[i].ff!=arr[i-1].ff) eqClass[arr[i].ss]=eqClass[arr[i-1].ss]+1;			 else eqClass[arr[i].ss]=eqClass[arr[i-1].ss];		} 		dp.pb(ordering); dp2.pb(eqClass);		k++;	}	return {dp,dp2};}
