class segmentTree{
private:
	ll *segment;
	ll *lazy;
	ll n; string type;
	void updateMAX(ll s,ll e,ll l,ll r,ll idx,ll val){
		if(e<l||r<s) return;
		if(s==e){
			segment[idx]=val;
			return;
		}
		ll mid = (s+e)>>1;
		updateMAX(s,mid,l,r,2*idx,val);
		updateMAX(mid+1,e,l,r,2*idx+1,val);
		segment[idx]=max(segment[2*idx],segment[2*idx+1]);
	}

	ll queryMAX(ll s,ll e,ll l,ll r,ll idx){
		if(e<l||r<s) return -INF;
		if(l<=s&&e<=r){
			return segment[idx];
		}
		ll mid = (s+e)>>1;
		ll lt = queryMAX(s,mid,l,r,2*idx);
		ll rt = queryMAX(mid+1,e,l,r,2*idx+1);
		return max(lt,rt);
	}

	void callme(ll idx){
		segment[idx]=min(lazy[idx],segment[idx]);
		lazy[2*idx]=min(lazy[2*idx],lazy[idx]);
		lazy[2*idx+1]=min(lazy[2*idx+1],lazy[idx]);
	}

	void updateMIN(ll s,ll e,ll l,ll r,ll idx,ll val){
		if(e<l||r<s) return;
		if(l<=s and e<=r){
			lazy[idx]=min(lazy[idx],val);
			return;
		}
		ll mid = (s+e)>>1;
		updateMIN(s,mid,l,r,2*idx,val);
		updateMIN(mid+1,e,l,r,2*idx+1,val);
		segment[idx]=min(segment[2*idx],segment[2*idx+1]);
	}

	ll queryMIN(ll s,ll e,ll l,ll r,ll idx){
		if(lazy[idx]!=INF) callme(idx);
		if(e<l||r<s) return INF;
		if(l<=s&&e<=r){
			return segment[idx];
		}
		ll mid = (s+e)>>1;
		ll lt = queryMIN(s,mid,l,r,2*idx);
		ll rt = queryMIN(mid+1,e,l,r,2*idx+1);
		return min(lt,rt);
	}

public:
	segmentTree(ll x,string ms){
		n = x;
		type = ms;
		segment = new ll[6*n+2];
		lazy = new ll[6*n+2];
		cf(i,0,4*n) segment[i]=INF;
		cf(i,0,4*n) lazy[i]=INF;
	}

	void update(ll l,ll r,ll val){
		if(type=="MAX"){
			updateMAX(1,n,l,r,1,val);
		}
		else if(type=="MIN"){
			updateMIN(1,n,l,r,1,val);
		}
	}

	ll query(ll l,ll r){
		if(type=="MAX"){
			return queryMAX(1,n,l,r,1);
		}
		else if(type=="MIN"){
			return queryMIN(1,n,l,r,1);
		}
		return -1;
	}
};


void solve(){
	ll n,q; cin>>n>>q;
	ll bcnt = (n-2)*(n-2);
	segmentTree h(n,"MIN"),v(n,"MIN");

	cf(i,1,n) h.update(i,i,n),v.update(i,i,n);

	cf(i,1,q){
		ll typ,x; cin>>typ>>x;
		if(typ==1){
			ll elem = h.query(x,x);
			v.update(1,elem,x);
			bcnt-=(elem-2);
		}
		if(typ==2){
			ll elem = v.query(x,x);
			h.update(1,elem,x);
			bcnt-=(elem-2);
		}
	}

	cout<<bcnt<<endl;
}

