template <typename T, typename U>
struct LazySegTree {
  std::function<T (T, T)> op;
  T id;
  std::function<U (U, U)> lazy_op;
  U lazy_id;
  std::function<T (U, int)> lazy_apply;

  int n;

  std::vector<T> node;
  std::vector<T> lazy_node;

  LazySegTree(std::function<T (T, T)> _op, T _id, std::function<U (U, U)> _lazy_op, U _lazy_id, std::function<T (U, int)> _lazy_apply, std::vector<T> valvec) {
    op = _op;
    id = _id;
    lazy_op = _lazy_op;
    lazy_id = _lazy_id;
    lazy_apply = _lazy_apply;

    for (n = 1; n < valvec.size(); n *= 2);

    node.resize(2*n-1);
    for (int i = 0; i < valvec.size(); i++) node[n-1+i] = valvec[i];
    for (int i = valvec.size(); i < n; i++) node[n-1+i] = id;
    for (int i = n-2; i >= 0; i--) node[i] = op(node[2*i+1], node[2*i+2]);

    lazy_node.resize(2*n-1);
    for (int i = 0; i < 2*n-1; i++) lazy_node[i] = 1000000000;
  }

  void eval(int k, int l, int r) {
    node[k] = std::min(node[k], lazy_node[k]);
    if (k < n-1) {
      lazy_node[2*k+1] = std::min(lazy_node[2*k+1], lazy_node[k]);
      lazy_node[2*k+2] = std::min(lazy_node[2*k+2], lazy_node[k]);
    }
    lazy_node[k] = 1000000000;
  }

  T op_range(int a, int b) { return op_range(a, b, 0, 0, n); }
  T op_range(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return id;

    eval(k, l, r);

    if (a <= l && r <= b) return node[k];
    return op(op_range(a, b, 2*k+1, l, (l+r)/2), op_range(a, b, 2*k+2, (l+r)/2, r));
  }

  void update_range(int a, int b, T val) { return update_range(a, b, val, 0, 0, n); }
  void update_range(int a, int b, T val, int k, int l, int r) {
    if (r <= a || b <= l) return;

    eval(k, l, r);

    if (a <= l && r <= b) {
      lazy_node[k] = val;
      return;
    }
    update_range(a, b, val, 2*k+1, l, (l+r)/2);
    update_range(a, b, val, 2*k+2, (l+r)/2, r);
  }
};

int main() {
  int N, Q;
  std::cin >> N >> Q;

  std::vector<int> width_valvec(N, N-2);
  std::vector<int> height_valvec(N, N-2);
  LazySegTree<int,int> width(
      [](int a, int b) { return std::min<int>(a, b); },
      1000000000,
      [](int a, int b) { return std::min<int>(a, b); },
      1000000000,
      [](int a, int b) { return std::min<int>(a, b); },
      width_valvec);
  LazySegTree<int,int> height(
      [](int a, int b) { return std::min<int>(a, b); },
      1000000000,
      [](int a, int b) { return std::min<int>(a, b); },
      1000000000,
      [](int a, int b) { return std::min<int>(a, b); },
      width_valvec);

  long long int ngot = 0;
  for (int i = 0; i < Q; i++) {
    int type, x;
    std::cin >> type >> x;
    x--;
    if (type == 1) {
      int heightx = height.op_range(x,x+1);
      //std::cout << heightx << std::endl;
      ngot += heightx;
      width.update_range(1,heightx+1,x-1);
    } else {
      int widthx = width.op_range(x,x+1);
      //std::cout << widthx << std::endl;
      ngot += widthx;
      height.update_range(1,widthx+1,x-1);
    }
  }
  std::cout << ((long long int)N-2)*((long long int)N-2)-ngot << std::endl;
  return 0;
}

