using namespace std;

const int INF = 1e9;

struct ZKW {
    vector<pair<int, int>> arr; int n;
    ZKW(int sz) : arr(sz * 2, make_pair(INF, 0)), n(sz) {}
    void upd(int x, pair<int, int> v) {
        for(arr[x += n] = v; x > 1; x >>= 1) {
            arr[x >> 1] = min(arr[x], arr[x ^ 1]);
        }
    }
    pair<int, int> ask(int l, int r) {// [l, r]
        pair<int, int> ret(INF, 0); r++;
        for(l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if(l & 1) ret = min(ret, arr[l++]);
            if(r & 1) ret = min(ret, arr[--r]);
        }
        return ret;
    }
};

ZKW LR(maxn), BT(maxn);
int n, k;

int solve(int l, int r, int b, int t) {
    if(r < l || t < b) return 0;
    //printf("%lld %lld %lld %lld\n", l, r, b, t);
    int ret = 0;
    auto A = b == 2 ? LR.ask(l, r) : make_pair(INF, 0LL);
    auto B = l == 2 ? BT.ask(b, t) : make_pair(INF, 0LL);
    //printf("%lld %lld\n", A.second, B.second);
    if(min(A, B).first == INF) return (r - l + 1) * (t - b + 1);
    if(A < B) { // L, R
        ret += solve(l, A.second - 1, b, t);
        ret += solve(A.second + 1, r, b, t);
    }
    else { // B, T
        ret += solve(l, r, b, B.second - 1);
        ret += solve(l, r, B.second + 1, t);
    }
    return ret;
}

