void build(int v, int l, int r) {
    lz[0][v] = lz[1][v] = n;
    x[0][v] = x[1][v] = n;
    if (l == r) {
        return;
    }
    int m = (l + r) / 2;
    build(2 * v, l, m);
    build(2 * v + 1, m + 1, r);
}
void push(int t, int v) {
    x[t][v] = min(x[t][v], lz[t][v]);
    lz[t][2 * v] = min(lz[t][2 * v], x[t][v]);
    lz[t][2 * v + 1] = min(lz[t][2 * v + 1], x[t][v]);
}
int find_min(int v, int l, int r, int b) {
    push(t, v);
    if (l == r && r == b) {
        return x[t][v];
    }
    int m = (l + r) / 2;
    if (b <= m) {
        return find_min(2 * v, l, m, b);
    }
    return find_min(2 * v + 1, m + 1, r, b);
}
void upd(int v, int l, int r, int L, int R, int z) {
    if (L <= l && r <= R) {
        lz[t][v] = min(lz[t][v], z);
      	push(t, v);
        return;
    }
    if (r < L || R < l) {
        return;
    }
    push(t, v);
    int m = (l + r) / 2;
    upd(2 * v, l, m, L, R, z);
    upd(2 * v + 1, m + 1, r, L, R, z);
    x[t][v] = min(x[t][2 * v], x[t][2 *  v + 1]);
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> q;
    build(1, 1, n);
    ll r = (n - 2) * (n - 2);
    while (q--) {
        int a; cin >> t >> a; t--;
        int b = find_min(1, 1, n, a);
        r -= max(0, b - 2); t = 1 - t;
        upd(1, 1, n, 1, b, a);
    }
    cout << r << endl;
    return 0;
}

