template <typename T>
struct segment_tree {
  using F = function<T(T, T)>;
  using C = function<bool(T)>;
  int sz;
  vector<T> seg;

  const F f;
  const T M1;

  segment_tree(int n, const F f, const T &M1) : f(f), M1(M1) {
    sz = 1;
    while (sz < n) sz <<= 1;
    seg.assign(2 * sz, M1);
  }
  segment_tree(const vector<T> &v, const F f, const T &M1) : f(f), M1(M1) {
    int n = int(v.size());
    sz = 1;
    while (sz < n) sz <<= 1;
    seg.assign(2 * sz, M1);
    for (int i = 0; i < n; i++) set(i, v[i]);
    build();
  }

  void set(int k, const T &x) { seg[k + sz] = x; }

  void build() { for (int k = sz - 1; k > 0; k--) seg[k] = f(seg[2 * k], seg[2 * k + 1]); }

  void update(int k, const T &x) {
    k += sz;
    seg[k] = x;
    while (k >>= 1) seg[k] = f(seg[2 * k], seg[2 * k + 1]);
  }

  T query(int a, int b) {
    T L = M1, R = M1;
    for (a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if (a & 1) L = f(L, seg[a++]);
      if (b & 1) R = f(seg[--b], R);
    }
    return f(L, R);
  }

  T operator[](const int &k) const { return seg[k + sz]; }

  int find_subtree(int a, const C &check, T &M, bool type) {
    while (a < sz) {
      T nxt = type ? f(seg[2 * a + type], M) : f(M, seg[2 * a + type]);
      if (check(nxt)) a = 2 * a + type;
      else M = nxt, a = 2 * a + 1 - type;
    }
    return a - sz;
  }

  int find_first(int a, const C &check) {
    T L = M1;
    if (a <= 0) {
      if (check(f(L, seg[1]))) return find_subtree(1, check, L, false);
      return -1;
    }
    int b = sz;
    for (a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
      if (a & 1) {
        T nxt = f(L, seg[a]);
        if (check(nxt)) return find_subtree(a, check, L, false);
        L = nxt;
        ++a;
      }
    }
    return -1;
  }

  int find_last(int b, const C &check) {
    T R = M1;
    if (b >= sz) {
      if (check(f(seg[1], R))) return find_subtree(1, check, R, true);
      return -1;
    }
    int a = sz;
    for (b += sz; a < b; a >>= 1, b >>= 1) {
      if (b & 1) {
        T nxt = f(seg[--b], R);
        if (check(nxt)) return find_subtree(b, check, R, true);
        R = nxt;
      }
    }
    return -1;
  }
};
