void solve() {
  int N, Q;
  CIN(N, Q);
  segment_tree<int> h_st(N - 2, [](int a, int b){ return max(a, b); }, 0);
  segment_tree<int> v_st(N - 2, [](int a, int b){ return max(a, b); }, 0);
  int ans = 0;
  rep(_, Q) {
    int t, x;
    CIN(t, x);
    x -= 2;
    if(t == 1) {
      int d = h_st.find_first(0, [&](int a){ return a > x; });
      if (d == -1) d = N - 2;
      ans += d;
      v_st.update(x, d);
    } else {
      int d = v_st.find_first(0, [&](int a){ return a > x; });
      if (d == -1) d = N - 2;
      ans += d;
      h_st.update(x, d);
    }
  }
  COUT((N - 2) * (N - 2) - ans);
}


