void upd(int rt, int l, int r, int ll, int rr, int v, int A[]) {
  if (ll <= l && rr >= r) {
    chmin(A[rt], v);
    return;
  }
  if (A[rt]) {
    chmin(A[rt << 1], A[rt]);
    chmin(A[rt << 1 | 1], A[rt]);
    A[rt] = 0;
  }
  int mid = (l + r) >> 1;
  if (ll <= mid) upd(rt << 1, l, mid, ll, rr, v, A);
  if (rr > mid) upd(rt << 1 | 1, mid + 1, r, ll, rr, v, A);
}
int query(int rt, int l, int r, int p, int A[]) {
  if (l == r) {
    return A[rt];
  }
  int mid = (l + r) >> 1;
  if (A[rt]) {
    chmin(A[rt << 1 | 1], A[rt]);
    chmin(A[rt << 1], A[rt]);
    A[rt] = 0;
  }
  if (p <= mid) return query(rt << 1, l, mid, p, A);
  return query(rt << 1 | 1, mid + 1, r, p, A);
}
