#include <bits/stdc++.h>
using namespace std;

int MAX_N=262144;
vector<vector<int64_t>> seg(MAX_N*2-1,vector<int64_t>(2));
int64_t qu(int t,int a,int b,int k,int l, int r){
  if(r<=a||b<=l){
    return -1;
  }
  else if(a<=l&&r<=b){
    return seg[k][t];
  }
  else{
    int64_t X=qu(t,a,b,k*2+1,l,(l+r)/2);
    int64_t Y=qu(t,a,b,k*2+2,(l+r)/2,r);
    return max(X,Y);
  }
}

void chmax(int t,int64_t a,int b){
  int D=MAX_N-1+b;
  seg[D][t]=a;
  while(D>0){
    D--;
    D/=2;
    seg[D][t]=max(seg[2*D+1][t],seg[2*D+2][t]);
  }
}


int main(){
  int64_t N,Q;
  cin>>N>>Q;
  int64_t Z=(N-2)*(N-2);
  chmax(0,N,N-2);
  chmax(1,N,N-2);
  for(int i=0;i<Q;i++){
    int t,b,T;
    cin>>t>>b;
    t--;
    T=(t+1)%2;
    int l=0,r=N;
    while(r-l>1){
      int D=(l+r)/2;
      if(qu(T,0,D,0,0,MAX_N)>=b-1){
        r=D;
      }
      else{
        l=D;
      }
    }
    Z-=l;
    chmax(t,l,b-2);
  }
  cout<<Z<<endl;
}

