struct LazySegmentTree {
private:
    int n;
    vector<ll> node,lazy;
    vector<bool> upd;
public:
    LazySegmentTree(vector<ll> v) {
        int sz = v.size();
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2*n-1);
        lazy.resize(2*n-1,1e9);
        upd.resize(2*n-1,false);
        for (int i = 0;i < sz;++i) node[i+n-1] = v[i];
        for (int i = n-2;i >= 0;--i) node[i] = min(node[i*2+1],node[i*2+2]);
    }

    void eval(int k,int l,int r) {
        if (upd[k]) {
            node[k] = min(node[k],lazy[k]);
            if (r-l > 1) {
                lazy[2*k+1] = min(lazy[2*k+1],lazy[k]);
                lazy[2*k+2] = min(lazy[2*k+2],lazy[k]);
                upd[2*k+1] = upd[2*k+2] = true;
            }
            lazy[k] = 1e9;
            upd[k] = false;
        }
    }

    void update(int a,int b,ll x,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = n;
        eval(k,l,r);
        if (b <= l || r <= a) return;
        if (a <= l && r <= b) {
            lazy[k] = min(lazy[k],x);
            upd[k] = true;
            eval(k,l,r);
        } else {
            update(a,b,x,2*k+1,l,(l+r)/2);
            update(a,b,x,2*k+2,(l+r)/2,r);
            node[k] = min(node[2*k+1],node[2*k+2]);
        }
    }

    ll getmin(int a,int b,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = n;
        if (b <= l || r <= a) return INT64_MAX;
        eval(k,l,r);
        if (a <= l && r <= b) return node[k];
        ll vl = getmin(a,b,k*2+1,l,(l+r)/2);
        ll vr = getmin(a,b,2*k+2,(l+r)/2,r);
        return min(vl,vr);
    }
};

int main() {
    ll n;
    int q;
    cin >> n >> q;
    ll ans = (n-2)*(n-2);
    LazySegmentTree segx(vector<ll>(n+1,n)),segy(vector<ll>(n+1,n));
    while (q--) {
        int c,d;
        cin >> c >> d;
        if (c == 1) {
            ll x = segx.getmin(d,d+1);
            ans -= x-2;
            segy.update(0,x,d);
        } else {
            ll y = segy.getmin(d,d+1);
            ans -= y-2;
            segx.update(0,y,d);
        }
        // for (int i = 0;i < n;++i) cout << segy.getmin(i,i+1) << " ";
        // cout << ans << newl;
    }
    cout << ans << newl;
}

