void pointUpdate(int* t, int node, int tl, int tr, int index, int val) {
	if(tl == tr)
		t[node] = val;
	else {
		int mid = (tl+tr)/2;
		if(index <= mid)
			pointUpdate(t,2*node,tl,mid,index,val);
		else
			pointUpdate(t,2*node+1,mid+1,tr,index,val);

		t[node] = min(t[2*node],t[2*node+1]);
	}
}

int pointQuery(int* t, int node,int tl, int tr, int index) {
	if(tl == tr)
		return t[node];

	int mid = (tl+tr)/2;
	if(index <= mid)
		return min(t[node],pointQuery(t,2*node,tl,mid,index));

	return min(t[node],pointQuery(t,2*node+1,mid+1,tr,index));
}

void rangeUpdate(int* t, int node, int tl, int tr, int l, int r, int val) {
	if(r < l)
		return;

	if((tl == l) && (tr == r)) {
		t[node] = min(t[node],val);
	}
	else {
		int mid = (tl+tr)/2;
		if(r <= mid)
			rangeUpdate(t,2*node,tl,mid,l,r,val);
		else if(l > mid)
			rangeUpdate(t,2*node+1,mid+1,tr,l,r,val);
		else{
			rangeUpdate(t,2*node,tl,mid,l,mid,val);
			rangeUpdate(t,2*node+1,mid+1,tr,mid+1,r,val);
		}

