struct segTree{
    segTree *leftSeg;
    segTree *rightSeg;
    int push;
    int from , till;

    segTree(int l, int r){
        from = l;
        till = r;
        push = -1;
        if(l == r)
            return;
        int mid = ( l + r)/2;
        leftSeg = new segTree(l, mid);
        rightSeg = new segTree(mid+1, r);
    }

    void update(int l, int r, int curr){
        if(from != till && push != -1){
            leftSeg->push = push;
            rightSeg->push = push;
            push = -1;
        }

        if( l > till || r < from )
            return;

        if(from >= l && till <= r){
            push = curr;
            return;
        }

        leftSeg->update(l, r, curr);
        rightSeg->update(l, r, curr);
    }

    int get(int ind){
        if(from == till){
            if(push != -1)
                return push;
            return nn;
        }
        if(push != -1){
            leftSeg->push = push;
            rightSeg->push = push;
            push = -1;
        }
        if(ind <= leftSeg->till)
            return leftSeg->get(ind);
        else
            return rightSeg->get(ind);

    }


};


