const int MAXN = 2e5 + 5;

int n , Q , vis[MAXN][3];
int tr[MAXN << 2][2] , tag[MAXN << 2][2];
void build(int l , int r , int now) {
	tag[now][0] = 1e9;tag[now][1] = 1e9;
	if(l == r) {
		tr[now][0] = tr[now][1] = n;
		return;
	}
	int mid = (l + r) >> 1;
	build(l , mid , now << 1);
	build(mid + 1 , r , now << 1 | 1);
	tr[now][0] = min(tr[now << 1][0] , tr[now << 1 | 1][0]);
	tr[now][1] = min(tr[now << 1][1] , tr[now << 1 | 1][1]);
}
void push_down(int now) {
	if(tag[now][0] != 1e9) {
		int v = tag[now][0];
		tr[now << 1][0] = min(tr[now << 1][0] , v);tag[now << 1][0] = min(tag[now << 1][0] , v);
		tr[now << 1 | 1][0] = min(tr[now << 1 | 1][0] , v);tag[now << 1 | 1][0] = min(tag[now << 1 | 1][0] , v);
		tag[now][0] = 1e9;
	}
	if(tag[now][1] != 1e9) {
		int v = tag[now][1];
		tr[now << 1][1] = min(tr[now << 1][1] , v);tag[now << 1][1] = min(tag[now << 1][1] , v);
		tr[now << 1 | 1][1] = min(tr[now << 1 | 1][1] , v);tag[now << 1 | 1][1] = min(tag[now << 1 | 1][1] , v);
		tag[now][1] = 1e9;
	}
}
void update(int l , int r , int now , int x , int y , int v , int t) {
	if(l >= x && r <= y) {
		if(t == 0) tr[now][t] = min(tr[now][t] , v) , tag[now][t] = min(tag[now][t] , v);
		if(t == 1) tr[now][t] = min(tr[now][t] , v) , tag[now][t] = min(tag[now][t] , v);
		return;
	}
	int mid = (l + r) >> 1;
	push_down(now);
	if(x <= mid) update(l , mid , now << 1 , x , y , v , t);
	if(y > mid) update(mid + 1 , r , now << 1 | 1 , x , y , v , t);
	tr[now][0] = min(tr[now << 1][0] , tr[now << 1 | 1][0]);
