class SegmentTree {
  const ll inf = 1e18;
  int n, n0;
  vector<ll> max_v;

  void push(int k) {
    if (max_v[k] < max_v[2 * k + 1]) {
      max_v[2 * k + 1] = max_v[k];
    }
    if (max_v[k] < max_v[2 * k + 2]) {
      max_v[2 * k + 2] = max_v[k];
    }
  }

  void update(int k) { max_v[k] = max(max_v[2 * k + 1], max_v[2 * k + 2]); }

  void _update_min(ll x, int a, int b, int k, int l, int r) {
    if (b <= l || r <= a) {
      return;
    }
    if (a <= l && r <= b) {
      max_v[k] = min(max_v[k], x);
      return;
    }

    push(k);
    _update_min(x, a, b, 2 * k + 1, l, (l + r) / 2);
    _update_min(x, a, b, 2 * k + 2, (l + r) / 2, r);
    update(k);
  }

  ll _query_max(int a, int b, int k, int l, int r) {
    if (b <= l || r <= a) {
      return 0;
    }
    if (a <= l && r <= b) {
      return max_v[k];
    }
    push(k);
    ll lv = _query_max(a, b, 2 * k + 1, l, (l + r) / 2);
    ll rv = _query_max(a, b, 2 * k + 2, (l + r) / 2, r);
    return max(lv, rv);
  }

 public:
  SegmentTree(int n) { SegmentTree(n, nullptr); }

  SegmentTree(int n, ll *a) : n(n) {
    max_v.resize(4 * n);
    n0 = 1;
    while (n0 < n) n0 <<= 1;

    for (int i = 0; i < n; ++i) {
      max_v[n0 - 1 + i] = (a != nullptr ? a[i] : 0);
    }

    for (int i = n; i < n0; ++i) {
      max_v[n0 - 1 + i] = -inf;
    }
    for (int i = n0 - 2; i >= 0; i--) update(i);
  }

  void update_min(int a, int b, ll x) { return _update_min(x, a, b, 0, 0, n0); }

  ll query_max(int a, int b) { return _query_max(a, b, 0, 0, n0); }
};

