            update1((2*v)+1,tm+1,tr,pos,val);
        tree1[v]=min(tree1[(2*v)],tree1[(2*v)+1]);
    }
}
ll query1(ll v,ll tl,ll tr,ll l,ll r)
{
    if (l>r) 
        return inf;
    if((l==tl)&&(r==tr))
        return tree1[v];
    ll tm=(tl+tr)/2;
    return min(query1(2*v,tl,tm,l,min(r,tm)),query1((2*v)+1,tm+1,tr,max(l,tm+1),r));
}
