const int maxn = 2e5 + 5;

int n, q, qtype, x, st[2][4 * maxn]; // st[row / col][node];
bool marked[2][4 * maxn]; 

void build(int v, int tl, int tr, int type) {
    if (tl == tr) {
        st[type][v] = n;
    } else {
        int tm = (tl + tr) / 2;
        build(v*2, tl, tm, type);
        build(v*2+1, tm+1, tr, type);
        st[type][v] = 0;
    }
}

void push(int v, int type) {
    if (marked[type][v]) {
        st[type][v*2] = st[type][v*2+1] = st[type][v];
        marked[type][v*2] = marked[type][v*2+1] = true;
        marked[type][v] = false;
    }
}

void update(int v, int tl, int tr, int l, int r, int new_val, int type) {
    if (l > r) 
        return;
    if (l == tl && tr == r) {
        st[type][v] = new_val;
        marked[type][v] = true;
    } else {
        push(v, type);
        int tm = (tl + tr) / 2;
        update(v*2, tl, tm, l, min(r, tm), new_val, type);
        update(v*2+1, tm+1, tr, max(l, tm+1), r, new_val, type);
    }
}

int get(int v, int tl, int tr, int pos, int type) {
    if (tl == tr) {
        return st[type][v];
    }
    push(v, type);
    int tm = (tl + tr) / 2;
    if (pos <= tm) 
        return get(v*2, tl, tm, pos, type);
    else
        return get(v*2+1, tm+1, tr, pos, type);
}


int32_t main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> q;
    build(1, 1, n, 0);
    build(1, 1, n, 1);
    int ans = (n - 2) * (n - 2);
    for(int i = 0; i < q; i++)
    {
        cin >> qtype >> x;
        qtype--;
        int end = get(1, 1, n, x, qtype) - 1;
        ans -= max(end - 1, 0ll);
        int lo = 1, hi = end + 1, mid;
        while(lo < hi)
        {
            mid = (lo + hi) / 2;
            if(get(1, 1, n, mid, qtype ^ 1) < x)
                lo = mid + 1;
            else
                hi = mid;
        }
        assert(lo == hi);
        if(lo < end)
            update(1, 1, n, lo, end, x, qtype ^ 1);
        update(1, 1, n, x, x, 1, qtype);
    }
    cout << ans << "\n";
    return 0;
}

