struct F {
    ll x;
};

ll mapping(F l, ll x){ return min(x, l.x);}
F composition(F l, F r) { return F{min(l.x, r.x)};}

F id() { return F{INFLL};}

ll op(ll x, ll y){ return min(x, y);}

ll e() { return INFLL;}

class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}

    int N, Q;

    bool input() {
        is >> N >> Q;
        return !!is;
    }

    void run();
};

void solver::run(){
    if(!input()) return;
    ll black = (N-2ll)*(N-2ll);
