        segw.set(i, N-2);
        segh.set(i, N-2);
    } // end i

    for (int i = 0; i < Q; ++i) {
        char c;
        ll x;
        is >> c >> x ;
        x--;
        if(c == '1'){
            ll p = segh.get(x);
            black -= p;
            segw.apply(0, p+1, F{x-1});
        }
        else{
            ll p = segw.get(x);
            black -= p;
            segh.apply(0, p+1, F{x-1});
        }
    } // end i
    cout << black << endl;

}

