const int roz = (1<<19);

int tree[roz][2];

int ask(int lo,int hi,int u,int a,int b,int idx)
{
    if(lo == a && b == hi) return tree[u][idx];
    if(b<=a) return 1e9;
    int mid =(lo+hi)/2;
    int l = ask(lo,mid,u*2,a,min(b,mid),idx);
    int r = ask(mid,hi,u*2+1,max(a,mid),b,idx);
    return min(l,r);
}

void wst(int pos,int val,int idx)
{
    pos += roz/2;
    tree[pos][idx] = val;
    pos /= 2;
    while(pos >= 1)
    {
        tree[pos][idx] = min(tree[pos*2][idx],tree[pos*2+1][idx]);
        pos /= 2;
    }
    return;
}

