    fill_n(trow,4*MAXN,N-1);
    fill_n(tcol,4*MAXN,N-1);
}

void update(ll node, ll start, ll end, ll l, ll r, ll val, ll kon) { // kon=0-row
    if(start>end || l>end || r<start) return;

    if(l<=start&&end<=r) {
        if(!kon) {
            trow[node] = min(trow[node],val);
        } else {
            tcol[node] = min(tcol[node],val);
        }
        return;
    }

    ll mid = (start+end)/2;

    if(l<=mid) update(2*node,start,mid,l,r,val,kon);
    if(mid+1<=r) update(2*node+1,mid+1,end,l,r,val,kon);

    /*if(!kon) {
        trow[node] = min(trow[node],trow[2*node]);
        trow[node] = min(trow[node],trow[2*node+1]);
    } else {
        tcol[node] = min(tcol[node],min(tcol[2*node],tcol[2*node+1]));
    }*/
}

ll query(ll node, ll start,ll end,ll l,ll r, ll kon) {
    if(start>end || l>end || r<start) return N-1;

    if(l<=start&&end<=r) {
        if(!kon) {
            return trow[node];
        } else {
            return tcol[node];
        }

    }

    ll mid = (start+end)/2;

    ll left = N-1, right = N-1;

    if(l<=mid) left = query(2*node,start,mid,l,r,kon);
    if(mid+1<=r) right = query(2*node+1,mid+1,end,l,r,kon);

    if(!kon) {
        return min(trow[node],min(left,right));
    } else {
        return min(tcol[node],min(left,right));
    }

}


