void build(int v, int l, int r) {
    lz[0][v] = lz[1][v] = n;
    x[0][v] = x[1][v] = n;
    if (l == r) {
        return;
    }
    int m = (l + r) / 2;
    build(2 * v, l, m);
    build(2 * v + 1, m + 1, r);
}
void push(int t, int v) {
  	for (int i = 0; i < 2; i++) {
        x[i][v] = min(x[i][v], lz[i][v]);
        lz[i][2 * v] = min(lz[i][2 * v], x[i][v]);
        lz[i][2 * v + 1] = min(lz[i][2 * v + 1], x[i][v]);      	
    }
}
int find_min(int v, int l, int r, int b) {
    push(t, v);
    if (l == r && r == b) {
        return x[t][v];
    }
    int m = (l + r) / 2;
    if (b <= m) {
        return find_min(2 * v, l, m, b);
    }
    return find_min(2 * v + 1, m + 1, r, b);
}
void upd(int v, int l, int r, int L, int R, int z) {
    if (L <= l && r <= R) {
        lz[t][v] = min(lz[t][v], z);
      	push(t, v);
        return;
    }
    if (r < L || R < l) {
        return;
    }
    push(t, v);
    int m = (l + r) / 2;
    upd(2 * v, l, m, L, R, z);
    upd(2 * v + 1, m + 1, r, L, R, z);
}

