struct MyMain {
	int N = in;
	int Q = in;

	void Run() {
		int borderX = N - 1;
		int borderY = N - 1;
		arr<int> scoreX(N, -1);
		arr<int> scoreY(N, -1);
		int leftScore = N - 2;
		int topScore = N - 2;

		int score = (N - 2) * (N - 2);
		REP(q, Q) {
			int order = in;
			int x = in(-1);

			if (order == 1) {
				if (x < borderX) {
					score -= topScore;
					int i = x;
					while (i < N && scoreX[i] < 0) {
						scoreX[i] = topScore;
						i++;
					}
					borderX = x;
					leftScore = borderX - 1;
				}
				else {
					score -= scoreX[x];
				}
			}
			else {
				if (x < borderY) {
					score -= leftScore;
					int i = x;
					while (i < N && scoreY[i] < 0) {
						scoreY[i] = leftScore;
						i++;
					}
					borderY = x;
					topScore = borderY - 1;
				}
				else {
					score -= scoreY[x];
				}
			}
		}

		out << score;
	}
};

