int solve() {

    SS(ll, N, Q);

    using lint = long long;
    using M    = lint;
    const M ID_OM(4e18);
    auto f = [](M a, M b) -> M {
        return min(a, b);
    };
    auto g = [](M a, M b) -> M {
        return b == ID_OM ? a : b;
    };
    auto p = [](M a, int b) -> M {
        return a;
    };
    auto row = make_segtree(vector<M>(N, N - 1), M(4e18), ID_OM, f, g, g, p);
    auto col = make_segtree(vector<M>(N, N - 1), M(4e18), ID_OM, f, g, g, p);

    ll res = (N - 2) * (N - 2);

    REP (_, Q) {
        SS(int, T, X);
        if (T == 1) {
            ll near = row.query(X - 1, X);
            res -= near - 1;
            if (col[near - 1] > X - 1) col.update(0, near, X - 1);
        } else {
            ll near = col.query(X - 1, X);
            res -= near - 1;
            if (row[near - 1] > X - 1) row.update(0, near, X - 1);
        }
    }

    print(res);

    return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

struct Node{
    int left, right;
    bool lazy;
    int k;
}nodes[2][800000];

void build(int tp, int u, int l, int r, int n){
    nodes[tp][u].left = l;
    nodes[tp][u].right = r;
    nodes[tp][u].k = n;
    nodes[tp][u].lazy = false;
    if(l == r){
        return;
    }
    build(tp, u << 1, l, (l + r) >> 1, n);
    build(tp, (u << 1) + 1, ((l + r) >> 1) + 1, r, n);
    return;
}

int query(int tp, int u, int x){
    if(!nodes[tp][u].lazy)
        return nodes[tp][u].k;
    if(x <= nodes[tp][u << 1].right)
        return query(tp, u << 1, x);
    else
        return query(tp, (u << 1) + 1, x);
}

void modify(int tp, int u, int l, int r, int k){
    if(nodes[tp][u].left == l && nodes[tp][u].right == r && !nodes[tp][u].lazy){
        if(k < nodes[tp][u].k)
            nodes[tp][u].k = k;
        return;
    }
    if(nodes[tp][u].left == l && nodes[tp][u].right == r && k < nodes[tp][u].k){
        nodes[tp][u].k = k;
        nodes[tp][u].lazy = false;
        return;
    }

    if(!nodes[tp][u].lazy && nodes[tp][u].k < k)
        k = nodes[tp][u].k;
    nodes[tp][u].lazy = true;
    if(r <= nodes[tp][u << 1].right)
        modify(tp, u << 1, l, r, k);
    else if(l >= nodes[tp][(u << 1) + 1].left)
        modify(tp, (u << 1) + 1, l, r, k);
    else{
        modify(tp, u << 1, l, nodes[tp][u << 1].right, k);
        modify(tp, (u << 1) + 1, nodes[tp][(u << 1) + 1].left, r, k);
    }
    nodes[tp][u].k = min(nodes[tp][u << 1].k, nodes[tp][(u << 1) + 1].k);
}


void solve(){
    int n, q;
    cin >> n >> q;
    build(0, 1, 1, n, n);
    build(1, 1, 1, n, n);
    long long ans = (n - 2) * 1ll * (n - 2);
    while(q--){
        int t, x;
        cin >> t >> x;
        int m = query(t - 1, 1, x);
        if(m <= 2)
            continue;
        ans -= m * 1ll - 2;
        modify(2 - t, 1, 2, m - 1, x);
    }
    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int T = 1;
    //cin >> T;
    while(T--){
        solve();
    }
    return 0;
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

const int N = 2e6;

int x[2][N], lz[2][N];

void build(int v, int l, int r, int n) {
    if (l == r) {
        x[0][v] = x[1][v] = n;
        return;
    }
    int m = (l + r) / 2;
    build(2 * v, l, m, n);
    build(2 * v + 1, m + 1, r, n);
    x[0][v] = x[1][v] = n;
}
void push(int t, int v) {
    if (!lz[t][v]) {
        return;
    }
    x[t][v] = min(x[t][v], lz[t][v]);
    if (!lz[t][2 * v]) {
        lz[t][2 * v] = 1e9;
    }
    if (!lz[t][2 * v + 1]) {
        lz[t][2 * v + 1] = 1e9;
    }
    lz[t][2 * v] = min(lz[t][2 * v], x[t][v]);
    lz[t][2 * v + 1] = min(lz[t][2 * v + 1], x[t][v]);
    lz[t][v] = 0;
}
int find_min(int t, int v, int l, int r, int L, int R) {
    push(t, v);
    if (L <= l && r <= R) {
        return x[t][v];
    }
    if (r < L || R < l) {
        return 1e9;
    }
    int m = (l + r) / 2;
    return min(find_min(t, 2 * v, l, m, L, R),
               find_min(t, 2 * v + 1, m + 1, r, L, R));
}
void upd(int t, int v, int l, int r, int L, int R, int z) {
    if (L <= l && r <= R) {
        if (!lz[t][v] || z < lz[t][v]) {
            lz[t][v] = z;
            push(t, v);
        }
        return;
    }
    if (r < L || R < l) {
        return;
    }
    int m = (l + r) / 2;
    upd(t, 2 * v, l, m, L, R, z);
    upd(t, 2 * v + 1, m + 1, r, L, R, z);
    x[t][v] = min(x[t][2 * v], x[t][2 * v + 1]);
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    ll n, q; cin >> n >> q;
    build(1, 1, n, n);
    ll r = (ll)(n - 2) * (n - 2);
    while (q--) {
        int t, a; cin >> t >> a;
        int b = find_min(t - 1, 1, 1, n, a, a);
        r -= max(0, b - 2);
        if (b > 1) {
            upd(2 - t, 1, 1, n, 2, b, a);
        }
    }
    cout << max(0, r) << endl;
    return 0;
}

