        return;
    }
    ll mid=(l+r)/2;
    koro(2*node,l,mid,val);
    koro(2*node+1,mid+1,r,val);
    return;
}
void update(ll node,ll l,ll r,ll indl,ll indr,ll val)
{
    if(indl>indr || indl>r || indr<l)
        return;
    if(l>=indl && r<=indr)
    {
        koro(node,l,r,val);
        return;
    }
    done(node);
    ll mid=(l+r)/2;
    update(node*2,l,mid,indl,indr,val);
    update(node*2+1,mid+1,r,indl,indr,val);
    return;
}
ll query(ll node,ll l,ll r,ll le,ll ri)
{
    if(le>ri || l>ri || r<le)
        return 0;
    if(le<=l && r<=ri)
        return t[node];
    done(node);
    ll mid=(l+r)/2;
    return ((query(2*node,l,mid,le,ri)+query(2*node+1,mid+1,r,le,ri)));
}
void done1(ll node)
{
    if(marked1[node])
    {
        marked1[2*node]=marked1[2*node+1]=true;
        t1[2*node]=t1[2*node+1]=t1[node];
        marked1[node]=false;
    }
    return;
}
void koro1(ll node,ll l,ll r,ll val)
{
    if(t1[node]==0)
    {
        t1[node]=val;
        marked1[node]=true;
        return;
    }
    if(l==r || marked1[node]==true)
    {
        t1[node]=min(t1[node],val);
        marked1[node]=true;
        return;
    }
    ll mid=(l+r)/2;
    koro1(2*node,l,mid,val);
    koro1(2*node+1,mid+1,r,val);
    return;
}
void update1(ll node,ll l,ll r,ll indl,ll indr,ll val)
{
    if(indl>indr || indl>r || indr<l)
        return;
    if(l>=indl && r<=indr)
    {
        koro1(node,l,r,val);
        return;
    }
    done1(node);
    ll mid=(l+r)/2;
    update1(node*2,l,mid,indl,indr,val);
    update1(node*2+1,mid+1,r,indl,indr,val);
    return;
}
ll query1(ll node,ll l,ll r,ll le,ll ri)
{
    if(le>ri || l>ri || r<le)
        return 0;
    if(le<=l && r<=ri)
        return t1[node];
    done1(node);
    ll mid=(l+r)/2;
    return ((query1(2*node,l,mid,le,ri)+query1(2*node+1,mid+1,r,le,ri)));
}
