template <class T>
struct BIT {
    BIT(int n) : b(n + 1), n(n) {}
    void add(int i, T v) {
        for (int k = i + 1; k <= n; k += k & -k) b[k] += v;
    }
    T sum(int k) {
        T s = 0;
        for (; k > 0; k -= k & -k) s += b[k];
        return s;
    }
    vector<T> b;
    int n;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, q;
    cin >> n >> q;

    BIT<int> bt[2] = { n, n };
    auto f = [&](int h, int k, int v) {
        bt[h].add(0, v);
        bt[h].add(k, -v);
    };
    for (int h = 0; h < 2; h++) {
        f(h, n - 2, n - 2);
    }

    ll s = 0;
    for (int i = 0; i < q; i++) {
        int t, x;
        cin >> t >> x;
        t--; x -= 2;

        int k = bt[t ^ 1].sum(x + 1);
        if (k > 0) {
            s += k;
            int y = bt[t].sum(k - 1 + 1);
            if (x < y) {
                f(t, k, x - y);
            }
        }
    }

    s = (ll)(n - 2) * (n - 2) - s;
    cout << s << endl;

    return 0;
}

