template<class T>
struct Compress{
    vector<T> cv; //順番にして重複を消したもの
    bool flag;
    Compress():flag(false){};

    Compress(const vector<T> &v):flag(false){
        add(v);
    }
    int size(){
        return (int)cv.size();
    }
    //vectorを追加
    void add(const vector<T> &v){
        flag=false;
        copy(v.begin(),v.end(),back_inserter(cv));
    }
    //Tを追加
    void add(const T x){
        flag=false;
        cv.emplace_back(x);
    }
    //テーブルを作る O(NlogN)
    void build(){
        flag=true;
        sort(cv.begin(),cv.end());
        cv.erase(unique(cv.begin(),cv.end()),cv.end());
    }
    //vectorの要素を座標圧縮したものを返す O(NlogN)
    vector<int> get(const vector<T> &v) const{
        assert(flag);
        vector<int> ret(v.size());
        for(int i=0;i<v.size();i++) ret[i]=lower_bound(cv.begin(),cv.end(),v[i])-cv.begin();
        return ret;
    }
    //xを座標圧縮したものを返す O(logN)
    int get(const T x)const{
        return lower_bound(cv.begin(),cv.end(),x)-cv.begin();
    }
    //座標圧縮後のkが示す実際の値 O(1)
    T &operator[](int k){
        return cv[k];
    }
};

template<class T,class F>
struct SegmentTree{
    const F f;
    int size;
    vector<T> seg;
    const T unit;

    SegmentTree(int N,const F _f,const T &_unit) :f(_f),unit(_unit){
        size=1;
        while(size<N) size<<=1;
        seg.assign(2*size,unit);
    }
    void set(int k,const T &x){
        seg[k+size]=x;
    }
    void build(){
        for(int k=size-1;k>0;k--){
            seg[k]=f(seg[2*k],seg[2*k+1]);
        }
    }
    void update(int k,const T &x){
        k+=size;
        seg[k]=x;
        while(k>>=1){
            seg[k]=f(seg[2*k],seg[2*k+1]);
        }
    }
    //[a:b)
    T query(int a,int b){
        T L=unit,R=unit;
        for(a+=size,b+=size;a<b;a>>=1,b>>=1){
            if(a&1) L=f(L,seg[a++]);
            if(b&1) R=f(seg[--b],R);
        }
        return f(L,R);
    }

    T operator[](const int &k) const{
        return seg[k+size];
    }
};

void solve(){
    ll N,Q;
    cin>>N>>Q;
    Compress<int> C1,C2;
    vector<int> h,w;
    vector<pii> V;

    for(int i=0;i<Q;i++){
        int q,v;
        cin>>q>>v;
        v--;
        V.emplace_back(q,v);
        if(q==1) h.push_back(v);
        else w.push_back(v);
    }
    C1.add(h); C2.add(w);
    C1.add(N-1); C2.add(N-1);
    C1.build(); C2.build();
    auto f=[](int a,int b){
        return min(a,b);
    };
    SegmentTree<int,decltype(f)> seg1(N,f,N-1),seg2(N,f,N-1);
    ll ret=0;
    for(int i=0;i<Q;i++){
        int q,v;
        tie(q,v)=V[i];

        if(q==1){
            int cv=C1.get(v);
            int deep=seg1.query(cv,N);
            ret+=deep-1;
            int c2=C2.get(deep);
            if(seg2[c2]>v){
                seg2.update(c2,v);
            }
        }else{
            int cv=C2.get(v);
            int deep=seg2.query(cv,N);
            ret+=deep-1;
            int c1=C1.get(deep);
            if(seg1[c1]>v){
                seg1.update(c1,v);
            }
        }
    }
    cout<<(N-2)*(N-2)-ret<<endl;
}

