struct ft {
	vector <int> BIT;
	int sz;

	void init(int n) {
		BIT.resize(n + 1, 0);
		sz = n;
	}

	void upd(int i, int val) {
		for(; i <= sz; i += i&-i)
		BIT[i] = max(BIT[i], val);
	}

	int qry(int i) {
		int mx = 0;
		for(; i; i -= i&-i)
		mx = max(mx, BIT[i]);
		return mx;
	}
};

