struct segtree
{
    vector<int> rows, cols;
    int sz;
    void init(int n)
    {
        sz = n;
        rows.assign(4*n, n);
        cols.assign(4*n, n);
    }
    void update_rows(int v, int tl, int tr, int l, int r, int x)
    {
        if (tl == l && tr == r)
        {
            rows[v] = min(rows[v], x); return;
        }
        if (l > r) return;
        int tm = (tl + tr) / 2;
        update_rows(2*v, tl, tm, l, min(r, tm), x);
        update_rows(2*v+1, tm+1, tr, max(l, tm+1), r, x);
    }
    void update_rows(int r, int x)
    {
        update_rows(1, 0, sz-1, 0, r, x);
    }
    int getMin_rows(int v, int tl, int tr, int x)
    {
        if (tl == tr) return rows[v];
        int tm = (tl + tr) / 2;
        if (x <= tm) return min(rows[v], getMin_rows(2*v, tl, tm, x));
        else return min(rows[v], getMin_rows(2*v+1, tm+1, tr, x));
    }
    int getMin_rows(int x)
    {
        return getMin_rows(1, 0, sz-1, x);
    }
    void update_cols(int v, int tl, int tr, int l, int r, int x)
    {
        if (tl == l && tr == r)
        {
            cols[v] = min(cols[v], x); return;
        }
        if (l > r) return;
        int tm = (tl + tr) / 2;
        update_cols(2*v, tl, tm, l, min(r, tm), x);
        update_cols(2*v+1, tm+1, tr, max(l, tm+1), r, x);
    }
    void update_cols(int r, int x)
    {
        update_cols(1, 0, sz-1, 0, r, x);
    }
    int getMin_cols(int v, int tl, int tr, int x)
    {
        if (tl == tr) return cols[v];
        int tm = (tl + tr) / 2;
        if (x <= tm) return min(cols[v], getMin_cols(2*v, tl, tm, x));
        else return min(cols[v], getMin_cols(2*v+1, tm+1, tr, x));
    }
    int getMin_cols(int x)
    {
        return getMin_cols(1, 0, sz-1, x);
    }

};
