      }
      while(it!=M.end() && it->second > y) {
        it = M.erase(it);
      }
    }
    M.insert({x, y});
  }
  ll query(ll X) {
    auto it = M.lower_bound(X);
    if(it==M.begin()) {
      return n;
    } else {
      it--;
      return it->second;
    }
  }
  map<ll,ll> M;
  ll n;
};

int main() {
  ll n,q;
  cin >> n >> q;
  ll ans = (n-2)*(n-2);
  Query EC(n); // pos -> earliest column < pos
  Query FC(n); // time -> first column earlier than time
  Query ER(n);
  Query FR(n);
  EC.add(n, 0);
  FC.add(0, n);
  ER.add(n, 0);
  FR.add(0, n);
  for(ll i=1; i<=q; i++) {
    ll typ,pos;
    cin >> typ >> pos;
    ll removed = 0;
    if(typ == 1) { // col
      ll ec = EC.query(pos);
      ll fr = FR.query(ec);
      removed = fr-2;
      EC.add(pos, i);
      FC.add(i, pos);
    } else {
      ll er = ER.query(pos);
      ll fc = FC.query(er);
      //cerr << "pos=" << pos << " er=" << er << " fc=" << fc << endl;
      removed = fc-2;
      ER.add(pos, i);
      FR.add(i, pos);
    }
    ans -= removed;
    //cerr << "typ=" << typ << " pos=" << pos << " removed=" << removed << " ans=" << ans << endl;
  }
  cout << ans << endl;
}

