struct Node{
    int left, right;
    bool lazy;
    int k;
}nodes[2][800000];

void build(int tp, int u, int l, int r, int n){
    nodes[tp][u].left = l;
    nodes[tp][u].right = r;
    nodes[tp][u].k = n;
    nodes[tp][u].lazy = false;
    if(l == r){
        return;
    }
    build(tp, u << 1, l, (l + r) >> 1, n);
    build(tp, (u << 1) + 1, ((l + r) >> 1) + 1, r, n);
    return;
}

int query(int tp, int u, int x){
    if(!nodes[tp][u].lazy)
        return nodes[tp][u].k;
    if(x <= nodes[tp][u << 1].right)
        return query(tp, u << 1, x);
    else
        return query(tp, (u << 1) + 1, x);
}

void modify(int tp, int u, int l, int r, int k){
    if(nodes[tp][u].left == l && nodes[tp][u].right == r && !nodes[tp][u].lazy){
        if(k < nodes[tp][u].k)
            nodes[tp][u].k = k;
        return;
    }
    if(nodes[tp][u].left == l && nodes[tp][u].right == r && k < nodes[tp][u].k){
        nodes[tp][u].k = k;
        nodes[tp][u].lazy = false;
        return;
    }
    nodes[tp][u].lazy = true;
    if(r <= nodes[tp][u << 1].right)
        modify(tp, u << 1, l, r, k);
    else if(l >= nodes[tp][(u << 1) + 1].left)
        modify(tp, (u << 1) + 1, l, r, k);
    else{
        modify(tp, u << 1, l, nodes[tp][u << 1].right, k);
        modify(tp, (u << 1) + 1, nodes[tp][(u << 1) + 1].left, r, k);
    }
    nodes[tp][u].k = min(nodes[tp][u << 1].k, nodes[tp][(u << 1) + 1].k);
}


void solve(){
    int n, q;
    cin >> n >> q;
    build(0, 1, 1, n, n);
    build(1, 1, 1, n, n);
    long long ans = (n - 2) * 1ll * (n - 2);
    while(q--){
        int t, x;
        cin >> t >> x;
        int m = query(t - 1, 1, x);
        if(m <= 2)
            continue;
        ans -= m * 1ll - 2;
        modify(2 - t, 1, 2, m - 1, x);
    }
    cout << ans << "\n";
}

