    void build(int p,int l,int r)
    {
        t[p].r=r,t[p].l=l;
        if(r==l)
        {
            t[p].data=a[l];
            return;
        }
        int mid=(r+l)/2;
        build(2*p,l,mid);
        build(2*p+1,mid+1,r);
        t[p].data=min(t[2*p].data,t[2*p+1].data);
    }
    void spread(int p)
    {
        if(t[p].add!=oo)
        {
            t[2*p].data=min(t[p].add,t[2*p].data);
            t[2*p+1].data=min(t[p].add,t[2*p+1].data);;
            t[2*p].add=min(t[p].add,t[2*p].add);
            t[2*p+1].add=min(t[p].add,t[2*p+1].add);
            t[p].add=oo;
        }
    }
    void change(int p,int l,int r,ll d)
    {
        if(l<=t[p].l&&t[p].r<=r)
        {
            t[p].data=min(t[p].data,d);
            t[p].add=min(t[p].add,d);
            return;
        }
        spread(p);
        int mid=(t[p].l+t[p].r)/2;
        if(l<=mid) change(2*p,l,r,d);
        if(r>mid) change (2*p+1,l,r,d);
        t[p].data=min(t[2*p].data,t[2*p+1].data);

    }
    ll ask(int p,int l,int r)
    {
        if(t[p].l>=l&&t[p].r<=r) return t[p].data;
        spread(p);
        int mid=(t[p].l+t[p].r)/2;
        ll ans=oo;
        if(l<=mid) ans=min(ask(2*p,l,r),ans);
        if(r>mid) ans=min(ask(2*p+1,l,r),ans);
        return ans;
    }
    void changeone(int p,int x,int v)
    {
        if(t[p].l==t[p].r)
        {
            t[p].data=v;
            return;
        }
        spread(p);
        int mid=(t[p].l+t[p].r)/2;
        if(x<=mid) changeone(2*p,x,v);
        else changeone(2*p+1,x,v);
        t[p].data=min(t[2*p].data,t[2*p+1].data);
    }



}c,r;

