        if(op==1)
        {
            int rr=c.ask(1,x,x);
            if(rr==1) continue;
            r.change(1,1,rr-1,x);
            res-=rr-2;
        }
        else
        {
            int rr=r.ask(1,x,x);
            if(rr==1) continue;
            c.change(1,1,rr-1,x);
            res-=rr-2;
        }
    }
