using namespace std;
typedef long long ll;

const int N = 2e6;
int t[N][2], lz[N][2];
ll n, q, a, w;

void build(int v, int l, int r) {
    t[v][0] = lz[v][0] = n;
    t[v][1] = lz[v][1] = n;
    if (l == r) {
        return;
    }
    int m = (l + r) >> 1;
    build(2 * v, l, m);
    build(2 * v + 1, m + 1, r);
}
void push(int v) {
    for (int i = 0; i < 2; i++) {
        t[v][i] = min(t[v][i], lz[v][i]);
        lz[2 * v][i] = min(lz[2 * v][i], t[v][i]);
        lz[2 * v + 1][i] = min(lz[2 * v + 1][i], t[v][i]);
    }
}
void upd(int v, int l, int r, int L, int R, int x) {
    if (R < l || r < L) {
        return;
    }
    if (L <= l && r <= R) {
        lz[v][w] = min(lz[v][w], x);
        push(v); return;
    }
    int m = (l + r) >> 1;
    upd(2 * v, l, m, L, R, x);
    upd(2 * v + 1, m + 1, r, L, R, x);
}
int find_min(int v, int l, int r, int L, int R) {
    push(v);
    if (L <= l && r <= R) {
        return t[v][w];
    }
    if (r < L || R < l) {
        return 1e9;
    }
    int m = (l + r) >> 1;
    return min(find_min(2 * v, l, m, L, R),
               find_min(2 * v + 1, m + 1, r, L, R));
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> q;
    ll r = (n - 2) * (n - 2);
    build(1, 1, n);
    while (q--) {
        cin >> w >> a; w--;
        int b = find_min(1, 1, n, a, a);
        r -= max(0, b - 2);
        w = 1 - w; upd(1, 1, n, 1, b - 1, a);
    }
    cout << r << endl;
    return 0;
}

