const int inf=1e9+7;
const ll mod=1e9+7;
const ll mod1=998244353;
const ll big=1e18;
const double PI=2*asin(1);

ll N;

struct SegmentTree {
  vector<pair<ll, ll> > Tree[20];

  void init() {
    for(ll i=0;i<20;++i) {
      Tree[i].resize((1<<i));
      for(ll j=0;j<Tree[i].size();++j) Tree[i][j] = mp(N-2, big);
    }
  }

  void eval(ll pos1, ll pos2) {
    if(Tree[pos1][pos2].se==big) return;
    if(pos1+1<20) {
      Tree[pos1+1][2*pos2].se = min(Tree[pos1+1][2*pos2].se, Tree[pos1][pos2].se);
      Tree[pos1+1][2*pos2+1].se = min(Tree[pos1+1][2*pos2+1].se, Tree[pos1][pos2].se);
    }
    Tree[pos1][pos2].fi = min(Tree[pos1][pos2].fi, Tree[pos1][pos2].se);
    Tree[pos1][pos2].se = big;
    return;
  }

  void update(ll ql, ll qr, ll x, ll pos1=0, ll pos2=0, ll sl=0, ll sr=(1<<19)) {
    eval(pos1, pos2);
    if(qr<=sl || sr<=ql) return;
    if(ql<=sl && sr<=qr) {
      Tree[pos1][pos2].se = min(Tree[pos1][pos2].se, x);
      eval(pos1, pos2);
      return;
    }
    update(ql, qr, x, pos1+1, 2*pos2, sl, (sl+sr)/2);
    update(ql, qr, x, pos1+1, 2*pos2+1, (sl+sr)/2, sr);
    Tree[pos1][pos2].fi = min(Tree[pos1+1][2*pos2].fi, Tree[pos1+1][2*pos2+1].fi);
    return;
  }

  ll find(ll ql, ll qr, ll pos1=0, ll pos2=0, ll sl=0, ll sr=(1<<19)) {
    eval(pos1, pos2);
    if(sr<=ql || qr<=sl) return big;
    if(ql<=sl && sr<=qr) return Tree[pos1][pos2].fi;
    return min(find(ql, qr, pos1+1, 2*pos2, sl, (sl+sr)/2), find(ql, qr, pos1+1, 2*pos2+1, (sl+sr)/2, sr));
  }
};

int main() {
  ll Q;
  cin>>N>>Q;
  SegmentTree seg1, seg2;
  seg1.init();
  seg2.init();
  ll ans = 0;
  ll query, x;
  ll tmp;
  for(ll i=0;i<Q;++i) {
    cin>>query>>x;
    x -= 2;
    if(query==1) {
      tmp = seg1.find(x, x+1);
      ans += tmp;
      seg2.update(0, tmp, x);
    }
    else {
      tmp = seg2.find(x, x+1);
      ans += tmp;
      seg1.update(0, tmp, x);
    }
  }
  cout<<(N-2)*(N-2)-ans<<endl;
}

