void crt(int node ,int s,int e,int k)
{
    if(s==e)
        t[node][k]=a[s][k];
    else
    {
        int mid=(s+e)/2;
        crt(2*node,s,mid,k);
        crt(2*node+1,mid+1,e,k);
        t[node][k]=op(t[2*node][k],t[2*node+1][k]);
    }
}

void update(int node,int l,int r,int s,int e,int k,int val)
{
    t[node][k]=min(t[node][k], lazy[node][k]);
    if(s!=e)
    {
        lazy[2*node][k]=min(lazy[2*node][k], lazy[node][k]);
        lazy[2*node+1][k]=min(lazy[2*node +1][k], lazy[node][k]);
    }
    if(l>e || r<s)
        return ;
    if(l<=s && e<=r)
    {
        t[node][k]=min(t[node][k],val);
        if(s!=e)
        {
            lazy[2*node][k]=min(lazy[2*node][k],val);
            lazy[2*node+1][k]=min(lazy[2*node +1][k], val);
        }
        return ;
    }
    int mid=(s+e)/2;
    update(2*node,l,r,s,mid,k,val);
    update(2*node+1,l,r,mid+1,e,k,val);
    t[node][k]=op(t[2*node][k],t[2*node+1][k]);
}

int query(int node,int l,int r,int s ,int e,int k)
{

    t[node][k]=min(t[node][k], lazy[node][k]);
    if(s!=e)
    {
        lazy[2*node][k]=min(lazy[2*node][k], lazy[node][k]);
        lazy[2*node+1][k]=min(lazy[2*node +1][k], lazy[node][k]);
    }    
    if(l>e || r<s)
        return 1e6;
    if(l<=s && e<=r)
        return t[node][k];
    int mid=(s+e)/2;
    int p1=query(2*node,l,r,s,mid,k);
    int p2=query(2*node+1,l,r,mid+1,e,k);
    return op(p1,p2);
}

