int parent(int i) {return (i-1) / 2;}
int left(int i) {return (i*2+1);}
int right(int i) {return (i*2+2);}

void update(vector<int>& tree, int s, int i, int v) {
    if(chmin(tree.at(s-1+i),v)){
        int p = parent(s-1+i);
        while(p != 0) {
            tree.at(p) = min(tree.at(left(p)), tree.at(right(p)));
            p = parent(p);
        }
    }

}

int seg_find(vector<int>& tree, int s, int x, int y, int p=-1, int l=0, int r=0) {
    if(p == -1) {
        p = 0;
        l = 0;
        r = s;
    }
    // printf("l = %d, r = %d, p = %d\n", l, r, p);
    if(y <= l or r <= x) return INT_MAX;
    else if(x <= l and r <= y) return tree.at(p);
    else {
        int res_l = seg_find(tree, s, x, y, left(p), l, (l+r)/2);
        int res_r = seg_find(tree, s, x, y, right(p), (l+r)/2, r);
        return min(res_l, res_r);
    }
}

