typedef pair<ll,ll> p2;
#define sz(a) ll(a.size())
ll hell=pow(10,9);
class Tree{
	ll t[800005],lazy[800005];
	public:
	Tree(ll n){
		for(ll i=0;i<800005;i++)
			t[i]=n,lazy[i]=hell;
	}
	void push(ll v){
		ll &x=lazy[v];
		t[2*v]=min(t[2*v],x);
		t[2*v+1]=min(t[2*v+1],x);
		lazy[2*v]=min(lazy[2*v],x);
		lazy[2*v+1]=min(lazy[2*v+1],x);
		x=hell;
	}
	void upd(ll v,ll tl,ll tr,ll l,ll r,ll val){
		if(l>r)
			return;
		if(l==tl&&r==tr){
			t[v]=min(t[v],val);
			lazy[v]=min(lazy[v],val);
			return;
		}
		push(v);
		ll tm=(tl+tr)/2;
		upd(2*v,tl,tm,l,min(r,tm),val);
		upd(2*v+1,tm+1,tr,max(l,tm+1),r,val);
		t[v]=min(t[2*v],t[2*v+1]);
	}
	ll get(ll v,ll tl,ll tr,ll pos){
		if(tl==tr)
			return t[v];
		push(v);
		ll tm=(tl+tr)/2;
		if(pos<=tm) 
			return get(2*v,tl,tm,pos);
		else
			return get(2*v+1,tm+1,tr,pos);
	}
}; 
void solve(){
	ll n,q;
	cin>>n>>q;
	ll res=(n-2)*(n-2);
	Tree *t1 = new Tree(n);
	Tree *t2 = new Tree(n);
	for(ll i=0;i<q;i++){
		ll op,x;
		cin>>op>>x;
		if(op==1){
			ll val=(t1->get(1,1,n,x));
			res-=val-2;
			t2->upd(1,1,n,1,val-1,x);
		}
		else{
			ll val=(t2->get(1,1,n,x));
			res-=val-2;
			t1->upd(1,1,n,1,val-1,x);
		}
	}
	cout<<res;
}
