using namespace std;
typedef long long ll;
typedef long double ld;
#define MAX 5000000000000000000LL
#define MIN -5000000000000000000LL

ll n, q;
ll all, bll;
ll ans;

struct lazysegtree
{
	ll seg[5000010], lazy[5000010];

	/*ll init(ll no, ll s, ll e)
	{
		if(s == e)
			return seg[no] = a[s];

		ll mid = (s + e) / 2;
		ll lef = init(no * 2, s, mid);
		ll rig = init(no * 2 + 1, mid + 1, e);

		return seg[no] = min(lef, rig);
	}*/

	ll update(ll no, ll s, ll e, ll l, ll r, ll v)
	{
		if(lazy[no])
		{
			seg[no] = min(seg[no], lazy[no]);

			if(s != e)
			{
				lazy[no * 2] = min(lazy[no * 2], lazy[no]);
				lazy[no * 2 + 1] = min(lazy[no * 2 + 1], lazy[no]);
			}

			lazy[no] = n;
		}

		if(l > e || r < s)
			return seg[no];

		if(l <= s && e <= r)
		{
			seg[no] = min(seg[no], v);

			if(s != e)
			{
				lazy[no * 2] = min(lazy[no * 2], v);
				lazy[no * 2 + 1] = min(lazy[no * 2 + 1], v);
			}

			return seg[no];
		}

		ll mid = (s + e) / 2;
		ll al = update(no * 2, s, mid, l, r, v);
		ll bl = update(no * 2 + 1, mid + 1, e, l, r, v);

		seg[no] = min(al, bl);
		return seg[no];
	}

	ll query(ll no, ll s, ll e, ll l, ll r)
	{
		if(lazy[no])
		{
			seg[no] = min(seg[no], lazy[no]);

			if(s != e)
			{
				lazy[no * 2] = min(lazy[no * 2], lazy[no]);
				lazy[no * 2 + 1] = min(lazy[no * 2 + 1], lazy[no]);
			}

			lazy[no] = n;
		}

		if(l > e || r < s)
			return n;

		if(l <= s && e <= r)
			return seg[no];

		ll mid = (s + e) / 2;
		ll lef = query(no * 2, s, mid, l, r);
		ll rig = query(no * 2 + 1, mid + 1, e, l, r);

		return min(lef, rig);
	}
};

lazysegtree r, c;

int main(void)
{
	scanf("%lld %lld", &n, &q);

	ans = (n - 2) * (n - 2);

	for(ll i = 0 ; i < 5000010 ; i++)
	{
		r.seg[i] = n;
		r.lazy[i] = n;
		c.seg[i] = n;
		c.lazy[i] = n;
	}

	while(q--)
	{
		scanf("%lld %lld", &all, &bll);

		if(all == 1)
		{
			ll qq = r.query(1, 1, n, bll, bll);
			//printf("%lld\n", qq);
			ans -= max(0LL, qq - 2);
			c.update(1, 1, n, 1, qq, bll);
		}

		else
		{
			ll qq = c.query(1, 1, n, bll, bll);
			//printf("%lld\n", qq);
			ans -= max(0LL, qq - 2);
			r.update(1, 1, n, 1, qq, bll);
		}
	}

	printf("%lld", ans);
	return 0;
}

