using namespace std;

ll seg[2][800005];
ll lazy[2][800005];
ll n;

void push(ll i,ll v)
{
	if(lazy[i][v]==-1) return;
	seg[i][2*v]=min(seg[i][2*v],lazy[i][v]);
	seg[i][2*v+1]=min(seg[i][2*v+1],lazy[i][v]);
	if(lazy[i][2*v]!=-1)
	lazy[i][2*v]=min(lazy[i][v],lazy[i][2*v]);
	else
	lazy[i][2*v]=lazy[i][v];
	if(lazy[i][2*v+1]!=-1)
	lazy[i][2*v+1]=min(lazy[i][v],lazy[i][2*v+1]);
	else
	lazy[i][2*v+1]=lazy[i][v];
	lazy[i][v]=-1;
	return;
}

void build(ll v,ll tl,ll tr)
{
	if(tl==tr)
	{
		seg[0][v]=n-1;
		seg[1][v]=n-1;
		return;
	}
	ll tm=(tl+tr)/2;
	build(2*v,tl,tm);
	build(2*v+1,tm+1,tr);
	seg[0][v]=min(seg[0][2*v],seg[0][2*v+1]);
	seg[1][v]=min(seg[1][2*v],seg[1][2*v+1]);

}

void update(ll i,ll v,ll tl,ll tr,ll l,ll r,ll val)
{
	if(l>r) return;
	if(l>tr || tl>r) return;
	if(l<=tl && tr<=r)
	{
		seg[i][v]=min(seg[i][v],val);
		if(lazy[i][v]==-1)
			lazy[i][v]=val;
		else
			lazy[i][v]=min(lazy[i][v],val);
		return;
	}
	push(i,v);
	ll tm=(tl+tr)/2;
	update(i,2*v,tl,tm,l,r,val);
	update(i,2*v+1,tm+1,tr,l,r,val);
	seg[i][v]=min(seg[i][2*v],seg[i][2*v+1]);
}

ll query(ll i,ll v,ll tl,ll tr,ll pos)
{
	if(pos>tr || pos<tl) return 0;
	if(tl==tr)
	{
		return seg[i][v];
	}
	push(i,v);
	ll tm=(tl+tr)/2;
	if(pos<=tm) return query(i,2*v,tl,tm,pos);
	else return query(i,2*v+1,tm+1,tr,pos);
}

