class SGT{
	public :
	ll num[MAX] ;
	ll d = INF ;
	ll n = 1 ;

	void init(vll &a){
		while(n<a.size()) n *= 2 ;
		for(int i=0;i<n;i++){
			if(i<a.size()) num[i+n-1] = a.at(i) ;
			else num[i+n-1] = d ;
		}
		for(int i=n-2;i>=0;i--){
			num[i] = min(num[i*2+1],num[i*2+2]) ;
		}
	}

	void update(int i,ll a){
		i += n-1 ;
		num[i] = a ;
		while(i){
			i = (i-1)/2 ;
			num[i] = min(num[i*2+1],num[i*2+2]) ;
		}
	}

	ll query(int a,int b,int l,int r,int cur){
		if(a<=l&&r<=b) return num[cur] ;
		if(r<=a||b<=l) return d ;
		ll r1 = query(a,b,l,(l+r)/2,cur*2+1) ;
		ll r2 = query(a,b,(l+r)/2,r,cur*2+2) ;
		return min(r1,r2) ;
	}
} ;

