struct STree {
  int n;
  vi st;
  vi lazy;
  void build (int u, int l, int r, int val) {
    if (l == r) {
      st[u] = val;
      return;
    }
    int m = (l + r) >> 1;
    build(2 * u, l, m, val);
    build(2 * u + 1, m + 1, r, val);
    st[u] = min(st[2 * u], st[2 * u + 1]);
  }
  STree (int l, int r, int val) {
    n = r;
    st.resize(4 * r);
    lazy.resize(4 * r, INT_MAX);
    build(1, l, r, val);
  }
  void push (int u, int l, int r) {
    if (lazy[u] == INT_MAX) return;
    st[u] = min(st[u], lazy[u]);
    if (l != r) {
      lazy[2 * u] = min(lazy[2 * u], lazy[u]);
      lazy[2 * u + 1] = min(lazy[2 * u + 1], lazy[u]);
    }
    lazy[u] = INT_MAX;
  }
  void update (int u, int l, int r, int L, int R, int val) {
    push(u, l, r);
    if (r < L or R < l) return;
    if (L <= l and r <= R) {
      lazy[u] = val;
      push(u, l, r);
      return;
    }
    int m = (l + r) >> 1;
    update(2 * u, l, m, L, R, val);
    update(2 * u + 1, m + 1, r, L, R, val);
    st[u] = min(st[2 * u], st[2 * u + 1]);
  }
  void update (int l, int r, int val) {
    update(1, 1, n, l, r, val);
  }
  int get (int u, int l, int r, int L, int R) {
    push(u, l, r);
    if (r < L or R < l) return INT_MAX;
    if (L <= l and r <= R) return st[u];
    int m = (l + r) >> 1;
    return min(get(2 * u, l, m, L, R), get(2 * u + 1, m + 1, r, L, R));
  };
  int get (int l, int r) {
    return get(1, 1, n, l, r);
  }
};

int main () {
  ios::sync_with_stdio(false); cin.tie(0);
  ll n, q;
  cin >> n >> q;
  ll black = (n - 2) * (n - 2);
  STree vert(1, n, n);
  STree hor(1, n, n);
  while (q--) {
    int t, x;
    cin >> t >> x;
    if (t == 1) {
      int c = vert.get(x, x);
      black -= max(0, c - 2);
      hor.update(1, max(1, c - 1), x);
    }
    if (t == 2) {
      int r = hor.get(x, x);
      black -= max(0, r - 2);
      vert.update(1, max(1, r - 1), x);
    }
  }
  cout << black << '\n';
  return (0);
}

