template<typename Monoid>
class SegmentTreeDual {
	std::vector<Monoid> data;
	size_t sz;

	using F = std::function<Monoid (Monoid, Monoid)>;

	const F f;
	const Monoid E;

	public:
	SegmentTreeDual(const size_t N, const F f, const Monoid E) : f(f), E(E) {
		sz = 1;
		while(sz <= N) sz <<= 1;
		data.assign(sz << 1, E);
	}
	void set(int k, const Monoid x) {
		data[k + sz] = x;
	}
	void build() {
		for(int k = sz - 1; k > 0; k--) data[k] = f(data[k << 1 ^ 0], data[k << 1 ^ 1]);
	}
	void update(int a, int b, const Monoid x) {
		for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if(a & 1) {
				data[a] = f(data[a], x);
				a++;
			}
			if(b & 1) {
				b--;
				data[b] = f(data[b], x);
			}
		}
	}
	void update(int k, const Monoid x) {
		k += sz;
		data[k] = f(data[k], x);
	}
	void change(int k, const Monoid x) {
		k += sz;
		data[k] = x;
	}
	Monoid query(int k) {
		k += sz;
		Monoid ret = data[k];
		while(k >>= 1) ret = f(ret, data[k]);
		return ret;
	}
	const Monoid operator[](int k) {
		return query(k);
	}
};

int main() {
	int n, q; scanf("%d%d", &n, &q);

	cplib::segment_tree<cplib::max_monoid<int, -1>> A(n - 2);
	SegmentTreeDual<int> B(n - 2, [](int x, int y) { return std::min(x, y); }, n - 2);

	i64 ans = (i64)(n - 2) * (n - 2);
	while(q--) {
		int type, x; scanf("%d%d", &type, &x); x -= 2;

		if(type == 1) { // 縦
			int tmp = B[x];
			A.update(x, tmp);
			ans -= tmp;
		} else if(type == 2) { // 横
			auto f = [&](int v) { return v < x; };
			int r = A.search_right(0, f);

			ans -= r;
			B.update(0, r, x);
		}
	}

	printf("%lld\n", ans);

	return 0;
}

