int tx[4 * MAXN], ty[4 * MAXN];

void build(int v, int l, int r) {
    if (l == r - 1) {
        tx[v] = ty[v] = n - 1;
        return;
    }
    int mid = (l + r) / 2;
    build(2 * v + 1, l, mid);
    build(2 * v + 2, mid, r);
    tx[v] = min(tx[2 * v + 1], tx[2 * v + 2]);
    ty[v] = min(ty[2 * v + 1], ty[2 * v + 2]); 
}

void updatex(int v, int l, int r, int pos, int d) {
    if (pos < l || r <= pos)
        return;
    if (l == r - 1) {
        tx[v] = min(tx[v], d);
        return;
    }
    int mid = (l + r) / 2;
    updatex(2 * v + 1, l, mid, pos, d);
    updatex(2 * v + 2, mid, r, pos, d);
    tx[v] = min(tx[2 * v + 1], tx[2 * v + 2]);
}

void updatey(int v, int l, int r, int pos, int d) {
    if (pos < l || r <= pos)
        return;
    if (l == r - 1) {
        ty[v] = min(ty[v], d);
        return;
    }
    int mid = (l + r) / 2;
    updatey(2 * v + 1, l, mid, pos, d);
    updatey(2 * v + 2, mid, r, pos, d);
    ty[v] = min(ty[2 * v + 1], ty[2 * v + 2]);
}

int queryx(int v, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr)
        return tx[v];
    if (r <= ql || qr <= l)
        return n;
    int mid = (l + r) / 2;
    int left = queryx(2 * v + 1, l, mid, ql, qr);
    int right = queryx(2 * v + 2, mid, r, ql, qr);
    return min(left, right);
}

int queryy(int v, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr)
        return ty[v];
    if (r <= ql || qr <= l)
        return n;
    int mid = (l + r) / 2;
    int left = queryy(2 * v + 1, l, mid, ql, qr);
    int right = queryy(2 * v + 2, mid, r, ql, qr);
    return min(left, right);
}


