void probagate(int id , int node , int st , int en)
{
    if (lazy[id][node] != 1e9)
    {
        seg[id][node] = min(seg[id][node] , lazy[id][node]);
        if (st != en)
        {
            lazy[id][2*node] = min(lazy[id][node] , lazy[id][2*node]);
            lazy[id][2*node+1] = min(lazy[id][node] , lazy[id][2*node+1]);
        }
        lazy[id][node] = 1e9;
    }
}

void update(int id , int node , int st , int en , int l , int r , int val)
{
    probagate(id , node , st , en);

    if (st > en || st > r || en < l)
        return;

    if (st >= l && en <= r)
    {
        lazy[id][node] = min(lazy[id][node] , (ll)val);
        return probagate(id , node , st , en);
    }

    int mid = (st+en)/2;
    update(id , 2*node,st,mid,l,r,val);
    update(id , 2*node+1,mid+1,en,l,r,val);
    seg[id][node] = min(seg[id][2*node] , seg[id][2*node+1]);
}

int query(int id , int node , int st , int en , int l , int r)
{
    if (st > en || st > r || en < l) return 1e9;

    probagate(id , node , st , en);

    if (st >= l && en <= r)
    {
        return seg[id][node];
    }

    int mid = (st+en)/2;

    return min(query(id , 2*node , st , mid , l , r) , query(id , 2*node+1 , mid+1 , en , l , r));
}

