int qry(int *bit, int i) {
    int res=0;
    for (; i; i-=i&-i) {
	res=max(res,bit[i]);
    }
    return res;
}

void upd(int *bit, int i, int val) {
    for (; i<=n; i+=i&-i) {
	bit[i]=max(bit[i],val);
    }
}

int getfirst(int *bit, int bound) {
    int lo=0;
    int hi=n;
    while (hi-lo>1) {
	int mid=(lo+hi)/2;
	if (qry(bit,mid) >= bound) {
	    hi = mid;
	} else {
	    lo = mid;
	}
    }
    return hi;
}

