#define lson (idx<<1)
#define rson ((idx<<1) | 1)

const int mx = 2e5 + 9;

int n, q;

struct node {
    int l, r;
    int val;
    int lazy = mx;
};

struct SegTree {
    node tree[8 * mx];

    void build(int idx, int l, int r) {
        int mid = (l + r) / 2;

        tree[idx].l = l, tree[idx].r = r;
        if (l == r) {
            if (l == n) tree[idx].val = 1;
            else tree[idx].val = n;
            return;
        } 

        build(lson, l, mid);
        build(rson, mid + 1, r);

        tree[idx].val = min(tree[lson].val, tree[rson].val);
    }

    void propagate(int idx) {
        tree[idx].val = min(tree[idx].val, tree[idx].lazy);
        tree[lson].lazy = min(tree[lson].lazy, tree[idx].lazy);
        tree[rson].lazy = min(tree[rson].lazy, tree[idx].lazy);

        tree[idx].lazy = mx;
    }

    void update(int idx, int L, int R, int x) {
        int l = tree[idx].l, r = tree[idx].r;
        propagate(idx);

        if (r < L or R < l) return;
        if (L <= l and r <= R) {
            tree[idx].val = min(tree[idx].val, x);
            tree[idx].lazy = min(tree[idx].lazy, x);
            return;
        }

        update(lson, L, R, x);
        update(rson, L, R, x);

        tree[idx].val = min(tree[lson].val, tree[rson].val);
    }

    int query(int idx, int L, int R) {
        int l = tree[idx].l, r = tree[idx].r;
        propagate(idx);

        if (r < L or R < l) return mx;
        if (L <= l and r <= R) {
            return tree[idx].val;
        }

        int q1 = query(lson, L, R);
        int q2 = query(rson, L, R);

        return min(q1, q2);
    }
};

int main() {
    FIO();

    cin >> n >> q;

    SegTree R, C;
    R.build(1, 1, n);
    C.build(1, 1, n);

    ll ans = ll(n - 2) * (n - 2);
    while (q--) {
        int t, x; cin >> t >> x;
        if (t == 1) {
            int hi = R.query(1, x, x);
            ll stones = max(0, hi - 2);

            ans -= stones;
            R.update(1, x, x, 1);
            C.update(1, 1, hi, x);

        } else {
            int hi = C.query(1, x, x);
            ll stones = max(0, hi - 2);

            ans -= stones;
            C.update(1, x, x, 1);
            R.update(1, 1, hi, x);
        }
    }

    cout << ans << endl;
}

