void push(int v, int l, int r){
  if(cnt[v] != inf){
    t[v] = min(cnt[v], t[v]);
    if(l!=r){
      cnt[v*2] = min(cnt[v*2], cnt[v]);
      cnt[v*2+1] = min(cnt[v*2+1], cnt[v]);
    }
    cnt[v] = inf;
  }
}

void upd(int v, int l, int r, int ql, int qr, int k){
  push(v, l, r);
  if(ql<=l && r<=qr){
    cnt[v] = min(cnt[v], k);
    push(v, l, r);
  } else if(l>qr || ql>r){
    return;
  } else{
    push(v, l, r);
    int mid = (l+r)/2;
    upd(v*2, l, mid, ql, qr, k);
    upd(v*2+1, mid+1, r, ql, qr, k);
    t[v] = min(t[v*2], t[v*2+1]);
  }
}

int get(int v, int l, int r, int ql, int qr){
  push(v, l, r);
  if(ql<=l && r<=qr){
    return t[v];
  } else if(l>qr || ql>r){
    return inf;
  } else{
    int mid = (l+r)/2;
    return min(get(v*2, l, mid, ql, qr), get(v*2+1, mid+1, r, ql, qr));
  }
}

int t2[maxn*4];
