    endo operator*(endo rhs) { return {min(value, rhs.value)}; }
  };
  struct mono {
    int value = 1e9;
    mono operator+(mono rhs) { return {min(value, rhs.value)}; }
    mono operator*(endo rhs) { return {min(value, rhs.value)}; }
  };

