    auto g = [](ll a, ll x) { return (x == -1 ? a : x); };
    auto h = [](ll a, ll b) { return b; };
    LazySegmentTree<ll, ll> right(n, f, g, h, n-1, -1), bottom(n, f, g, h, n-1, -1);


