		rrep(i,Vstr.size()-2,0) {
			len++;
			if (Vstr[i] > Vstr[i+1]) {
				lms_type[i] = 0;					// L
				if (lms_type[i+1] == 1) {
					lms_type[i+1] = 2;				// LMS
					lms_long[i+1] = len;			// LMSの長さ格納
