struct st
{
    int tree[1600005],cov[1600005];
    void pushdown(int x)
    {
        if(!cov[x])return;
        tree[x*2]=tree[x*2+1]=cov[x*2]=cov[x*2+1]=cov[x];
        cov[x]=0;
    }
    void modify(int l,int r,int x,int a,int b,int c)
    {
        if(l>=a&&r<=b){tree[x]=cov[x]=c;return;}
        int mid=(l+r)>>1;
        pushdown(x);
        if(a<=mid)modify(l,mid,x*2,a,b,c);
        if(b>mid)modify(mid+1,r,x*2+1,a,b,c);
    }
    int query(int l,int r,int x,int a)
    {
        //cout<<l<<" "<<r<<" "<<x<<" "<<a<<endl;
        pushdown(x);
        if(l==r)return tree[x];
        int mid=(l+r)>>1;
        if(a<=mid)return query(l,mid,x*2,a);
        return query(mid+1,r,x*2+1,a);
    }
}T1,T2;
bool visited1[200005],visited2[200005];
int main()
{
    int n,q,c,x;
    scanf("%d%d",&n,&q);
    for(int i=1;i<=800000;i++)T1.tree[i]=T2.tree[i]=n;
    long long ans=1ll*(n-2)*(n-2);
    while(q--)
    {
        scanf("%d%d",&c,&x);
        if(c==1)
        {
            if(visited1[x])continue;
            visited1[x]=1;
            int t=T1.query(1,n,1,x)-1;
            ans-=t-1;
            if(t>1&&T2.query(1,n,1,1)>x)T2.modify(1,n,1,1,t-1,x);
        }
        else
        {
            if(visited2[x])continue;
            visited2[x]=1;
            int t=T2.query(1,n,1,x)-1;
            ans-=t-1;
            if(t>1&&T1.query(1,n,1,1)>x)T1.modify(1,n,1,1,t-1,x);
        }
    }
    printf("%lld",ans);
    return 0;
}

