		if(l(p)==r(p))return m(p);
		int mid=l(p)+r(p)>>1;
		int ans=m(p);
		if(x<=mid)ans=min(ans,ask(p<<1,x));
		else ans=min(ans,ask(p<<1|1,x));
		return ans;
	}
