    for (Query &query:queries) cin >> query.orient >> query.x, query.x--;
    ll ans = (n - 2) * (n - 2);
    ll v = solve(n, queries);
    ans -= v;

    for (Query &q: queries) if (q.orient == 1) q.orient = 2; else q.orient = 1;
    ll h = solve(n, queries);
    ans -= h;

    cout << ans << endl;

}

