	ios_base::sync_with_stdio(0);
	cin.tie(0);cout.tie(0);
	int q;
	cin >> n >> q;
	int ans = (n - 2) * (n - 2);
	int r = n, b = n;
	auto mrg = [&](info p, info q) {
		info r;
		r.v = min(p.v, q.v);
		r.e = n;
		r.lz = false;
		return r;
	};
	vector <int> rows(n + 1, 0), cols(n + 1, 0);
	segment_tree <info> rowr(mrg, n + 1), colb(mrg, n + 1);
	rowr.build(1, 0, n);
	colb.build(1, 0, n);
	rows[0] = rows[n] = cols[0] = cols[n] = 1;
	while (q--) {
		int id, x;
		cin >> id >> x;
		if (id == 1) {
			if (cols[x])
				break;
			ans -= (colb.query(1, 0, n, x, x).v - 2);
			cols[x] = 1;
			if (r > x) {
				rowr.updateRange(1, 0, n, 1, b, x);
				r = x;
			} 
		} else {
			if (rows[x])
				break;
			ans -= (rowr.query(1, 0, n, x, x).v - 2);
			rows[x] = 1;
			if (b > x) {
				colb.updateRange(1, 0, n, 1, r, x);
				b = x;
			}  
		}
	}
	cout << ans << '\n';
	return 0;
}

