using namespace std;

const int Q = 1 << 18;
int st[2 * Q];

const int inf = 1e9;

void se(int i, int x) {
	i += Q;
	st[i] = x;
	i >>= 1;
	while (i > 0) {
		st[i] = min(st[2 * i], st[2 * i + 1]);
		i >>= 1;
	}
}

int ge(int r) {
	r += Q;
	int res = inf;
	for (int l = Q; l < r; l >>= 1, r >>= 1) {
		if (l & 1) {
			res = min(res, st[l++]);
		}
		if (r & 1) {
			res = min(res, st[--r]);
		}
	}
	return res;
}

int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int n, q;
	cin >> n >> q;
	fill(st, st + 2 * Q, inf);
	vector<int>cols(n, -1);
	set<pair<int, int>> rows;
	for (int i = 0; i < q; i++) {
		int t, x;
		cin >> t >> x;
		if (t == 1) {
			cols[x - 1] = i;
		}
		if (t == 2) {
			rows.emplace(x - 1, i);
			se(i, x - 1);
		}
	}
	long long ans = 0;
	for (int i = 1; i <= n - 2; i++) {
		if (cols[i] == -1) {
			ans += rows.size();
		}
		else {
			int fin = n - 2;
			fin = min(fin, ge(cols[i]) - 1);
			ans += fin;
			vector<pair<int, int>> tt;
			for (auto uu : rows) {
				if (uu.first <= fin) {
					tt.push_back(uu);
					se(uu.second, inf);
				}
				else {
					break;
				}
			}
			for (auto uu : tt) {
				rows.erase(uu);
			}
			ans += rows.size();
		}
	}
	cout << (long long)(n - 2) * (n - 2) - ans;
	return 0;
}

