inline void build(int i,int lf,int rf){
	l[i]=lf,r[i]=rf;
	m1[i]=m2[i]=n-1;
	if(lf==rf){
		qwq[lf]=i;
		return;
	}
	int mid=(lf+rf)>>1;
	build(i<<1,lf,mid),build(i<<1|1,mid+1,rf);
}
inline void modify(int i,int x,int y,int z,int opt){
	if(l[i]>y||r[i]<x) return;
	if(x<=l[i]&&y>=r[i]){
		if(opt) m2[i]=min(m2[i],z);
		else m1[i]=min(m1[i],z);
		return;
	}
	modify(i<<1,x,y,z,opt),modify(i<<1|1,x,y,z,opt);
}
inline int query(int x,int opt){
	x=qwq[x];
	int tp=1ll<<30;
	while(x){
		if(opt) tp=min(tp,m2[x]);
		else tp=min(tp,m1[x]);
		x>>=1;
	}
	return tp;
}
int main(){
	cin>>n>>q;
	build(1,1,n-2);
	ans=1ll*(n-2)*(n-2);
	while(q--){
		scanf("%d%d",&x,&y);
		y--;
		if(x==1){
			tp=query(y,0);
			if(tp>1) ans-=tp-1,modify(1,1,tp-1,y,1);
		}
		else{
			tp=query(y,1);
			if(tp>1) ans-=tp-1,modify(1,1,tp-1,y,0);
		}
	}
	cout<<ans;
}

