using namespace std;

int N, Q;
int a[2][MAXN << 2];

int init(int sid, int l, int r, int id, int v) {
	if (l == r) {
		return a[sid][id] = v;
	}
	int m = (l + r) >> 1;
	return a[sid][id] = min(init(sid, l, m, id << 1, v), init(sid, m + 1, r, id << 1 | 1, v));
}

int query(int sid, int l, int r, int L, int R, int id) {
	if (r < L || R < l) {
		return INF;
	}
	if (L <= l && r <= R) {
		return a[sid][id];
	}
	int m = (l + r) >> 1;
	return min(query(sid, l, m, L, R, id << 1), query(sid, m + 1, r, L, R, id << 1 | 1));
}

void update(int sid, int l, int r, int L, int R, int id, int v) {
	if (r < L || R < l) {
		return;
	}
	if (l == r) {
		a[sid][id] = min(a[sid][id], v);
		return;
	}
	int m = (l + r) >> 1;
	update(sid, l, m, L, R, id << 1, v);
	update(sid, m + 1, r, L, R, id << 1 | 1, v);
	a[sid][id] = min(a[sid][id << 1], a[sid][id << 1 | 1]);
}

signed main()
{
	IO;
	cin >> N >> Q;

	init(0, 1, N, 1, N);
	init(1, 1, N, 1, N);

	int remain = (N - 2) * (N - 2);
	while (Q--) {
		int type, x;
		cin >> type >> x;

		if (type == 1) {
			int mn = query(0, 1, N, x, x, 1);
			// cout << "mn = " << mn << endl;
			remain -= mn - 2;
			update(1, 1, N, 1, mn, 1, x);
		} else {
			int mn = query(1, 1, N, x, x, 1);
			// cout << "mn = " << mn << endl;
			remain -= mn - 2;
			update(0, 1, N, 1, mn, 1, x);
		}
	}

	cout << remain << endl;
	return 0;
}

