// global variables:
int n, q;
class segment_tree{
private:
  int ST[mn * 4], lazy[mn * 4];
  void UPD(int id, int l, int r, int u, int v, int g) {
    if (lazy[id] < inf) {
      ST[id] = min(lazy[id], ST[id]);
      if (l < r) {
        lazy[id * 2] = min(lazy[id], lazy[id*2]);
        lazy[id * 2 + 1] = min(lazy[id], lazy[id*2 + 1]);
      }
      lazy[id] = inf;
    }

    if (u > r || v < l) return;
    if (u <= l && r <= v) {
      ST[id] = min(ST[id], g);
      if (l < r) {
        lazy[id * 2] = min(lazy[id * 2], g);
        lazy[id * 2 + 1] = min(lazy[id * 2 + 1], g);
      }
      return;
    }

    int mid = (l + r) / 2;
    UPD(id*2, l, mid, u, v, g);
    UPD(id*2 + 1, mid + 1, r, u, v, g);
    ST[id] = min(ST[id*2], ST[id*2 + 1]);
  }

  int GET(int id, int l, int r, int u, int v) {
    if (lazy[id] < inf) {
      ST[id] = min(lazy[id], ST[id]);
      if (l < r) {
        lazy[id * 2] = min(lazy[id], lazy[id*2]);
        lazy[id * 2 + 1] = min(lazy[id], lazy[id*2 + 1]);
      }
      lazy[id] = inf;
    }

    if (u > r || v < l) return inf;
    if (u <= l && r <= v) return ST[id];
    int mid = (l+r)/2;
    return min(GET(id*2, l, mid, u, v), GET(id*2+1, mid+1, r, u, v));
  }
public:
