template <typename T>
struct segtree {

  vector<T> seg, lazy;
  segtree(int n = 1e5) {
    n += 5;
    seg.resize(4*n, INT_MAX);
    lazy.resize(4*n, INT_MAX);
  }

  T join(T x, T y) {
    return min(x, y);
  }

  void lazy_update(int x, int s, int e) {
    if (lazy[x] == INT_MAX)	return ;
    seg[x] = min(seg[x], lazy[x]);

    if (s != e)
      lazy[2*x] = min(lazy[2*x], lazy[x]), lazy[2*x+1] = min(lazy[2*x+1], lazy[x]);
    lazy[x] = INT_MAX;
  }

  void build(int x, int s, int e, int val) {
    if (s == e) {
      seg[x] = val;
      return; 
    }

    int mid = (s + e) >> 1;
    build(2 * x, s, mid, val);
    build(2 * x + 1, mid + 1, e, val);

    seg[x] = join(seg[2*x], seg[2*x+1]);
  }

  void update(int x, int s, int e, int l, int r, T val) {
    lazy_update(x, s, e);
    if (s > r || e < l)	return ;

    if (s >= l && e <= r) {
      lazy[x] = min(lazy[x], val);
      lazy_update(x, s, e);
      return;
    }

    int mid = (s + e) >> 1;
    update(2 * x, s, mid, l, r, val);
    update(2 * x + 1, mid + 1, e, l, r, val);

    seg[x] = join(seg[2 * x], seg[2 * x + 1]);
  }

  T query(int x, int s, int e, int l, int r) {
    lazy_update(x, s, e);
    if (e < l || s > r)	return INT_MAX;
    if (s >= l && e <= r){
      return seg[x];
    }

    int mid = (s + e) >> 1;
    return join(query(2 * x, s, mid, l, r), query(2 * x + 1, mid + 1, e, l, r));
  }
};

