        // cout << "# ans : " << ans << endl;
        int q, x; cin >> q >> x;
        // cout << "--> query : " << q << ", " << x << endl;
        if (q == 1) {
            int b = segB.query(x - 1, x);
            if (x > 1) ans -= max(b - 2, 0);
            segR.update(0, b, x);
        } else {
            int r = segR.query(x - 1, x);
            if (x > 1) ans -= max(r - 2, 0);
            segB.update(0, r, x);
        }
        // cout << "--> ans : " << ans << endl;

        // cout << "-----------" << endl;
