int main(void){
  ll n, q;
  cin >> n >> q;



  lazy_segtree<ll, mymin, ret_inf, ll, mymin, mymin, ret_inf> h(n - 2); // min_w_of_h
  lazy_segtree<ll, mymin, ret_inf, ll, mymin, mymin, ret_inf> w(n - 2);
  for (ll i = 0; i < n-2; i++){
    h.set(i, n-3);
    w.set(i, n-3);
  }


  ll ans = (n-2)*(n-2);

  for (ll i = 0; i < q; i++){
    ll a, b;
    cin >> a >> b;

    b--; b--;

    if (a == 1){
      // w列の1〜min_w[b]までを0にする

      ans -= h.get(b) + 1;


      // 1〜min_w[b]までのmin_hを更新する．
      w.apply(0, h.get(b) + 1, b-1);

      h.set(b, 0);
    }
    else {

      ans -= w.get(b) + 1;

      h.apply(0, w.get(b) + 1, b-1);

      w.set(b, 0);
    }
  }

  cout << ans << endl;


  return 0;
}

