#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  ll N; cin >> N;
  ll Q; cin >> Q;

  priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> u;
  priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> l;
  for (ll i = 0; i < Q; i++) {
    ll a, b;
    cin >> a >> b;
    if (a == 1) {
      u.push({b, i});
    } else {
      l.push({b, i});
    }
  }

  ll black = (N - 2) * (N - 2);
  while(!u.empty()) {
    bool ng = false;
    pair<int, int> tu = u.top();
    while (!l.empty()) {
      pair<int, int> tl = l.top();
      if (tu.second < tl.second) {
        l.pop();
        black -= (tu.first - 2);
      } else {
        swap(u, l);
        ng = true;
        break;
      }
    }
    if (!ng) {
      black -= (N - 2);
      u.pop();
    }
  }
  ll ans = black;
  cout << ans << '\n';
  return 0;
}

