int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	int n, q;
	cin >> n >> q;
	vector<pair<int, int>> rows;
	vector<int>cols(n, -1);
	for (int i = 0; i < q; i++) {
		int t, x;
		cin >> t >> x;
		if (t == 1) {
			cols[x - 1] = i;
		}
		if (t == 2) {
			rows.emplace_back(x - 1, i);
		}
	}
	long long ans = 0;
	for (int i = 1; i <= n - 2; i++) {
		if (cols[i] == -1) {
			ans += rows.size();
		}
		else {
			int fin = n - 2;
			vector<pair<int, int>>lost;
			for (auto u : rows) {
				if (u.second < cols[i]) {
					fin = min(fin, u.first - 1);
				}
			}
			ans += fin;
			for (auto u : rows) {
				if (u.first > fin) {
					lost.push_back(u);
				}
			}
			ans += lost.size();
			rows = lost;
		}
	}
	cout <<(long long) (n - 2) * (n - 2) - ans;
	return 0;
}

