#define repex(i, a, b, c) for(int i = a; i < b; i += c)
#define repx(i, a, b) repex(i, a, b, 1)
#define rep(i, n) repx(i, 0, n)
#define repr(i, a, b) for(int i = a; i >= b; i--)

int main(){

    // 1. 入力情報.
    int N, Q;
    scanf("%d %d", &N, &Q);
    vector<int> a(N + 1), b(N + 1);
    repx(i, 1, N + 1) a[i] = b[i] = N;

    LL black = LL(N - 2) * (N - 2);

    // 2. クエリを処理.
    int H = N, W = N;
    while(Q--){
        int t, x;
        scanf("%d %d", &t, &x);

        // (1, x) に 白い石を置く.
        if(t == 1){
            if(x < W){
                repx(i, x, W) b[i] = H;
                W = x;
            }
            black -= b[x] - 2;
        }

        // (x, 1) に 白い石を置く.
        if(t == 2){
            if(x < H){
                repx(i, x, H) a[i] = W;
                H = x;
            }
            black -= a[x] - 2;
        }
    }

    // 3. 出力.
    printf("%lld\n", black);
    return 0;

}

