const int N = 2e5 + 10;

//range min assign and point update query
struct ST
{
    int seg[4*N];

    void build(int node,int ss,int se,int n)
    {
        if(ss == se)
        {
            seg[node] = n;
            return;
        }

        int mid = (ss + se)/2;
        build(node*2+1,ss,mid,n);
        build(node*2+2,mid+1,se,n);
        seg[node] = n;
    }

    void update(int node,int ss,int se,int l,int r,int val)
    {
        if(ss > r || se < l) return;

        if(l <= ss && se <= r) 
        {
            seg[node] = min(seg[node],val);
            return;
        }

        int mid = (ss + se)/2;

        update(node*2+1,ss,mid,l,r,val);
        update(node*2+2,mid+1,se,l,r,val);

        if(node != 0) seg[node] = min(seg[node],seg[(node-1)/2]);
    }

    int query(int node,int ss,int se,int id)
    {
        if(node != 0) seg[node] = min(seg[node],seg[(node-1)/2]);

        if(ss == se) return seg[node];

        int mid = (ss + se)/2;

        if(id <= mid) return query(node*2+1,ss,mid,id);
        else return query(node*2+2,mid+1,se,id);
    }
};

ST bottom,righ;

void solve()
{
    int n,q;
    cin >> n >> q;

    bottom.build(0,0,n-1,n-1);
    righ.build(0,0,n-1,n-1);

    int res = (n-2)*(n-2);

    int t,x;

    while(q--)
    {
        cin >> t >> x; x--;

        if(t == 1)
        {
            int lev = bottom.query(0,0,n-1,x);
            res-=lev;
            if(lev > 0) res++; 

            bottom.update(0,0,n-1,x,x,1);
            righ.update(0,0,n-1,0,lev,x);
        }
        else
        {
            int lev = righ.query(0,0,n-1,x);
            res-=lev;
            if(lev > 0) res++;
            righ.update(0,0,n-1,x,x,1);
            bottom.update(0,0,n-1,0,lev,x);
        }
    }

    cout << res; 
}

