bool contain(int value, vector<int> &v){
   int l = 0, r = v.size();
   while(l<r){
      int m = (l+r)/2;
      if( v[m]<value ){
         l = m+1;
      }else{
         r = m;
      }
   }
   return l!=v.size() and v[l]==value;
}

