	int op,x;
};
node que[max_q+1];
int main(){
	int n,q,gt1,gt2;
	long long ans;
	scanf("%d%d",&n,&q),memset(q1,0,sizeof(q1)),memset(q2,0,sizeof(q2)),memset(eq1,0,sizeof(eq1)),memset(eq2,0,sizeof(eq2));
