void build(int tp, int v, int l, int r) {
    add[tp][v] = n;
    t[tp][v] = n;
    if (l + 1 == r) {
        return;
    }
    int m = (l + r) / 2;
    build(tp, 2 * v + 1, l, m);
    build(tp, 2 * v + 2, m, r);
    return;
}

void push(int tp, int v) {
    add[tp][2 * v + 1] = min(add[tp][2 * v + 1], add[tp][v]);
    add[tp][2 * v + 2] = min(add[tp][2 * v + 2], add[tp][v]);
    add[tp][v] = n;
    return;
}

int get_val(int tp, int v) {
    return min(t[tp][v], add[tp][v]);
}

int get(int tp, int v, int l, int r, int pos) {
    if (pos >= r || pos < l) return n;
    if (l + 1 == r) {
        return get_val(tp, v);
    }
    push(tp, v);
    int m = (l + r) / 2;
    int ans = min(get(tp, 2 * v + 1, l, m, pos), get(tp, 2 * v + 2, m, r, pos));
    t[tp][v] = min(get_val(tp, 2 * v + 1), get_val(tp, 2 * v + 2));
    return ans;
}

void upd(int tp, int v, int l, int r, int ll, int rr, int val) {
    if (ll >= r || rr <= l) return;
    if (ll <= l && r <= rr) {
        add[tp][v] = min(add[tp][v], val);
        return;
    }
    push(tp, v);
    int m = (l + r) / 2;
    upd(tp, 2 * v + 1, l, m, ll, rr, val);
    upd(tp, 2 * v + 2, m, r, ll, rr, val);
    t[tp][v] = min(get_val(tp, 2 * v + 1), get_val(tp, 2 * v + 2));
    return;

}



