void lasy(int i,int l,int r,int x){
  if(L[x][i]==0)return;
  N[x][i]=L[x][i];
  if(r-l>1){
    L[x][i*2  ]=L[x][i];
    L[x][i*2+1]=L[x][i];
  }
  L[x][i]=0;
}
void lsadd(int a,int b,int c,int i,int l,int r,int x){
  lasy(i,l,r,x);
  if(r<=a||b<=l)return;
  if(a<=l&&r<=b){
    L[x][i]=MIN(c,L[x][i]);
    lasy(i,l,r,x);
  }
  else{
    lsadd(a,b,c,i*2  ,l,(l+r)/2,x);
    lsadd(a,b,c,i*2+1,(l+r)/2,r,x);
    N[x][i]=hyouka(N[x][i*2],N[x][i*2+1]);
  }
}
