    var bl: Long = (n - 2).toLong() * (n - 2).toLong()


    for (i in 1..q) {
        val (flg, x) = br.readLine()!!.split(' ').map { it.toInt() - 1 }

        val (a, b) = if (flg == 0) (tate to yoko) else (yoko to tate)

        if (x < a.minBlIdx) {
            bl -= a.minBl
            for (i in x until a.minBlIdx) {
                a.arr[i] = a.minBl
            }
            a.minBlIdx = x
            b.minBl = x - 1
        } else {
            bl -= a.arr[x]
        }
    }

    out.println(bl)

    out.flush()
}

class Field(val n: Int) {
    val arr = IntArray(n) { n - 2 }
    var minBl = n - 2
    var minBlIdx = n
}

