import java.util.Scanner;
import java.util.TreeSet;


public class Main {
	static class Range implements Comparable<Range>{
		long start;
		long depth;
		Range(long s , long d){
			start = s;
			depth = d;
		}
		public Range(Range r) {
			start = r.start;
			depth = r.depth;
		}
		@Override
		public int compareTo(Range o) {
			int c = Long.compare(start, o.start);
			if(c == 0){
				return Long.compare(o.depth, depth);
			}
			return c;
		}
	}
	static class Reversi{
		long black;
		TreeSet<Range> tops;
		TreeSet<Range> lefts;
		public Reversi(int N) {
			long n = (long)N;
			tops = new TreeSet<Range>();
			lefts = new TreeSet<Range>();

			black = (n - 2) * (n - 2);
			Range r = new Range(2, n - 2);
			tops.add(r);
			lefts.add(r);
		}
		void put(int q, int x){
			if(q == 1){
				Range r = tops.lower(new Range(x , -1));
				Range t0 = tops.first();
				black -= r.depth;
				if(t0.start != r.start){
					return ;
				}else{
					Range t = new Range(tops.pollFirst());
					Range l = new Range(lefts.pollFirst());
					l.depth = x - 2;
					lefts.add(l);
					Range t2 = new Range(x + 1, t.depth);
					tops.add(t);
					tops.add(t2);
				}
			}else{
				Range r = lefts.lower(new Range(x , -1));
				Range t0 = lefts.first();
				black -= r.depth;
				if(t0.start != r.start){
					return ;
				}else{
					Range t = new Range(lefts.pollFirst());
					Range l = new Range(tops.pollFirst());
					l.depth = x - 2;
					tops.add(l);
					Range t2 = new Range(x + 1, t.depth);
					lefts.add(t);
					lefts.add(t2);
				}

			}
		}
		long black(){
			return black;
		}
	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		Reversi r = new Reversi(N);
		int Q = sc.nextInt();
		for(int q = 0 ; q < Q ; ++q){
			int a = sc.nextInt();
			int x = sc.nextInt();
			r.put(a, x);
		}
		System.out.println(r.black());
	}
}

import java.io.*;
import java.util.*;
import java.math.BigDecimal;

@SuppressWarnings("unused")
public class Main {
    FastScanner in;
    PrintWriter out;
    final static int MOD = (int)1e9+7;

    void solve(){
        int N = in.nextInt(), Q = in.nextInt();
        int[][] query = new int[Q][2];
        for(int i = 0; i < Q; i++){
            query[i] = in.nextIntArrayDec(2);
        }

        ArrayList<DualSegmentTree> list = new ArrayList<>();
        long[] init = new long[N];
        Arrays.fill(init, N - 1);
        init[N-1] = 0;
        for(int i = 0; i < 2; i++) list.add(new DualSegmentTree(init));

        long ans = (long)(N - 2) * (N - 2);
        for(int i = 0; i < Q; i++){
            int m = (int)list.get(query[i][0]).getPoint(query[i][1]);
            ans -= m - 1;
            list.get(query[i][0] ^ 1).setSegment(0, m + 1, query[i][1]);
            list.get(query[i][0]).setSegment(query[i][1], query[i][1] + 1, 0);
        }
        out.println(ans);
    }

    class DualSegmentTree{
        int d;
        long[] node;

        /*作用素で使える単位元*/
        private long e = Long.MAX_VALUE;

        /*結合律が成り立ち、更新が可換であるような、各要素への作用素*/
        private long f(long nodeVal, long val){
            return Math.min(nodeVal, val);
        }

        /* 単位元で初期化 */
        public DualSegmentTree(int sz){
            long[] v = new long[sz];
            Arrays.fill(v, e);
            init(v);
        }

        /* 配列vで初期化 */
        public DualSegmentTree(long[] v){
            init(v);
        }

        private void init(long[] v){
            this.e = e;
            d = 1;
            while(d < v.length) d *= 2;
            node = new long[2*d];
            Arrays.fill(node, e);
            for(int i = 0; i < v.length; i++)
                node[i+d] = v[i];
        }

        /* 0-indexed:xの要素を取得する */
        public long getPoint(int x){
            x += d;
            long res = node[x];
            while(x > 1){
                x = x / 2;
                res = f(res, node[x]);
            }
            return res;
        }

        /* 指定した区間[L,R)に含まれるすべての要素に作用素を適用するクエリ */
        public void setSegment(int L, int R, long val){
            L += d;
            R += d;
            while (L < R) {
                if ((L & 1) != 0){
                    node[L] = f(node[L], val);
                    L++;
                }
                if ((R & 1) != 0){
                    --R;
                    node[R] = f(node[R], val);
                }
                L >>= 1;
                R >>= 1;
            }
        }
    }

    public static void main(String[] args) {
        new Main().m();
    }

    private void m() {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);
        /*
        try {
            String path = "input.txt";
            out = new PrintWriter(new BufferedWriter(new FileWriter(new File(path))));
        }catch (IOException e){
            e.printStackTrace();
        }
        */
        solve();
        out.flush();
        in.close();
        out.close();
    }

    static class FastScanner {
        private Reader input;

        public FastScanner() {this(System.in);}
        public FastScanner(InputStream stream) {this.input = new BufferedReader(new InputStreamReader(stream));}
        public void close() {
            try {
                this.input.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }

        public long nextLong() {
            try {
                int sign = 1;
                int b = input.read();
                while ((b < '0' || '9' < b) && b != '-' && b != '+') {
                    b = input.read();
                }
                if (b == '-') {
                    sign = -1;
                    b = input.read();
                } else if (b == '+') {
                    b = input.read();
                }
                long ret = b - '0';
                while (true) {
                    b = input.read();
                    if (b < '0' || '9' < b) return ret * sign;
                    ret *= 10;
                    ret += b - '0';
                }
            } catch (IOException e) {
                e.printStackTrace();
                return -1;
            }
        }

        public double nextDouble() {
            try {
                double sign = 1;
                int b = input.read();
                while ((b < '0' || '9' < b) && b != '-' && b != '+') {
                    b = input.read();
                }
                if (b == '-') {
                    sign = -1;
                    b = input.read();
                } else if (b == '+') {
                    b = input.read();
                }
                double ret = b - '0';
                while (true) {
                    b = input.read();
                    if (b < '0' || '9' < b) break;
                    ret *= 10;
                    ret += b - '0';
                }
                if (b != '.') return sign * ret;
                double div = 1;
                b = input.read();
                while ('0' <= b && b <= '9') {
                    ret *= 10;
                    ret += b - '0';
                    div *= 10;
                    b = input.read();
                }
                return sign * ret / div;
            } catch (IOException e) {
                e.printStackTrace();
                return Double.NaN;
            }
