class BIT {
	int n;
	long[] array;
	int mode = 1;

	public BIT(int n){
		this.n = n;
		this.array = new long[n+1];
	}

	public BIT(int n, int mode){
		this.n = n;
		this.array = new long[n+1];
		this.mode = mode;
	}

	public BIT(int[] a){
		this.n = a.length;
		this.array = new long[n+1];
		init(a);
	}
	public BIT(long[] a){
		this.n = a.length;
		this.array = new long[n+1];
		init(a);
	}

	public BIT(int[] a, int mode){
		this.n = a.length;
		this.array = new long[n+1];
		this.mode = mode;
		init(a);
	}
	public BIT(long[] a, int mode){
		this.n = a.length;
		this.array = new long[n+1];
		this.mode = mode;
		init(a);
	}

	public void init(int[] a){
		for(int i = 0; i < n; i++){
			add(i, a[i]);
		}
	}
	public void init(long[] a){
		for(int i = 0; i < n; i++){
			add(i, a[i]);
		}
	}

	public void add(int i, long a){
		switch(mode){
			case 1:
				for(i++; i < array.length; i += i&-i){
					array[i] += a;
				}
				break;

			case 2:
				add(i, i, a);
				break;

			default:
		}
	}

	public void add(int from, int to, long a){ // mode 2 only
		switch(mode){
			case 1:
				break;

			case 2:
				int i = from;
				for(i++; i < array.length; i += i&-i){
					array[i] += a;
				}
				i = to + 1;
				for(i++; i < array.length; i += i&-i){
					array[i] -= a;
				}
				break;

			default:
		}
	}

	public long get(int i){
		switch(mode){
			case 1:
				return getSum(i, i);
			case 2:
				return getSum(i);
			default:
				return getSum(i, i);
		}
	}

	public long getSum(int i){
		long r = 0;
		for(i++; i > 0; i -= i&-i){
			r += array[i];
		}
		return r;
	}

	public long getSum(int from, int to){ // mode 1 only
		return getSum(to) - getSum(from - 1);
	}

	public String toString(){
		StringBuilder sb = new StringBuilder();
		sb.append("[");
		for(int i = 0; i < n; i++){
			sb.append(get(i));
			if(i != n-1) sb.append(", ");
		}
		sb.append("]");
		return sb.toString();
	}
}

