public class Main {
  private static final UpdateRangeGetRangeSegmentTree.Operator OPERATOR = new UpdateRangeGetRangeSegmentTree.Operator(){
    @Override
    public int multiplyLazyValue(int lazy, int count) {
      return lazy;
    }

    @Override
    public int applyOffset(int lazy, int offset) {
      return lazy;
    }

    @Override
    public int mergeLazyValue(int oldLazy, int newLazy) {
      if (oldLazy == -1) {
        return newLazy;
      }
      return Math.min(oldLazy, newLazy);
    }

    @Override
    public int apply(int value, int lazy) {
      return Math.min(value, lazy);
    }

    @Override
    public int mergeValue(int smallIndexValue, int largeIndexValue) {
      return Math.min(smallIndexValue, largeIndexValue);
    }

    @Override
    public int getUnitValue() {
      return Integer.MAX_VALUE;
    }

  };

  private static long solve(int n, int q, int[][] txs) {
    int[] initialValues = new int[n];
    Arrays.fill(initialValues, n);
    UpdateRangeGetRangeSegmentTree segmentTree1 = new UpdateRangeGetRangeSegmentTree(OPERATOR, initialValues);
    UpdateRangeGetRangeSegmentTree segmentTree2 = new UpdateRangeGetRangeSegmentTree(OPERATOR, initialValues);
    long answer = (long)(n - 2) * (long)( n - 2);
    for (int[] tx : txs) {
      int type = tx[0];
      int x = tx[1];
      /*
      for (int i = 0; i < n; i++) {
        System.err.printf("i: %d, 1: %d, 2: %d\n", i, segmentTree1.get(i), segmentTree2.get(i));
      }
      */
      if (type == 1) {
        int v = segmentTree1.get(x);
//        System.err.printf("x: %d, v: %d\n", x, v);
        segmentTree2.update(0, v, x);
        answer -= v - 2;
      } else {
        int v = segmentTree2.get(x);
//        System.err.printf("x: %d, v: %d\n", x, v);
        segmentTree1.update(0, v, x);
        answer -= v - 2;
      }
//      System.err.println(answer);
    }
    return answer;
  }

  private static void execute(ContestReader reader, ContestWriter out) {
    int n = reader.nextInt();
    int q = reader.nextInt();
    int[][] txs = reader.nextInt(q, 2);
    out.println(solve(n, q, txs));
  }

