	@SuppressWarnings("static-method")
	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * AtCoder Beginner Contest 179 F問題
		 * 考察メモ
		 * 区間更新一点minがあればいい
		 */
		int N = io.nextInt(), Q = io.nextInt();
		Integer[] first = new Integer[N - 2];
		Arrays.fill(first, N - 2);
		LazySegTree<Integer, Integer> left = new LazySegTree<Integer, Integer>(first, (l, r) -> l + r, 0, Math::min, Math::min, N), 
				top = new LazySegTree<Integer, Integer>(first, (l, r) -> l + r, 0, Math::min, Math::min, N);
		long sum = (long)(N - 2) * (N - 2);
		while(Q --> 0) {
			int p = io.nextInt(), x = io.nextInt() - 2;
			if (p == 1) {
				int get = top.prod(x, x + 1);
				left.apply(0, get, x);
				sum -= get;
			} else {
				int get = left.prod(x, x + 1);
				top.apply(0, get, x);
				sum -= get;
			}
		}
		io.println(sum);
	}

