        var hBIT = new RangeBinaryIndexedTree(n);
        var hSet = new TreeSet<Integer>();
        var wBIT = new RangeBinaryIndexedTree(n);
        var wSet = new TreeSet<Integer>();
        hBIT.addRange(n - 2, 2);
        wBIT.addRange(n - 2, 2);
        hSet.add(n);
        wSet.add(n);
        for (int i = 0; i < q; i++) {
            int _1or2 = in.nextInt();
            int x = in.nextInt();
            if (_1or2 == 1) {
                ans -= wBIT.get(x);
                int first = wSet.first();
                if (x < first) {
                    wSet.add(x);
                    hBIT.addRange(-(first - 2 - (x - 2)), 2, hSet.first());
                }
            } else {
                ans -= hBIT.get(x);
                int first = hSet.first();
                if (x < first) {
                    hSet.add(x);
                    wBIT.addRange(-(first - 2 - (x - 2)), 2, wSet.first());
                }
            }
        }
        out.println(ans);
    }
    static final class RangeBinaryIndexedTree {
        final int length;
        final BinaryIndexedTree tree;
        RangeBinaryIndexedTree(int length) {
            this.length = length;
            tree = new BinaryIndexedTree(length + 1);
        }
        void addRange(long value, int fromIndex) {
            addRange(value, fromIndex, length);
        }
        void addRange(long value, int fromIndex, int toIndex) {
            Objects.checkFromToIndex(fromIndex, toIndex, length);
            if (value == 0 || fromIndex == toIndex)
                return;
            tree.add(fromIndex, value);
            tree.add(toIndex, -value);
        }
        long get(int index) {
            return tree.prefixSum(index + 1);
        }
    }
    static final class BinaryIndexedTree {
        final int length;
        final long[] a;

        BinaryIndexedTree(int length) {
            if (length < 1) {
                throw new IllegalArgumentException();
            }
            this.length = length;
            this.a = new long[length + 1];
        }
        void add(int index, long value) {
            if (index < 0 || index >= length) {
                throw new IndexOutOfBoundsException();
            }
            for (int j = index + 1; j <= length; j += Integer.lowestOneBit(j)) {
                a[j] += value;
            }
        }
        long prefixSum(int toIndex) {
            if (toIndex < 0 || toIndex > length) {
                throw new IndexOutOfBoundsException();
            }
            long result = 0;
            for (int i = toIndex; i >= 1; i -= Integer.lowestOneBit(i)) {
                result += a[i];
            }
            return result;
        }
        long get(int index) {
            return prefixSum(index + 1) - prefixSum(index);
        }
        void set(int index, long value) {
            add(index, value - get(index));
        }
    }
