import java.util.Objects;
import java.util.Scanner;
import java.util.TreeSet;

public class Main {

    private static class Wall implements Comparable<Wall> {
        private final int idx;
        private final int len;

        private Wall(int idx, int len) {
            this.idx = idx;
            this.len = len;
        }

        @Override
        public boolean equals(Object o) {
            if (o instanceof Wall) {
                Wall w = (Wall) o;
                return idx == w.idx && len == w.len;
            }
            return false;
        }

        @Override
        public int hashCode() {
            return Objects.hash(idx, len);
        }

        @Override
        public int compareTo(Wall w) {
            return idx != w.idx
                    ? Integer.compare(idx, w.idx)
                    : Integer.compare(len, w.len);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        final int N = sc.nextInt();
        final int Q = sc.nextInt();

        // 盤上に残っている黒い石の数。
        long blacks = ((long) N - 2) * (N - 2);

        TreeSet<Wall> verticalWalls = new TreeSet<>();
        verticalWalls.add(new Wall(N - 2, N - 2));

        TreeSet<Wall> horizontalWalls = new TreeSet<>();
        horizontalWalls.add(new Wall(N - 2, N - 2));

        for (int i = 0; i < Q; i++) {
            boolean isVertical = sc.nextInt() == 1;
            int idx = sc.nextInt() - 2;

            if (isVertical) {
                Wall wall = horizontalWalls.stream().filter(w -> idx < w.len).findFirst().get();
                blacks -= wall.idx;
                verticalWalls.add(new Wall(idx, wall.idx));

            } else {
                Wall wall = verticalWalls.stream().filter(w -> idx < w.len).findFirst().get();
                blacks -= wall.idx;
                horizontalWalls.add(new Wall(idx, wall.idx));
            }
        }

        System.out.println(blacks);
    }
}

import java.util.*;

public class Main {

	private static class Node {
		int rs;
		int cs;
		int re;
		int ce;
		Node right=null;
		Node left=null;

		public Node(int rs, int cs, int re,int ce) {
			this.rs=rs;
			this.cs=cs;
			this.re=re;
			this.ce=ce;
		}
	}

	static long find(Node t,int x,int y) {
        if(t.left==null&&t.right==null) {
        	if(x==1) {
        		t.left=new Node(t.rs,t.cs,t.re,y);
        		t.right=new Node(t.rs,y+1,t.re,t.ce);
        		return t.re-t.rs-1;
        	}
        	else if(y==1) {
        		t.left=new Node(x+1,t.cs,t.re,t.ce);
        		t.right=new Node(t.rs,t.cs,x,t.ce);
        		return t.ce-t.cs-1;
        	}
        }
        if(t.left.rs<=x&&t.left.re>x&&t.left.cs<=y&&t.left.ce>y) {
        	return find(t.left,x,y);
        }
        else if(t.right.rs<=x&&t.right.re>x&&t.right.cs<=y&&t.right.ce>y) {
        	return find(t.right,x,y);
        }
        else {
        	return 0;
        }
    }

	public static void main(String[] args) {
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int q=sc.nextInt();
		Node tree=new Node(1,1,n,n);
		long ans=0;
		boolean row[]=new boolean[n];
		boolean col[]=new boolean[n];
		while(q-->0) {
			int x=sc.nextInt();
			int y=sc.nextInt();
			if(x==1&&!col[y]) {
				long xx=find(tree,x==1?x:y,x==1?y:1);
				ans+=xx;
				col[y]=true;
			}
			if(x==2&&!row[y]) {
				long xx=find(tree,x==1?x:y,x==1?y:1);
				ans+=xx;
				row[y]=true;
			}
		}
		System.out.println(((long)(n-2)*(n-2))-ans);
	}
}

