#region Segment Tree

public class SegmentTree {
	int sz;
	int n;
	int[] data;
	public SegmentTree(int size, int X) {
		sz = size;
		n = 1;
		while (n < size) n *= 2;
		data = new int[n * 2];
		for (int i = 0; i < data.Length; i++)
			data[i] = X;
	}
	public int Get(int k) {
		k += n;
		var max = data[k];
		for (k = k / 2; k > 0; k /= 2)
			max = Min(max, data[k]);
		return max;
	}
	public void Query(int a, int b, int X) {
		for (a += n, b += n; a < b; a /= 2, b /= 2) {
			if ((a & 1) == 1) {
				data[a] = Min(data[a], X);
				a++;
			}
			if ((b & 1) == 1) {
				b--;
				data[b] = Min(data[b], X);
			}
		}
	}
	public int[] Items() {
		var res = new int[sz];
		for (int i = 0; i < sz; i++) res[i] = this.Get(i);
		return res;
	}
}
