		public static void Main(string[] args) {
			var sw = new StreamWriter(Console.OpenStandardOutput()) {
				AutoFlush =
#if DEBUG
			true
#else
			false
#endif
			};
			Console.SetOut(sw);
			new Program().Solve(new ConsoleInput(
#if DEBUG
			new StreamReader("../../../inputData.txt")
#else
			Console.In
#endif
			, ' '));
			Console.Out.Flush();
		}

		public void Solve(ConsoleInput cin) {
			var datum = cin.ReadIntArray(2);
			int N = datum[0], Q = datum[1];
			var colwiseBlack = new LazySegment<long, long?>(N - 2, (i, j) => Min(i, j), int.MaxValue,
				(x, a) => a ?? x, (a, b) => b ?? a, null,
				(x, i) => x, x => x
			);
			var rowwiseBlack = new LazySegment<long, long?>(N - 2, (i, j) => Min(i, j), int.MaxValue,
				(x, a) => a ?? x, (a, b) => b ?? a, null,
				(x, i) => x, x => x
			);
			colwiseBlack.RangeUpdate(0, N - 2, N - 2);
			rowwiseBlack.RangeUpdate(0, N - 2, N - 2);
			long black = (N - 2) * (long)(N - 2);
			int colmin = N;
			int rowmin = N;
			for(int q = 0; q < Q; q++) {
				var kind = cin.ReadInt;
				var place = cin.ReadInt - 2;
				if(kind == 1) {
					var count = colwiseBlack.GetValue(place, place + 1);
					black -= count;
					if(place < colmin) { 
						rowwiseBlack.RangeUpdate(0, (int)count, place);
						colmin = place;
					}
				} else {
					var count = rowwiseBlack.GetValue(place, place + 1);
					black -= count; 
					if(place < rowmin) {
						colwiseBlack.RangeUpdate(0, (int)count, place);
						rowmin = place;
					}
				}
			}
			Console.WriteLine(black);
		}
	}

