		);
	var RAQRMQ = new LazySegment<long, long>(N, (i, j) => Min(i,j), int.MaxValue,
		(x, a) => a+x, (a, b) => b+a, 0,
		(x, i) => x, x=>x
		);
			*/
	class LazySegment<T, S>: SegmentTree<T> {
		public LazySegment(int _N, Func<T, T, T> _OPER, T _unit,
			Func<T, S, T> _ACT, Func<S, S, S> _OPER_ACT, S _unit_OPER,
			Func<S, int, S> _POWERS, Func<S, S> _SQRT
		) : base(_N, _OPER, _unit) {
			lazy = Enumerable.Repeat(_unit_OPER, Nodes.Length).ToArray();
			FA = _ACT;
			FL = _OPER_ACT;
			uo = _unit_OPER;
			Power = _POWERS;
			SQ = _SQRT;
		}
		Func<T, S, T> FA { get; }
		Func<S, S, S> FL { get; }
		Func<S, int, S> Power { get; }
		Func<S, S> SQ { get; }
		void AL(ref S sOld, S sNew) { sOld = FL(sOld, sNew); }
		void AA(ref T t, S s) { t = FA(t, s); }
		S uo { get; }
		private S[] lazy { get; }
		//k is 0-indexed
		private void eval(int k) {
			if(!lazy[k].Equals(uo)) {
				if(k + 1 < width) {
					AL(ref lazy[2 * k + 1], SQ(lazy[k]));
					AL(ref lazy[2 * k + 2], SQ(lazy[k]));
				}
				AA(ref Nodes[k], lazy[k]);
				lazy[k] = uo;
			}
		}
		private void RangeUpdate(int start, int end, S value,
		int nodeIdx, int focusStart, int focusEnd) {
			if(focusEnd < 0) focusEnd = width;
			eval(nodeIdx);
			if(end <= focusStart || focusEnd <= start) return;
			if(start <= focusStart && focusEnd <= end) {
				AL(ref lazy[nodeIdx], Power(value, focusEnd - focusStart));
				eval(nodeIdx);
			} else {
				var midFocus = (focusStart + focusEnd) / 2;
				RangeUpdate(start, end, value, 2 * nodeIdx + 1, focusStart, midFocus);
				RangeUpdate(start, end, value, 2 * nodeIdx + 2, midFocus, focusEnd);
				Nodes[nodeIdx] = OPER(Nodes[2 * nodeIdx + 1], Nodes[2 * nodeIdx + 2]);
			}
		}
		public void RangeUpdate(int start, int end, S value) => RangeUpdate(start, end, value, 0, 0, -1);
		public override T GetValue(int start, int end) {
			return GetValue(start, end, 0, 0, -1);
		}
		private T GetValue(int start, int end,
		int nodeIdx, int focusStart, int focusEnd) {
			if(focusEnd < 0) focusEnd = width;
			eval(nodeIdx);
			if(end <= focusStart || focusEnd <= start) return unit;
			if(start <= focusStart && focusEnd <= end)
				return Nodes[nodeIdx];
			var midFocus = (focusStart + focusEnd) / 2;
			var leftV = GetValue(start, end, 2 * nodeIdx + 1, focusStart, midFocus);
			var rightV = GetValue(start, end, 2 * nodeIdx + 2, midFocus, focusEnd);
			return OPER(leftV, rightV);
		}
	}

}

