namespace abc179
{
    class Program
    {
        static void Main()
        {
            var nq = ReadNumList();
            var n = nq[0];
            var q = nq[1];
            var queries = new int[q][];
            for (var i = 0; i < q; ++i)
            {
                queries[i] = ReadNumList();
            }
            WriteLine(SR(n, queries));
        }
        static long SR(int n, int[][] queries)
        {
            var black = (long)(n - 2) * (n - 2);
            var vertMemo = new SortedList<int, int>();
            var horiMemo = new SortedList<int, int>();
            vertMemo.Add(0, n - 2);
            horiMemo.Add(0, n - 2);
            var minVert = n;
            var minHori = n;
            foreach (var query in queries)
            {
                query[1] -= 2;
                if (query[0] == 1)
                {
                    var reverses = vertMemo[0];
                    if (query[1] > 0)
                    {
                        vertMemo.Add(query[1], 0);
                        var currentPos = vertMemo.IndexOfKey(query[1]);
                        reverses = vertMemo.Values[currentPos - 1];
                        vertMemo[query[1]] = reverses;
                    }
                    if (minVert > query[1])
                    {
                        horiMemo[0] = query[1];
                        minVert = query[1];
                    }
                    black -= reverses;
                }
                else
                {
                    var reverses = horiMemo[0];
                    if (query[1] > 0)
                    {
                        horiMemo.Add(query[1], 0);
                        var currentPos = horiMemo.IndexOfKey(query[1]);
                        reverses = horiMemo.Values[currentPos - 1];
                        horiMemo[query[1]] = reverses;
                    }
                    if (minHori > query[1])
                    {
                        vertMemo[0] = query[1];
                        minHori = query[1];
                    }
                    black -= reverses;
                }
            }
            return black;
        }
        static int[] ReadNumList()
        {
            var line = Console.ReadLine().Split(' ');
            if (line.Length == 1 && string.IsNullOrEmpty(line[0]))
            {
                return new int[0];
            }
            var numList = new int[line.Length];
            for (var i = 0; i < line.Length; ++i)
            {
                numList[i] = int.Parse(line[i]);
            }
            return numList;
        }
    }
