            for (var _ = 0; _ < Testcase; _++) Solve();
        }
        static void Solve()
        {
            Cin.Scanf(out int N, out int Q);
            var Rfree = new HashSet<int>();
            var Rnum = new long[N+1];Fill(Rnum, -1);
            var Cfree = new HashSet<int>();
            var Cnum = new long[N+1];Fill(Cnum, -1);
            int rpre = N;
            int cpre = N;
            long ans = (long)(N - 2) * (N - 2);
            while (Q-- > 0)
            {
                Cin.Scanf(out int k, out int x);

                if (k == 1)//r
                {
                    if (x > rpre) { ans -= Rnum[x];continue; }
                    ans -= cpre - 2;
                    for(var i = rpre - 1; i >= x + 1; i--)
                    {
                        Rfree.Add(i);
                        Rnum[i] = cpre - 2;
                    }
                    rpre = x;
                }
                else
                {
                    if (x > cpre) { ans -= Cnum[x];continue; }
                    ans -= rpre - 2;
                    for(var i = cpre - 1; i >= x + 1; i--)
                    {
                        Cfree.Add(i);
                        Cnum[i] = rpre - 2;
                    }
                    cpre = x;
                }
            }
            OutL(ans);
        }
    }
