	private long[] dat;
	private int m=1,cnt,l=0;
	private long mv;
	private Func<long,long,long> Fm;
	public St(int n,bool mm){
		if(mm){mv=long.MinValue;Fm=Fmax;}
		else{mv=long.MaxValue;Fm=Fmin;}
		while(m<n){m<<=1;l++;}
		cnt=m+n-1;
		dat=new long[cnt];
		for(int i=0;i<cnt;i++){dat[i]=mv;}
	}
	private long Fmax(long a,long b){return Max(a,b);}
	private long Fmin(long a,long b){return Min(a,b);}
	public void Ud2(int a,int b,long d){Hn(a,b,0,0,m-1,d);}
	private void Hn(int a,int b,int k,int l,int r,long de){
		if(a<=l&&r<=b){dat[k]=Min(de,dat[k]);}
		else if(r>=a&&b>=l){
			if(dat[k]!=mv){
				dat[(k<<1)+1]=Fm(dat[k],dat[(k<<1)+1]);
				dat[(k<<1)+2]=Fm(dat[k],dat[(k<<1)+2]);
				dat[k]=mv;
			}
			Hn(a,b,(k<<1)+1,l,(l+r)>>1,de);
			Hn(a,b,(k<<1)+2,(l+r+1)>>1,r,de);
		}
	}
	public long Get(int a){
		int k=0,q=a+(1<<l);
		for(int i=l-1;i>=0;i--){
			if(dat[k]!=mv){
				dat[(k<<1)+1]=Fm(dat[k],dat[(k<<1)+1]);
				dat[(k<<1)+2]=Fm(dat[k],dat[(k<<1)+2]);
				dat[k]=mv;
			}
			k=(k<<1)+1+((q>>i)&1);
		}
		return dat[k]!=mv?dat[k]:0;
	}
}
