public sealed class DualSegmentTree<TMonoid> {
    public int Count { get; private set; }
    private TMonoid[] _node;
    private readonly Func<TMonoid, TMonoid, TMonoid> _merge;

    public DualSegmentTree(Func<TMonoid, TMonoid, TMonoid> merge) {
        _merge = merge;
    }

    public void Build(IList<TMonoid> array) {
        Build(array.Count, i => array[i]);
    }

    public void Build(int n, Func<int, TMonoid> create) {
        Count = n;

        _node = new TMonoid[2 * Count];

        for (int i = 0; i < n; i++) {
            _node[i + Count] = create(i);
        }

        for (int i = Count - 1; i > 0; i--) {
            _node[i] = _merge(_node[i << 1], _node[i << 1 | 1]);
        }
    }

    public TMonoid Get(int index) {
        int p = index + Count;
        var val = _node[p];
        p >>= 1;
        while (p > 0) {
            val = _merge(val, _node[p]);
            p >>= 1;
        }
        return val;
    }

    public void RangeMerge(int begin, int end, TMonoid val) {
        int l = begin + Count;
        int r = end + Count - 1;
        for (; l <= r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) { _node[l] = _merge(val, _node[l]); l++; }
            if ((r & 1) == 0) { _node[r] = _merge(_node[r], val); r--; }
        }
    }

    public TMonoid this[int index] {
        get { return Get(index); }
    }
};
