    {
        int n = ReadInt();
        int q = ReadInt();
        var tate = Enumerable.Repeat(n - 2, n).ToArray();
        var yoko = Enumerable.Repeat(n - 2, n).ToArray();
        int tatemin = n;
        int yokomin = n;

        long black = (long)(n - 2) * (n - 2);
        for (int i = 0; i < q; i++)
        {
            if (Read() == "1")
            {
                int x = ReadInt();
                int temp = tate[x - 1];
                black -= temp;
                if (x < tatemin)
                {
                    for (int j = 1; j <= temp; j++)
                    {
                        yoko[j] = Math.Min(yoko[j], x - 2);
                    }
                    tatemin = x;
                }
            }
            else
            {
                int x = ReadInt();
                int temp = yoko[x - 1];
                black -= temp;
                if (x < yokomin)
                {
                    for (int j = 1; j <= temp; j++)
                    {
                        tate[j] = Math.Min(tate[j], x - 2);
                    }
                    yokomin = x;
                }
            }
        }
        Console.WriteLine(black);
    }
