namespace AtCoderBeginnerContest179.Questions
{
    public class QuestionE : AtCoderQuestionBase
    {
        public override void Solve(IOManager io)
        {
            var n = io.ReadLong();
            long x = io.ReadInt();
            var m = io.ReadInt();

            long sum = x;
            var i = 1;
            var mods = new List<long>();
            var appeared = new HashSet<long>();
            mods.Add(x);
            appeared.Add(x);

            if (n == 1)
            {
                io.WriteLine(x);
                return;
            }
            else if (x == 0)
            {
                io.WriteLine(0);
                return;
            }

            while (true)
            {
                var next = F(x, m);

                if (appeared.Add(next))
                {
                    mods.Add(next);
                    i++;
                    x = next;
                    sum += x;
                }
                else
                {
                    break;
                }

                if (i == n)
                {
                    io.WriteLine(sum);
                    return;
                }
            }

            var nx = F(x, m);
            var remain = n - i;
            var lastIndex = -1;

            for (int j = 0; j < mods.Count; j++)
            {
                if (mods[j] == nx)
                {
                    lastIndex = j;
                    break;
                }
            }

            var loop = mods.Count - lastIndex;
            var prefixSum = new long[loop + 1];

            for (int j = 0; j + 1 < prefixSum.Length; j++)
            {
                prefixSum[j + 1] = prefixSum[j] + mods[lastIndex + j];
            }

            sum += prefixSum[^1] * (remain / loop);
            sum += prefixSum[remain % loop];

            io.WriteLine(sum);
        }

        long F(long a, int m) => a * a % m;
    }
}

namespace AtCoderBeginnerContest179
{
    class Program
    {
        static void Main(string[] args)
        {
            IAtCoderQuestion question = new QuestionE();
            using var io = new IOManager(Console.OpenStandardInput(), Console.OpenStandardOutput());
            question.Solve(io);
        }
    }
}

#region Base Class

namespace AtCoderBeginnerContest179.Questions
{

    public interface IAtCoderQuestion
    {
        string Solve(string input);
        void Solve(IOManager io);
    }

    public abstract class AtCoderQuestionBase : IAtCoderQuestion
    {
        public string Solve(string input)
        {
            var inputStream = new MemoryStream(Encoding.UTF8.GetBytes(input));
            var outputStream = new MemoryStream();
            using var manager = new IOManager(inputStream, outputStream);

            Solve(manager);
            manager.Flush();

            outputStream.Seek(0, SeekOrigin.Begin);
            var reader = new StreamReader(outputStream);
            return reader.ReadToEnd();
        }

        public abstract void Solve(IOManager io);
    }

    public class IOManager : IDisposable
    {
        private readonly StreamReader _reader;
        private readonly StreamWriter _writer;
        private bool _disposedValue;

        const char ValidFirstChar = '!';
        const char ValidLastChar = '~';

        public IOManager(Stream input, Stream output)
        {
            _reader = new StreamReader(input);
            _writer = new StreamWriter(output) { AutoFlush = false };
        }

        public char ReadChar()
        {
            Skip();
            return (char)_reader.Read();
        }

        public string ReadString()
        {
            var builder = new StringBuilder();
            int c;
            Skip();

            while (IsValidChar(c = _reader.Read()))
            {
                builder.Append((char)c);
            }

            return builder.ToString();
        }

        public string ReadLine()
        {
            Skip();
            return _reader.ReadLine();
        }

        public int ReadInt() => (int)ReadLong();

        public long ReadLong()
        {
            long result = 0;
            bool isPositive = true;
            Skip();
            int c = _reader.Read();

            if (c == '-')
            {
                isPositive = false;
                c = _reader.Read();
            }

            do
            {
                result = result * 10 + (c - '0');
            } while (IsValidChar(c = _reader.Read()));

            return isPositive ? result : -result;
        }

        public double ReadDouble() => double.Parse(ReadString());
        public decimal ReadDecimal() => decimal.Parse(ReadString());

        // C#のバージョンが上がったらね……。
        // private Span<char> ReadCharSpan(Span<char> buffer)

        public int[] ReadIntArray(int n)
        {
            var a = new int[n];
            for (int i = 0; i < a.Length; i++)
            {
                a[i] = ReadInt();
            }
            return a;
        }

        public long[] ReadLongArray(int n)
        {
            var a = new long[n];
            for (int i = 0; i < a.Length; i++)
            {
                a[i] = ReadLong();
            }
            return a;
        }

        public double[] ReadDoubleArray(int n)
        {
            var a = new double[n];
            for (int i = 0; i < a.Length; i++)
            {
                a[i] = ReadDouble();
            }
            return a;
        }

        public decimal[] ReadDecimalArray(int n)
        {
            var a = new decimal[n];
            for (int i = 0; i < a.Length; i++)
            {
                a[i] = ReadDecimal();
            }
            return a;
        }

        public void WriteLine<T>(T value) => _writer.WriteLine(value.ToString());

        public void WriteLine<T>(T[] value, char delimiter = ' ')
        {
            for (int i = 0; i < value.Length - 1; i++)
            {
                _writer.Write(value[i].ToString());
                _writer.Write(delimiter);
            }
            _writer.WriteLine(value[value.Length - 1].ToString());
        }

        public void Flush() => _writer.Flush();

        private static bool IsValidChar(int c) => ValidFirstChar <= c && c <= ValidLastChar;

        private static void ThrowInvalidOperationException(string s) => throw new InvalidOperationException();

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private void Skip()
        {
            while (!IsValidChar(_reader.Peek()))
            {
                if (_reader.EndOfStream)
                {
                    ThrowInvalidOperationException("End of file.");
                }
                _reader.Read();
            }
        }

        protected virtual void Dispose(bool disposing)
        {
            if (!_disposedValue)
            {
                if (disposing)
                {
                    _reader.Dispose();
                    _writer.Flush();
                    _writer.Dispose();
                }

                _disposedValue = true;
            }
        }

        public void Dispose()
        {
            Dispose(disposing: true);
            GC.SuppressFinalize(this);
        }
    }
}

