type Lim struct {
	pos   int
	depth int
}

func binary_search(x int, t_lim_list []Lim) int {
	l, r := 0, len(t_lim_list)-1
	for r-l > 1 {
		c := (l + r) / 2
		if t_lim_list[c].depth < x {
			r = c
		} else {
			l = c
		}
	}

	if x <= t_lim_list[r].depth {
		return t_lim_list[r].pos - 1
	} else {
		return t_lim_list[l].pos - 1
	}

	// for i := range t_lim_list {
