	sc.Split(bufio.ScanWords)

	N, Q := nextInt(), nextInt()
	black := (N - 2) * (N - 2)
	r_lim_list := make([]Lim, 0)
	d_lim_list := make([]Lim, 0)

	r_lim_list = append(r_lim_list, Lim{N, N})
	d_lim_list = append(r_lim_list, Lim{N, N})
