			d = binary_search(x, d_lim_list)
			black -= d - 1
			if x < r_lim_list[len(r_lim_list)-1].pos {
				r_lim_list = append(r_lim_list, Lim{x, d})
			}
		} else {
			d = binary_search(x, r_lim_list)
			black -= d - 1
			if x < d_lim_list[len(d_lim_list)-1].pos {
				d_lim_list = append(d_lim_list, Lim{x, d})
			}
		}
	}
	fmt.Println(black)
