struct SegTree(T, E)
{
	alias T delegate(T, E) G;
	alias T delegate(E, E) H;
	int n;
	G g; H h;
	T d1; E d0;
	T[] dat; E[] laz;
	this(int _n, G _g, H _h, T _d1, E _d0, T[] v = [])
	{
		g = _g;	h = _h;
		d1 = _d1; d0 = _d0;
		init(_n);
		if (_n == cast(int)v.length) build(_n, v);
	}
	void init(int _n)
	{
		n = 1;
		while (n < _n) n *= 2;
		dat.length = n; dat[] = d1;
		laz.length = 2*n-1; laz[] = d0;
	}
	void build(int _n, T[] v)
	{
		foreach (i; 0.._n) dat[i] = v[i];
	}
	void update(int a, int b, E x, int k, int l, int r)
	{
		if (r <= a || b <= l) return;
		if (a <= l && r <= b)
		{
			laz[k] = h(laz[k], x);
			return;
		}
		update(a, b, x, k*2+1, l, (l+r)/2);
		update(a, b, x, k*2+2, (l+r)/2, r);
	}
	void update(int a, int b, E x)
	{
		update(a, b, x, 0, 0, n);
	}
	T query(int k)
	{
		T c = dat[k];
		k += n-1;
		E x = laz[k];
		while (k > 0)
		{
			k = (k-1)/2;
			x = h(x,laz[k]);
		}
		return g(c,x);
	}
}

