import sys

BLACK = 1
WHITE = 2
NONE = 0

def query1(x, stonesMatrix):
    position = x - 1
    copiedStonesMatrix = stonesMatrix.copy()
    for i in range(len(copiedStonesMatrix)):
        if(copiedStonesMatrix[i][position] == WHITE):
            break
        copiedStonesMatrix[i][position] = WHITE
    return copiedStonesMatrix

def query2(x, stonesMatrix):
    position = x - 1
    copiedStonesMatrix = stonesMatrix.copy()
    for i in range(len(copiedStonesMatrix)):
        if(copiedStonesMatrix[position][i] == WHITE):
            break
        copiedStonesMatrix[position][i] = WHITE
    return copiedStonesMatrix

def createStonesMatrix(size):
    stoneList = []
    for i in range(size):
        if(i == 0):
            stoneList.append(createFirstLineStones(size))
        elif(i == size - 1):
            stoneList.append(createLastLinesStones(size))
        else:
            stoneList.append(createMiddleLinesStones(size))
    return stoneList

def createFirstLineStones(size):
    stones = []
    for i in range(size):
        if(i == size - 1):
            stones.append(WHITE)
        else:
            stones.append(NONE)
    return stones

def createMiddleLinesStones(size):
    stones = []
    for i in range(size):
        if(i == size - 1):
            stones.append(WHITE)
        elif(i == 0):
            stones.append(NONE)
        else:
            stones.append(BLACK)
    return stones

def createLastLinesStones(size):
    stones = []
    for i in range(size):
        stones.append(WHITE)
    return stones

def countBlackStones(stonesMatrix):
    count = 0
    for stonesLine in stonesMatrix:
        for stone in stonesLine:
            if stone == BLACK:
                count += 1
    return count

