# search smallest i ( s <= i < e ) such that f(i) == True
def bisearch_smallest(f, s, e = None):
	if e == None:
		e = s - 1
		s = 0
	else:
		e -= 1

	while s < e:
		m = (s + e) // 2
		if f(m):
			e = m
