def createStonesMatrix(size):
    stoneList = []
    for i in range(size):
        if(i == 0):
            stoneList.append(createFirstLineStones(size))
        elif(i == size - 1):
            stoneList.append(createLastLinesStones(size))
        else:
            stoneList.append(createMiddleLinesStones(size))
    return stoneList

def createFirstLineStones(size):
    stones = []
    for i in range(size):
        if(i == size - 1):
            stones.append(WHITE)
        else:
            stones.append(NONE)
    return stones

def createMiddleLinesStones(size):
    stones = []
    for i in range(size):
        if(i == size - 1):
            stones.append(WHITE)
        elif(i == 0):
            stones.append(NONE)
        else:
            stones.append(BLACK)
    return stones

def createLastLinesStones(size):
    stones = []
    for i in range(size):
        stones.append(WHITE)
    return stones

