    macro_rules !println {($($arg :tt ) *) =>(::std ::writeln !(_out ,$($arg ) *) .expect ("io error" ) ) }
    macro_rules! echo {
        ($iter :expr ) => {
            echo!($iter, '\n')
        };
        ($iter :expr ,$sep :expr ) => {
            let mut iter = $iter.into_iter();
            if let Some(item) = iter.next() {
                print!("{}", item);
            }
            for item in iter {
                print!("{}{}", $sep, item);
            }
            println!();
        };
    }
    let n = scan!();
    let q = scan!();
    let qs = scan!([(marker::Usize1, marker::Usize1); q]);
    let n = n - 2;
    let mut rect = (n, n);
    let mut xmap = std::collections::BTreeSet::new();
    let mut ymap = std::collections::BTreeSet::new();
    let mut ans = n * n;
    for (t, x) in qs {
        let x = x - 1;
        if t == 0 {
            let y = x;
            if y < rect.1 {
                ans -= rect.0;
                if y + 1 < rect.1 {
                    xmap.insert((rect.1, y + 1, rect.0));
                }
                if 0 < y {
                    rect = (rect.0, y);
                } else {
                    rect = (0, 0);
                }
            } else {
                // end, start, depth
                if let Some(&(r1, s, r0)) = xmap.range((y + 1, 0, 0)..).next() {
                    if s <= y && y < r1 {
                        xmap.remove(&(r1, s, r0));
                        ans -= r0;
                        if y + 1 < r1 {
                            xmap.insert((r1, y + 1, r0));
                        }
                        if s < y {
                            xmap.insert((y, s, r0));
                        }
                    }
                }
            }
        } else {
            if x < rect.0 {
                ans -= rect.1;
                if x + 1 < rect.0 {
                    ymap.insert((rect.0, x + 1, rect.1));
                }
                if 0 < x {
                    rect = (x, rect.1);
                } else {
                    rect = (0, 0)
                }
            } else {
                if let Some(&(r0, s, r1)) = ymap.range((x + 1, 0, 0)..).next() {
                    if s <= x && x < r0 {
                        ymap.remove(&(r0, s, r1));
                        ans -= r1;
                        if x + 1 < r0 {
                            ymap.insert((r0, x + 1, r1));
                        }
                        if s < x {
                            ymap.insert((x, s, r1));
                        }
                    }
                }
            }
        }
    }
    println!("{}", ans);
}

