const CUSTOM_STACK_SIZE_MIB: Option<usize> = Some(1024);
const INTERACTIVE: bool = false;

fn main() -> std::io::Result<()> {
  match CUSTOM_STACK_SIZE_MIB {
    Some(stack_size_mib) => std::thread::Builder::new()
      .name("run_solver".to_owned())
      .stack_size(stack_size_mib * 1024 * 1024)
      .spawn(run_solver)?
      .join()
      .unwrap(),
    None => run_solver(),
  }
}

fn run_solver() -> std::io::Result<()> {
  let stdin = std::io::stdin();
  let reader = stdin.lock();
  let stdout = std::io::stdout();
  let writer = stdout.lock();
  macro_rules! with_wrapper {
    ($($wrapper:expr)?) => {{
      let mut writer = $($wrapper)?(writer);
      solve(reader, &mut writer)?;
      writer.flush()
    }};
  }
  if cfg!(debug_assertions) || INTERACTIVE {
    with_wrapper!()
  } else {
    with_wrapper!(std::io::BufWriter::new)
  }
}

fn solve<R, W>(reader: R, mut writer: W) -> std::io::Result<()>
where
  R: BufRead,
  W: Write,
{
  let mut _scanner = lib::io::Scanner::new(reader);
  #[allow(unused_macros)]
  macro_rules! scan {
    ($T:ty) => {
      _scanner.parse_next::<$T>()?.unwrap()
    };
    ($($T:ty),+) => {
      ($(scan!($T)),+)
    };
    ($T:ty; $n:expr) => {
      _scanner.parse_next_n::<$T>($n)?.unwrap()
    };
    ($($T:ty),+; $n:expr) => {
      iter::repeat_with(|| -> std::io::Result<_> { Ok(($(scan!($T)),+)) })
        .take($n)
        .collect::<std::io::Result<Vec<_>>>()?
    };
  }
  #[allow(unused_macros)]
  macro_rules! scan_bytes_map {
    ($f:expr) => {
      _scanner.map_next_bytes($f)?
    };
    ($f:expr; $n:expr) => {
      _scanner.map_next_bytes_n($n, $f)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! print {
    ($($arg:tt)*) => {
      write!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! println {
    ($($arg:tt)*) => {
      writeln!(writer, $($arg)*)?
    };
  }
  #[allow(unused_macros)]
  macro_rules! answer {
    ($($arg:tt)*) => {{
      println!($($arg)*);
      return Ok(());
    }};
  }
  {
    use dual_segment_tree::*;

    let (n, q) = scan!(usize, usize);

    let mut st1 = DualSegmentTree::new(n - 2, |&l, &r| l.min(r), usize::MAX);
    let mut st2 = DualSegmentTree::new(n - 2, |&l, &r| l.min(r), usize::MAX);
    for i in 0..n - 2 {
      st1.update(i, i + 1, &(n - 2));
      st2.update(i, i + 1, &(n - 2));
    }

    let mut ans = (n - 2) * (n - 2);
    for _ in 0..q {
      let (t, x) = scan!(u8, usize);
      let x = x - 2;
      match t {
        1 => {
          let c = st1.get(x);
          st2.update(0, c, &x);
          st1.update(x, x + 1, &0);
          ans -= c;
        }
        2 => {
          let c = st2.get(x);
          st1.update(0, c, &x);
          st2.update(x, x + 1, &0);
          ans -= c;
        }
        _ => unreachable!(),
      }
    }
    println!("{}", ans);
  }
  #[allow(unreachable_code)]
  Ok(())
}

use proconio::input;
use std::collections::BTreeMap;

fn lower_bound(map: &BTreeMap<usize, usize>, target: usize) -> usize {
    *map.range(target..).next().unwrap().clone().1
}

fn main() {
    input! {
        n: usize,
        q: usize,
        query: [(usize, usize); q],
    }

    let mut h_map = BTreeMap::new();
    let mut w_map = BTreeMap::new();

    h_map.insert(n-1, n);
    w_map.insert(n-1, n);

    let mut ans = 0;

    for &(c, x) in query.iter() {
        if c == 1 {
            let t = lower_bound(&h_map, x);
            if t <= 1 {
                continue;
            }
            ans += t-2;
            if let Some(&y) = w_map.get(&(t-1)) {
                *w_map.entry(t-1).or_default() = y.min(x);
            }
            else {
                *w_map.entry(t-1).or_default() = x;
            }
        }
        else {
            let t = lower_bound(&w_map, x);
            if t <= 1 {
                continue;
            }
            ans += t-2;
            if let Some(&y) = h_map.get(&(t-1)) {
                *h_map.entry(t-1).or_default() = y.min(x);
            }
            else {
                *h_map.entry(t-1).or_default() = x;
            }
        }
        // dbg!(c, x, ans);
        // dbg!(h_map.clone());
        // dbg!(w_map.clone());

    }

    println!("{}", (n-2)*(n-2) - ans);
}

