fn main() -> io::Result<()> {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024)
        .spawn(|| {
            let stdin = io::stdin();
            let stdout = io::stdout();
            run(KInput::new(stdin.lock()), io::BufWriter::new(stdout.lock()))
        })?
        .join()
        .unwrap()
}

fn run<I: Input, O: Write>(mut kin: I, mut out: O) -> io::Result<()> {
    macro_rules! output { ($($args:expr),+) => { write!(&mut out, $($args),+)?; }; }
    macro_rules! outputln {
        ($($args:expr),+) => { output!($($args),+); outputln!(); };
        () => { output!("\n"); if cfg!(debug_assertions) { out.flush()?; } }
    }

    let (n, q): (usize, usize) = kin.input();

    let mut ans = (n - 2).pow(2);
    let z = || n;
    let f = |x: &usize, y: &usize| *x.min(y);
    let mut r = FenwickTree::new(n + 1, z, f);
    let mut c = FenwickTree::new(n + 1, z, f);
    for (t, x) in kin.iter::<(u8, usize)>().take(q) {
        if t == 1 {
            let y = kdbg!(r.get(x));
            ans -= y - 2;
            c.apply(y - 1, x);
        } else {
            let y = kdbg!(c.get(x));
            ans -= y - 2;
            r.apply(y - 1, x);
        }
        kdbg!(ans);
    }
    outputln!("{}", ans);

    Ok(())
}

pub struct FenwickTree<T, F, Z> {
    a: Vec<T>,
    f: F,
    z: Z,
}
impl<T, F: Fn(&T, &T) -> T, Z: Fn() -> T> FenwickTree<T, F, Z> {
    pub fn new(n: usize, z: Z, f: F) -> Self {
        Self {
            a: std::iter::repeat_with(&z).take(n + 1).collect(),
            f,
            z,
        }
    }
    pub fn apply(&mut self, mut i: usize, x: T) {
        i += 1;
        while i > 0 {
            self.a[i] = (self.f)(&self.a[i], &x);
            i -= i & (!i + 1);
        }
    }
    pub fn get(&self, mut i: usize) -> T {
        let mut s = (self.z)();
        while i < self.a.len() {
            s = (self.f)(&self.a[i], &s);
            i += i & (!i + 1);
        }
        s
    }
}

