fn main() {
    input! {
        nq: (usize, usize),
        qs: [(usize, Usize1);nq.1],
    };
    let n = nq.0;
    let mut black_remain = (n - 2) * (n - 2);
    let mut v_right = vec![n-1;n-1];
    let mut v_down = vec![n-1;n-1];
    for (rd, x) in qs {
        if rd == 1 {
            let v = v_down[x];
            black_remain -= v - 1;
            for i in 1..v {
                v_right[i] = cmp::min(v_right[i], x);
            }
        } else {
            let v = v_right[x];
            black_remain -= v - 1;
            for i in 1..v {
                v_down[i] = cmp::min(v_down[i], x);
            }
        }
    }
    println!("{}", black_remain);
}

