                    ans -= r0;
                    if y + 1 < r1 {
                        xmap.insert((r1, y + 1, r0));
                    }
                    if y > s {
                        xmap.insert((y, s, r0));
                    }
                }
            }
            if y == 0 {
                rect = (0, 0);
            }
        } else {
            if x < rect.0 {
                ans -= rect.1;
                if x + 1 < rect.0 {
                    ymap.insert((rect.0, x + 1, rect.1));
                }
                if x > 0 {
                    rect = (x, rect.1);
                } else {
                    rect = (0, 0)
                }
            } else {
                if let Some(&(r0, s, r1)) = ymap.range((x, 0, 0)..).next() {
                    ymap.remove(&(r0, s, r1));
                    ans -= r1;
                    if x + 1 < r0 {
                        ymap.insert((r0, x + 1, r1));
                    }
                    if x > s {
                        ymap.insert((x, s, r1));
                    }
                }
            }
            if x == 0 {
                rect = (0, 0);
            }
        }
    }
    println!("{}", ans);
}

