pub struct SegTree<T: Monoid + Clone> {
    dat: Vec<T>,
    n: usize,
}

impl<T: Monoid + Copy> SegTree<T> {
    pub fn new(n: usize) -> Self {
        let dat = vec![T::unit(); n << 1];
        SegTree { dat: dat, n: n }
    }
    pub fn update(&mut self, k: usize, v: T) {
        let mut k = k + self.n;
        self.dat[k] = v;
        while {
            k >>= 1;
            k > 0
        } {
            self.dat[k] = T::add(&self.dat[k << 1], &self.dat[k << 1 | 1]);
        }
    }
    pub fn get(&self, a: usize, b: usize) -> T {
        let mut a = a + self.n;
        let mut b = b + self.n;
        let mut va = T::unit();
        let mut vb = T::unit();
        while a < b {
            if a & 1 != 0 {
                va = T::add(&va, &self.dat[a]);
                a += 1;
            }
            if b & 1 != 0 {
                vb = T::add(&self.dat[b - 1], &vb);
            }
            a >>= 1;
            b >>= 1;
        }
        T::add(&va, &vb)
    }
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, q: usize);
    let mut xseg = SegTree::<Min<usize>>::new(q + 1);
    let mut yseg = SegTree::<Min<usize>>::new(q + 1);
    let mut xs = BTreeMap::new();
    let mut ys = BTreeMap::new();
    xseg.update(0, Min(n - 1));
    yseg.update(0, Min(n - 1));
    let mut ret = (n - 2) * (n - 2);
    for i in 0..q {
        let i = i + 1;
        parse!(it, t: usize, x: u1);
        let (xs, xseg, yseg) = if t == 1 {
            (&mut xs, &mut xseg, &mut yseg)
        } else {
            (&mut ys, &mut yseg, &mut xseg)
        };

        let py = if let Some((_, &pxi)) = xs.range(..x).rev().next() {
            yseg.get(0, pxi)
        } else {
            yseg.get(0, i)
        };

        ret -= py.0 - 1;
        xs.insert(x, i);
        xseg.update(i, Min(x));
    }
    println!("{}", ret);
}

