use std::fmt::Debug;
use std::str::FromStr;

pub struct TokenReader {
    reader: std::io::Stdin,
    tokens: Vec<String>,
    index: usize,
}

impl TokenReader {
    pub fn new() -> Self {
        Self {
            reader: std::io::stdin(),
            tokens: Vec::new(),
            index: 0,
        }
    }

    pub fn next<T>(&mut self) -> T
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index += 1;
        self.tokens[self.index - 1].parse().unwrap()
    }

    pub fn vector<T>(&mut self) -> Vec<T>
    where
        T: FromStr,
        T::Err: Debug,
    {
        if self.index >= self.tokens.len() {
            self.load_next_line();
        }
        self.index = self.tokens.len();
        self.tokens.iter().map(|tok| tok.parse().unwrap()).collect()
    }

    pub fn load_next_line(&mut self) {
        let mut line = String::new();
        self.reader.read_line(&mut line).unwrap();

        self.tokens = line
            .split_whitespace()
            .map(String::from)
            .collect();
        self.index = 0;
    }
}

struct Fenwick {
    nodes: Vec<usize>,
}

impl Fenwick {
    fn new(len: usize) -> Self {
        Self {
            nodes: vec![1 << 30; len + 1],
        }
    }

    fn set(&mut self, value: usize, mut pos: usize) {
        while pos < self.nodes.len() {
            self.nodes[pos] = std::cmp::min(self.nodes[pos], value);
            pos += Fenwick::lsb(pos);
        }
    }

    fn get(&self, mut pos: usize) -> usize {
        let mut res = 1 << 30;
        while pos > 0 {
            res = std::cmp::min(res, self.nodes[pos]);
            pos -= Fenwick::lsb(pos);
        }
        res
    }

    fn lsb(num: usize) -> usize {
        num & (!(num - 1))
    }
}

struct Helper {
    tree: Fenwick,
    len: usize,
}

impl Helper {
    fn new(len: usize) -> Self {
        Self {
            tree: Fenwick::new(len),
            len,
        }
    }

    fn update_lower(&mut self, value: usize, pos: usize) {
        self.tree.set(value, self.len + 1 - pos);
    }

    fn get_lowest(&self, pos: usize) -> usize {
        self.tree.get(self.len + 1 - pos)
    }
}

fn main() {
    let mut reader = TokenReader::new();
    let n = reader.next();
    let q = reader.next();

    let mut rows = Helper::new(n);
    let mut cols = Helper::new(n);
    let mut total: i64 = (n as i64 - 2) * (n as i64 - 2);

    rows.update_lower(n, n);
    cols.update_lower(n, n);

    for _ in 0..q {
        let kind: i32 = reader.next();
        let pos = reader.next();

        if pos == 1 || pos == n {
            continue;
        }

        if kind == 1 {
            let limit = rows.get_lowest(pos);
            total -= limit as i64 - 2;
            cols.update_lower(pos, limit - 1);
        } else {
            let limit = cols.get_lowest(pos);
            total -= limit as i64 - 2;
            rows.update_lower(pos, limit - 1);
        }
    }
    println!("{}", total);
}

