fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (let _ = write!(out,$($format)*););
    }
    input! {
        n: usize, q: usize,
        qs: [(i32, usize1); q],
    }
    let mut row = vec![1 << 20; n];
    let mut col = vec![1 << 20; n];
    let mut rt = n - 1;
    let mut ct = n - 1;
    let mut tot: i64 = 0;
    for (ty, x) in qs {
        if ty == 1 {
            if x < ct {
                for i in x..ct {
                    col[i] = rt;
                }
                ct = x;
            }
            tot += col[x] as i64 - 1;
            col[x] = 1;
        } else {
            if x < rt {
                for i in x..rt {
                    row[i] = ct;
                }
                rt = x;
            }
            tot += row[x] as i64 - 1;
            row[x] = 1;
        }
    }
    puts!("{}\n", (n - 2) as i64 * (n - 2) as i64 - tot);
}

