fn main() {
    input! { n : u64 , q : usize , query : [(i32 , u64) ; q] }
    let mut res = (n - 2) * (n - 2);
    use std::collections::BTreeMap;
    let mut row = BTreeMap::new();
    let mut col = BTreeMap::new();
    row.insert(n - 1, n - 2);
    col.insert(n - 1, n - 2);
    for (t, x) in query {
        if t == 1 {
            let y = col.range(x - 1..).next().unwrap();
            res -= y.1;
            let r = row.entry(*(y.1)).or_insert(n - 1);
            *r = std::cmp::min(*r, x - 2);
        } else {
            let y = row.range(x - 1..).next().unwrap();
            res -= y.1;
            let r = col.entry(*(y.1)).or_insert(n - 1);
            *r = std::cmp::min(*r, x - 2);
        }
    }
