extern crate proconio;
use proconio::input;
fn main() {
    input!{
        n: usize,
        q: usize,
        query: [(u64, usize); q],
    }

    let arr = vec![n-2; 200000];
    let mut tree_x = DualSegmentTree::new(n-2, &arr, n-2, std::cmp::min, n-2, std::cmp::min);
    let mut tree_y = DualSegmentTree::new(n-2, &arr, n-2, std::cmp::min, n-2, std::cmp::min);

    let mut ans = ((n-2)*(n-2)) as u64;
    for i in 0..q {
        match query[i] {
            (1, t) => {
                let mx = tree_y.get(t-2) as u64; 
                ans -= mx;
                tree_x.range_query(0, mx as usize, t-2);
            },
            (2, t) => {
                let mx = tree_x.get(t-2) as u64;
                ans -= mx;
                tree_y.range_query(0, mx as usize, t-2);
            },
            (_, _) => panic!(),
        }
    }

    println!("{}", ans);
}

struct DualSegmentTree<R, S, T, U>{
    elements: Vec<R>,
    size: usize,
    unite: T,
    operator: Vec<S>,
    unit: S,
    composite: U,
}

impl<R, S, T, U> DualSegmentTree<R, S, T, U> 
    where 
        R: Copy,
        S: Copy,
        U: Fn(S, S) -> S,
        T: Fn(R, S) -> R,
{
    pub fn new(unit_e: R, arr: &Vec<R>, n: usize, unite: T, unit_op: S, composite: U ) -> DualSegmentTree<R, S, T, U>{
        let mut size: usize = 1;
        while size < n  {
            size <<= 1;
        }
        let mut elements = vec![unit_e; size];
        for i in 0..n {
            elements[i] = arr[i];
        }
        let unit = unit_op;
        let operator = vec![unit; 2*size];
        DualSegmentTree{
            elements,
            size,
            unite,
            operator,
            unit: unit_op,
            composite,
        }
    }

    // [l, r)での関数をセットする.
    pub fn range_query(&mut self, l: usize, r: usize, op: S) {
        if l != r {
            self.sub_range(0, self.size, l, r, op);
        }
    }

    fn sub_range(&mut self, min: usize, max: usize, l: usize, r: usize, op: S){
        let mid = (min + max)/2;
        if l == min && r == max {
            self.operator[self.size/(r-l) + l/(r-l)] = (self.composite)(op, self.operator[self.size/(r-l) + l/(r-l)]);
        }else{
            if l < mid && mid < r{
                self.sub_range(min, mid, l, mid, op) ; self.sub_range(mid, max, mid, r, op) ;
            }else if mid <= l {
                self.sub_range(mid, max, l, r, op)
            }else if r <= mid {
                self.sub_range(min, mid, l, r, op)
            }else{
                panic!("invalid input: min: {}, max: {}, l: {}, r: {}", min, max, l, r );
            }
        }
    }

    pub fn get(&self, index: usize) -> R{
        (self.unite)(self.elements[index], self.sub_get(index + self.size))
    }

    fn sub_get(&self, index: usize) -> S {
        if index == 0 {
            self.unit
        }else{
            (self.composite)(self.operator[index], self.sub_get(index >> 1))
        }
    }

    // pub fn debug(&self) {
    //     println!("{:?}", self.operator);
    // }
}

