struct SegmentTree {
    n: usize,
    xs: Vec<i64>,
}

impl SegmentTree {
    pub fn new(n: usize) -> SegmentTree {
        let n = n.next_power_of_two();
        let xs = vec![0; 2 * n];
        SegmentTree { n, xs }
    }
    pub fn add(&mut self, l: usize, r: usize, x: i64) {
        let mut l = l + self.n;
        let mut r = r + self.n;
        while l < r {
            if l & 1 != 0 {
                self.xs[l] += x;
                l += 1;
            }
            if r & 1 != 0 {
                r -= 1;
                self.xs[r] += x;
            }
            l >>= 1;
            r >>= 1;
        }
    }
    pub fn get(&self, i: usize) -> i64 {
        let mut i = self.n + i;
        let mut res = 0;
        while i != 0 {
            res += self.xs[i];
            i /= 2;
        }
        res
    }
}

