#[fastout]
fn main() {
    input!(n: usize, q: usize, query: [(usize, usize); q]);

    let mut min_xv = vec![n - 2; n - 2];
    let mut min_yv = vec![n - 2; n - 2];
    let mut min_x = n - 2;
    let mut min_y = n - 2;
    let mut ans = (n - 2).pow(2);

    for que in query {
        if que.0 == 1 {
            ans -= min_xv[que.1 - 2];
            if min_x > que.1 - 2 {
                min_x = que.1 - 2;
                for i in 0..min_y {
                    min_yv[i] = que.1 - 2;
                }
            }
        } else {
            ans -= min_yv[que.1 - 2];
            if min_y > que.1 - 2 {
                min_y = que.1 - 2;
                for i in 0..min_x {
                    min_xv[i] = que.1 - 2;
                }
            }
        }
    }

