        #[inline]
        pub fn partition_point_inner(
            &self,
            start: usize,
            mut pred: impl FnMut(&T::Inner) -> bool,
        ) -> usize {
            self.partition_point(start, |x| pred(x.get()))
        }

        #[inline]
        pub fn lower_bound_inner_by(
            &self,
            start: usize,
            mut cmp: impl FnMut(&T::Inner) -> cmp::Ordering,
