            self.partition_point_inner(start, |x| cmp(x) == cmp::Ordering::Less)
        }

        #[inline]
        pub fn upper_bound_inner_by(
            &self,
            start: usize,
            mut cmp: impl FnMut(&T::Inner) -> cmp::Ordering,
        ) -> usize {
