            self.reverse_partition_point(start, |x| pred(x.get()))
        }

        #[inline]
        pub fn reverse_lower_bound_inner_by(
            &self,
            end: usize,
            mut cmp: impl FnMut(&T::Inner) -> cmp::Ordering,
        ) -> usize {
            self.reverse_partition_point_inner(end, |x| cmp(x) == cmp::Ordering::Less)
