                res -= bb - 2;
                for j in x + 1..rb {
                    confirmed_c.insert(j, bb - 2);
                }
                rb = x;
            } else {
                res -= confirmed_c.get(&x).expect("somethong wrong");
            }
        } else
        // 横flip
        {
            if x < bb {
                res -= rb - 2;
                for j in x + 1..bb {
                    confirmed_r.insert(j, rb - 2);
                }
                bb = x;
            } else {
