            g
        } else {
            std::cmp::min(f, g)
        }
    };
    let apply = |f, a| {
        if f == id {
            a
        } else {
            std::cmp::min(f, a)
        }
    };
    let mut seg1 = LazySegmentTree::new(&a, e, mult, id, com, apply);
    let mut seg2 = LazySegmentTree::new(&a, e, mult, id, com, apply);
    let q: usize = rd.get();
