		|a, b| std::cmp::min(a, b),
	);
	left.operate(0, n as usize, n - 1);
	let mut top = LazySegmentTree::new(
		n as usize,
		std::i64::MAX,
		|a, b| std::cmp::min(a, b),
		|a, b| std::cmp::min(a, b),
