pub struct SegTree<T: Monoid + Clone> {
    dat: Vec<T>,
    n: usize,
}

impl<T: Monoid + Copy> SegTree<T> {
    pub fn new(n: usize) -> Self {
        let dat = vec![T::unit(); n << 1];
        SegTree { dat: dat, n: n }
    }
    pub fn update(&mut self, k: usize, v: T) {
        let mut k = k + self.n;
        self.dat[k] = v;
        while {
            k >>= 1;
            k > 0
        } {
            self.dat[k] = T::add(&self.dat[k << 1], &self.dat[k << 1 | 1]);
        }
    }
    pub fn get(&self, a: usize, b: usize) -> T {
        let mut a = a + self.n;
        let mut b = b + self.n;
        let mut va = T::unit();
        let mut vb = T::unit();
        while a < b {
            if a & 1 != 0 {
                va = T::add(&va, &self.dat[a]);
                a += 1;
            }
            if b & 1 != 0 {
                vb = T::add(&self.dat[b - 1], &vb);
            }
            a >>= 1;
            b >>= 1;
        }
        T::add(&va, &vb)
    }
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, q: usize);
    let mut ret = (n - 2) * (n - 2);
    let mut d = n - 1;
    let mut r = n - 1;
    let mut xs = vec![n - 1; n];
    let mut ys = vec![n - 1; n];
    for _ in 0..q {
        parse!(it, t: usize, x: u1);
        let (xs, ys, r, d) = if t == 1 {
            (&mut xs, &mut ys, &mut r, &mut d)
        } else {
            (&mut ys, &mut xs, &mut d, &mut r)
        };
        if x < *r {
            for i in x..*r {
                xs[i] = *d;
            }
            *r = x;
            ret -= *d - 1;
        } else {
            ret -= xs[x] - 1;
        }
    }
    println!("{}", ret);
}

