                if let Some(&(r0, s, r1)) = ymap.range((x + 1, 0, 0)..).next() {
                    ymap.remove(&(r0, s, r1));
                    ans -= r1;
                    if x + 1 < r0 {
                        ymap.insert((r0, x + 1, r1));
                    }
                    if x > s {
                        ymap.insert((x, s, r1));
                    }
                }
            }
            if x == 0 {
                rect = (0, 0);
            }
        }
    }
    println!("{}", ans);
}

