struct IEffection {}
impl Effection<usize, usize> for IEffection {
    fn operate(element: usize, effector: usize) -> usize {
        std::cmp::min(element, effector)
    }
}
struct IMultiOperator;
impl MultiOperator<usize> for IMultiOperator {
    fn multi_operate(element: usize, num: usize) -> usize {
        element
    }
}

fn main() {
    input! {
        n: usize,
        q: usize,
        queries: [(Chars, usize); q],
    }

    let mut tree_h =
        LazySegmentTree::<usize, IMonoidT, usize, IMonoidE, IEffection, IMultiOperator>::new(n);
    let mut tree_w =
        LazySegmentTree::<usize, IMonoidT, usize, IMonoidE, IEffection, IMultiOperator>::new(n);

    tree_h.update(0, n, n - 2);
    tree_w.update(0, n, n - 2);

    let mut total = (n - 2) * (n - 2);
    for (q, x) in queries {
        if q[0] == '1' {
            let val = tree_h.get(x - 2, x - 1);
            total -= val;
            tree_w.update(0, val, x - 2);
        } else {
            let val = tree_w.get(x - 2, x - 1);
            total -= val;
            tree_h.update(0, val, x - 2);
        }
    }
    println!("{}", total);
}

