pub trait OpMonoid {
    type T: Clone + PartialEq;
    fn id() -> Self::T;
    fn op(a: &Self::T, b: &Self::T) -> Self::T;
    fn op2(a: &Self::T, b: &Self::T) -> Self::T;
    fn op3(a: &Self::T, b: &i64) -> Self::T;
}
pub struct LazySegTree<M: OpMonoid> {
    n: usize,
    data: Vec<M::T>,
    lazy: Vec<M::T>,
}
impl<M: OpMonoid> LazySegTree<M> {
    pub fn new(n_: usize) -> LazySegTree<M> {
        let mut n = 1 as usize;
        while (n < n_) {
            n *= 2;
        }
        LazySegTree {
            n: n,
            data: vec![M::id().clone(); (2 * n)],
            lazy: vec![M::id().clone(); (2 * n)],
        }
    }
    #[macro_use]
    pub fn update(&mut self, index: usize, v: M::T) {
        let mut k = index + self.n - 1;
        self.data[k] = v;
        while (k > 0) {
            k = (k - 1) / 2;
            self.data[k] = M::op(&self.data[2 * k + 1], &self.data[2 * k + 2]);
        }
    }
    pub fn eval(&mut self, k: usize, l: i32, r: i32) {
        if self.lazy[k] != M::id().clone() {
            if (r - l) > 1 {
                self.lazy[2 * k + 1] = M::op2(&self.lazy[2 * k + 1], &self.lazy[k]);
                self.lazy[2 * k + 2] = M::op2(&self.lazy[2 * k + 2], &self.lazy[k]);
            }
            self.data[k] = M::op2(&self.data[k], &M::op3(&self.lazy[k], &((r - l) as i64)));
            self.lazy[k] = M::id().clone();
        }
    }
    pub fn update_range_sub(&mut self, a: usize, b: usize, v: M::T, k: usize, l: i32, r: i32) {
        let mut r = r;
        if r < 0 {
            r = self.n as i32;
        }
        self.eval(k, l, r);
        if b as i32 <= l || r <= a as i32 {
            return;
        }
        if a as i32 <= l && r <= b as i32 {
            self.lazy[k] = v.clone();
            self.eval(k, l, r);
        } else {
            self.update_range_sub(a, b, v.clone(), 2 * k + 1, l, (l + r) / 2);
            self.update_range_sub(a, b, v.clone(), 2 * k + 2, (l + r) / 2, r);
            self.data[k] = M::op(&self.data[2 * k + 1], &self.data[2 * k + 2]);
        }
    }
    pub fn update_range(&mut self, l: usize, r: usize, v: M::T) {
        self.update_range_sub(l, r, v, 0, 0, -1);
    }
    pub fn query_sub(&mut self, a: usize, b: usize, k: usize, l: i32, r: i32) -> M::T {
        let mut r = r;
        if r < 0 {
            r = self.n as i32
        };
        if b as i32 <= l || r <= a as i32 {
            return M::id();
        }
        self.eval(k, l, r);
        if a as i32 <= l && r <= b as i32 {
            return self.data[k].clone();
        }
        let vl = self.query_sub(a, b, 2 * k + 1, l, (l + r) / 2);
        let vr = self.query_sub(a, b, 2 * k + 2, (l + r) / 2, r);
        return M::op(&vl, &vr);
    }
    pub fn query(&mut self, l: usize, r: usize) -> M::T {
        self.query_sub(l, r, 0, 0, -1)
    }
}
struct MIN;
impl OpMonoid for MIN {
    type T = u64;
    fn id() -> Self::T {
        u64::max_value()
    }
    fn op(a: &Self::T, b: &Self::T) -> Self::T {
