struct DualSegmentTree<T, U>{
    elements: Vec<u64>,
    size: usize,
    unite: T,
    operator: Vec<u64>,
    unit: u64,
    composite: U,
}

impl<T, U> DualSegmentTree<T, U> 
    where 
        U: Fn(u64, u64) -> u64,
        T: Fn(u64, u64) -> u64,
{
    pub fn new(arr: &[u64], n: usize, unite: T, unit: u64, composite: U ) -> DualSegmentTree<T, U>{
        let mut size: usize = 1;
        while size < n  {
            size <<= 1;
        }
        let mut elements = vec![0; size];
        for i in 0..n {
            elements[i] = arr[i];
        }
        let unit = unit;
        let operator = vec![unit; 2*size];
        DualSegmentTree{
            elements,
            size,
            unite,
            operator,
            unit,
            composite,
        }
    }

    // [l, r)での関数をセットする.
    pub fn range_query(&mut self, l: usize, r: usize, op: u64) {
        if l != r {
            self.sub_range(0, self.size, l, r, op);
        }
    }

    fn sub_range(&mut self, min: usize, max: usize, l: usize, r: usize, op: u64) -> u64{
        let mid = (min + max)/2;
        if l == min && r == max {
            self.operator[self.size/(r-l) + l/(r-l)] = (self.composite)(op, self.operator[self.size/(r-l) + l/(r-l)]);
            0
        }else{
            if l < mid && mid < r{
                self.sub_range(min, mid, l, mid, op) + self.sub_range(mid, max, mid, r, op)
            }else if mid <= l {
                self.sub_range(mid, max, l, r, op)
            }else if r <= mid {
                self.sub_range(min, mid, l, r, op)
            }else{
                panic!("invalid input: min: {}, max: {}, l: {}, r: {}", min, max, l, r );
            }
        }
    }

    pub fn get(&self, index: usize) -> u64{
        (self.unite)(self.elements[index], self.sub_get(index + self.size))
    }

    fn sub_get(&self, index: usize) -> u64 {
        if index == 0 {
            self.unit
        }else{
            (self.composite)(self.operator[index], self.sub_get(index >> 1))
        }
    }

    pub fn debug(&self) {
        println!("{:?}", self.operator);
    }
}

